SOURCE_KEYS = {
    'xlsx': {'path', 'origin', 'owned', 'file_format'},
    'sqlite': {'path', 'owned'},
    'h2': {'mode', 'path', 'host', 'port', 'database', 'user'},
    'firebird': {'host', 'port', 'database', 'user', 'charset', 'role'},
    'oracle': {'host', 'port', 'service', 'sid', 'user', 'mode', 'schema'},
}
WORKBOOK_SUFFIXES = frozenset(('.xlsx', '.xlsm'))
XLSM_DATA_NOTICE = 'XLSM: makra VBA i przyciski makr nie są uruchamiane. Odczytujemy zapisane dane; kopia XLSX nie zachowa makr.'


def workbook_file_format(source):
    options=source['options']
    return options.get('file_format') or ('xlsm' if any(Path(options.get(k,'')).suffix.lower()=='.xlsm' for k in ('path','origin')) else 'xlsx')


def validate_source(value: dict) -> dict:
    if not isinstance(value, dict): raise UserError('Nieprawidłowa definicja źródła.')
    kind = value.get('kind')
    if kind not in SOURCE_KEYS: raise UserError('Nieobsługiwany typ źródła.')
    raw = value.get('options', {})
    if not isinstance(raw, dict) or set(raw) - SOURCE_KEYS[kind]:
        raise UserError('Źródło zawiera nieobsługiwane opcje lub sekret.')
    options = {}
    for k, v in raw.items():
        if k == 'port':
            try: v = int(v)
            except (ValueError, TypeError): raise UserError('Port musi być liczbą.')
            if not 1 <= v <= 65535: raise UserError('Port poza zakresem 1–65535.')
        elif k == 'owned': v = bool(v)
        else: v = clean_text(v, 2048)
        options[k] = v
    for k in ('host', 'database', 'path'):
        if kind == 'h2' and any(x in str(options.get(k, '')) for x in (';', '\n', '\r', '?')):
            raise UserError('H2: znaki ; ? i nowe linie są niedozwolone. Parametry INIT i własne URL JDBC nie są obsługiwane.')
    if kind == 'h2' and options.get('mode', 'file') not in ('file', 'tcp', 'ssl'):
        raise UserError('Nieprawidłowy tryb H2.')
    if kind == 'oracle' and options.get('mode', 'thin') not in ('thin', 'thick'):
        raise UserError('Nieprawidłowy tryb Oracle.')
    if kind == 'xlsx' and 'file_format' in options and options['file_format'] not in ('xlsx','xlsm'):
        raise UserError('Nieprawidłowy format oryginału skoroszytu.')
    result = {'id': clean_text(value.get('id') or uid(), 64), 'kind': kind,
              'name': clean_text(value.get('name') or KIND_NAMES[kind], 100), 'options': options}
    if kind == 'xlsx': result['workbook'] = validate_workbook(value.get('workbook'))
    return result


def validate_dataset(raw: dict) -> dict:
    if not isinstance(raw, dict): raise UserError('Nieprawidłowy zbiór danych.')
    result = {k: clean_text(raw.get(k, ''), 50000 if k == 'sql' else 512)
              for k in ('source_id', 'schema', 'table', 'sql')}
    if not result['source_id']: raise UserError('Wybierz źródło danych.')
    if bool(result['table']) == bool(result['sql']):
        raise UserError('Wybierz tabelę albo zapytanie SQL, nie oba naraz.')
    if result['sql']: result['sql'] = validate_select(result['sql'])
    if raw.get('dataset_id') or raw.get('snapshot_id'):
        result['dataset_id'] = workbook_id(raw.get('dataset_id'))
        result['snapshot_id'] = workbook_id(raw.get('snapshot_id'))
    return result


def validate_analysis(raw: dict) -> dict:
    if not isinstance(raw, dict): raise UserError('Nieprawidłowa analiza.')
    a = {'id': clean_text(raw.get('id') or uid(), 64),
         'name': clean_text(raw.get('name') or 'Nowa analiza', 100),
         'dataset': validate_dataset(raw.get('dataset', {})),
         'rows': [], 'columns': [], 'measures': [], 'filters': [], 'calculations': [],
         'totals': bool(raw.get('totals', True)), 'subtotals': bool(raw.get('subtotals', False))}
    for axis, limit in (('rows', 3), ('columns', 2)):
        values = raw.get(axis, [])
        if not isinstance(values, list) or len(values) > limit:
            raise UserError(f'Maksymalnie {limit} pola w obszarze {axis}.')
        for d in values:
            grain = d.get('grain', 'raw')
            if grain not in ('raw', 'year', 'month', 'day'): raise UserError('Nieobsługiwane grupowanie dat.')
            a[axis].append({'field': clean_text(d.get('field'), 512), 'grain': grain})
    dims = a['rows'] + a['columns']
    if len({(d['field'], d['grain']) for d in dims}) != len(dims):
        raise UserError('To samo pole i grupowanie nie może wystąpić jednocześnie na obu osiach.')
    ms = raw.get('measures', [])
    if not isinstance(ms, list) or len(ms) > 12: raise UserError('Maksymalnie 12 miar.')
    for m in ms:
        agg = m.get('agg', 'sum')
        if agg not in AGG_NAMES: raise UserError('Nieobsługiwana agregacja.')
        fmt = m.get('format', 'auto')
        if fmt not in ('auto', 'money', 'integer', 'percent'): raise UserError('Nieobsługiwany format.')
        a['measures'].append({'id': clean_text(m.get('id') or uid(), 64),
                              'field': clean_text(m.get('field', ''), 512), 'agg': agg,
                              'label': clean_text(m.get('label', ''), 100), 'format': fmt,
                              'numerator': clean_text(m.get('numerator', ''), 64),
                              'denominator': clean_text(m.get('denominator', ''), 64)})
    if len({m['id'] for m in a['measures']}) != len(a['measures']): raise UserError('Powtórzone identyfikatory miar.')
    base_ids = {m['id'] for m in a['measures'] if m['agg'] != 'ratio'}
    for m in a['measures']:
        if m['agg'] == 'ratio' and (m['numerator'] not in base_ids or m['denominator'] not in base_ids):
            raise UserError('Iloraz musi odnosić się do dwóch istniejących miar bazowych.')
    fs = raw.get('filters', [])
    if not isinstance(fs, list) or len(fs) > 30: raise UserError('Maksymalnie 30 filtrów.')
    for f in fs:
        op = f.get('op', 'eq')
        if op not in ('eq','ne','gt','ge','lt','le','contains','starts','ends','in','between','isnull','notnull'):
            raise UserError('Nieobsługiwany operator filtra.')
        v = f.get('value', '')
        if isinstance(v, list):
            if len(v) > 300: raise UserError('Maksymalnie 300 wartości w filtrze IN.')
            v = [clean_text(x, 2000) for x in v]
        else: v = clean_text(v, 2000)
        grain = f.get('grain', 'raw')
        if grain not in ('raw','year','month','day'): raise UserError('Nieprawidłowy filtr daty.')
        a['filters'].append({'field': clean_text(f.get('field'),512),'op':op,'value':v,'grain':grain})
    cs = raw.get('calculations', [])
    if not isinstance(cs, list) or len(cs) > 12: raise UserError('Maksymalnie 12 pól obliczeniowych.')
    for c in cs:
        name = clean_text(c.get('name'),100)
        if not name: raise UserError('Pole obliczeniowe musi mieć nazwę.')
        a['calculations'].append({'name':name, 'expr':clean_text(c.get('expr'),2000)})
    if len({c['name'] for c in a['calculations']}) != len(a['calculations']):
        raise UserError('Powtórzone nazwy pól obliczeniowych.')
    return a


def new_project() -> dict:
    return {'version': PROJECT_VERSION, 'name': 'Bez tytułu', 'sources': [], 'analyses': [], 'active': '', 'workpads': [], 'active_workpad': '', 'join_views': []}


def validate_project(raw: dict) -> dict:
    if not isinstance(raw, dict) or raw.get('version') not in (1, 2, 3, PROJECT_VERSION):
        raise UserError('Nieobsługiwana wersja projektu. Nie wykonano migracji ani zmian w pliku.')
    if len(raw.get('sources', [])) > 100 or len(raw.get('analyses', [])) > 200:
        raise UserError('Projekt przekracza limit źródeł lub analiz.')
    if not isinstance(raw.get('join_views',[]),list) or len(raw.get('join_views',[]))>100:raise UserError('Nieprawidłowa lista zapisanych połączeń tabel.')
    p = {'version':PROJECT_VERSION, 'name':clean_text(raw.get('name','Projekt'),100),
         'sources':[validate_source(s) for s in raw.get('sources',[])],
         'analyses':[validate_analysis(a) for a in raw.get('analyses',[])],
         'active':clean_text(raw.get('active',''),64),
         'workpads':[sheet_validate_book(b) for b in raw.get('workpads',[])],
         'active_workpad':clean_text(raw.get('active_workpad',''),64),
         'join_views':[database_saved_join(v) for v in raw.get('join_views',[])]}
    if len(p['workpads'])>12 or len({b['id'] for b in p['workpads']})!=len(p['workpads']):
        raise UserError('Projekt może zawierać do 12 różnych skoroszytów roboczych.')
    if len(dumps(p).encode('utf-8'))>SHEET_MAX_BYTES:raise UserError('Definicja projektu z arkuszami przekracza 32 MB.')
    sids = {s['id'] for s in p['sources']}
    if len(sids) != len(p['sources']): raise UserError('Powtórzone identyfikatory źródeł.')
    aids = {a['id'] for a in p['analyses']}
    if len(aids) != len(p['analyses']): raise UserError('Powtórzone identyfikatory analiz.')
    if any(a['dataset']['source_id'] not in sids for a in p['analyses']):
        raise UserError('Analiza odwołuje się do nieistniejącego źródła.')
    for a in p['analyses']:
        source=next(s for s in p['sources'] if s['id']==a['dataset']['source_id'])
        if source['kind']=='xlsx': workbook_version(source,a['dataset'])
    joins=p['join_views']
    if len(joins)>100 or len({v['id'] for v in joins})!=len(joins):raise UserError('Projekt może zawierać do 100 różnych zapisanych połączeń tabel.')
    by_source={s['id']:s for s in p['sources']}
    for view in joins:
        plan=view['plan'];source=by_source.get(plan['source_id'])
        if source is None or source['kind']!=plan['backend']:raise UserError('Zapisane połączenie nie pasuje do źródła w projekcie.')
    if p['active'] not in aids: p['active'] = next(iter(aids), '')
    return p


SQL_FORBIDDEN = {'INSERT','UPDATE','DELETE','MERGE','CREATE','DROP','ALTER','TRUNCATE',
                 'GRANT','REVOKE','EXECUTE','EXEC','CALL','COMMIT','ROLLBACK','SAVEPOINT',
                 'ATTACH','DETACH','PRAGMA','VACUUM','REINDEX','REPLACE','INTO','LOCK',
                 'READFILE','WRITEFILE','FILE_READ','FILE_WRITE','CSVREAD','CSVWRITE',
                 'LOAD_EXTENSION','SYSTEM_EXECUTE','UTL_HTTP','UTL_FILE','DBMS_SCHEDULER'}


def validate_select(sql: str) -> str:
    """Zachowawcza kontrola leksykalna. NIE jest granicą uprawnień ani sandboxem."""
    sql = sql.strip()
    if sql.endswith(';'): sql = sql[:-1].rstrip()
    if len(sql) > 50000 or not sql: raise UserError('Zapytanie jest puste lub zbyt długie.')
    tokens = []; i = 0
    while i < len(sql):
        ch = sql[i]
        if ch.isspace(): i += 1; continue
        if sql.startswith('--', i):
            end = sql.find('\n', i); i = len(sql) if end < 0 else end + 1; continue
        if sql.startswith('/*', i):
            end = sql.find('*/', i + 2)
            if end < 0: raise UserError('Niedomknięty komentarz SQL.')
            if '/*' in sql[i+2:end]: raise UserError('Zagnieżdżone komentarze nie są obsługiwane.')
            i = end + 2; continue
        if ch in ("'", '"'):
            quote = ch; i += 1
            while True:
                end = sql.find(quote, i)
                if end < 0: raise UserError('Niedomknięty literał lub identyfikator SQL.')
                if end+1 < len(sql) and sql[end+1] == quote: i = end+2; continue
                i = end+1; break
            continue
        if ch in (';', '\x00', '`', '[', ']'):
            raise UserError('Dozwolone jest jedno SELECT/WITH; identyfikatory zapisuj w podwójnych cudzysłowach.')
        m = re.match(r'[A-Za-z_][A-Za-z0-9_$]*', sql[i:])
        if m:
            token = m.group().upper(); tokens.append(token); i += len(m.group()); continue
        i += 1
    if not tokens or tokens[0] not in ('SELECT','WITH') or 'SELECT' not in tokens:
        raise UserError('Dozwolone jest jedno zapytanie SELECT, opcjonalnie z CTE WITH.')
    bad = set(tokens) & SQL_FORBIDDEN
    if bad: raise UserError('Niedozwolona konstrukcja SQL: ' + ', '.join(sorted(bad)))
    return sql


# ======================== 2. ADAPTERY BAZ ===================================
@dataclasses.dataclass(frozen=True)
class Column:
    name: str
    db_type: str = ''
    kind: str = 'text'
    exact: bool = False

    def as_dict(self): return dataclasses.asdict(self)


def type_kind(db_type: str) -> str:
    typ = str(db_type).upper()
    if any(t in typ for t in ('BLOB','BINARY','RAW','ARRAY')): return 'binary'
    if any(t in typ for t in ('DATE','TIME')): return 'date'
    if 'BOOL' in typ: return 'boolean'
    if any(t in typ for t in ('INT','NUM','DEC','REAL','FLOAT','DOUBLE','MONEY')): return 'number'
    return 'text'


class ExactAggregate:
    mode = 'sum'
    def __init__(self): self.total = Decimal(0); self.n = 0; self.edge = None
    def step(self, value):
        if value is None: return
        x = Decimal(str(value))
        if not x.is_finite(): raise ValueError('Niefinitywna liczba')
        with localcontext() as c:
            c.prec = 80
            self.total += x
        self.n += 1
        if self.edge is None or (self.mode == 'min' and x < self.edge) or (self.mode == 'max' and x > self.edge):
            self.edge = x
    def finalize(self):
        if not self.n: return None
        with localcontext() as c:
            c.prec = 50
            return str(self.total / self.n if self.mode == 'avg' else
                       self.edge if self.mode in ('min','max') else self.total)


def install_decimal_functions(conn):
    for mode in ('sum','avg','min','max'):
        conn.create_aggregate('ps_' + mode, 1, type('Exact_' + mode, (ExactAggregate,), {'mode':mode}))
    def op(a,b,which):
        if a is None or b is None: return None
        x,y = Decimal(str(a)),Decimal(str(b))
        with localcontext() as c:
            c.prec = 50
            if which == 'add': v = x+y
            elif which == 'sub': v = x-y
            elif which == 'mul': v = x*y
            else:
                if y == 0: return None
                v = x/y
            return str(v)
    for name in ('add','sub','mul','div'):
        conn.create_function('ps_'+name, 2, lambda a,b,n=name:op(a,b,n), deterministic=True)
    conn.create_function('ps_neg',1,lambda a:None if a is None else str(Decimal(str(a)).copy_negate()),deterministic=True)
    conn.create_function('ps_abs',1,lambda a:None if a is None else str(Decimal(str(a)).copy_abs()),deterministic=True)
    def decimal_key(value):
        if value is None: return None
        number=Decimal(str(value))
        if not number.is_finite(): raise ValueError('Niefinitywna liczba')
        if number.is_zero(): return '0'
        with localcontext() as context:
            context.prec=max(80,len(number.as_tuple().digits))
            return str(number.normalize())
    conn.create_function('ps_key',1,decimal_key,deterministic=True)
    conn.create_function('ps_cmp',2,lambda a,b:None if a is None or b is None else
                         (Decimal(str(a))>Decimal(str(b)))-(Decimal(str(a))<Decimal(str(b))),deterministic=True)
    conn.create_collation('PS_DECIMAL', lambda a,b:(Decimal(a)>Decimal(b))-(Decimal(a)<Decimal(b)))


class Adapter:
    kind = ''
    def __init__(self, source, password='', runtime=None, cancelled=None, timeout=60):
        self.source = source; self.options = source['options']; self.password = password
        self.runtime = runtime or {}; self.cancelled = cancelled or threading.Event()
        self.timeout = max(5,min(int(timeout),600)); self.conn = None; self.active_cursor = None
    def connect(self): raise NotImplementedError
    def execute(self, sql, params=()):
        self.check_cancel()
        cur = self.conn.cursor(); self.active_cursor = cur
        with contextlib.suppress(Exception): cur.arraysize = 500
        cur.execute(sql, list(params))
        return cur
    def fetch(self, sql, params=(), limit=None):
        cur = self.execute(sql,params); out=[]
        try:
            while True:
                self.check_cancel(); chunk = cur.fetchmany(500)
                if not chunk: break
                out.extend(tuple(r) for r in chunk)
                if limit is not None and len(out) > limit: raise UserError('Przekroczono limit liczby grup lub obiektów. Zawęź filtr.')
            return out
        finally:
            with contextlib.suppress(Exception): cur.close()
            self.active_cursor = None
    def check_cancel(self):
        if self.cancelled.is_set(): raise Cancelled('Anulowano wykonanie. Poprzedni wynik nie został nadpisany.')
    def cancel(self): self.cancelled.set()
    def close(self):
        if self.conn is not None:
            with contextlib.suppress(Exception): self.conn.rollback()
            with contextlib.suppress(Exception): self.conn.close()
            self.conn = None
    def bind(self, index): return ':p'+str(index) if self.kind == 'oracle' else '?'
    def limited(self, sql, limit):
        limit = max(1,min(int(limit),MAX_GROUPS+1))
        if self.kind in ('oracle','h2'): return sql + f' FETCH FIRST {limit} ROWS ONLY'
        if self.kind == 'firebird': return sql + f' ROWS {limit}'
        return sql + f' LIMIT {limit}'
    def relation(self, dataset):
        if dataset.get('sql'): return '(' + validate_select(dataset['sql']) + ') ps_source'
        return (qident(dataset['schema']) + '.' if dataset.get('schema') else '') + qident(dataset['table'])
    def tables(self): raise NotImplementedError
    def columns(self, dataset):
        cur = self.execute(self.limited('SELECT * FROM '+self.relation(dataset),25))
        try:
            names = [str(d[0]) for d in cur.description]
            rows = cur.fetchmany(25)
            cols = []
            for i,n in enumerate(names):
                value = next((r[i] for r in rows if r[i] is not None),None)
                kind = 'number' if isinstance(value,(Decimal,int,float)) else 'date' if isinstance(value,(dt.date,dt.datetime)) else 'text'
                cols.append(Column(n,'wynik zapytania / typ z próbki',kind,isinstance(value,Decimal)))
            return unique_columns(cols)
        finally: cur.close(); self.active_cursor=None
    def date_expr(self, expression, grain):
        if grain == 'raw': return expression
        if self.kind == 'sqlite':
            return "strftime('%s', %s)" % ({'year':'%Y','month':'%Y-%m','day':'%Y-%m-%d'}[grain],expression)
        if self.kind == 'oracle':
            return "TO_CHAR(%s, '%s', 'NLS_DATE_LANGUAGE=English')" % (expression,{'year':'YYYY','month':'YYYY-MM','day':'YYYY-MM-DD'}[grain])
        if self.kind == 'h2':
            return "FORMATDATETIME(%s, '%s')" % (expression,{'year':'yyyy','month':'yyyy-MM','day':'yyyy-MM-dd'}[grain])
        year = f'CAST(EXTRACT(YEAR FROM {expression}) AS VARCHAR(4))'
        month = f"LPAD(CAST(EXTRACT(MONTH FROM {expression}) AS VARCHAR(2)), 2, '0')"
        day = f"LPAD(CAST(EXTRACT(DAY FROM {expression}) AS VARCHAR(2)), 2, '0')"
        return year if grain=='year' else f"{year} || '-' || {month}" + (f" || '-' || {day}" if grain=='day' else '')


def unique_columns(cols):
    names = [c.name for c in cols]
    if len(set(names)) != len(names): raise UserError('Wynik SQL ma powtórzone nazwy kolumn. Dodaj jednoznaczne aliasy AS.')
    if len(cols) > 200: raise UserError('Zbiór ma ponad 200 kolumn. Wybierz potrzebne kolumny przez SQL.')
    return cols


class SQLiteAdapter(Adapter):
    kind = 'sqlite'
    def connect(self):
        path = Path(self.options.get('path','')).expanduser().resolve()
        if not path.is_file(): raise UserError('Nie znaleziono pliku SQLite. Nie utworzono nowej bazy: '+str(path))
        self.conn = sqlite3.connect(path.as_uri()+'?mode=ro', uri=True, timeout=5)
        self.conn.execute('PRAGMA query_only=ON'); self.conn.execute('PRAGMA trusted_schema=OFF')
        self.conn.execute('PRAGMA busy_timeout=5000')
        self.text_encoding=self.conn.execute('PRAGMA encoding').fetchone()[0]
        install_decimal_functions(self.conn)
        self.conn.set_progress_handler(lambda:1 if self.cancelled.is_set() else 0,2000)
        self.conn.execute('BEGIN')
        allowed = {sqlite3.SQLITE_SELECT,sqlite3.SQLITE_READ,sqlite3.SQLITE_FUNCTION,
                   getattr(sqlite3,'SQLITE_RECURSIVE',33)}
        def auth(action,a,b,db,trigger):
            if action==sqlite3.SQLITE_FUNCTION and str(b).lower() in ('load_extension','readfile','writefile'):
                return sqlite3.SQLITE_DENY
            return sqlite3.SQLITE_OK if action in allowed else sqlite3.SQLITE_DENY
        self.conn.set_authorizer(auth)
        return self
    def tables(self):
        return [{'schema':'main','name':r[0],'type':r[1]} for r in self.fetch(
            "SELECT name,type FROM sqlite_schema WHERE type IN ('table','view') AND name NOT LIKE 'sqlite_%' ORDER BY name",limit=2000)]
    def columns(self,dataset):
        if dataset.get('sql'): return super().columns(dataset)
        # Table-valued PRAGMA remains read-only; temporarily permit only its internal metadata actions.
        self.conn.set_authorizer(None)
        try:
            rows = self.conn.execute('SELECT name,type FROM pragma_table_xinfo(?) WHERE hidden<>1 ORDER BY cid',
                                     (dataset['table'],)).fetchall()
        finally:
            # query_only + URI remain enforced; reinstate full authorizer via explicit shared policy.
            self.conn.set_authorizer(sqlite_authorizer)
        if not rows: raise UserError('Tabela nie istnieje albo nie ma dostępnych kolumn.')
        return unique_columns([Column(n,t,type_kind(t),'DECIMAL_TEXT' in t.upper()) for n,t in rows])
    def cancel(self):
        super().cancel()
        if self.conn is not None:
            with contextlib.suppress(Exception): self.conn.interrupt()
    def close(self):
        if self.conn is not None: self.conn.set_authorizer(None)
        super().close()


# Workbook metadata is part of the project, not a widget's transient selection.
# Logical sheet/dataset IDs survive a compatible refresh. Analysis references pin
# immutable data revisions; adding another sheet never invalidates that result.
WORKBOOK_FORMAT = 1
MAX_WORKBOOK_SHEETS = 200
MAX_DATA_REVISIONS = 40


def workbook_id(value):
    value = str(value or '')
    if not re.fullmatch(r'[a-f0-9]{32}', value):
        raise UserError('Nieprawidłowy identyfikator danych skoroszytu.')
    return value


def workbook_hash(value):
    value = str(value or '')
    if not re.fullmatch(r'[a-f0-9]{64}', value):
        raise UserError('Nieprawidłowa suma kontrolna migawki.')
    return value


def worksheet_name(value):
    # Names are identifiers in XLSX: never trim meaningful spaces or silently truncate.
    if not isinstance(value,str) or not value.strip() or len(value)>200 or any(c in value for c in '\0\r\n'):
        raise UserError('Nieprawidłowa nazwa arkusza XLSX.')
    return value


def worksheet_options(raw=None, sheet=''):
    raw = raw or {}
    try: start = int(raw.get('header_row', 1))
    except (ValueError, TypeError): raise UserError('Wskaż numer pierwszego wiersza danych / nagłówka.') from None
    if not 1 <= start <= 1048576: raise UserError('Numer wiersza jest poza arkuszem XLSX.')
    area = clean_text(raw.get('range', ''), 64).replace('$', '').upper().strip()
    if area:
        match = re.fullmatch(r'([A-Z]{1,3})([1-9]\d*):([A-Z]{1,3})([1-9]\d*)', area)
        if not match: raise UserError('Zakres wpisz jako A1:C100 (bez nazwy arkusza).')
        def col(s):
            n = 0
            for c in s: n = n * 26 + ord(c) - 64
            return n
        left, top, right, bottom = col(match[1]), int(match[2]), col(match[3]), int(match[4])
        if not (1 <= left <= right <= 16384 and 1 <= top <= bottom <= 1048576 and right-left < 200):
            raise UserError('Zakres musi mieć od 1 do 200 kolumn i mieścić się w arkuszu.')
        if start == 1: start = top
        if not top <= start <= bottom: raise UserError('Pierwszy wiersz musi mieścić się we wskazanym zakresie.')
    return {'sheet': worksheet_name(sheet or raw.get('sheet')) if sheet or raw.get('sheet') else '',
            'header': bool(raw.get('header', True)), 'header_row': start,
            'range': area, 'decimal': ',' if raw.get('decimal') == ',' else '.'}


def worksheet_bounds(options):
    options = worksheet_options(options)
    if not options['range']: return 0, 199, options['header_row'], 1048576
    a, b = options['range'].split(':')
    def cell(s):
        m = re.fullmatch(r'([A-Z]+)(\d+)', s); n = 0
        for c in m[1]: n = n * 26 + ord(c) - 64
        return n-1, int(m[2])
    left, top = cell(a); right, bottom = cell(b)
    return left, right, max(top, options['header_row']), bottom


def validate_import_columns(raw):
    if not isinstance(raw, list) or not 1 <= len(raw) <= 200:
        raise UserError('Zbiór musi mieć od 1 do 200 kolumn.')
    out = [{'name': clean_text(c.get('name'), 100), 'type': str(c.get('type', 'text'))} for c in raw]
    if (any(not c['name'] or c['type'] not in ('text','integer','decimal','date','datetime') for c in out)
            or len({c['name'].casefold() for c in out}) != len(out)):
        raise UserError('Nieprawidłowe albo powtórzone kolumny zbioru.')
    return out


def validate_workbook(raw):
    if not isinstance(raw, dict) or raw.get('format') != WORKBOOK_FORMAT:
        raise UserError('Nieobsługiwany katalog skoroszytu.')
    revision = workbook_hash(raw.get('revision'))
    sheets = raw.get('sheets', [])
    if not isinstance(sheets, list) or not 1 <= len(sheets) <= MAX_WORKBOOK_SHEETS:
        raise UserError('Skoroszyt musi mieć od 1 do 200 arkuszy komórek.')
    out = {'format': WORKBOOK_FORMAT, 'revision': revision,
           'captured': clean_text(raw.get('captured', ''), 64), 'sheets': [], 'datasets': []}
    for item in sheets:
        name = worksheet_name(item.get('name'))
        out['sheets'].append({'id': workbook_id(item.get('id')), 'name': name,
                              'hidden': bool(item.get('hidden')), 'missing': bool(item.get('missing'))})
    ids = {s['id'] for s in out['sheets']}
    if len(ids) != len(sheets) or len({s['name'] for s in out['sheets']}) != len(sheets):
        raise UserError('Powtórzone arkusze w katalogu.')
    datasets = raw.get('datasets', [])
    if not isinstance(datasets, list) or len(datasets) > MAX_WORKBOOK_SHEETS:
        raise UserError('Za dużo zbiorów skoroszytu.')
    for d in datasets:
        did = workbook_id(d.get('id')); sid = workbook_id(d.get('sheet_id'))
        if sid not in ids: raise UserError('Zbiór wskazuje nieznany arkusz.')
        name = next(s['name'] for s in out['sheets'] if s['id'] == sid)
        value = {'id': did, 'sheet_id': sid, 'name': name,
                 'options': worksheet_options(d.get('options'), name), 'current': '', 'versions': []}
        versions = d.get('versions', [])
        if not isinstance(versions, list) or len(versions) > MAX_DATA_REVISIONS:
            raise UserError('Przekroczono limit zachowanych wersji zbioru; utwórz osobne źródło.')
        for v in versions:
            rows = int(v.get('rows', 0))
            if not 0 <= rows <= 2000000: raise UserError('Nieprawidłowa liczba rekordów migawki.')
            value['versions'].append({'id': workbook_id(v.get('id')),
                'source_revision': workbook_hash(v.get('source_revision')),
                'path': clean_text(v.get('path', ''), 2048), 'sha256': workbook_hash(v.get('sha256')),
                'created': clean_text(v.get('created',''),64), 'rows': rows,
                'options': worksheet_options(v.get('options', value['options']),name),
                'columns': validate_import_columns(v.get('columns',[])),
                'source_columns': validate_import_columns(v.get('source_columns',v.get('columns',[])))})
        vids = {v['id'] for v in value['versions']}
        if len(vids) != len(value['versions']): raise UserError('Powtórzone wersje zbioru.')
        value['current'] = str(d.get('current') or '')
        if value['current'] and value['current'] not in vids: raise UserError('Brak bieżącej migawki zbioru.')
        out['datasets'].append(value)
    if len({d['id'] for d in out['datasets']}) != len(datasets) or len({d['sheet_id'] for d in out['datasets']}) != len(datasets):
        raise UserError('Powtórzone zbiory arkusza.')
    return out


def workbook_sheet(source, sheet_id):
    item = next((s for s in source['workbook']['sheets'] if s['id'] == sheet_id), None)
    if item is None: raise UserError('Arkusz nie należy do tego skoroszytu.')
    return item


def workbook_dataset(source, dataset_id='', sheet_id=''):
    item = next((d for d in source['workbook']['datasets']
                 if d['id'] == dataset_id or (sheet_id and d['sheet_id'] == sheet_id)), None)
    if item is None: raise UserError('Nie znaleziono definicji zbioru arkusza.')
    return item


def workbook_version(source, reference):
    d = workbook_dataset(source, reference.get('dataset_id',''))
    vid = reference.get('snapshot_id','')
    if not vid: raise UserError('Analiza skoroszytu musi wskazywać konkretną wersję danych.')
    version = next((v for v in d['versions'] if v['id'] == vid), None)
    if version is None: raise UserError('Migawka przypisana do analizy nie jest dostępna.')
    return d, version


def workbook_reference(source, sheet_id):
    d = workbook_dataset(source, sheet_id=sheet_id)
    if not d['current']: raise UserError('Najpierw przygotuj wybrany arkusz do analizy.')
    return {'source_id': source['id'], 'dataset_id': d['id'], 'snapshot_id': d['current'],
            'schema': 'main', 'table': 'dane', 'sql': ''}


def source_data_fingerprint(source, reference=None):
    if source['kind'] != 'xlsx': return digest(source)
    d, v = workbook_version(source, reference or {})
    return digest({'source_id': source['id'], 'dataset_id': d['id'],
                   'snapshot_id': v['id'], 'content': v['sha256'], 'origin': v['source_revision']})


def dataset_caption(source, reference):
    if source['kind'] == 'xlsx':
        d, v = workbook_version(source, reference)
        return source['name'] + '  /  ' + d['name'] + '  ·  ' + v['created'][:16].replace('T',' ') + ' UTC'
    if source['kind']=='sqlite' and source['options'].get('owned') and reference.get('table')=='dane':
        return source['name'] + '  /  lokalny import · bez katalogu arkuszy'
    return source['name'] + '  /  ' + ('Zapytanie SQL' if reference.get('sql') else
        (reference.get('schema','')+'.' if reference.get('schema') else '')+reference.get('table',''))


class WorkbookAdapter(SQLiteAdapter):
    """XLSX is the source identity; this adapter only executes a pinned SQLite extract."""
    kind = 'sqlite'
    def bind_dataset(self, reference):
        if reference.get('sql'):raise UserError('Skoroszyt korzysta z nazwanych zbiorów, nie z własnego SQL.')
        _, version = workbook_version(self.source, reference)
        self.options = {'path': version['path']}
        self._data_version = version
    def connect(self):
        version = getattr(self, '_data_version', None)
        if version is None: raise UserError('Wybierz arkusz, nie cały skoroszyt jako tabelę.')
        path = Path(version['path'])
        if not path.is_file(): raise UserError('Brak zapisanej migawki arkusza. Otwórz projekt z dołączonymi danymi.')
        if file_digest(path) != version['sha256']:
            raise UserError('Lokalne dane arkusza zostały zmienione. Nie użyto ich w analizie.')
        return super().connect()
    def relation(self, dataset):
        if dataset.get('sql'): raise UserError('Własny SQL dla skoroszytu nie jest dostępny. Użyj konstruktora analizy.')
        return '"main"."dane"'


def sqlite_authorizer(action,a,b,db,trigger):
    if action==sqlite3.SQLITE_FUNCTION and str(b).lower() in ('load_extension','readfile','writefile'):
        return sqlite3.SQLITE_DENY
    return sqlite3.SQLITE_OK if action in {sqlite3.SQLITE_SELECT,sqlite3.SQLITE_READ,
           sqlite3.SQLITE_FUNCTION,getattr(sqlite3,'SQLITE_RECURSIVE',33)} else sqlite3.SQLITE_DENY


class OracleAdapter(Adapter):
    kind = 'oracle'
    def connect(self):
        oracle = require_module('oracledb','oracle'); o=self.options
        if o.get('mode','thin')=='thick':
            lib=self.runtime.get('oracle_client','')
            if not lib or not Path(lib).is_dir():
                raise DependencyError('oracle','external','W ustawieniach wybierz katalog zgodnego Oracle Client dla trybu Thick.')
            try:oracle.init_oracle_client(lib_dir=lib)
            except Exception as exc:
                raise DependencyError('oracle','external','Nie można załadować Oracle Client: '+safe_error(exc,self.password)) from exc
        kw={'host':o.get('host'),'port':o.get('port',1521),'user':o.get('user'),
            'password':self.password,'tcp_connect_timeout':10}
        if o.get('sid'): kw['sid']=o['sid']
        else: kw['service_name']=o.get('service')
        try:self.conn=oracle.connect(**kw)
        except Exception as exc:
            error=exc.args[0] if exc.args else exc
            code=getattr(error,'full_code','')
            hint=''
            if code in ('ORA-01017','ORA-28000','ORA-28001'):
                hint='Sprawdź login, hasło i stan konta Oracle. Sterownik jest dostępny. '
            elif code in ('ORA-01031','ORA-00942'):
                hint='Konto Oracle nie ma wymaganych uprawnień do wybranego źródła. '
            elif code.startswith('ORA-125') or code in ('DPY-6000','DPY-6005'):
                hint='Sprawdź host, port, Service Name/SID oraz dostęp do sieci lub VPN. '
            if hint:raise UserError(hint+safe_error(exc,self.password)) from exc
            raise
        self.conn.call_timeout=self.timeout*1000
        def output_handler(cursor,metadata):
            if metadata.type_code==oracle.DB_TYPE_NUMBER:
                return cursor.var(str,size=256,arraysize=cursor.arraysize,outconverter=Decimal)
        self.conn.outputtypehandler=output_handler
        cur=self.conn.cursor()
        try:
            cur.execute("ALTER SESSION SET NLS_NUMERIC_CHARACTERS='.,'")
            cur.execute("ALTER SESSION SET NLS_CALENDAR='GREGORIAN'")
            cur.execute("SET TRANSACTION READ ONLY")
        finally: cur.close()
        return self
    def tables(self):
        owner=self.options.get('schema') or self.options.get('user','').upper()
        rows=self.fetch(self.limited('SELECT table_name, \'TABLE\' FROM all_tables WHERE owner=:p1 '
                         "UNION ALL SELECT view_name, 'VIEW' FROM all_views WHERE owner=:p2 ORDER BY 1",2001),[owner,owner],2000)
        return [{'schema':owner,'name':r[0],'type':r[1]} for r in rows]
    def columns(self,dataset):
        if dataset.get('sql'): return super().columns(dataset)
        owner=dataset.get('schema') or self.options.get('schema') or self.options.get('user','').upper()
        rows=self.fetch('SELECT column_name,data_type FROM all_tab_columns WHERE owner=:p1 AND table_name=:p2 ORDER BY column_id',
                        [owner,dataset['table']],200)
        if not rows: raise UserError('Brak metadanych tabeli. Sprawdź schemat i uprawnienia.')
        return unique_columns([Column(n,t,type_kind(t),t=='NUMBER') for n,t in rows])
    def cancel(self):
        super().cancel()
        if self.conn is not None:
            with contextlib.suppress(Exception): self.conn.cancel()


class FirebirdAdapter(Adapter):
    kind='firebird'
    def connect(self):
        fb=require_module('firebird.driver','firebird'); o=self.options
        lib=self.runtime.get('firebird_client','')
        if lib:
            if not Path(lib).is_file(): raise DependencyError('firebird','external','Nie znaleziono wybranej biblioteki fbclient.')
            fb.driver_config.fb_client_library.value=lib
        database=o.get('database','')
        if not database: raise UserError('Wpisz alias lub ścieżkę bazy Firebird.')
        if o.get('host'): database=f"{o['host']}/{o.get('port',3050)}:{database}"
        self.conn=fb.connect(database,user=o.get('user'),password=self.password,
                             charset=o.get('charset') or 'UTF8',role=o.get('role') or None)
        self.conn.begin(fb.tpb(fb.Isolation.SNAPSHOT,lock_timeout=min(self.timeout,30),access_mode=fb.TraAccessMode.READ))
        with contextlib.suppress(Exception):
            # Firebird 4+ provides a server-side statement timeout in milliseconds.
            self.conn._att.set_statement_timeout(self.timeout*1000)
        return self
    def tables(self):
        rows=self.fetch("SELECT TRIM(RDB$RELATION_NAME), CASE WHEN RDB$VIEW_BLR IS NULL THEN 'TABLE' ELSE 'VIEW' END "
                        "FROM RDB$RELATIONS WHERE COALESCE(RDB$SYSTEM_FLAG,0)=0 ORDER BY RDB$RELATION_NAME",limit=2000)
        return [{'schema':'','name':r[0],'type':r[1]} for r in rows]
    def columns(self,dataset):
        if dataset.get('sql'): return super().columns(dataset)
        rows=self.fetch('SELECT TRIM(r.RDB$FIELD_NAME), f.RDB$FIELD_TYPE, f.RDB$FIELD_SUB_TYPE, f.RDB$FIELD_SCALE '
                        'FROM RDB$RELATION_FIELDS r JOIN RDB$FIELDS f ON f.RDB$FIELD_NAME=r.RDB$FIELD_SOURCE '
                        'WHERE r.RDB$RELATION_NAME=? ORDER BY r.RDB$FIELD_POSITION',[dataset['table']],200)
        names={7:'SMALLINT',8:'INTEGER',10:'FLOAT',12:'DATE',13:'TIME',14:'CHAR',16:'BIGINT',
               23:'BOOLEAN',24:'DECFLOAT',25:'DECFLOAT',26:'INT128',27:'DOUBLE',28:'TIME WITH TIME ZONE',
               29:'TIMESTAMP WITH TIME ZONE',35:'TIMESTAMP',37:'VARCHAR',261:'BLOB'}
        result=[]
        for name,typ,sub,scale in rows:
            dbt='DECIMAL' if sub in (1,2) and typ in (7,8,16,26) else names.get(typ,'UNKNOWN')
            result.append(Column(name,dbt,type_kind(dbt),dbt=='DECIMAL'))
        if not result: raise UserError('Brak kolumn: sprawdź nazwę tabeli i uprawnienia.')
        return unique_columns(result)
    def cancel(self):
        super().cancel()
        if self.conn is not None:
            with contextlib.suppress(Exception):
                fb=require_module('firebird.driver','firebird')
                # firebird-driver 2.0.3 exposes cancellation on its attachment,
                # not on the DB-API Connection; isolated here as a pinned-driver detail.
                from firebird.driver.types import CancelType
                self.conn._att.cancel_operation(CancelType.RAISE)


class JDBCCursor:
    def __init__(self,statement,result):
        self.statement=statement; self.result=result; md=result.getMetaData()
        self.types=[md.getColumnType(i) for i in range(1,md.getColumnCount()+1)]
        self.description=[(str(md.getColumnLabel(i)),str(md.getColumnTypeName(i)))
                          for i in range(1,md.getColumnCount()+1)]
    def fetchmany(self,size=500):
        out=[]
        for _ in range(size):
            if not self.result.next(): break
            row=[]
            for i,t in enumerate(self.types,1):
                if t in (-6,5,4,-5):
                    value=self.result.getString(i); value=int(value) if value is not None else None
                elif t in (2,3):
                    value=self.result.getBigDecimal(i); value=Decimal(str(value)) if value is not None else None
                elif t in (6,7,8):
                    value=self.result.getDouble(i); value=None if self.result.wasNull() else float(value)
                elif t in (-7,16):
                    value=self.result.getBoolean(i); value=None if self.result.wasNull() else bool(value)
                elif t in (-2,-3,-4,2004):
                    if i-1 in getattr(self,'identity_binary_columns',set()):
                        raw=self.result.getBytes(i);value=None if raw is None else bytes(raw)
                    else:
                        stream=self.result.getBinaryStream(i);value=None if stream is None else '[dane binarne — niepobierane]'
                        if stream is not None:stream.close()
                elif t in (1,12,-1,-9,-15,2005,2011,1111) and getattr(self,'cell_preview',False):
                    lob=self.result.getClob(i)
                    try:
                        try:value=None if lob is None else str(lob.getSubString(1,MAX_CELL_TEXT+1))
                        except UnicodeDecodeError:value=str(lob.getSubString(1,MAX_CELL_TEXT+2))
                    finally:
                        if lob is not None:lob.free()
                else:
                    value=self.result.getString(i); value=None if value is None else str(value)
                row.append(value)
            out.append(tuple(row))
        return out
    def close(self):
        with contextlib.suppress(Exception): self.result.close()
        with contextlib.suppress(Exception): self.statement.close()


class H2Adapter(Adapter):
    kind='h2'
    def connect(self):
        jp=require_module('jpype','h2'); jar=self.runtime.get('h2_jar','')
        if not jar or not Path(jar).is_file(): raise DependencyError('h2','external','W ustawieniach wybierz JAR H2 2.x. Potrzebna jest też zgodna 64-bitowa Java.')
        if not jp.isJVMStarted():
            try: jp.startJVM(classpath=[str(Path(jar).resolve())],convertStrings=True)
            except Exception as e: raise DependencyError('h2','external','Nie można uruchomić Javy: '+safe_error(e)) from e
        o=self.options; mode=o.get('mode','file')
        if mode=='file':
            path=Path(o.get('path','')).expanduser().resolve()
            text=str(path)
            if text.endswith('.mv.db'): text=text[:-6]
            if not Path(text+'.mv.db').is_file(): raise UserError('Nie znaleziono istniejącego pliku H2 .mv.db. Nie utworzono bazy.')
            url='jdbc:h2:file:'+text.replace('\\','/')+';IFEXISTS=TRUE;ACCESS_MODE_DATA=r'
        else:
            if not o.get('database'): raise UserError('Podaj nazwę lub ścieżkę bazy na serwerze H2.')
            url=f"jdbc:h2:{mode}://{o.get('host','localhost')}:{o.get('port',9092)}/{o['database']};IFEXISTS=TRUE"
        jp.JClass('org.h2.Driver')
        self.conn=jp.JClass('java.sql.DriverManager').getConnection(url,o.get('user','sa'),self.password)
        if self.conn.getMetaData().getDatabaseMajorVersion()<2:
            self.conn.close(); self.conn=None
            raise UserError('Ta wersja obsługuje H2 2.x. Nie migruje plików H2 1.4.')
        self.conn.setAutoCommit(False)
        self.conn.setReadOnly(True)  # JDBC hint; the DB account must ALSO be read-only.
        self.conn.setTransactionIsolation(8)  # SERIALIZABLE: consistent totals across GROUP BY queries.
        return self
    def execute(self,sql,params=()):
        self.check_cancel(); jp=__import__('jpype'); stmt=self.conn.prepareStatement(sql)
        self.active_statement=stmt
        try:
            stmt.setFetchSize(500); stmt.setQueryTimeout(self.timeout)
            for i,v in enumerate(params,1):
                if v is None: stmt.setNull(i,0)
                elif isinstance(v,bool): stmt.setBoolean(i,v)
                elif isinstance(v,(Decimal,int)): stmt.setBigDecimal(i,jp.JClass('java.math.BigDecimal')(str(v)))
                elif isinstance(v,dt.datetime): stmt.setTimestamp(i,jp.JClass('java.sql.Timestamp').valueOf(v.isoformat(' ')))
                elif isinstance(v,dt.date): stmt.setDate(i,jp.JClass('java.sql.Date').valueOf(v.isoformat()))
                elif isinstance(v,float): stmt.setDouble(i,v)
                elif isinstance(v,(bytes,bytearray,memoryview)):stmt.setBytes(i,jp.JArray(jp.JByte)(bytes(v)))
                else: stmt.setString(i,str(v))
            cur=JDBCCursor(stmt,stmt.executeQuery()); self.active_cursor=cur; return cur
        except Exception:
            with contextlib.suppress(Exception): stmt.close()
            raise
    def tables(self):
        rows=self.fetch("SELECT TABLE_SCHEMA,TABLE_NAME,TABLE_TYPE FROM INFORMATION_SCHEMA.TABLES "
                        "WHERE TABLE_SCHEMA<>'INFORMATION_SCHEMA' ORDER BY TABLE_SCHEMA,TABLE_NAME",limit=2000)
        return [{'schema':r[0],'name':r[1],'type':r[2]} for r in rows]
    def columns(self,dataset):
        if dataset.get('sql'):
            cur=self.execute(self.limited('SELECT * FROM '+self.relation(dataset),1))
            try: return unique_columns([Column(n,t,type_kind(t),t in ('NUMERIC','DECIMAL')) for n,t in cur.description])
            finally: cur.close()
        rows=self.fetch('SELECT COLUMN_NAME,DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS '
                        'WHERE TABLE_SCHEMA=? AND TABLE_NAME=? ORDER BY ORDINAL_POSITION',
                        [dataset.get('schema') or 'PUBLIC',dataset['table']],200)
        if not rows: raise UserError('Nie znaleziono kolumn H2.')
        return unique_columns([Column(n,t,type_kind(t),t in ('NUMERIC','DECIMAL')) for n,t in rows])
    def cancel(self):
        super().cancel()
        stmt=getattr(self,'active_statement',None)
        if stmt is not None:
            with contextlib.suppress(Exception): stmt.cancel()


ADAPTERS={'xlsx':WorkbookAdapter,'sqlite':SQLiteAdapter,'h2':H2Adapter,'firebird':FirebirdAdapter,'oracle':OracleAdapter}

# ======================== 3. PLANOWANIE I WYKONANIE ANALIZ ==================
class QueryBuilder:
    def __init__(self, adapter: Adapter, analysis: dict, columns: list[Column]):
        self.adapter=adapter; self.a=analysis; self.fields={c.name:c for c in columns}
        self.calcs={}; self.params=[]
        for c in analysis['calculations']:
            if c['name'] in self.fields: raise UserError('Nazwa pola obliczeniowego koliduje z kolumną: '+c['name'])
            self.calcs[c['name']]=self.compile_expression(c['expr'])
            self.fields[c['name']]=Column(c['name'],'DECIMAL_TEXT' if adapter.kind=='sqlite' else 'DECIMAL','number',True)
        for d in analysis['rows']+analysis['columns']: self.dimension(d)
        for m in analysis['measures']:
            if m['agg'] not in ('count_rows','ratio'):
                field=self.field(m['field'])
                if m['agg'] in ('sum','avg') and field.kind!='number':
                    raise UserError(f'{AGG_NAMES[m["agg"]]} wymaga kolumny liczbowej: {m["field"]}. '
                                    'Dla SQL nadaj liczbie właściwy typ przez CAST; dla plików wybierz typ przy imporcie.')
        # Validate filters even in an empty-result scenario.
        self.where(); self.params=[]

    def field(self,name):
        if name not in self.fields: raise UserError('Nie znaleziono pola: '+name+'. Schemat źródła mógł się zmienić.')
        return self.fields[name]

    def expression(self,name):
        self.field(name)
        return self.calcs[name] if name in self.calcs else qident(name)

    def compile_expression(self,text):
        refs={}
        def replace(m):
            name=m.group(1)
            if name not in self.fields or self.fields[name].kind!='number':
                raise UserError('W obliczeniu można użyć istniejących pól liczbowych: '+name)
            key='__field_'+str(len(refs)); refs[key]=name; return key
        replaced=re.sub(r'\[([^\[\]]+)\]',replace,text)
        try: tree=ast.parse(replaced,mode='eval')
        except (SyntaxError,ValueError) as e: raise UserError('Błędna formuła. Przykład: [Ilość] * [Cena].') from e
        if sum(1 for _ in ast.walk(tree))>100: raise UserError('Formuła jest zbyt złożona.')
        def emit(n,depth=0):
            if depth>15: raise UserError('Formuła jest zbyt głęboko zagnieżdżona.')
            if isinstance(n,ast.Expression): return emit(n.body,depth+1)
            if isinstance(n,ast.Name) and n.id in refs: return self.expression(refs[n.id])
            if isinstance(n,ast.Constant) and type(n.value) in (int,float):
                v=Decimal(str(n.value) if type(n.value) is int else ast.get_source_segment(replaced,n).replace('_',''))
                if not v.is_finite() or abs(v.adjusted())>30: raise UserError('Stała liczbowa poza zakresem formuły.')
                return "'"+str(v)+"'" if self.adapter.kind=='sqlite' else str(v)
            if isinstance(n,ast.UnaryOp) and isinstance(n.op,(ast.UAdd,ast.USub)):
                x=emit(n.operand,depth+1)
                if isinstance(n.op,ast.UAdd): return x
                return f'ps_neg({x})' if self.adapter.kind=='sqlite' else f'(-({x}))'
            if isinstance(n,ast.BinOp) and isinstance(n.op,(ast.Add,ast.Sub,ast.Mult,ast.Div)):
                left,right=emit(n.left,depth+1),emit(n.right,depth+1)
                opname={ast.Add:'add',ast.Sub:'sub',ast.Mult:'mul',ast.Div:'div'}[type(n.op)]
                if self.adapter.kind=='sqlite': return f'ps_{opname}({left},{right})'
                if isinstance(n.op,ast.Div): return f'(({left}) * 1.0 / NULLIF(({right}),0))'
                operator={ast.Add:'+',ast.Sub:'-',ast.Mult:'*'}[type(n.op)]
                return f'(({left}) {operator} ({right}))'
            if isinstance(n,ast.Call) and isinstance(n.func,ast.Name) and n.func.id=='abs' and len(n.args)==1 and not n.keywords:
                return ('ps_abs' if self.adapter.kind=='sqlite' else 'ABS')+'('+emit(n.args[0],depth+1)+')'
            raise UserError('Dozwolone formuły: [Pole], liczby, + − * /, nawiasy i abs(). Bez kodu Pythona.')
        return emit(tree)

    def dimension(self,d):
        col=self.field(d['field'])
        if col.kind=='binary': raise UserError('Kolumna binarna nie może być wymiarem.')
        if d.get('grain','raw')!='raw' and col.kind!='date':
            raise UserError('Grupowanie dat wymaga pola daty: '+col.name+'. Dla tekstu użyj CAST w SQL albo typu daty przy imporcie.')
        expression=self.expression(d['field'])
        if self.adapter.kind=='sqlite' and col.exact and col.kind=='number' and d.get('grain','raw')=='raw':
            return f'ps_key({expression}) COLLATE PS_DECIMAL'
        if self.adapter.kind=='sqlite' and col.kind=='text' and d.get('grain','raw')=='raw':
            # Stable text coordinates across independently grouped subtotal queries.
            return expression+' COLLATE BINARY'
        return self.adapter.date_expr(expression,d.get('grain','raw'))

    def parameter(self,value,col=None,grain='raw'):
        if col and grain=='raw' and value is not None:
            try:
                if col.kind=='number':
                    value=Decimal(str(value).replace('\u202f','').replace(' ',''))
                    if not value.is_finite(): raise ValueError()
                    if self.adapter.kind=='sqlite':
                        if col.exact: value=str(value)
                        elif value==value.to_integral_value() and -(2**63)<=value<2**63: value=int(value)
                        else: value=float(value)
                elif col.kind=='boolean':
                    if str(value).lower() not in ('true','false','1','0','tak','nie'): raise ValueError()
                    value=str(value).lower() in ('true','1','tak')
                elif col.kind=='date':
                    value=str(value)
                    parsed=dt.datetime.fromisoformat(value) if 'T' in value or ' ' in value else dt.date.fromisoformat(value)
                    # SQLite stores the raw date text. Keep its delimiter,
                    # fractional precision and offset so drill-down matches the
                    # exact dimension key returned by that database.
                    if self.adapter.kind!='sqlite':value=parsed
            except (ValueError,decimal.InvalidOperation,OverflowError) as e:
                raise UserError(f'Nieprawidłowa wartość filtra dla pola {col.name}. Liczby: 1234.56; daty: RRRR-MM-DD.') from e
        self.params.append(value)
        if len(self.params)>900: raise UserError('Za dużo parametrów filtrów. Zawęź listy IN.')
        return self.adapter.bind(len(self.params))

    def where(self,extra=None):
        parts=[]
        for f in self.a['filters']+list(extra or []):
            col=self.field(f['field']); grain=f.get('grain','raw')
            expression=self.dimension({'field':f['field'],'grain':grain})
            op=f['op']; value=f.get('value','')
            if op=='isnull': parts.append(expression+' IS NULL'); continue
            if op=='notnull': parts.append(expression+' IS NOT NULL'); continue
            def compare(v,operator):
                param=self.parameter(v,col,grain)
                if self.adapter.kind=='sqlite' and col.exact and col.kind=='number' and grain=='raw':
                    return f'ps_cmp({expression}, {param}) {operator} 0'
                return expression+' '+operator+' '+param
            if op in ('eq','ne','gt','ge','lt','le'):
                parts.append(compare(value,{'eq':'=','ne':'<>','gt':'>','ge':'>=','lt':'<','le':'<='}[op]))
            elif op in ('contains','starts','ends'):
                if col.kind!='text': raise UserError('Filtr tekstowy wymaga kolumny tekstowej: '+col.name)
                if isinstance(value,list): raise UserError('Filtr tekstowy wymaga jednej wartości.')
                value=value.replace('~','~~').replace('%','~%').replace('_','~_')
                value=('%' if op in ('contains','ends') else '')+value+('%' if op in ('contains','starts') else '')
                parts.append(expression+' LIKE '+self.parameter(value)+" ESCAPE '~'")
            elif op in ('in','between'):
                values=value if isinstance(value,list) else [v.strip() for v in value.split(';')]
                if not values or len(values)>300: raise UserError('Filtr IN wymaga 1–300 wartości.')
                if op=='between':
                    if len(values)!=2: raise UserError('Przedział wymaga dwóch wartości oddzielonych średnikiem.')
                    parts.append('('+compare(values[0],'>=')+' AND '+compare(values[1],'<=')+')')
                else:
                    parts.append('('+' OR '.join(compare(v,'=') for v in values)+')')
        return ' WHERE '+' AND '.join('('+p+')' for p in parts) if parts else ''

    def aggregate(self,m):
        if m['agg']=='count_rows': return 'COUNT(*)'
        expression=self.expression(m['field']); col=self.field(m['field']); agg=m['agg']
        if agg=='count_distinct':
            if self.adapter.kind=='sqlite' and col.exact and col.kind=='number': expression+=' COLLATE PS_DECIMAL'
            elif self.adapter.kind=='sqlite' and col.kind=='text': expression+=' COLLATE BINARY'
            return 'COUNT(DISTINCT '+expression+')'
        fn=agg.upper()
        if self.adapter.kind=='sqlite' and col.exact and agg in ('sum','avg','min','max'):
            fn='ps_'+agg
        return fn+'('+expression+')'

    def query(self,rn,cn):
        self.params=[]
        dims=self.a['rows'][:rn]+self.a['columns'][:cn]
        expressions=[self.dimension(d) for d in dims]
        measures=[self.aggregate(m) for m in self.a['measures'] if m['agg']!='ratio']
        if not measures: raise UserError('Dodaj przynajmniej jedną miarę bazową.')
        sql='SELECT '+', '.join(expressions+measures)+' FROM '+self.adapter.relation(self.a['dataset'])
        sql+=self.where()
        if expressions: sql+=' GROUP BY '+', '.join(expressions)
        return sql,list(self.params)

    def preview_query(self,extra=None):
        self.params=[]
        cols=[c for c in self.fields.values() if c.kind!='binary']
        if not cols: raise UserError('Brak niebinarnych kolumn do podglądu.')
        sql='SELECT '+', '.join(self.expression(c.name)+' AS '+qident(c.name) for c in cols)
        sql+=' FROM '+self.adapter.relation(self.a['dataset'])+self.where(extra)
        return self.adapter.limited(sql,PREVIEW_LIMIT+1),list(self.params),cols


def normalize_field_value(value,col,grain='raw'):
    if value is not None and grain=='raw' and col.kind=='number' and isinstance(value,str):
        try: return Decimal(value)
        except decimal.InvalidOperation: raise UserError('Źródło zwróciło tekst zamiast liczby: '+col.name)
    return value


def key_order(key):
    parts=[]
    for s in key:
        v=json.loads(s)
        if v is None: parts.append((0,''))
        elif v['t']=='n': parts.append((2,Decimal(v['v'])))
        elif v['t']=='b': parts.append((1,v['v']))
        else: parts.append((3,v['v']))
    return tuple(parts)+((9,''),)  # subtotals follow their children; grand total last.


def grouping_levels(analysis):
    rn,cn=len(analysis['rows']),len(analysis['columns'])
    rows=[rn]
    if analysis['subtotals']: rows+=list(range(rn-1,0,-1))
    if analysis['totals'] and rn: rows.append(0)
    cols=[cn]+([0] if analysis['totals'] and cn else [])
    return list(itertools.product(rows,cols))


def query_metadata(sql,params):
    return {'sql':sql,'parameters':[pack(p) for p in params]}


def result_base(adapter,analysis,kind):
    meta = {'kind':kind,'analysis':analysis,'fingerprint':digest(analysis),'analysis_id':analysis['id'],
            'source_id':adapter.source['id'],'source_name':adapter.source['name'],
            'backend':adapter.kind,'created':utcnow(),'queries':[],'warnings':[],'columns':[],
            'complete':True,'row_count':0}
    if adapter.source['kind']=='xlsx':
        d,v=workbook_version(adapter.source,analysis['dataset'])
        meta.update(sheet_name=d['name'],data_revision=v['id'],source_revision=v['source_revision'])
        meta['source_name']=dataset_caption(adapter.source,analysis['dataset'])
        meta['warnings'].append('Zapisane wyniki formuł XLSX; program nie przelicza formuł ani nie potwierdza ich aktualności.')
    return meta


def run_pivot(adapter,analysis,out_path,progress=lambda _:None):
    started=time.monotonic(); progress('Odczyt metadanych i walidacja analizy')
    cols=adapter.columns(analysis['dataset']); qb=QueryBuilder(adapter,analysis,cols)
    meta=result_base(adapter,analysis,'pivot'); groups={}; rowkeys=set(); colkeys=set(); nrows=len(analysis['rows'])
    levels=grouping_levels(analysis); base_ms=[m for m in analysis['measures'] if m['agg']!='ratio']
    if not base_ms: raise UserError('Dodaj miarę, np. liczbę rekordów.')
    bytes_used=0
    for ix,(rn,cn) in enumerate(levels):
        adapter.check_cancel(); progress(f'Agregacja w bazie · poziom {ix+1} z {len(levels)}')
        sql,params=qb.query(rn,cn); meta['queries'].append(query_metadata(sql,params))
        cursor=adapter.execute(sql,params)
        try:
            while True:
                adapter.check_cancel(); batch=cursor.fetchmany(500)
                if not batch: break
                for raw in batch:
                    dims=analysis['rows'][:rn]+analysis['columns'][:cn]
                    keys=tuple(dumps(pack(normalize_field_value(v,qb.field(d['field']),d['grain'])))
                               for v,d in zip(raw[:rn+cn],dims))
                    rk,ck=keys[:rn],keys[rn:]
                    vals={}
                    for m,v in zip(base_ms,raw[rn+cn:]):
                        if v is not None and m['agg'] not in ('min','max'):
                            try: v=Decimal(str(v))
                            except decimal.InvalidOperation: raise UserError('Agregacja zwróciła nieprawidłową liczbę.')
                        elif m['agg'] in ('min','max'):
                            v=normalize_field_value(v,qb.field(m['field']))
                        vals[m['id']]=v
                    for m in analysis['measures']:
                        if m['agg']=='ratio':
                            num,den=vals[m['numerator']],vals[m['denominator']]
                            with localcontext() as c:
                                c.prec=50
                                try: vals[m['id']]=None if num is None or den is None or Decimal(str(den))==0 else Decimal(str(num))/Decimal(str(den))
                                except decimal.InvalidOperation: raise UserError('Iloraz wymaga miar liczbowych.')
                    packed=[pack(vals[m['id']]) for m in analysis['measures']]
                    groups[(rk,ck)]=packed; rowkeys.add(rk); colkeys.add(ck)
                    bytes_used+=len(dumps(packed))+sum(len(k) for k in keys)
                    if len(groups)>MAX_GROUPS or bytes_used>MAX_RESULT_BYTES:
                        raise UserError('Pivot przekracza limit grup lub pamięci wyniku. Zawęź filtry. Nie pokazano częściowego pivota.')
                    if len(colkeys)*len(analysis['measures'])+max(1,nrows)>MAX_COLUMNS:
                        raise UserError(f'Pivot byłby szerszy niż {MAX_COLUMNS} kolumn. Przenieś pole do wierszy lub dodaj filtr.')
                    if len(rowkeys)*(len(colkeys)*len(analysis['measures'])+max(1,nrows))>MAX_CELLS:
                        raise UserError(f'Pivot przekracza {MAX_CELLS:,} komórek. Zawęź filtry. Nie obcięto wyniku.')
        finally:
            with contextlib.suppress(Exception): cursor.close()
            adapter.active_cursor=None
    ordered_rows=sorted(rowkeys,key=key_order); ordered_cols=sorted(colkeys,key=key_order)
    if not analysis['columns'] and not ordered_cols: ordered_cols=[()]
    if analysis['rows']:
        for i,d in enumerate(analysis['rows']):
            col=qb.field(d['field']); kind=col.kind if d['grain']=='raw' else 'text'
            meta['columns'].append({'id':f'd{i}','label':d['field']+({'raw':'','year':' · rok','month':' · miesiąc','day':' · dzień'}[d['grain']]),
                                    'kind':kind,'format':'auto','dimension':True})
    else:
        meta['columns'].append({'id':'d0','label':'Zakres','kind':'text','format':'auto','dimension':True})
    for ck in ordered_cols:
        title=' / '.join(display_cell(json.loads(v)) for v in ck)
        if not ck and analysis['columns']: title='Ogółem'
        for mi,m in enumerate(analysis['measures']):
            label=m['label'] or (AGG_NAMES[m['agg']]+(' · '+m['field'] if m['field'] else ''))
            kind=qb.field(m['field']).kind if m['agg'] in ('min','max') else 'number'
            meta['columns'].append({'id':f'v{len(meta["columns"])}','label':label,'group':title,
                                    'kind':kind,'format':m['format'],'measure':m['id'],
                                    'colkey':[json.loads(v) for v in ck],'dimension':False})
    def rows():
        for rk in ordered_rows:
            if nrows:
                cells=[json.loads(v) for v in rk]
                if len(rk)<nrows:
                    cells.append(pack('Ogółem' if not rk else 'Razem'))
                    cells.extend([None]*(nrows-len(cells)))
            else: cells=[pack('Cały zbiór')]
            for ck in ordered_cols:
                cells.extend(groups.get((rk,ck),[None]*len(analysis['measures'])))
            yield cells,len(rk)<nrows,[json.loads(v) for v in rk]
    meta['row_count']=len(ordered_rows); meta['elapsed']=round(time.monotonic()-started,3)
    meta['scope_note']='Pełna agregacja źródła po zastosowaniu filtrów. Puste kombinacje wymiarów nie są zerami.'
    if any(c.kind=='number' and any(t in c.db_type.upper() for t in ('REAL','FLOAT','DOUBLE')) for c in cols):
        meta['warnings'].append('Źródło zawiera liczby zmiennoprzecinkowe; ich dokładność zależy od typu w bazie.')
    if adapter.kind=='oracle':
        meta['warnings'].append('Oracle utożsamia pusty tekst z NULL. Daty bez strefy nie są konwertowane do innej strefy.')
    meta['warnings'].append('SQLite: grupowanie tekstów i liczba unikalnych tekstów używają BINARY (rozróżniają wielkość liter). '
                            'LIKE działa według reguł SQLite.' if adapter.kind=='sqlite' else
                            'Porównania tekstów i unikalność zależą od kolacji bazy. Dla kolacji ignorujących wielkość liter '
                            'ujednolić klucze wymiarów w SQL (np. UPPER), aby reprezentacja grup była stała między poziomami sum.')
    progress('Budowanie i zapis pełnego wyniku')
    ResultStore.write(out_path,meta,rows())
    return meta


def run_preview(adapter,analysis,out_path,extra=None,progress=lambda _:None,drill=False):
    started=time.monotonic(); progress('Pobieranie oznaczonego podglądu, nie całej tabeli')
    cols=adapter.columns(analysis['dataset']); qb=QueryBuilder(adapter,analysis,cols)
    sql,params,cols=qb.preview_query(extra)
    data=adapter.fetch(sql,params,PREVIEW_LIMIT+1)
    more=len(data)>PREVIEW_LIMIT; data=data[:PREVIEW_LIMIT]
    meta=result_base(adapter,analysis,'drill' if drill else 'preview')
    meta['columns']=[{'id':f'f{i}','label':c.name,'kind':c.kind,'format':'auto','dimension':False} for i,c in enumerate(cols)]
    meta['queries']=[query_metadata(sql,params)]
    meta['row_count']=len(data); meta['complete']=not more; meta['has_more']=more
    meta['elapsed']=round(time.monotonic()-started,3)
    meta['scope_note']=f'Podgląd maks. {PREVIEW_LIMIT} rekordów po filtrach. ' + (
        'Źródło zawiera więcej rekordów; sortowanie dotyczy wyłącznie pobranej próbki.' if more else
        'W tym wykonaniu źródło nie zwróciło więcej rekordów niż limit podglądu.')
    if drill:
        meta['warnings'].append('Szczegóły pochodzą z NOWEJ transakcji: baza mogła zmienić się od czasu utworzenia pivota. '
                                'Dla liczby unikalnych pokazujemy rekordy źródłowe, także powtarzające się.')
    def rows():
        for row in data:
            yield [pack(normalize_field_value(v,c)) for v,c in zip(row,cols)],False,[]
    ResultStore.write(out_path,meta,rows()); return meta


# ======================== 4. WYNIKI, PROJEKTY, IMPORT / EKSPORT ===============
class ResultStore:
    @staticmethod
    def write(path,meta,rows):
        path=Path(path); tmp=path.with_suffix('.part')
        with contextlib.suppress(FileNotFoundError): tmp.unlink()
        conn=sqlite3.connect(tmp)
        try:
            conn.executescript('CREATE TABLE meta(value TEXT NOT NULL); '
                               'CREATE TABLE rows(id INTEGER PRIMARY KEY,data TEXT NOT NULL,is_total INTEGER NOT NULL,rowkey TEXT NOT NULL);')
            conn.execute('INSERT INTO meta VALUES(?)',(dumps(meta),))
            size=0
            for i,(cells,total,key) in enumerate(rows):
                text=dumps(cells); size+=len(text)
                if size>MAX_RESULT_BYTES: raise UserError('Wynik przekracza limit pamięci podręcznej.')
                conn.execute('INSERT INTO rows VALUES(?,?,?,?)',(i,text,int(total),dumps(key)))
            conn.commit(); conn.close(); os.replace(tmp,path)
            with contextlib.suppress(OSError): path.chmod(0o600)
        except Exception:
            conn.close()
            with contextlib.suppress(FileNotFoundError): tmp.unlink()
            raise
    @staticmethod
    def connect(path):
        conn=sqlite3.connect(Path(path).resolve().as_uri()+'?mode=ro',uri=True)
        conn.create_collation('PS_DECIMAL',lambda a,b:(Decimal(a)>Decimal(b))-(Decimal(a)<Decimal(b)))
        return conn
    @staticmethod
    def metadata(path):
        with contextlib.closing(ResultStore.connect(path)) as c: return json.loads(c.execute('SELECT value FROM meta').fetchone()[0])
    @staticmethod
    def page(path,page=0,sort=None,direction='asc'):
        with contextlib.closing(ResultStore.connect(path)) as c:
            meta=json.loads(c.execute('SELECT value FROM meta').fetchone()[0]); total=meta['row_count']
            page=max(0,min(int(page),max(0,(total-1)//PAGE_SIZE)))
            order='id'
            if sort is not None and sort!='':
                ix=next((i for i,col in enumerate(meta['columns']) if col['id']==sort),None)
                if ix is None: raise UserError('Nieznana kolumna sortowania.')
                expr=f"json_extract(data, '$[{ix}].v')"
                if meta['columns'][ix]['kind']=='number':
                    expr=f"CASE WHEN json_extract(data, '$[{ix}].t')='n' THEN {expr} ELSE NULL END COLLATE PS_DECIMAL"
                order='is_total, '+expr+(' DESC' if direction=='desc' else ' ASC')+', id'
            result=[]
            for idx,text,is_total,_ in c.execute(f'SELECT id,data,is_total,rowkey FROM rows ORDER BY {order} LIMIT ? OFFSET ?',
                                                 (PAGE_SIZE,page*PAGE_SIZE)):
                cells=json.loads(text)
                for cell,col in zip(cells,meta['columns']):
                    if cell is not None: cell['d']=display_cell(cell,col['format'])
                result.append({'i':idx,'v':cells,'total':bool(is_total)})
            return {'rows':result,'page':page,'pages':max(1,math.ceil(total/PAGE_SIZE)),'count':total,'columns':meta['columns']}
    @staticmethod
    def drill_filters(path,row_id,column_id):
        with contextlib.closing(ResultStore.connect(path)) as c:
            meta=json.loads(c.execute('SELECT value FROM meta').fetchone()[0])
            if meta['kind']!='pivot': raise UserError('Szczegóły są dostępne tylko z tabeli przestawnej.')
            col=next((x for x in meta['columns'] if x['id']==column_id and x.get('measure')),None)
            if col is None: raise UserError('Wybierz komórkę miary, nie nagłówek wymiaru.')
            row=c.execute('SELECT rowkey FROM rows WHERE id=?',(int(row_id),)).fetchone()
            if row is None: raise UserError('Nie znaleziono wiersza wyniku.')
            a=meta['analysis']; filters=[]
            for dims,keys in ((a['rows'],json.loads(row[0])),(a['columns'],col['colkey'])):
                for d,cell in zip(dims,keys):
                    filters.append({'field':d['field'],'grain':d['grain'],'op':'isnull' if cell is None else 'eq',
                                    'value':'' if cell is None else cell['v']})
            m=next(m for m in a['measures'] if m['id']==col['measure'])
            if m['agg'] not in ('count_rows','ratio'):
                filters.append({'field':m['field'],'grain':'raw','op':'notnull','value':''})
            return a,filters
    @staticmethod
    def iter_rows(path):
        with contextlib.closing(ResultStore.connect(path)) as c:
            for cells,total in c.execute('SELECT data,is_total FROM rows ORDER BY id'):
                yield json.loads(cells),bool(total)


def project_resource_slots(project, include_originals=True):
    """Yield mutable path locations and their data role; never recursively treat arbitrary strings as paths."""
    for source in project['sources']:
        if source['kind']=='sqlite' and source['options'].get('owned'):
            yield source['options'],'path',source['id'],'.sqlite'
        elif source['kind']=='xlsx':
            if include_originals:yield source['options'],'path','book-'+source['id'],'.'+workbook_file_format(source)
            for dataset in source['workbook']['datasets']:
                for version in dataset['versions']:
                    yield version,'path','data-'+version['id'],'.sqlite'


class ProjectStore:
    @staticmethod
    def load(path,resource_dir):
        path=Path(path).resolve()
        if not path.is_file() or path.stat().st_size>MAX_PROJECT:raise UserError('Projekt nie istnieje lub przekracza 128 MB.')
        conn=sqlite3.connect(path.as_uri()+'?mode=ro',uri=True)
        try:
            conn.execute('PRAGMA trusted_schema=OFF');conn.execute('PRAGMA query_only=ON')
            if conn.execute('PRAGMA application_id').fetchone()[0]!=PROJECT_APP_ID:
                raise UserError('To nie jest projekt Pivot Studio. Otwórz bazę przez Dodaj źródło.')
            if conn.execute('PRAGMA user_version').fetchone()[0] not in (1,2,3,PROJECT_VERSION):
                raise UserError('Nieobsługiwana wersja projektu. Oryginał pozostaje bez zmian.')
            row=conn.execute('SELECT document FROM project WHERE id=1').fetchone()
            if not row:raise UserError('Projekt nie zawiera definicji.')
            project=validate_project(json.loads(row[0]));total=0;loaded={}
            for record,key,rid,suffix in project_resource_slots(project):
                value=record.get(key,'')
                if not value.startswith('@resource:'):continue
                resource_id=value[10:]
                cachekey=(resource_id,suffix)
                if cachekey not in loaded:
                    entry=conn.execute('SELECT checksum,data FROM resources WHERE id=?',(resource_id,)).fetchone()
                    if entry is None:raise UserError('Brak dołączonych danych projektu.')
                    checksum,blob=entry;total+=len(blob)
                    if total>MAX_PROJECT or hashlib.sha256(blob).hexdigest()!=checksum:
                        raise UserError('Uszkodzony zasób projektu.')
                    target=private_dir(Path(resource_dir))/(checksum+suffix)
                    if not target.exists() or file_digest(target)!=checksum:atomic_bytes(target,blob)
                    loaded[cachekey]=str(target)
                record[key]=loaded[cachekey]
            return project,file_digest(path)
        except (sqlite3.Error,ValueError,TypeError) as exc:raise UserError('Nieprawidłowy projekt: '+str(exc)) from exc
        finally:conn.close()
    @staticmethod
    def save(path,project,expected=None,include_data=False,owned_roots=(),include_originals=False):
        path=Path(path).expanduser().resolve().with_suffix('.pivot');project=validate_project(project)
        if path.exists():
            if expected is None:raise UserError('Plik już istnieje. Wybierz nową nazwę albo otwórz go przed zapisem.')
            if file_digest(path)!=expected:raise UserError('Projekt został zmieniony przez inny proces. Zapisz kopię.')
        path.parent.mkdir(parents=True,exist_ok=True)
        fd,name=tempfile.mkstemp(prefix='.'+path.name+'-',suffix='.tmp',dir=path.parent);os.close(fd)
        tmp=Path(name);conn=sqlite3.connect(tmp);legacy=False
        try:
            if path.exists():
                old=sqlite3.connect(path.as_uri()+'?mode=ro',uri=True)
                try:
                    legacy=old.execute('PRAGMA user_version').fetchone()[0]<PROJECT_VERSION
                    old.backup(conn)
                finally:old.close()
            else:
                conn.executescript('CREATE TABLE project(id INTEGER PRIMARY KEY CHECK(id=1),document TEXT NOT NULL);'
                    'CREATE TABLE history(id INTEGER PRIMARY KEY,created TEXT NOT NULL,document TEXT NOT NULL);'
                    'CREATE TABLE resources(id TEXT PRIMARY KEY,checksum TEXT NOT NULL,data BLOB NOT NULL);')
            conn.execute(f'PRAGMA application_id={PROJECT_APP_ID}');conn.execute(f'PRAGMA user_version={PROJECT_VERSION}')
            previous=conn.execute('SELECT document FROM project WHERE id=1').fetchone()
            if previous:conn.execute('INSERT INTO history(created,document) VALUES(?,?)',(utcnow(),previous[0]))
            conn.execute('DELETE FROM history WHERE id NOT IN (SELECT id FROM history ORDER BY id DESC LIMIT 20)')
            conn.execute('DELETE FROM resources');size=0
            if include_data:
                for record,key,rid,suffix in project_resource_slots(project,include_originals):
                    value=record.get(key,'')
                    if not value or value.startswith('@not-included'):
                        if suffix in WORKBOOK_SUFFIXES and include_originals:
                            raise UserError('Brak kopii XLSX. Połącz oryginał albo zapisz wyłącznie gotowe dane.')
                        continue
                    sp=Path(value).resolve()
                    if not any(sp.is_relative_to(Path(r).resolve()) for r in owned_roots):
                        raise UserError('Dołączanie danych jest ograniczone do zasobów zaimportowanych przez Pivot Studio.')
                    if not sp.is_file():raise UserError('Brak danych do dołączenia: '+sp.name)
                    if record.get('sha256') and file_digest(sp)!=record['sha256']:
                        raise UserError('Migawka została zmieniona poza programem. Nie dołączono jej do projektu.')
                    if suffix in WORKBOOK_SUFFIXES:
                        owner=next(x for x in project['sources'] if x['kind']=='xlsx' and x['options'] is record)
                        if file_digest(sp)!=owner['workbook']['revision']:raise UserError('Kopia XLSX została zmieniona. Nie zapisano innej wersji jako oryginału.')
                    size+=sp.stat().st_size
                    if size>MAX_PROJECT-4*1024*1024:raise UserError('Dołączone dane przekraczają limit projektu 128 MB.')
                    if suffix in WORKBOOK_SUFFIXES:
                        blob=sp.read_bytes()
                        if hashlib.sha256(blob).hexdigest()!=owner['workbook']['revision']:raise UserError('Kopia XLSX zmieniła się podczas zapisu projektu.')
                    else:
                        with tempfile.TemporaryDirectory() as backup_dir:
                            bp=Path(backup_dir)/'data.sqlite'
                            src=sqlite3.connect(sp.as_uri()+'?mode=ro',uri=True);dest=sqlite3.connect(bp)
                            try:src.backup(dest)
                            finally:dest.close();src.close()
                            blob=bp.read_bytes()
                        if record.get('sha256') and file_digest(sp)!=record['sha256']:
                            raise UserError('Migawka zmieniła się podczas zapisu projektu.')
                    checksum=hashlib.sha256(blob).hexdigest()
                    # The byte-stable backup can change SQLite header bytes. Its exact hash becomes the transport version.
                    if 'sha256' in record:record['sha256']=checksum
                    conn.execute('INSERT INTO resources VALUES(?,?,?)',(rid,checksum,blob))
                    record[key]='@resource:'+rid
                if not include_originals:
                    for source in project['sources']:
                        if source['kind']=='xlsx':source['options']['path']='@not-included'
            conn.execute('INSERT OR REPLACE INTO project VALUES(1,?)',(dumps(project),));conn.commit()
            conn.execute('VACUUM');conn.close()
            if tmp.stat().st_size>MAX_PROJECT:raise UserError('Projekt przekracza 128 MB.')
            with tmp.open('r+b') as f:os.fsync(f.fileno())
            if path.exists() and file_digest(path)!=expected:raise UserError('Projekt zmienił się podczas zapisu. Nie nadpisano go.')
            if legacy:
                backup=path.with_name(path.stem+'.przed-v'+str(PROJECT_VERSION)+'-'+uid()[:8]+'.pivot')
                with path.open('rb') as src,backup.open('xb') as dst:shutil.copyfileobj(src,dst)
                if file_digest(backup)!=expected:raise UserError('Nie potwierdzono kopii projektu przed migracją.')
            os.replace(tmp,path)
            with contextlib.suppress(OSError):path.chmod(0o600)
            return str(path),file_digest(path)
        finally:
            with contextlib.suppress(Exception):conn.close()
            with contextlib.suppress(FileNotFoundError):tmp.unlink()


# One policy for the file picker and operating-system drag & drop. No disk I/O
# in the hover path: inaccessible drives are checked later by a worker.
TABULAR_SUFFIXES = frozenset(('.csv', '.tsv', '.txt')) | WORKBOOK_SUFFIXES
SQLITE_SUFFIXES = frozenset(('.sqlite', '.sqlite3', '.db', '.db3', '.s3db'))
MAX_INCOMING_FILES = 16
FILE_PICKER_FILTER = ('Dane i projekty (*.csv *.tsv *.txt *.xlsx *.xlsm *.sqlite *.sqlite3 *.db *.db3 *.s3db *.pivot);;'
                      'Excel (*.xlsx *.xlsm);;Tekst / CSV (*.csv *.tsv *.txt);;'
                      'SQLite (*.sqlite *.sqlite3 *.db *.db3 *.s3db);;Projekt Pivot Studio (*.pivot);;Wszystkie pliki (*)')


def incoming_file_plan(paths):
    """Classify a bounded set of local paths without touching the filesystem.

    An unsupported member rejects the whole selection rather than silently
    importing a different subset. Actual file contents are checked after drop.
    """
    if isinstance(paths, (str, os.PathLike)):
        paths = [os.fspath(paths)]
    if not isinstance(paths, (list, tuple)) or not paths:
        raise UserError('Wybierz plik XLSX, XLSM, CSV, SQLite lub projekt .pivot.')
    if len(paths) > MAX_INCOMING_FILES:
        raise UserError(f'Wybierz najwyżej {MAX_INCOMING_FILES} plików naraz.')
    result, seen = [], set()
    for raw in paths:
        if not isinstance(raw, (str, os.PathLike)):
            raise UserError('Przeciągnij plik z folderu na komputerze, nie tekst ani odnośnik.')
        text = os.fspath(raw)
        if (not isinstance(text, str) or not text or len(text) > 2048
                or any(ord(c) < 32 for c in text) or '://' in text):
            raise UserError('Nieprawidłowa ścieżka. Zapisz plik na dysku i przeciągnij go ponownie.')
        path = Path(os.path.abspath(os.path.expanduser(text)))
        key = os.path.normcase(str(path))
        if key in seen:
            continue
        seen.add(key)
        suffix = path.suffix.lower()
        if path.name.lower().endswith(('.mv.db', '.h2.db')):
            raise UserError('To plik H2. Użyj „Połącz bazę → H2”, aby wybrać zgodny sterownik i tryb otwarcia.')
        if suffix in TABULAR_SUFFIXES:
            kind = 'tabular'
        elif suffix in SQLITE_SUFFIXES:
            kind = 'sqlite'
        elif suffix == '.pivot':
            kind = 'project'
        elif suffix in ('.xls', '.xlsb', '.ods'):
            raise UserError('Ten format arkusza nie jest obsługiwany. Zapisz dane jako XLSX lub CSV; makr nie uruchamiamy.')
        else:
            raise UserError('Nieobsługiwany format: '+path.name+'. Obsługiwane: XLSX, XLSM, CSV/TSV/TXT, SQLite i .pivot.')
        result.append({'path':str(path), 'kind':kind, 'name':path.name})
    if any(x['kind']=='project' for x in result) and len(result)!=1:
        raise UserError('Otwórz jeden projekt .pivot oddzielnie. Potem dodaj do niego pliki danych.')
    return result


def local_file_state(path):
    """Metadata fingerprint for preview/import race checks, not a cryptographic seal."""
    import stat
    path=Path(path).expanduser().resolve()
    try:
        info=path.stat()
    except OSError as exc:
        raise UserError('Nie można odczytać pliku: '+str(path)+'. Sprawdź, czy dysk jest dostępny, a plik pobrany lokalnie.') from exc
    if not stat.S_ISREG(info.st_mode):
        raise UserError('Wybierz zwykły plik, nie folder ani urządzenie: '+path.name)
    return {'path':str(path),'size':info.st_size,'mtime_ns':info.st_mtime_ns,
            'device':info.st_dev,'inode':info.st_ino}


@contextlib.contextmanager
def checked_xlsx(path):
    """Bounded, read-only ZIP container shared by metadata and the streaming reader."""
    try:
        with zipfile.ZipFile(path) as archive:
            entries=archive.infolist()
            if len(entries)>10000 or sum(x.file_size for x in entries)>256*1024*1024:
                raise UserError('XLSX przekracza limit rozpakowanych danych (256 MB).')
            if len({x.filename for x in entries})!=len(entries):
                raise UserError('XLSX ma powtórzone składniki archiwum. Zapisz nową kopię w arkuszu źródłowym.')
            if any(x.flag_bits & 1 for x in entries):
                raise UserError('Archiwum XLSX jest zaszyfrowane. Wybierz niezabezpieczoną kopię danych.')
            if any(x.file_size>1024*1024 and x.file_size/max(1,x.compress_size)>1000 for x in entries):
                raise UserError('Podejrzany współczynnik kompresji XLSX.')
            yield archive
    except (zipfile.BadZipFile, KeyError, ET.ParseError, EOFError, UnicodeError, ValueError) as exc:
        raise UserError('Nie można odczytać struktury XLSX. Plik jest uszkodzony albo ma inny format. Oryginał pozostaje bez zmian.') from exc


def xlsx_sheet_catalog(archive):
    """Read workbook metadata only, never shared strings, macros or external links."""
    for name in ('xl/workbook.xml','xl/_rels/workbook.xml.rels'):
        if archive.getinfo(name).file_size>4*1024*1024:
            raise UserError('Metadane XLSX są zbyt duże.')
    workbook=ET.fromstring(archive.read('xl/workbook.xml'))
    rels=ET.fromstring(archive.read('xl/_rels/workbook.xml.rels'))
    mapping={r.attrib.get('Id'):r for r in rels if r.attrib.get('TargetMode')!='External'}
    container=workbook.find('s:sheets',XNS)
    if container is None:raise UserError('Nie znaleziono listy arkuszy XLSX.')
    sheets=[];seen=set()
    for sheet in container:
        name=sheet.attrib.get('name','')
        rel=mapping.get(sheet.attrib.get('{'+XNS['r']+'}id',''))
        if rel is None:raise UserError('Nieprawidłowe odwołanie do arkusza XLSX.')
        if not rel.attrib.get('Type','').endswith('/worksheet'):continue
        target=rel.attrib.get('Target','')
        if '\\' in target:raise UserError('Nieprawidłowa ścieżka arkusza XLSX.')
        target=posixpath.normpath(target.lstrip('/') if target.startswith('/') else 'xl/'+target)
        if not name or name in seen or not target.startswith('xl/') or target not in archive.namelist():
            raise UserError('Nieprawidłowa nazwa lub ścieżka arkusza XLSX.')
        seen.add(name);sheets.append({'name':name,'path':target,'hidden':sheet.attrib.get('state','visible')!='visible'})
    if not sheets:raise UserError('Plik XLSX nie zawiera arkuszy komórek do importu.')
    return workbook,sheets


def inspect_local_file(path, cancelled=None):
    """Worker-only preflight. SQLite is opened mode=ro; no source is added yet."""
    plan=incoming_file_plan([path])[0];state=local_file_state(plan['path'])
    def check():
        if cancelled is not None and cancelled.is_set():raise Cancelled('Odczyt pliku anulowany.')
    check()
    try:
        with open(state['path'],'rb') as stream:head=stream.read(16)
    except OSError as exc:
        raise UserError('Nie można otworzyć pliku '+plan['name']+'. Sprawdź uprawnienia i dostępność lokalnej kopii.') from exc
    result=dict(plan,path=state['path'],file_state=state)
    if plan['kind']=='sqlite':
        if head!=b'SQLite format 3\x00':
            raise UserError('Ten plik nie jest rozpoznawaną bazą SQLite. Nie utworzono pustej bazy. Dla H2 lub Firebird użyj „Połącz bazę”.')
        source=validate_source({'name':Path(path).stem,'kind':'sqlite','options':{'path':state['path']}})
        adapter=SQLiteAdapter(source,cancelled=cancelled)
        try:
            adapter.connect();tables=[{'schema':'main','name':r[0],'type':r[1]} for r in adapter.fetch(
                "SELECT name,type FROM main.sqlite_schema WHERE type IN ('table','view') ORDER BY name",limit=DATABASE_MAX_OBJECTS)];check()
        finally:adapter.close()
        result.update(source=source,tables=tables)
    elif plan['kind']=='project':
        if head!=b'SQLite format 3\x00':raise UserError('To nie jest poprawny projekt .pivot.')
    elif Path(path).suffix.lower() in WORKBOOK_SUFFIXES:
        if head.startswith(bytes.fromhex('D0CF11E0A1B11AE1')):
            raise UserError('Plik ma format starszego lub zaszyfrowanego Excela. Zapisz niezabezpieczoną kopię XLSX albo CSV.')
        with checked_xlsx(state['path']) as archive:
            _,result['sheets']=xlsx_sheet_catalog(archive)
        result['file_format']=Path(path).suffix.lower()[1:]
        if result['file_format']=='xlsm':result['notice']=XLSM_DATA_NOTICE
        if local_file_state(state['path'])!=state:
            raise UserError('Plik zmienił się podczas odczytu listy arkuszy. Ponów odczyt.')
    check();return result


# Import never modifies the source file. Types proposed from a sample are validated for EVERY row.
XNS={'s':'http://schemas.openxmlformats.org/spreadsheetml/2006/main',
     'r':'http://schemas.openxmlformats.org/officeDocument/2006/relationships'}


def xlsx_rows(path,sheet_name='',options=None,cancelled=None):
    """Streaming selection, physical row coordinates, cached formulas; never evaluates code."""
    opts=worksheet_options(options,sheet_name)
    left,right,first_row,last_row=worksheet_bounds(opts)
    def check():
        if cancelled is not None and cancelled.is_set():raise Cancelled('Odczyt arkusza anulowany.')
    with checked_xlsx(path) as z:
        shared=[]
        if 'xl/sharedStrings.xml' in z.namelist():
            with z.open('xl/sharedStrings.xml') as f:
                for event,elem in ET.iterparse(f,events=('end',)):
                    if elem.tag.endswith('}si'):
                        check()
                        shared.append(''.join(t.text or '' for t in elem.iter() if t.tag.endswith('}t')))
                        elem.clear()
                        if len(shared)>1000000: raise UserError('Za dużo wspólnych ciągów tekstowych w XLSX.')
        workbook,sheets=xlsx_sheet_catalog(z)
        chosen=next((item for item in sheets if not sheet_name or item['name']==sheet_name),None)
        if chosen is None:raise UserError('Nie znaleziono wskazanego arkusza XLSX.')
        target=chosen['path']
        date_styles=set(); date1904=False
        props=workbook.find('s:workbookPr',XNS)
        if props is not None: date1904=props.attrib.get('date1904') in ('1','true')
        if 'xl/styles.xml' in z.namelist():
            styles=ET.fromstring(z.read('xl/styles.xml'))
            customs={int(n.attrib['numFmtId']):n.attrib.get('formatCode','') for n in styles.findall('s:numFmts/s:numFmt',XNS)}
            for i,xf in enumerate(styles.findall('s:cellXfs/s:xf',XNS)):
                num=int(xf.attrib.get('numFmtId',0)); fmt=customs.get(num,'')
                cleaned=re.sub(r'"[^"]*"|\\.|\[[^\]]*\]','',fmt).lower()
                if 14<=num<=22 or (num in customs and re.search(r'[ymdhis]',cleaned)):
                    date_styles.add(i)
        with z.open(target) as f:
            previous_row=0;emitted=False
            for event,elem in ET.iterparse(f,events=('end',)):
                if not elem.tag.endswith('}row'): continue
                check();physical=int(elem.attrib.get('r',previous_row+1));previous_row=physical
                if physical<first_row:elem.clear();continue
                if physical>last_row:break
                if not emitted and physical>first_row:
                    # The selected header is actually empty; don't silently use a later row.
                    yield [];emitted=True
                values={}; last=-1
                for cell in elem.findall('s:c',XNS):
                    match=re.match(r'([A-Z]+)',cell.attrib.get('r',''))
                    if match:
                        idx=0
                        for ch in match.group(1): idx=idx*26+ord(ch)-64
                        idx-=1
                    else: idx=last+1
                    if idx<left or idx>right:
                        if not opts['range'] and idx>=200 and (cell.find('s:v',XNS) is not None or cell.find('s:is',XNS) is not None):
                            raise UserError('Arkusz ma ponad 200 kolumn. Wskaż w imporcie potrzebny zakres.')
                        continue
                    idx-=left;last=max(last,idx);typ=cell.attrib.get('t','n');v=cell.find('s:v',XNS)
                    text=v.text if v is not None else None
                    formula=cell.find('s:f',XNS)
                    if formula is not None and (v is None or (text is None and typ!='str')):
                        raise UserError('Arkusz „'+chosen['name']+'”, komórka '+cell.attrib.get('r','?')+
                            ': formuła nie ma zapisanego wyniku. Przelicz i zapisz plik w Excelu / LibreOffice; nie zastąpiono wyniku przez NULL.')
                    if typ=='s' and text is not None:
                        try:
                            n=int(text)
                            if n<0:raise ValueError()
                            value=shared[n]
                        except (ValueError,IndexError): raise UserError('Uszkodzony indeks tekstu XLSX.')
                    elif typ=='inlineStr': value=''.join(t.text or '' for t in cell.findall('s:is//s:t',XNS))
                    elif typ=='b': value='true' if text=='1' else 'false'
                    elif typ=='e': raise UserError('Arkusz „'+chosen['name']+'”, komórka '+cell.attrib.get('r','?')+': błąd formuły '+str(text))
                    else:
                        value=text
                        if text and typ=='n' and int(cell.attrib.get('s',0)) in date_styles:
                            try:
                                serial=float(text); base=dt.datetime(1904,1,1) if date1904 else dt.datetime(1899,12,30)
                                if not date1904 and 60<=serial<61:
                                    raise UserError('XLSX zawiera nieistniejącą datę Excela: 1900-02-29. Popraw komórkę w źródle.')
                                if not date1904 and 0<serial<60: serial+=1
                                date=base+dt.timedelta(days=serial)
                                value=date.date().isoformat() if date.time()==dt.time() else date.isoformat(timespec='seconds')
                            except (ValueError,OverflowError): pass
                    values[idx]=value
                if opts['range']:last=right-left
                yield [values.get(i) for i in range(last+1)];emitted=True
                elem.clear()


def import_rows(path,options,cancelled=None):
    path=Path(path)
    if not path.is_file(): raise UserError('Nie znaleziono pliku importu.')
    if path.suffix.lower() in WORKBOOK_SUFFIXES:
        yield from xlsx_rows(path,options.get('sheet',''),options,cancelled); return
    if path.suffix.lower() not in TABULAR_SUFFIXES:raise UserError('Nieobsługiwany format importu. Wybierz XLSX, XLSM lub CSV.')
    encoding=options.get('encoding','utf-8-sig')
    if encoding not in ('utf-8-sig','cp1250','utf-16'): raise UserError('Nieobsługiwane kodowanie.')
    delimiter=options.get('delimiter','auto')
    with path.open('r',encoding=encoding,newline='') as f:
        if delimiter=='auto':
            sample=f.read(65536); f.seek(0)
            try: delimiter=csv.Sniffer().sniff(sample,delimiters=',;\t|').delimiter
            except csv.Error: delimiter=';'
        if delimiter not in (',',';','\t','|'): raise UserError('Nieobsługiwany separator.')
        csv.field_size_limit(MAX_CELL_TEXT)
        for row in csv.reader(f,delimiter=delimiter,strict=True): yield row


def suggest_type(values,decimal_separator='.'):
    values=[str(v).strip() for v in values if v is not None and str(v).strip()!='']
    if not values: return 'text'
    if all(re.fullmatch(r'-?(0|[1-9]\d*)',v) and len(v.lstrip('-'))<=18 for v in values): return 'integer'
    def numeric(v):
        if decimal_separator==',': v=v.replace(',','.')
        if re.match(r'^-?0\d',v): return False
        return bool(re.fullmatch(r'-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?',v))
    if all(numeric(v) for v in values): return 'decimal'
    if all(re.fullmatch(r'\d{4}-\d{2}-\d{2}',v) for v in values):
        try:
            for v in values: dt.date.fromisoformat(v)
            return 'date'
        except ValueError: pass
    if all(re.match(r'^\d{4}-\d\d-\d\d[T ]\d\d:',v) for v in values):
        try:
            for v in values: dt.datetime.fromisoformat(v)
            return 'datetime'
        except ValueError: pass
    return 'text'


def import_preview(path,options):
    if incoming_file_plan([path])[0]['kind']!='tabular':raise UserError('Podgląd importu wymaga XLSX, XLSM lub CSV.')
    state=local_file_state(path)
    iterator=import_rows(path,options)
    try:
        first=next(iterator,None)
        if first is None: raise UserError('Plik jest pusty.')
        sample=list(itertools.islice(iterator,500))
    finally:
        with contextlib.suppress(Exception): iterator.close()
    header=bool(options.get('header',True)); width=max([len(first)]+[len(r) for r in sample])
    if not 1<=width<=200: raise UserError('Import wymaga 1–200 kolumn.')
    names=[]; seen=set()
    for i in range(width):
        name=clean_text(first[i] if header and i<len(first) else f'Kolumna {i+1}',100) or f'Kolumna {i+1}'
        base=name; n=2
        while name.casefold() in seen: name=base+' '+str(n); n+=1
        seen.add(name.casefold()); names.append(name)
    if not header: sample.insert(0,first)
    columns=[]
    for i,name in enumerate(names):
        vals=[r[i] if i<len(r) else None for r in sample]
        columns.append({'name':name,'type':suggest_type(vals,options.get('decimal','.'))})
    if local_file_state(path)!=state:raise UserError('Plik zmienił się podczas podglądu. Odczytaj go ponownie.')
    return {'file_state':state,'columns':columns,'sample':[[pack(v) for v in row] for row in sample[:20]],
            'note':'Typy zaproponowano na próbce do 500 rekordów; cały import zostanie ściśle sprawdzony. '
                   'Zera wiodące pozostają tekstem. Puste komórki → NULL. XLSX/XLSM: tylko zapisane wyniki formuł, bez przeliczania.'}


def import_file(path,options,columns,target,cancelled=None,progress=lambda _:None,expected_state=None):
    if incoming_file_plan([path])[0]['kind']!='tabular':raise UserError('Import wymaga XLSX, XLSM lub CSV.')
    initial_state=local_file_state(path)
    if expected_state is not None and initial_state!=expected_state:
        raise UserError('Plik zmienił się od podglądu. Otwórz import ponownie; nie dodano częściowych danych.')
    if not columns or len(columns)>200: raise UserError('Nieprawidłowe kolumny importu.')
    names=[clean_text(c.get('name'),100) for c in columns]
    if any(not n for n in names) or len({n.casefold() for n in names})!=len(names): raise UserError('Nazwy kolumn muszą być niepuste i unikalne.')
    types={'text':'TEXT','integer':'INTEGER','decimal':'DECIMAL_TEXT','date':'DATE_TEXT','datetime':'DATETIME_TEXT'}
    if any(c.get('type') not in types for c in columns): raise UserError('Nieobsługiwany typ importu.')
    target=Path(target); tmp=target.with_suffix('.part'); conn=sqlite3.connect(tmp);iterator=None
    try:
        conn.execute('CREATE TABLE dane ('+', '.join(qident(n)+' '+types[c['type']] for n,c in zip(names,columns))+')')
        statement='INSERT INTO dane VALUES ('+','.join('?' for _ in columns)+')'
        iterator=import_rows(path,options,cancelled)
        if options.get('header',True): next(iterator,None)
        batch=[]; count=0
        for rownum,row in enumerate(iterator,2 if options.get('header',True) else 1):
            if cancelled and cancelled.is_set(): raise Cancelled('Import anulowany. Oryginał nie został zmieniony.')
            if len(row)>len(columns): raise UserError(f'Wiersz {rownum}: za dużo kolumn. Sprawdź separator.')
            out=[]
            for i,c in enumerate(columns):
                value=row[i] if i<len(row) else None
                if value is None or value=='': out.append(None); continue
                text=str(value)
                if len(text)>MAX_CELL_TEXT: raise UserError(f'Wiersz {rownum}: zbyt długa komórka.')
                try:
                    if c['type']=='integer':
                        if not re.fullmatch(r'[+-]?\d+',text.strip()): raise ValueError()
                        value=int(text)
                        if not -(2**63)<=value<2**63: raise ValueError()
                    elif c['type']=='decimal':
                        if options.get('decimal','.')==',': text=text.replace(',','.')
                        value=Decimal(text)
                        if not value.is_finite() or len(value.as_tuple().digits)>38 or abs(value.adjusted())>50: raise ValueError()
                        value=str(value)
                    elif c['type']=='date': value=dt.date.fromisoformat(text.strip()).isoformat()
                    elif c['type']=='datetime': value=dt.datetime.fromisoformat(text.strip()).isoformat()
                    else: value=text
                except (ValueError,decimal.InvalidOperation,OverflowError):
                    raise UserError(f'Wiersz {rownum}, kolumna {c["name"]}: wartość nie pasuje do typu {c["type"]}. '
                                    'Zmień typ na tekst lub popraw źródło. Nie pominięto błędnego wiersza.')
                out.append(value)
            batch.append(out); count+=1
            if count>2000000: raise UserError('Import przekracza limit 2 mln rekordów. Użyj bezpośredniego połączenia z bazą.')
            if len(batch)>=1000:
                conn.executemany(statement,batch); batch=[]; progress(f'Import: {count:,} rekordów')
                if tmp.exists() and tmp.stat().st_size>512*1024*1024: raise UserError('Import przekracza limit 512 MB.')
        if batch: conn.executemany(statement,batch)
        if cancelled and cancelled.is_set():raise Cancelled('Import anulowany. Oryginał pozostał bez zmian.')
        if local_file_state(path)!=initial_state:raise UserError('Plik zmienił się w trakcie importu. Nie dodano częściowego zbioru.')
        conn.commit(); conn.close()
        if cancelled and cancelled.is_set():raise Cancelled('Import anulowany. Oryginał pozostał bez zmian.')
        # Atomic publication is the cancellation boundary: after this point the
        # completed output must be reported as success, not a rolled-back import.
        os.replace(tmp,target)
        with contextlib.suppress(OSError): target.chmod(0o600)
        return {'path':str(target),'rows':count,'columns':columns}
    finally:
        if iterator is not None:
            with contextlib.suppress(Exception):iterator.close()
        with contextlib.suppress(Exception): conn.close()
        with contextlib.suppress(FileNotFoundError): tmp.unlink()


# ===================== WORKBOOK SOURCES / IMMUTABLE EXTRACTS =====================
def workbook_check_cancel(cancelled):
    if cancelled is not None and cancelled.is_set():
        raise Cancelled('Operacja skoroszytu anulowana. Wcześniejsze dane pozostają dostępne.')


def workbook_stage(path, directory, cancelled=None, previous=None):
    """Worker-only stable copy; no publication until the user confirms the navigator."""
    suffix=Path(path).suffix.lower()
    if suffix not in WORKBOOK_SUFFIXES: raise UserError('Wybierz skoroszyt XLSX lub XLSM (same dane, bez uruchamiania makr).')
    initial = local_file_state(path)
    if initial['size'] > 256*1024*1024: raise UserError('Skoroszyt przekracza limit 256 MB.')
    root = Path(directory); root.mkdir(parents=True, exist_ok=False)
    target = root/('workbook'+suffix); checksum=hashlib.sha256()
    try:
        with Path(path).open('rb') as src, target.open('xb') as dst:
            while chunk := src.read(1024*1024):
                workbook_check_cancel(cancelled);checksum.update(chunk);dst.write(chunk)
            dst.flush();os.fsync(dst.fileno())
        workbook_check_cancel(cancelled)
        if local_file_state(path)!=initial or file_digest(path)!=checksum.hexdigest():
            raise UserError('XLSX zmienił się podczas kopiowania. Zapisz go i ponów odczyt.')
        with checked_xlsx(target) as archive: _, catalog=xlsx_sheet_catalog(archive)
        if len(catalog)>MAX_WORKBOOK_SHEETS: raise UserError('Limit 200 arkuszy w jednym źródle.')
        old = validate_source(previous) if previous else None
        old_sheets = {x['name']:x for x in old['workbook']['sheets']} if old else {}
        sheets=[];datasets=[]
        for row in catalog:
            before=old_sheets.get(row['name']);sid=before['id'] if before else uid()
            sheets.append({'id':sid,'name':row['name'],'hidden':row['hidden'],'missing':False})
            prev=next((d for d in old['workbook']['datasets'] if d['sheet_id']==sid),None) if old else None
            datasets.append(clone(prev) if prev else {'id':uid(),'sheet_id':sid,'name':row['name'],
                'options':worksheet_options(sheet=row['name']),'versions':[],'current':''})
        if old:
            present={x['name'] for x in sheets}
            for sheet in old['workbook']['sheets']:
                if sheet['name'] not in present:
                    sheets.append(dict(sheet,missing=True))
                    datasets.append(clone(workbook_dataset(old,sheet_id=sheet['id'])))
        source=validate_source({'id':old['id'] if old else uid(),'name':old['name'] if old else Path(path).name,
            'kind':'xlsx','options':{'path':str(target),'origin':str(Path(path).resolve()),'owned':True,
                                   **({'file_format':'xlsm'} if suffix=='.xlsm' else {})},
            'workbook':{'format':WORKBOOK_FORMAT,'revision':checksum.hexdigest(),'captured':utcnow(),
                        'sheets':sheets,'datasets':datasets}})
        workbook_check_cancel(cancelled)
        return {'source':source,'directory':str(root),'original_state':initial,
                'refresh':bool(old),'previous_fingerprint':digest(old) if old else ''}
    except BaseException:
        shutil.rmtree(root,ignore_errors=True);raise


def verify_workbook_copy(source, cancelled=None):
    path=source['options'].get('path','')
    if not path or path.startswith('@') or not Path(path).is_file():
        raise UserError('Kopia XLSX nie została dołączona albo jest niedostępna. Gotowe zbiory nadal działają. '
                        'Wybierz „Połącz oryginał” w przeglądzie skoroszytu.')
    workbook_check_cancel(cancelled)
    if file_digest(path)!=source['workbook']['revision']:
        raise UserError('Kopia skoroszytu nie odpowiada zapisanej wersji. Nie odczytano innych danych.')
    workbook_check_cancel(cancelled);return path


def workbook_prepare_bundle(source, selections, directory, cancelled=None, progress=lambda _:None, compatible=False):
    """One atomic metadata publication for the entire selected set. Original and old DBs are untouched."""
    source=validate_source(source);path=verify_workbook_copy(source,cancelled)
    if not isinstance(selections,list) or not 1<=len(selections)<=MAX_WORKBOOK_SHEETS:
        raise UserError('Zaznacz co najmniej jeden arkusz.')
    selected=[workbook_id(x.get('sheet_id')) for x in selections]
    if len(set(selected))!=len(selected): raise UserError('Ten sam arkusz wybrano więcej niż raz.')
    target=Path(directory);target.mkdir(parents=True,exist_ok=False)
    prepared=[]
    try:
        for index,selection in enumerate(selections):
            workbook_check_cancel(cancelled)
            sheet=workbook_sheet(source,selection['sheet_id'])
            if sheet['missing']: raise UserError('Arkusza „'+sheet['name']+'” nie ma w nowej wersji pliku.')
            dataset=workbook_dataset(source,sheet_id=sheet['id'])
            if len(dataset['versions'])>=MAX_DATA_REVISIONS: raise UserError('Limit wersji arkusza. Dodaj plik jako osobne źródło.')
            options=worksheet_options(selection.get('options',dataset['options']),sheet['name'])
            progress(f'Arkusz {index+1}/{len(selections)} · {sheet["name"]}')
            preview=import_preview(path,options)
            source_columns=validate_import_columns(preview['columns'])
            columns=validate_import_columns(selection.get('columns') or source_columns)
            if len(columns)!=len(source_columns):raise UserError('Liczba kolumn zmieniła się od podglądu. Sprawdź arkusz ponownie.')
            if compatible and dataset['current']:
                previous=next(v for v in dataset['versions'] if v['id']==dataset['current'])
                if (columns!=previous['columns'] or options!=previous['options']
                        or source_columns!=previous.get('source_columns',previous['columns'])):
                    raise UserError('Zmieniła się struktura / interpretacja arkusza „'+sheet['name']+
                        '”. Nie podmieniono danych analiz. Dodaj zmieniony plik jako osobne źródło.')
            revision_id=uid();db=target/(revision_id+'.sqlite')
            result=import_file(path,options,columns,db,cancelled,progress,preview['file_state'])
            version={'id':revision_id,'source_revision':source['workbook']['revision'],
                     'path':str(db),'sha256':file_digest(db),'created':utcnow(),
                     'rows':result['rows'],'columns':columns,'source_columns':source_columns,'options':options}
            dataset['versions'].append(version);dataset['current']=revision_id;dataset['options']=options
            prepared.append(sheet['id'])
        workbook_check_cancel(cancelled)
        source=validate_source(source)
        return {'source':source,'prepared':prepared,'extract_directory':str(target)}
    except BaseException:
        shutil.rmtree(target,ignore_errors=True);raise


def workbook_sample(source,sheet_id,options,output,cancelled=None):
    source=validate_source(source);sheet=workbook_sheet(source,sheet_id)
    if sheet['missing']:raise UserError('Arkusz został usunięty ze źródła. Wcześniejsze analizy zachowują swoje migawki.')
    path=verify_workbook_copy(source,cancelled)
    preview=import_preview(path,worksheet_options(options,sheet['name']))
    columns=[{'id':'c'+str(i),'label':c['name'],'kind':'text','format':'auto'} for i,c in enumerate(preview['columns'])]
    rows=[(r+[None]*(len(columns)-len(r)),False,[]) for r in preview['sample']]
    meta={'kind':'sample','source_id':source['id'],'source_name':source['name']+' / '+sheet['name'],
          'sheet_name':sheet['name'],'created':utcnow(),'columns':columns,'row_count':len(rows),
          'complete':False,'has_more':False,'scope_note':'Próbka do 20 wierszy. Pełne typy i dane zostaną sprawdzone podczas przygotowania.',
          'warnings':[preview['note']],'queries':[],'sample_options':worksheet_options(options,sheet['name']),
          'sample_columns':preview['columns']}
    workbook_check_cancel(cancelled);ResultStore.write(output,meta,rows);return meta


class WorkbookCoordinator:
    """Application service for workbook ingestion. Qt never edits catalogs or publishes files."""
    def __init__(self,service):
        self.service=service;self.root=private_dir(service.import_dir/'workbooks');self.pending={}
    def job(self,op,args,output='',context=None):
        jid=self.service.hub.submit(op,args,output=output)
        self.service.hub.jobs[jid].update(generation=self.service.generation,workbook_context=context or {})
        return {'job_id':jid}
    def source(self,sid):
        source=self.service.source(sid)
        if source['kind']!='xlsx':raise UserError('To źródło nie jest skoroszytem.')
        return source
    def discard(self,token):
        pending=self.pending.pop(token,None)
        if pending:
            path=Path(pending['directory'])
            if path.parent==self.root and path.name.startswith('book-'):shutil.rmtree(path,ignore_errors=True)
    def handle(self,action,args):
        svc=self.service
        if action=='workbook_stage':
            previous=self.source(args['source_id']) if args.get('source_id') else None
            if not previous and len(svc.document['sources'])>=100:raise UserError('Limit 100 źródeł.')
            path=clean_text(args.get('path'),2048)
            return self.job('workbook_stage',{'path':path,'directory':str(self.root/('book-'+uid())),
                            'previous':previous},context={'previous':digest(previous) if previous else ''})
        if action=='workbook_discard':self.discard(args.get('token',''));return {'ok':True}
        if action=='workbook_import':
            token=args.get('token','');pending=self.pending.get(token)
            if pending is None:raise UserError('Podgląd skoroszytu wygasł. Dodaj plik ponownie.')
            return self.job('workbook_prepare',{'source':pending['source'],'selections':args['selections'],
                'directory':str(self.root/('extract-'+uid())),'compatible':pending['refresh']},
                context={'token':token,'expected':pending['previous_fingerprint'],'new':not pending['refresh']})
        if action=='workbook_prepare':
            source=self.source(args['source_id']);svc.authorize(source)
            return self.job('workbook_prepare',{'source':source,'selections':args['selections'],
                'directory':str(self.root/('extract-'+uid())),'compatible':False},
                context={'expected':digest(source),'new':False})
        if action=='workbook_sample':
            source=self.source(args['source_id']);svc.authorize(source)
            return self.job('workbook_sample',{'source':source,'sheet_id':args['sheet_id'],
                'options':args.get('options',{})},str(svc.session/(uid()+'.sqlite')),
                context={'source_id':source['id'],'revision':source['workbook']['revision']})
        if action=='workbook_relink':
            # Relinking is only allowed for byte-identical content, not an inferred sheet match.
            source=self.source(args['source_id']);svc.authorize(source)
            return self.job('workbook_stage',{'path':args['path'],'directory':str(self.root/('book-'+uid())),
                'previous':source},context={'previous':digest(source),'relink':True,'revision':source['workbook']['revision']})
        raise UserError('Nieznana operacja skoroszytu.')
    def finalize(self,job):
        svc=self.service;value=job['value'];context=job.get('workbook_context',{})
        if job['operation']=='workbook_stage':
            if context.get('relink'):
                if value['source']['workbook']['revision']!=context['revision']:
                    shutil.rmtree(value['directory'],ignore_errors=True)
                    raise UserError('Wybrany plik ma inną zawartość niż zapisany skoroszyt. Użyj odświeżania albo dodaj osobne źródło.')
                self.publish(value['source'],context['previous'],False)
                return
            token=uid();self.pending[token]=value;value['token']=token;return
        if job['operation']=='workbook_sample':
            source=self.source(context['source_id'])
            if source['workbook']['revision']!=context['revision']:raise UserError('Wersja skoroszytu zmieniła się podczas podglądu.')
            svc.results[job['id']]={'path':job['output'],'meta':value,'source_fingerprint':context['revision']}
            value['result_id']=job['id'];return
        if job['operation']=='workbook_prepare':
            try:self.publish(value['source'],context.get('expected',''),context.get('new',False))
            except BaseException:
                shutil.rmtree(value['extract_directory'],ignore_errors=True);raise
            if context.get('token'):self.pending.pop(context['token'],None)
    def publish(self,source,expected,new):
        svc=self.service;source=validate_source(source)
        old=next((x for x in svc.document['sources'] if x['id']==source['id']),None)
        if (new and old is not None) or (not new and (old is None or digest(old)!=expected)):
            raise UserError('Źródło zmieniło się od zatwierdzenia. Nie podmieniono danych; ponów operację.')
        if new and len(svc.document['sources'])>=100:raise UserError('Limit 100 źródeł.')
        before=clone(svc.document);trusted=set(svc.trusted)
        try:
            if old is None:svc.document['sources'].append(source)
            else:svc.document['sources'][svc.document['sources'].index(old)]=source;svc.trusted.discard(digest(old))
            svc.trusted.add(digest(source));svc.checkpoint()
        except BaseException:svc.document=before;svc.trusted=trusted;raise
    def cleanup_job(self,job):
        path=Path(job.get('args',{}).get('directory',''))
        if path.parent!=self.root or not path.name.startswith(('book-','extract-')):return
        referenced=[]
        for source in self.service.document['sources']:
            if source['kind']=='xlsx':
                referenced.append(source['options'].get('path',''))
                referenced.extend(v['path'] for d in source['workbook']['datasets'] for v in d['versions'])
        if any(p and not p.startswith('@') and Path(p).parent==path for p in referenced):return
        shutil.rmtree(path,ignore_errors=True)
    def close(self):
        for token in list(self.pending):self.discard(token)
        for job in list(self.service.hub.jobs.values()):
            if job['operation'] in ('workbook_stage','workbook_prepare') and job['status']!='running':self.cleanup_job(job)


def csv_safe(cell):
    if cell is None: return ''
    text=cell['v']
    if cell['t']=='n': return text
    if text.lstrip(' \r\n').startswith(('=','+','-','@','\t','\r','\n')) or text.startswith(('\t','\r','\n')):
        return "'"+text
    return text


def excel_column(index):
    text=''; index+=1
    while index:
        index,r=divmod(index-1,26); text=chr(65+r)+text
    return text


def xml_text(text):
    text=re.sub(r'[\x00-\x08\x0b\x0c\x0e-\x1f]', '', str(text))
    return xml_escape(text)


def xlsx_cell(ref,cell,style=0):
    if cell is None: return f'<c r="{ref}" s="{style}"/>'
    text=cell['v']
    if cell['t']=='n':
        number=Decimal(text)
        # Excel uses 15 significant digits. Keep higher precision as explicit text.
        significant=len(''.join(str(x) for x in number.as_tuple().digits).rstrip('0')) or 1
        if significant<=15 and -300<number.adjusted()<300:
            return f'<c r="{ref}" s="{style}"><v>{text}</v></c>'
    return f'<c r="{ref}" s="{style}" t="inlineStr"><is><t xml:space="preserve">{xml_text(text)}</t></is></c>'


