def database_relation_meta(adapter, obj):
    """Resolve identifiers against the current database before generating a SELECT."""
    schema=str(obj.get('schema',''));name=str(obj.get('name',''))
    if not name or len(name)>512 or '\0' in name+schema:raise UserError('Nieprawidłowy obiekt bazy.')
    a=adapter
    if a.kind=='sqlite':
        if schema not in ('','main'):raise UserError('Ta sesja otwiera wyłącznie bazę main.')
        found=a.fetch("SELECT type FROM main.sqlite_schema WHERE name=? AND type IN ('table','view')",[name],1)
        if not found:raise UserError('Tabela lub widok nie istnieje. Odśwież strukturę bazy.')
        a.conn.set_authorizer(sqlite_metadata_authorizer)
        try:
            raw=a.fetch("PRAGMA main.table_xinfo('"+name.replace("'","''")+"')",limit=2500)
            cols=[{'name':r[1],'type':r[2] or '', 'pk_position':int(r[5])} for r in raw if r[6]!=1]
        finally:a.conn.set_authorizer(sqlite_authorizer)
    else:
        # Metadata, never a sample SELECT for datatype discovery.
        if a.kind=='h2':
            raw=a.fetch('SELECT COLUMN_NAME,DATA_TYPE FROM INFORMATION_SCHEMA.COLUMNS WHERE TABLE_SCHEMA=? AND TABLE_NAME=? ORDER BY ORDINAL_POSITION',[schema or 'PUBLIC',name],2500)
        elif a.kind=='oracle':
            raw=a.fetch('SELECT COLUMN_NAME,DATA_TYPE FROM ALL_TAB_COLUMNS WHERE OWNER=:p1 AND TABLE_NAME=:p2 ORDER BY COLUMN_ID',[schema,name],2500)
        elif a.kind=='firebird':
            raw=a.fetch('SELECT TRIM(r.RDB$FIELD_NAME),f.RDB$FIELD_TYPE FROM RDB$RELATION_FIELDS r JOIN RDB$FIELDS f ON f.RDB$FIELD_NAME=r.RDB$FIELD_SOURCE WHERE r.RDB$RELATION_NAME=? ORDER BY r.RDB$FIELD_POSITION',[name],2500)
        else:raise UserError('Nieobsługiwane źródło.')
        cols=[{'name':str(n),'type':str(t),'pk_position':0} for n,t in raw]
    if not cols:raise UserError('Nie odczytano kolumn obiektu. Sprawdź uprawnienia i odśwież strukturę.')
    return cols


def database_exact_decimal(adapter, column):
    return adapter.kind=='sqlite' and 'DECIMAL_TEXT' in str(column.get('type','')).upper()


def database_order_expression(adapter, column, expression):
    return expression+(' COLLATE PS_DECIMAL' if database_exact_decimal(adapter,column) else '')


DATABASE_CELL_MAX_BYTES = 1024*1024
DATABASE_CELL_CHUNK = 65536


def database_row_identity(adapter,obj,cols,alias):
    """Read real key metadata; UI-supplied sorting keys are not row identities."""
    obj={'schema':obj.get('schema',''),'name':obj['name'],'kind':obj.get('kind','table')}
    obj['id']=database_object_id(obj['schema'],obj['kind'],obj['name'])
    names={c['name'] for c in cols};primary=[c['name'] for c in sorted(cols,key=lambda c:c['pk_position']) if c['pk_position']]
    if adapter.kind=='oracle':
        rows=adapter.fetch("SELECT k.COLUMN_NAME FROM ALL_CONSTRAINTS c JOIN ALL_CONS_COLUMNS k ON k.OWNER=c.OWNER AND k.CONSTRAINT_NAME=c.CONSTRAINT_NAME WHERE c.OWNER=:p1 AND c.TABLE_NAME=:p2 AND c.CONSTRAINT_TYPE='P' AND c.STATUS='ENABLED' ORDER BY k.POSITION",[obj['schema'],obj['name']],64)
        primary=[str(r[0]) for r in rows]
    elif adapter.kind=='h2':
        rows=adapter.fetch("SELECT k.COLUMN_NAME FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS c JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE k ON k.CONSTRAINT_SCHEMA=c.CONSTRAINT_SCHEMA AND k.CONSTRAINT_NAME=c.CONSTRAINT_NAME WHERE c.TABLE_SCHEMA=? AND c.TABLE_NAME=? AND c.CONSTRAINT_TYPE='PRIMARY KEY' ORDER BY k.ORDINAL_POSITION",[obj['schema'] or 'PUBLIC',obj['name']],64)
        primary=[str(r[0]) for r in rows]
    elif adapter.kind=='firebird':
        rows=adapter.fetch("SELECT TRIM(s.RDB$FIELD_NAME) FROM RDB$RELATION_CONSTRAINTS c JOIN RDB$INDEX_SEGMENTS s ON s.RDB$INDEX_NAME=c.RDB$INDEX_NAME WHERE c.RDB$RELATION_NAME=? AND c.RDB$CONSTRAINT_TYPE='PRIMARY KEY' ORDER BY s.RDB$FIELD_POSITION",[obj['name']],64)
        primary=[str(r[0]) for r in rows]
    if primary and len(primary)<=64 and all(n in names for n in primary):
        return {'object':obj,'kind':'pk','columns':primary,'expressions':[alias+'.'+qident(n) for n in primary]}
    if adapter.kind=='oracle' and obj['kind']=='table':
        return {'object':obj,'kind':'rowid','columns':[],'expressions':[alias+'.ROWID']}
    # SQLite rowids without INTEGER PRIMARY KEY can change during VACUUM.
    # Never promise a stable locator for such a table or a keyless view.
    return None


def database_identity_value(value):
    if isinstance(value,(bytes,bytearray,memoryview)):
        if len(value)>4096:raise UserError('Klucz rekordu jest zbyt duży.')
        return {'type':'bytes','value':bytes(value).hex()}
    if value is None:raise UserError('Pusty klucz nie identyfikuje rekordu.')
    if isinstance(value,(dt.datetime,dt.date,dt.time)):return {'type':type(value).__name__,'value':value.isoformat()}
    if not isinstance(value,(str,int,float,Decimal,bool)) or len(str(value))>4096:raise UserError('Nieobsługiwany klucz rekordu.')
    return {'type':type(value).__name__,'value':str(value)}


def database_identity_unpack(value,adapter):
    if not isinstance(value,dict) or not isinstance(value.get('value'),str) or len(value['value'])>8192:raise UserError('Nieprawidłowy klucz rekordu.')
    typ=value.get('type');raw=value['value']
    try:
        if typ=='bytes':return bytes.fromhex(raw)
        if typ=='str':return raw
        if typ=='int':return int(raw)
        if typ in ('Decimal','float'):
            result=Decimal(raw) if typ=='Decimal' else float(raw)
            if not math.isfinite(result):raise ValueError()
            return str(result) if adapter.kind=='sqlite' and typ=='Decimal' else result
        if typ=='bool' and raw in ('True','False'):return raw=='True'
        if typ in ('datetime','date','time'):
            result=getattr(dt,typ).fromisoformat(raw)
            return raw if adapter.kind=='sqlite' else result
    except (ValueError,decimal.InvalidOperation):pass
    raise UserError('Nieprawidłowy typ klucza rekordu.')


def database_row_token(adapter,specs,values):
    objects={};position=0
    for spec in specs:
        count=len(spec['expressions']);parts=values[position:position+count];position+=count
        if len(parts)!=count or any(v is None for v in parts):continue  # Unmatched LEFT JOIN.
        try:
            locator={'kind':spec['kind'],'columns':spec['columns'],'values':[database_identity_value(v) for v in parts]}
        except UserError:continue
        objects[spec['object']['id']]={'object':spec['object'],'locator':locator}
        if len(dumps(objects).encode('utf-8'))>16384:objects.pop(spec['object']['id'])
    return {'version':1,'source_key':digest(adapter.source),'objects':objects}


def database_identity_expressions(adapter,specs):
    expressions=[expr for spec in specs for expr in spec['expressions']]
    if adapter.kind=='sqlite':
        expressions=[f'CASE WHEN length(CAST({expr} AS BLOB))<=4096 THEN {expr} ELSE NULL END' for expr in expressions]
    elif adapter.kind=='h2':
        expressions=[f'CASE WHEN OCTET_LENGTH(CAST({expr} AS CHARACTER VARYING))<=4096 THEN {expr} ELSE NULL END' for expr in expressions]
    return expressions


def database_preview_value(value,deferred=False):
    if isinstance(value,(bytes,bytearray,memoryview)):cell=pack('[BLOB: '+str(len(value))+' bajtów]');deferred=True
    elif hasattr(value,'read'):cell=pack('[LOB — treść dostępna po dwukliku]');deferred=True
    elif isinstance(value,str) and len(value)>MAX_CELL_TEXT:cell=pack(value[:MAX_CELL_TEXT-40]+' … [tekst skrócony w podglądzie]');deferred=True
    else:cell=pack(value)
    if cell is not None and deferred:cell['deferred']=True
    return cell


def database_cell_query(adapter,args):
    token=args.get('row_token');oid=args.get('object_id');column=args.get('column')
    if not isinstance(token,dict) or token.get('version')!=1 or token.get('source_key')!=digest(adapter.source):raise UserError('Komórka należy do innego lub zmienionego źródła. Odśwież stronę.')
    if not isinstance(token.get('objects'),dict) or len(token['objects'])>DATABASE_JOIN_MAX_TABLES:raise UserError('Nieprawidłowa tożsamość rekordu.')
    entry=token['objects'].get(oid)
    if not isinstance(entry,dict):raise UserError('Rekord nie ma potwierdzonego klucza. Nie można bezpiecznie odczytać tej komórki osobno.')
    raw=entry.get('object');locator=entry.get('locator')
    if not isinstance(raw,dict) or not isinstance(locator,dict):raise UserError('Nieprawidłowa tożsamość rekordu.')
    obj={k:raw.get(k) for k in ('schema','name','kind')}
    if obj['kind'] not in DATABASE_RELATIONS or any(not isinstance(v,str) or len(v)>512 or any(ord(c)<32 for c in v) for v in obj.values()) or not obj['name']:raise UserError('Nieprawidłowy obiekt komórki.')
    obj['id']=database_object_id(obj['schema'],obj['kind'],obj['name'])
    if oid!=obj['id'] or raw.get('id')!=oid:raise UserError('Nieprawidłowy identyfikator obiektu komórki.')
    cols=database_relation_meta(adapter,obj);names={c['name']:c for c in cols}
    if column not in names:raise UserError('Kolumna nie istnieje. Odśwież strukturę i stronę danych.')
    spec=database_row_identity(adapter,obj,cols,'ps_cell')
    if spec is None or locator.get('kind')!=spec['kind'] or locator.get('columns')!=spec['columns']:raise UserError('Klucz rekordu zmienił się. Odśwież stronę danych.')
    values=locator.get('values')
    if not isinstance(values,list) or len(values)!=len(spec['expressions']):raise UserError('Niepełny klucz rekordu.')
    params=[database_identity_unpack(v,adapter) for v in values]
    if any(v is None for v in params):raise UserError('Pusty klucz rekordu.')
    where=' AND '.join(expr+' = '+adapter.bind(i+1) for i,expr in enumerate(spec['expressions']))
    relation=adapter.relation({'schema':obj['schema'],'table':obj['name']})+' ps_cell'
    return obj,names[column],'ps_cell.'+qident(column),' FROM '+relation+' WHERE '+where,params


def database_jdbc_cell_chunks(adapter,lob,meta):
    """One JDBC stream, including a decoder across UTF-16 surrogate boundaries."""
    import codecs
    jp=__import__('jpype');binary=meta['encoding']=='binary';width=1 if binary else 2
    buffer=jp.JArray(jp.JByte if binary else jp.JChar)(DATABASE_CELL_CHUNK)
    reader=lob.getBinaryStream() if binary else lob.getCharacterStream();consumed=0
    decoder=None if binary else codecs.getincrementaldecoder('utf-16-le' if sys.byteorder=='little' else 'utf-16-be')('strict')
    try:
        while True:
            adapter.check_cancel();count=int(reader.read(buffer,0,len(buffer)));adapter.check_cancel()
            if count<0:break
            if count==0:raise UserError('Odczyt LOB nie postępuje.')
            consumed+=count;raw=memoryview(buffer).tobytes()[:count*width]
            yield raw if binary else decoder.decode(raw,final=False).encode('utf-8')
        if consumed<meta['size']:raise UserError('Nie ukończono odczytu LOB: strumień zakończył się przed końcem wartości.')
        if decoder is not None:
            tail=decoder.decode(b'',final=True)
            if tail:yield tail.encode('utf-8')
    finally:reader.close()


@contextlib.contextmanager
def database_cell_stream(adapter,args):
    """A single verified row, streamed within one read transaction; never OFFSET."""
    obj,column,expression,clause,params=database_cell_query(adapter,args)
    meta={'object':obj,'column':column['name'],'encoding':'utf-8','size':None,'unit':'bytes','is_null':False}
    if adapter.kind=='sqlite':
        rows=adapter.fetch('SELECT typeof('+expression+'), length(CAST('+expression+' AS BLOB))'+clause+' LIMIT 2',params,2)
        if len(rows)!=1:raise UserError('Rekord usunięto lub klucz nie jest jednoznaczny. Odśwież stronę.')
        typ,size=rows[0];meta.update(size=int(size or 0),is_null=typ=='null',encoding='binary' if typ=='blob' else 'utf-8')
        if typ not in ('text','blob','null'):
            # SQLite CAST(REAL AS TEXT/BLOB) rounds to about 15 digits.
            raw=adapter.fetch('SELECT '+expression+clause+' LIMIT 2',params,2)
            if len(raw)!=1:raise UserError('Rekord nie jest jednoznaczny.')
            data=str(raw[0][0]).encode('utf-8');meta['size']=len(data);yield meta,iter([data]);return
        def chunks():
            import codecs
            decoder=codecs.getincrementaldecoder(getattr(adapter,'text_encoding','utf-8'))('strict') if typ!='blob' else None
            position=1
            while position<=meta['size']:
                adapter.check_cancel()
                part=adapter.fetch('SELECT substr(CAST('+expression+' AS BLOB),'+str(position)+','+str(DATABASE_CELL_CHUNK)+')'+clause+' LIMIT 2',params,2)
                if len(part)!=1 or not isinstance(part[0][0],bytes) or not part[0][0]:raise UserError('Nie ukończono odczytu komórki.')
                data=part[0][0];position+=len(data)
                yield decoder.decode(data,final=False).encode('utf-8') if decoder is not None else data
            if decoder is not None:
                tail=decoder.decode(b'',final=True)
                if tail:yield tail.encode('utf-8')
        with contextlib.closing(chunks()) as stream:yield meta,stream
        return
    cur=adapter.execute(adapter.limited('SELECT '+expression+clause,2),params);lob=None;firebird_subtype=None
    try:
        if adapter.kind=='firebird':cur.stream_blob_threshold=0
        if adapter.kind=='h2':
            if not cur.result.next():raise UserError('Rekord już nie istnieje. Odśwież stronę.')
            binary=cur.types[0] in (-2,-3,-4,2004)
            lob=cur.result.getBlob(1) if binary else cur.result.getClob(1)
            if cur.result.next():raise UserError('Klucz nie jest jednoznaczny. Odśwież stronę.')
            value=lob;meta.update(encoding='binary' if binary else 'utf-8',unit='bytes' if binary else 'utf-16 units',size=int(lob.length()) if lob is not None else 0,is_null=lob is None)
        else:
            rows=cur.fetchmany(2)
            if len(rows)!=1:raise UserError('Rekord usunięto lub klucz nie jest jednoznaczny. Odśwież stronę.')
            value=rows[0][0];meta['is_null']=value is None
            if hasattr(value,'read'):
                lob=value;binary=(any(t in str(column['type']).upper() for t in ('BLOB','BFILE')) or str(column['type'])=='261')
                if adapter.kind=='firebird':binary=not lob.is_text()
                meta.update(encoding='binary' if binary else 'utf-8',unit='bytes' if binary or adapter.kind=='firebird' else 'utf-16 units',size=int(lob.size() if adapter.kind=='oracle' else lob.length))
                if adapter.kind=='firebird' and not binary:
                    # firebird-driver 2.0.3 decodes every read(size) separately.
                    # Read raw bytes and retain decoder state across chunks.
                    firebird_subtype=lob.sub_type;lob.sub_type=0
        def chunks():
            adapter.check_cancel()
            if value is None:return
            if adapter.kind=='h2':
                yield from database_jdbc_cell_chunks(adapter,lob,meta);return
            if lob is None:
                if isinstance(value,(bytes,bytearray,memoryview)):data=bytes(value);meta['encoding']='binary'
                elif isinstance(value,(dict,list)):data=json.dumps(value,ensure_ascii=False,default=str).encode('utf-8')
                else:data=str(value).encode('utf-8')
                meta.update(size=len(data),unit='bytes')
                for offset in range(0,len(data),DATABASE_CELL_CHUNK):adapter.check_cancel();yield data[offset:offset+DATABASE_CELL_CHUNK]
                return
            position=1;decoder=None
            if firebird_subtype is not None:
                import codecs
                decoder=codecs.getincrementaldecoder(lob._charset)('strict')
            while True:
                adapter.check_cancel()
                if adapter.kind=='firebird':part=lob.read(DATABASE_CELL_CHUNK)
                else:
                    amount=min(DATABASE_CELL_CHUNK,max(0,meta['size']-position+1))
                    if not amount:break
                    def read(n):return lob.read(offset=position,amount=n)
                    try:part=read(amount)
                    except UnicodeDecodeError:part=read(amount+1)  # Do not split a UTF-16 surrogate pair.
                    if isinstance(part,str) and part and 0xD800<=ord(part[-1])<=0xDBFF:part=read(amount+1)
                adapter.check_cancel()
                if not part:
                    if position<=meta['size']:raise UserError('Nie ukończono odczytu LOB: strumień zakończył się przed końcem wartości.')
                    break
                if decoder is not None:
                    position+=len(part);yield decoder.decode(part,final=False).encode('utf-8');continue
                if isinstance(part,str):position+=len(part.encode('utf-16-le'))//2;data=part.encode('utf-8')
                else:position+=len(part);data=bytes(part)
                yield data
            if decoder is not None:
                tail=decoder.decode(b'',final=True)
                if tail:yield tail.encode('utf-8')
        with contextlib.closing(chunks()) as stream:yield meta,stream
    finally:
        if lob is not None and adapter.kind in ('h2','firebird'):
            if firebird_subtype is not None:lob.sub_type=firebird_subtype
            with contextlib.suppress(Exception):(lob.free if adapter.kind=='h2' else lob.close)()
        cur.close();adapter.active_cursor=None


def database_cell(adapter,args):
    with database_cell_stream(adapter,args) as (meta,chunks):
        data=bytearray();truncated=False
        for chunk in chunks:
            remaining=DATABASE_CELL_MAX_BYTES-len(data)
            data.extend(chunk[:remaining])
            if len(chunk)>remaining:truncated=True;break
        adapter.check_cancel();raw=bytes(data)
        encoding=meta['encoding'];format_='text';text='NULL' if meta['is_null'] else ''
        if not meta['is_null']:
            candidate='utf-16' if raw.startswith((b'\xff\xfe',b'\xfe\xff')) else 'utf-8-sig' if raw.startswith(b'\xef\xbb\xbf') else 'utf-8'
            try:
                import codecs
                text=codecs.getincrementaldecoder(candidate)('strict').decode(raw,final=not truncated)
                if encoding=='binary' and any(ord(c)<32 and c not in '\r\n\t' for c in text):raise UnicodeError()
                encoding=candidate
            except UnicodeError:text=raw.hex(' ');format_='hex';encoding='binary'
            if format_=='text' and not truncated:
                try:
                    # Classify only. A float round-trip would silently change
                    # financial JSON numbers and lexical forms such as 1e-400.
                    parsed=json.loads(text,parse_float=Decimal,parse_int=Decimal)
                    if isinstance(parsed,(dict,list)):format_='json'
                except (ValueError,RecursionError):pass
        return dict(meta,text=text,format=format_,encoding=encoding,truncated=truncated,preview_bytes=len(raw),limit_bytes=DATABASE_CELL_MAX_BYTES,read_at=utcnow(),
                    scope='Bieżąca wartość rekordu wskazanego kluczem; od czasu odczytu strony dane mogły się zmienić.')


def database_cell_export(adapter,args):
    destination=Path(args['destination']).expanduser().resolve()
    fd,temp=tempfile.mkstemp(prefix='.'+destination.name+'.',suffix='.tmp',dir=destination.parent);written=0
    try:
        with os.fdopen(fd,'wb') as output,database_cell_stream(adapter,args) as (meta,chunks):
            for chunk in chunks:adapter.check_cancel();output.write(chunk);written+=len(chunk)
            output.flush();os.fsync(output.fileno());adapter.check_cancel()
        adapter.check_cancel();os.replace(temp,destination)
        return {'destination':str(destination),'bytes':written,'encoding':meta['encoding'],'read_at':utcnow(),'scope':'BLOB zapisany bez zmian; tekst zapisany jako UTF-8. Wartość z bieżącego odczytu rekordu.'}
    finally:
        with contextlib.suppress(FileNotFoundError):Path(temp).unlink()


def database_page(adapter, args):
    """One bounded live page. Filters/sort run at source, not on an arbitrary sample.

    Page offsets are positions, not persistent row IDs. With concurrent writes,
    subsequent pages may change; a page is not advertised as an offline snapshot.
    """
    obj=args.get('object',{});cols=database_relation_meta(adapter,obj);names={c['name']:c for c in cols}
    offset=max(0,int(args.get('offset',0)))
    if offset>100000000:raise UserError('Zbyt odległa strona; zawęź dane filtrem.')
    limit=max(1,min(int(args.get('limit',DATABASE_PAGE_SIZE)),DATABASE_PAGE_SIZE,max(1,20000//len(cols))))
    params=[]
    def bind(value):params.append(value);return adapter.bind(len(params))
    clauses=[]
    for item in args.get('filters',[]):
        if len(clauses)>=16:raise UserError('Maksymalnie 16 filtrów przeglądu.')
        name=item.get('column');op=item.get('op','contains')
        if name not in names:raise UserError('Filtr wskazuje nieistniejącą kolumnę.')
        expr='ps_db.'+qident(name)
        if op in ('is_null','not_null'):clauses.append(expr+(' IS NULL' if op=='is_null' else ' IS NOT NULL'));continue
        raw=item.get('value','')
        if not isinstance(raw,(str,int,float)) or len(str(raw))>4096:raise UserError('Nieprawidłowa wartość filtra.')
        if op=='contains':
            # LIKE wildcards typed by user are literal, including the escape itself.
            text=str(raw).replace('!','!!').replace('%','!%').replace('_','!_')
            if adapter.kind=='oracle':expr='TO_CHAR('+expr+')'
            else:expr='CAST('+expr+(' AS TEXT)' if adapter.kind=='sqlite' else ' AS VARCHAR(8191))')
            clauses.append(expr+' LIKE '+bind('%'+text+'%')+" ESCAPE '!'")
        elif op in ('eq','ne','lt','gt','le','ge'):
            exact=database_exact_decimal(adapter,names[name])
            if item.get('numeric') or exact:
                try:raw=Decimal(str(raw))
                except decimal.InvalidOperation:raise UserError('Filtr liczbowy wymaga liczby.') from None
                if not raw.is_finite():raise UserError('Filtr wymaga skończonej liczby.')
                if adapter.kind=='sqlite':raw=str(raw)
            operator={'eq':' = ','ne':' <> ','lt':' < ','gt':' > ','le':' <= ','ge':' >= '}[op]
            param=bind(raw)
            clauses.append(f'ps_cmp({expr}, {param})'+operator+'0' if exact else expr+operator+param)
        else:raise UserError('Nieobsługiwany filtr przeglądu.')
    exprs=[];deferred_exprs=[]
    for col in cols:
        alias=qident(col['name']);name='ps_db.'+alias
        if adapter.kind=='sqlite':
            deferred_exprs.append(f"CASE WHEN typeof({name})='blob' OR (typeof({name})='text' AND (length({name})>{MAX_CELL_TEXT} OR length(CAST({name} AS BLOB))>{MAX_CELL_TEXT*4})) THEN 1 ELSE 0 END")
            # Avoid transferring large binary values in a general-purpose preview.
            name=(f"CASE WHEN typeof({name})='blob' THEN '[BLOB: '||length({name})||' bajtów]' "
                  f"WHEN typeof({name})='text' AND (length({name})>{MAX_CELL_TEXT} OR length(CAST({name} AS BLOB))>{MAX_CELL_TEXT*4}) THEN substr({name},1,{MAX_CELL_TEXT-40})||' … [tekst skrócony w podglądzie]' ELSE {name} END AS {alias}")
        exprs.append(name)
    identity=database_row_identity(adapter,obj,cols,'ps_db');identities=[identity] if identity else []
    exprs.extend(database_identity_expressions(adapter,identities))
    exprs.extend(deferred_exprs)
    dataset={'schema':obj.get('schema',''),'table':obj['name']}
    sql='SELECT '+', '.join(exprs)+' FROM '+adapter.relation(dataset)+' ps_db'
    if clauses:sql+=' WHERE '+' AND '.join(clauses)
    sort=args.get('sort','');direction='DESC' if args.get('direction')=='desc' else 'ASC'
    if sort and sort not in names:raise UserError('Kolumna sortowania zniknęła. Odśwież strukturę.')
    primary=[c['name'] for c in sorted(cols,key=lambda c:c['pk_position']) if c['pk_position']]
    # Database keys reported by catalog are accepted only if every member still exists.
    if not primary:
        pk=args.get('primary_key',[])
        if pk and all(isinstance(n,str) and n in names for n in pk):primary=list(pk)
    order=([database_order_expression(adapter,names[sort],'ps_db.'+qident(sort))+' '+direction] if sort else [])
    # Distinct text keys such as '1' and '1.0' tie numerically. Keep their
    # original key order as a final tie-break, also when sorting that same key.
    order+=['ps_db.'+qident(n)+' ASC' for n in primary if n!=sort or database_exact_decimal(adapter,names[n])]
    # Without a key, don't force a full sort (or try to sort a LOB column) just to open a table.
    if order:sql+=' ORDER BY '+', '.join(order)
    if adapter.kind in ('oracle','h2'):sql+=f' OFFSET {offset} ROWS FETCH NEXT {limit+1} ROWS ONLY'
    elif adapter.kind=='firebird':sql+=f' ROWS {offset+1} TO {offset+limit+1}'
    else:sql+=f' LIMIT {limit+1} OFFSET {offset}'
    cur=adapter.execute(sql,params)
    try:
        if adapter.kind=='firebird':cur.stream_blob_threshold=0
        if adapter.kind=='h2':cur.cell_preview=True;cur.identity_binary_columns=set(range(len(cols),len(cols)+sum(len(s['expressions']) for s in identities)))
        adapter.check_cancel();raw=cur.fetchmany(limit+1);adapter.check_cancel()
        identity_count=sum(len(s['expressions']) for s in identities);flag_start=len(cols)+identity_count
        values=[[database_preview_value(v,bool(row[flag_start+i]) if deferred_exprs else adapter.kind=='h2' and any(t in str(cols[i]['type']).upper() for t in ('BINARY','BLOB','CLOB','LARGE OBJECT'))) for i,v in enumerate(row[:len(cols)])] for row in raw[:limit]]
        tokens=[database_row_token(adapter,identities,row[len(cols):flag_start]) for row in raw[:limit]]
    finally:cur.close();adapter.active_cursor=None
    oid=database_object_id(obj.get('schema',''),obj.get('kind','table'),obj['name'])
    result={'object':obj,'columns':[dict(c,origin={'object_id':oid,'column':c['name']}) for c in cols],'rows':values,'row_tokens':tokens,'offset':offset,'limit':limit,'has_more':len(raw)>limit,
            'read_at':utcnow(),'sort':sort,'direction':args.get('direction','asc'),'filters':args.get('filters',[]),
            'stable_order':bool(primary),'scope':'Strona z żywej bazy. Numery to pozycje w widoku, nie identyfikatory rekordów.',
            'sql':sql,'parameters':[{ 'index':i+1,'value':str(v)} for i,v in enumerate(params)]}
    if len(dumps(result).encode('utf-8'))>12*1024*1024:raise UserError('Strona danych jest zbyt duża. Zmniejsz liczbę rekordów na stronę.')
    return result


def database_cell_text(cell):
    if cell is None:return 'NULL'
    if cell.get('t')=='b':return 'TRUE' if cell.get('v')=='true' else 'FALSE'
    return str(cell.get('v',''))


def database_graph_subset(catalog, query='', schema='', include_system=False, focus='', limit=120):
    """Deterministic bounded graph plan; full tree stays available, no guessed edges."""
    objects={o['id']:o for o in catalog.get('objects',[]) if o['kind'] in DATABASE_RELATIONS}
    ids=[k for k,o in objects.items() if (include_system or not o['system']) and (not schema or o['schema']==schema)
         and (not query or query.casefold() in (database_label(o)+' '+' '.join(c['name'] for c in o['columns'])).casefold())]
    if focus and focus in objects:
        neighbors={focus}
        for e in catalog.get('relations',[]):
            if focus in (e['source'],e['target']):neighbors.update((e['source'],e['target']))
        ids=[k for k in ids if k in neighbors]
    total=len(ids);ids=ids[:max(1,limit)];chosen=set(ids)
    edges=[e for e in catalog.get('relations',[]) if e['source'] in chosen and e['target'] in chosen]
    return {'objects':[objects[k] for k in ids],'relations':edges,'visible':len(ids),'total':total,
            'omitted':max(0,total-len(ids)),'unresolved':sum(not e['resolved'] for e in catalog.get('relations',[]))}


# ================= Relational views: explicit FK plans, no inferred joins =====
DATABASE_JOIN_VERSION = 1
DATABASE_JOIN_MAX_TABLES = 8
DATABASE_JOIN_MAX_COLUMNS = 200


class DatabaseJoinChoice(UserError):
    """A relationship choice is necessary, not an excuse to guess a join."""


def database_join_identifier(value):
    if not isinstance(value,str) or not value or len(value)>512 or any(ord(c)<32 for c in value):
        raise UserError('Nieprawidłowa nazwa obiektu lub pola w połączeniu.')
    return value


def database_join_object(raw):
    """Small serializable metadata contract. DDL, credentials and rows never belong here."""
    if not isinstance(raw,dict) or raw.get('kind') not in DATABASE_RELATIONS:
        raise UserError('Połączenie wymaga tabel lub widoków.')
    name=database_join_identifier(raw.get('name'));schema=raw.get('schema','')
    if schema:database_join_identifier(schema)
    if not isinstance(schema,str):raise UserError('Nieprawidłowy schemat połączenia.')
    oid=database_object_id(schema,raw['kind'],name)
    if raw.get('id',oid)!=oid:raise UserError('Identyfikator tabeli nie pasuje do jej nazwy.')
    columns=[];seen=set();raw_columns=raw.get('columns',[])
    if not isinstance(raw_columns,list) or not 1<=len(raw_columns)<=DATABASE_JOIN_MAX_COLUMNS:raise UserError('Nieprawidłowy katalog kolumn połączenia.')
    for c in raw_columns:
        if not isinstance(c,dict):raise UserError('Nieprawidłowa definicja kolumny.')
        if c.get('hidden'):continue
        n=database_join_identifier(c.get('name'))
        if n in seen:raise UserError('Powtórzona kolumna w metadanych połączenia.')
        seen.add(n);pk=c.get('pk_position',0)
        if type(pk) is not int or not 0<=pk<=DATABASE_JOIN_MAX_COLUMNS:raise UserError('Nieprawidłowa pozycja klucza.')
        columns.append({'name':n,'type':clean_text(c.get('type',''),200),'pk_position':pk,'nullable':bool(c.get('nullable',True))})
    if not columns or len(columns)>DATABASE_JOIN_MAX_COLUMNS:
        raise UserError('Połączenie wymaga pełnych metadanych; limit wynosi 200 kolumn wyniku.')
    return {'id':oid,'name':name,'schema':schema,'kind':raw['kind'],'columns':columns}


def database_join_edge(raw,objects):
    if not isinstance(raw,dict) or raw.get('declared') is not True or raw.get('resolved') is not True:
        raise UserError('Połączenie wymaga zadeklarowanego klucza obcego z odczytanymi kolumnami.')
    source,target=raw.get('source'),raw.get('target')
    if not isinstance(source,str) or not isinstance(target,str):raise UserError('Nieprawidłowe końce relacji.')
    if source not in objects or target not in objects:raise UserError('Relacja wskazuje tabelę spoza zaznaczenia.')
    if source==target:raise DatabaseJoinChoice('Połączenie tabeli z samą sobą wymaga dwóch ról/aliasów; zaznaczenie jednego węzła otwiera jego dane.')
    left,right=raw.get('source_columns'),raw.get('target_columns')
    if not isinstance(left,list) or not isinstance(right,list) or not left or len(left)!=len(right) or len(left)>64:
        raise UserError('Niepełny klucz wielokolumnowy. Odśwież strukturę.')
    if any(not isinstance(n,str) for n in left+right):raise UserError('Nieprawidłowe kolumny klucza.')
    if len(set(left))!=len(left) or len(set(right))!=len(right):raise UserError('Powtórzone kolumny klucza.')
    for names,oid in ((left,source),(right,target)):
        known={c['name'] for c in objects[oid]['columns']}
        if any(not isinstance(n,str) or n not in known for n in names):raise UserError('Kolumna relacji zniknęła ze struktury.')
    name=database_join_identifier(raw.get('name'))
    eid=digest([source,name,left])[:32]
    if raw.get('id')!=eid:raise UserError('Identyfikator relacji nie pasuje do jej definicji.')
    return {'id':eid,'name':name,'source':source,'target':target,'source_columns':list(left),'target_columns':list(right),
            'declared':True,'resolved':True}


def database_join_order(objects,edges,base):
    """Exactly one connected tree. No implicit bridge or ignored cycle predicate."""
    if base not in objects:raise UserError('Tabela podstawowa nie należy do połączenia.')
    if len(edges)!=len(objects)-1:
        raise DatabaseJoinChoice('Wybierz dokładnie jedną drogę łączącą tabele (bez cyklu). Każdy wybrany klucz jest używany w całości.')
    remaining={e['id']:e for e in edges};seen={base};steps=[]
    while remaining:
        candidates=[e for e in remaining.values() if (e['source'] in seen)!=(e['target'] in seen)]
        if not candidates:raise DatabaseJoinChoice('Zaznaczone tabele nie tworzą spójnego połączenia. Zaznacz potrzebną tabelę pośrednią; program nie wykonuje CROSS JOIN.')
        edge=min(candidates,key=lambda e:(database_label(objects[e['source']]),database_label(objects[e['target']]),e['id']))
        old=edge['source'] if edge['source'] in seen else edge['target'];new=edge['target'] if old==edge['source'] else edge['source']
        steps.append({'relation':edge['id'],'existing':old,'added':new,'may_expand':old==edge['target']})
        seen.add(new);remaining.pop(edge['id'])
    if seen!=set(objects):raise DatabaseJoinChoice('Brak wspólnej drogi relacji. Zaznacz także tabelę pośrednią.')
    return steps


def database_join_validate(raw):
    """Untrusted project/callback values are validated before building any SQL."""
    if not isinstance(raw,dict) or raw.get('version')!=DATABASE_JOIN_VERSION:raise UserError('Nieobsługiwana definicja połączenia tabel.')
    if raw.get('backend') not in ('sqlite','h2','firebird','oracle'):raise UserError('Nieznany silnik połączenia.')
    source_id=database_join_identifier(raw.get('source_id'))
    records=raw.get('objects')
    if not isinstance(records,list) or not 2<=len(records)<=DATABASE_JOIN_MAX_TABLES:raise UserError('Zaznacz od 2 do 8 powiązanych tabel.')
    objects={}
    for record in records:
        obj=database_join_object(record)
        if obj['id'] in objects:raise UserError('Ta sama tabela występuje dwukrotnie. Role self-join nie są jeszcze obsługiwane.')
        if raw['backend']=='sqlite' and obj['schema']!='main':raise UserError('SQLite: połączenie obejmuje wyłącznie main otwartego pliku.')
        objects[obj['id']]=obj
    if sum(len(o['columns']) for o in objects.values())>DATABASE_JOIN_MAX_COLUMNS:
        raise UserError('Wspólny wynik przekroczyłby 200 kolumn. Wybierz mniej tabel lub użyj własnego SQL z wyborem kolumn.')
    raw_edges=raw.get('relations')
    if not isinstance(raw_edges,list) or len(raw_edges)>DATABASE_JOIN_MAX_TABLES-1:raise UserError('Nieprawidłowy zestaw relacji.')
    edges=[database_join_edge(e,objects) for e in raw_edges]
    if len({e['id'] for e in edges})!=len(edges):raise UserError('Powtórzona relacja.')
    mode=raw.get('join_type','left')
    if mode not in ('left','inner'):raise UserError('Obsługiwane połączenia: wszystkie rekordy podstawy (LEFT) lub tylko dopasowane (INNER).')
    base=raw.get('base');steps=database_join_order(objects,edges,base)
    ordered=[base]+[s['added'] for s in steps]
    by_id={e['id']:e for e in edges}
    return {'version':DATABASE_JOIN_VERSION,'source_id':source_id,'backend':raw['backend'],'base':base,'join_type':mode,
        'objects':[objects[oid] for oid in ordered],'relations':[by_id[s['relation']] for s in steps]}


def database_join_plan(catalog,selected_ids,base=None,relation_ids=None,join_type='left'):
    if not isinstance(selected_ids,(list,tuple)) or any(not isinstance(k,str) for k in selected_ids):raise UserError('Nieprawidłowe zaznaczenie tabel.')
    ids=list(dict.fromkeys(selected_ids));lookup={o['id']:o for o in catalog.get('objects',[]) if o['kind'] in DATABASE_RELATIONS}
    if not 2<=len(ids)<=DATABASE_JOIN_MAX_TABLES:raise UserError('Wybierz od 2 do 8 tabel. Jedną tabelę otwierasz bez łączenia.')
    if any(k not in lookup for k in ids):raise UserError('Zaznaczenie nie występuje w aktualnym katalogu.')
    chosen=set(ids)
    edges=[e for e in catalog.get('relations',[]) if e['source'] in chosen and e['target'] in chosen and e['source']!=e['target']]
    if relation_ids is not None:
        if not isinstance(relation_ids,(list,tuple)) or len(set(relation_ids))!=len(relation_ids):raise UserError('Nieprawidłowy wybór relacji.')
        by_id={e['id']:e for e in edges}
        if any(k not in by_id for k in relation_ids):raise UserError('Wybrany klucz nie łączy zaznaczonych tabel.')
        edges=[by_id[k] for k in relation_ids]
    if any(not e.get('declared') or not e.get('resolved') for e in edges):
        raise DatabaseJoinChoice('Nie wszystkie kolumny relacji są dostępne. Odśwież strukturę i sprawdź uprawnienia; nie zgaduję kluczy.')
    if base is None:
        # A child->parent chain has one leaf-grain root. Stable, independent of
        # selection order, object positions and keyboard focus.
        parents={e['target'] for e in edges};roots=chosen-parents
        base=min(roots or chosen,key=lambda k:(database_label(lookup[k]).casefold(),k))
    return database_join_validate({'version':DATABASE_JOIN_VERSION,'source_id':catalog['source_id'],'backend':catalog['backend'],
        'objects':[lookup[k] for k in ids],'relations':edges,'base':base,'join_type':join_type})


def database_join_caption(plan):
    return ' + '.join(o['name'] for o in plan['objects'])


def database_join_description(plan):
    base=next(o['name'] for o in plan['objects'] if o['id']==plan['base'])
    text='Podstawa: '+base+' · '+('wszystkie rekordy podstawy (LEFT)' if plan['join_type']=='left' else 'tylko dopasowane (INNER)')
    return text


def database_join_warning(plan):
    objects={o['id']:o for o in plan['objects']}
    steps=database_join_order(objects,plan['relations'],plan['base'])
    if any(s['may_expand'] for s in steps):
        return 'Połączenie może zwielokrotnić wiersze podstawy (1:N). Nie sumuj powtórzonych wartości bez ustalenia poziomu miary.'
    return 'Wynik ma poziom rekordów podstawy, o ile klucze docelowe są unikalne. Wartości tabel nadrzędnych mogą się powtarzać; pivot nie jest modelem wielotabelowym Excela.'


def database_join_alias(label,used):
    """Portable identifiers <= 30 UTF-8 bytes, including older Oracle configurations."""
    alias=label
    if len(alias.encode('utf-8'))>30:alias=alias.encode('utf-8')[:20].decode('utf-8','ignore')+'_'+digest(label)[:9]
    if alias in used:alias='pole_'+digest([label,len(used)])[:24]
    used.add(alias);return alias


def database_join_compile(plan,adapter,preview=False,extra_expressions=()):
    plan=database_join_validate(plan)
    if adapter.kind!=plan['backend'] or adapter.source['id']!=plan['source_id']:raise UserError('Plan należy do innego połączenia lub silnika.')
    objects={o['id']:o for o in plan['objects']};aliases={o['id']:'ps_j'+str(i) for i,o in enumerate(plan['objects'])}
    duplicate_names=collections.Counter(o['name'] for o in plan['objects']);used=set();columns=[];expressions=[]
    for obj in plan['objects']:
        prefix=database_label(obj) if duplicate_names[obj['name']]>1 else obj['name']
        for c in obj['columns']:
            label=prefix+' · '+c['name'];alias=database_join_alias(label,used);expr=aliases[obj['id']]+'.'+qident(c['name']);value=expr
            if preview and adapter.kind=='sqlite':
                value=(f"CASE WHEN typeof({expr})='blob' THEN '[BLOB: '||length({expr})||' bajtów]' "
                    f"WHEN typeof({expr})='text' AND (length({expr})>{MAX_CELL_TEXT} OR length(CAST({expr} AS BLOB))>{MAX_CELL_TEXT*4}) THEN substr({expr},1,{MAX_CELL_TEXT-40})||' … [tekst skrócony w podglądzie]' ELSE {expr} END")
            expressions.append(value+' AS '+qident(alias))
            columns.append({'name':alias,'label':label,'type':c['type'],'pk_position':0,'origin':{'object_id':obj['id'],'column':c['name']},'expression':expr})
    root=objects[plan['base']]
    clause=' FROM '+adapter.relation({'schema':root['schema'],'table':root['name']})+' '+aliases[root['id']]
    by_id={e['id']:e for e in plan['relations']}
    for step in database_join_order(objects,plan['relations'],plan['base']):
        edge=by_id[step['relation']];added=objects[step['added']]
        # Referenced (parent) key is on the left: important for SQLite text
        # collations when the child's column declares a different collation.
        pairs=[aliases[edge['target']]+'.'+qident(t)+' = '+('+' if adapter.kind=='sqlite' else '')+aliases[edge['source']]+'.'+qident(s)
               for s,t in zip(edge['source_columns'],edge['target_columns'])]
        clause+=(' LEFT JOIN ' if plan['join_type']=='left' else ' INNER JOIN ')+adapter.relation({'schema':added['schema'],'table':added['name']})+' '+aliases[added['id']]+' ON '+' AND '.join(pairs)
    return {'sql':'SELECT '+', '.join([*expressions,*extra_expressions])+clause,'columns':columns,'aliases':aliases,'plan':plan}


def database_live_foreign_keys(adapter,obj):
    """Targeted live FK metadata, not a full catalogue scan for every data page."""
    a=adapter;sc=obj['schema'];name=obj['name'];rows=[]
    if a.kind=='sqlite':
        a.conn.set_authorizer(sqlite_metadata_authorizer)
        try:raw=a.fetch("PRAGMA main.foreign_key_list('"+name.replace("'","''")+"')",limit=DATABASE_MAX_ITEMS)
        finally:a.conn.set_authorizer(sqlite_authorizer)
        for key,pos,target,source_col,target_col,*rest in raw:
            rows.append(('FK '+str(key+1),int(pos),'main',target,source_col,target_col))
    elif a.kind=='oracle':
        sql=('SELECT f.CONSTRAINT_NAME,s.POSITION,p.OWNER,p.TABLE_NAME,s.COLUMN_NAME,t.COLUMN_NAME '
             'FROM ALL_CONSTRAINTS f JOIN ALL_CONS_COLUMNS s ON s.OWNER=f.OWNER AND s.CONSTRAINT_NAME=f.CONSTRAINT_NAME '
             'JOIN ALL_CONSTRAINTS p ON p.OWNER=f.R_OWNER AND p.CONSTRAINT_NAME=f.R_CONSTRAINT_NAME '
             'JOIN ALL_CONS_COLUMNS t ON t.OWNER=p.OWNER AND t.CONSTRAINT_NAME=p.CONSTRAINT_NAME AND t.POSITION=s.POSITION '
             "WHERE f.CONSTRAINT_TYPE='R' AND f.OWNER=:p1 AND f.TABLE_NAME=:p2 ORDER BY f.CONSTRAINT_NAME,s.POSITION")
        rows=a.fetch(sql,[sc,name],DATABASE_MAX_ITEMS)
    elif a.kind=='h2':
        sql=('SELECT f.CONSTRAINT_NAME,s.ORDINAL_POSITION,p.TABLE_SCHEMA,p.TABLE_NAME,s.COLUMN_NAME,t.COLUMN_NAME '
             'FROM INFORMATION_SCHEMA.TABLE_CONSTRAINTS f '
             'JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE s ON s.CONSTRAINT_SCHEMA=f.CONSTRAINT_SCHEMA AND s.CONSTRAINT_NAME=f.CONSTRAINT_NAME '
             'JOIN INFORMATION_SCHEMA.REFERENTIAL_CONSTRAINTS r ON r.CONSTRAINT_SCHEMA=f.CONSTRAINT_SCHEMA AND r.CONSTRAINT_NAME=f.CONSTRAINT_NAME '
             'JOIN INFORMATION_SCHEMA.TABLE_CONSTRAINTS p ON p.CONSTRAINT_SCHEMA=r.UNIQUE_CONSTRAINT_SCHEMA AND p.CONSTRAINT_NAME=r.UNIQUE_CONSTRAINT_NAME '
             'JOIN INFORMATION_SCHEMA.KEY_COLUMN_USAGE t ON t.CONSTRAINT_SCHEMA=p.CONSTRAINT_SCHEMA AND t.CONSTRAINT_NAME=p.CONSTRAINT_NAME AND t.ORDINAL_POSITION=s.POSITION_IN_UNIQUE_CONSTRAINT '
             'WHERE f.TABLE_SCHEMA=? AND f.TABLE_NAME=? ORDER BY f.CONSTRAINT_NAME,s.ORDINAL_POSITION')
        rows=a.fetch(sql,[sc,name],DATABASE_MAX_ITEMS)
    elif a.kind=='firebird':
        sql=('SELECT TRIM(f.RDB$CONSTRAINT_NAME),s.RDB$FIELD_POSITION,TRIM(p.RDB$RELATION_NAME),TRIM(s.RDB$FIELD_NAME),TRIM(t.RDB$FIELD_NAME) '
             'FROM RDB$RELATION_CONSTRAINTS f JOIN RDB$REF_CONSTRAINTS r ON r.RDB$CONSTRAINT_NAME=f.RDB$CONSTRAINT_NAME '
             'JOIN RDB$RELATION_CONSTRAINTS p ON p.RDB$CONSTRAINT_NAME=r.RDB$CONST_NAME_UQ '
             'JOIN RDB$INDEX_SEGMENTS s ON s.RDB$INDEX_NAME=f.RDB$INDEX_NAME '
             'JOIN RDB$INDEX_SEGMENTS t ON t.RDB$INDEX_NAME=p.RDB$INDEX_NAME AND t.RDB$FIELD_POSITION=s.RDB$FIELD_POSITION '
             "WHERE f.RDB$CONSTRAINT_TYPE='FOREIGN KEY' AND f.RDB$RELATION_NAME=? ORDER BY f.RDB$CONSTRAINT_NAME,s.RDB$FIELD_POSITION")
        rows=[(n,p,'',tn,s,t) for n,p,tn,s,t in a.fetch(sql,[name],DATABASE_MAX_ITEMS)]
    grouped=collections.defaultdict(list)
    for n,pos,ts,tn,s,t in rows:grouped[str(n)].append((int(pos),str(ts or ''),str(tn),str(s),str(t) if t is not None else None))
    out=[]
    for name,records in grouped.items():
        records.sort();out.append({'name':name,'target_schema':records[0][1],'target_table':records[0][2],
            'source_columns':[r[3] for r in records],'target_columns':[r[4] for r in records]})
    return out


def database_join_verify(adapter,plan):
    """Verify all selected columns and used FKs on the same connection as the SELECT."""
    plan=database_join_validate(plan);live={};objects={o['id']:o for o in plan['objects']}
    for obj in plan['objects']:
        adapter.check_cancel();cols=database_relation_meta(adapter,obj);live[obj['id']]=cols
        if [c['name'] for c in cols]!=[c['name'] for c in obj['columns']]:
            raise UserError('Struktura tabeli '+database_label(obj)+' zmieniła się. Odśwież mapę i ponownie wybierz połączenie.')
        # Remote inspectors present types more richly than the low-level reader;
        # compare exact SQLite types, while all engines revalidate FK membership.
        if adapter.kind=='sqlite' and [(c['type'],c['pk_position']) for c in cols]!=[(c['type'],c['pk_position']) for c in obj['columns']]:
            raise UserError('Zmieniono typy lub klucz tabeli '+database_label(obj)+'. Odśwież strukturę.')
    normalize=(lambda s:str(s).translate(str.maketrans('ABCDEFGHIJKLMNOPQRSTUVWXYZ','abcdefghijklmnopqrstuvwxyz'))) if adapter.kind=='sqlite' else str
    cache={}
    for edge in plan['relations']:
        source,target=objects[edge['source']],objects[edge['target']]
        if source['id'] not in cache:cache[source['id']]=database_live_foreign_keys(adapter,source)
        matches=[]
        for fk in cache[source['id']]:
            if normalize(fk['target_schema'])!=normalize(target['schema']) or normalize(fk['target_table'])!=normalize(target['name']):continue
            targets=fk['target_columns']
            if targets and all(x is None for x in targets):
                targets=[c['name'] for c in sorted(live[target['id']],key=lambda c:c['pk_position']) if c['pk_position']]
            if (list(map(normalize,fk['source_columns']))==list(map(normalize,edge['source_columns'])) and
                list(map(normalize,targets))==list(map(normalize,edge['target_columns']))):matches.append(fk)
        if not matches:raise UserError('Klucz '+edge['name']+' nie ma już tej samej definicji. Odczyt połączenia zatrzymano; odśwież mapę.')
    return live


def database_join_filters(adapter,columns,filters):
    mapping={c['name']:c for c in columns};clauses=[];params=[]
    if not isinstance(filters,list) or len(filters)>16:raise UserError('Maksymalnie 16 filtrów połączenia.')
    def bind(v):params.append(v);return adapter.bind(len(params))
    for item in filters:
        if not isinstance(item,dict) or item.get('column') not in mapping:raise UserError('Filtr wskazuje nieznane pole połączenia.')
        column=mapping[item['column']];expr=column['expression'];op=item.get('op','contains')
        if op in ('is_null','not_null'):clauses.append(expr+(' IS NULL' if op=='is_null' else ' IS NOT NULL'));continue
        value=item.get('value','')
        if not isinstance(value,(str,int,float)) or isinstance(value,bool) or len(str(value))>4096:raise UserError('Nieprawidłowa wartość filtra.')
        if op=='contains':
            value=str(value).replace('!','!!').replace('%','!%').replace('_','!_')
            expr='TO_CHAR('+expr+')' if adapter.kind=='oracle' else 'CAST('+expr+(' AS TEXT)' if adapter.kind=='sqlite' else ' AS VARCHAR(8191))')
            clauses.append(expr+' LIKE '+bind('%'+value+'%')+" ESCAPE '!'")
        elif op in ('eq','ne','lt','gt','le','ge'):
            exact=database_exact_decimal(adapter,column)
            if item.get('numeric') or exact:
                try:value=Decimal(str(value))
                except decimal.InvalidOperation:raise UserError('Filtr liczbowy wymaga liczby.') from None
                if not value.is_finite():raise UserError('Filtr wymaga skończonej liczby.')
                if adapter.kind=='sqlite':value=str(value)
            operator={'eq':' = ','ne':' <> ','lt':' < ','gt':' > ','le':' <= ','ge':' >= '}[op]
            param=bind(value)
            clauses.append(f'ps_cmp({expr}, {param})'+operator+'0' if exact else expr+operator+param)
        else:raise UserError('Nieobsługiwany filtr połączenia.')
    return (' WHERE '+' AND '.join('('+x+')' for x in clauses) if clauses else ''),params


def database_join_page(adapter,args):
    plan=database_join_validate(args.get('plan'))
    if adapter.kind!=plan['backend'] or adapter.source['id']!=plan['source_id']:raise UserError('Plan należy do innego źródła lub silnika.')
    live=database_join_verify(adapter,plan)
    identities=[]
    for i,obj in enumerate(plan['objects']):
        spec=database_row_identity(adapter,obj,live[obj['id']],'ps_j'+str(i))
        if spec:identities.append(spec)
    hidden=database_identity_expressions(adapter,identities)
    compiled=database_join_compile(plan,adapter,preview=True);columns=compiled['columns'];flags=[]
    if adapter.kind=='sqlite':
        for c in columns:
            expr=c['expression'];flags.append(f"CASE WHEN typeof({expr})='blob' OR (typeof({expr})='text' AND (length({expr})>{MAX_CELL_TEXT} OR length(CAST({expr} AS BLOB))>{MAX_CELL_TEXT*4})) THEN 1 ELSE 0 END")
    compiled=database_join_compile(plan,adapter,preview=True,extra_expressions=[*hidden,*flags]);sql=compiled['sql']
    where,params=database_join_filters(adapter,columns,args.get('filters',[]));sql+=where
    offset=max(0,int(args.get('offset',0)))
    if offset>100000000:raise UserError('Zbyt odległa strona; zawęź wynik filtrem.')
    limit=max(1,min(int(args.get('limit',DATABASE_PAGE_SIZE)),DATABASE_PAGE_SIZE,max(1,20000//len(columns))))
    names={c['name']:c for c in columns};sort=args.get('sort','');direction='DESC' if args.get('direction')=='desc' else 'ASC'
    if sort and sort not in names:raise UserError('Nieprawidłowe pole sortowania.')
    order=[database_order_expression(adapter,names[sort],names[sort]['expression'])+' '+direction] if sort else [];keys=[];stable=adapter.kind=='sqlite'
    for obj in plan['objects']:
        pk=[c['name'] for c in sorted(live[obj['id']],key=lambda c:c['pk_position']) if c['pk_position']]
        stable=stable and bool(pk) and all(not c['nullable'] for c in obj['columns'] if c['pk_position'])
        for name in pk:
            expr=compiled['aliases'][obj['id']]+'.'+qident(name)
            column=next(c for c in live[obj['id']] if c['name']==name)
            if not sort or expr!=names[sort]['expression'] or database_exact_decimal(adapter,column):keys.append(expr+' ASC')
    if order or keys:sql+=' ORDER BY '+', '.join(order+keys)
    if adapter.kind in ('oracle','h2'):sql+=f' OFFSET {offset} ROWS FETCH NEXT {limit+1} ROWS ONLY'
    elif adapter.kind=='firebird':sql+=f' ROWS {offset+1} TO {offset+limit+1}'
    else:sql+=f' LIMIT {limit+1} OFFSET {offset}'
    adapter.check_cancel();cur=adapter.execute(sql,params)
    try:
        if adapter.kind=='firebird':cur.stream_blob_threshold=0
        if adapter.kind=='h2':cur.cell_preview=True;cur.identity_binary_columns=set(range(len(columns),len(columns)+len(hidden)))
        raw=cur.fetchmany(limit+1);adapter.check_cancel()
        flag_start=len(columns)+len(hidden)
        rows=[[database_preview_value(v,bool(row[flag_start+i]) if flags else adapter.kind=='h2' and any(t in str(columns[i]['type']).upper() for t in ('BINARY','BLOB','CLOB','LARGE OBJECT'))) for i,v in enumerate(row[:len(columns)])] for row in raw[:limit]]
        tokens=[database_row_token(adapter,identities,row[len(columns):flag_start]) for row in raw[:limit]]
    finally:cur.close();adapter.active_cursor=None
    result={'object':{'id':'join-'+digest(plan)[:24],'name':database_join_caption(plan),'kind':'join','schema':''},
        'columns':[{k:v for k,v in c.items() if k!='expression'} for c in columns],'rows':rows,'row_tokens':tokens,
        'offset':offset,'limit':limit,'has_more':len(raw)>limit,'stable_order':stable,'read_at':utcnow(),
        'scope':'Połączone rekordy z żywej bazy; kolejne strony mogą się zmieniać przy równoległym zapisie. Filtry działają po JOIN (WHERE).',
        'plan':plan,'plan_fingerprint':digest(plan),'sql':sql,'parameters':[{'index':i+1,'value':str(v)} for i,v in enumerate(params)],
        'warning':database_join_warning(plan),'sort':sort,'direction':args.get('direction','asc'),'filters':args.get('filters',[])}
    if len(dumps(result).encode('utf-8'))>12*1024*1024:raise UserError('Strona jest zbyt duża. Zawęź połączenie lub liczbę rekordów.')
    return result


def database_saved_join(raw):
    if not isinstance(raw,dict):raise UserError('Nieprawidłowy zapis połączonego widoku.')
    plan=database_join_validate(raw.get('plan'));sid=clean_text(raw.get('id') or uid(),64)
    name=clean_text(raw.get('name') or database_join_caption(plan),100)
    # No rendered SQL or data is trusted/restored as executable source.
    return {'id':sid,'name':name,'plan':plan}


def database_graph_layout(objects,relations,sizes,available_width=1200,compact=False):
    """Deterministic component-first layout using real node dimensions.

    Linked nodes sit in adjacent breadth-first layers. Disconnected components
    pack into shelves; no scene-wide shrink is needed to read the labels.
    The UI may preserve user positions instead of applying this suggestion.
    """
    lookup={o['id']:o for o in objects};neighbors={k:set() for k in lookup};incoming=collections.Counter()
    for edge in relations:
        s,t=edge['source'],edge['target']
        if s in lookup and t in lookup and s!=t:neighbors[s].add(t);neighbors[t].add(s);incoming[t]+=1
    key=lambda k:(database_label(lookup[k]).casefold(),k)
    todo=set(lookup);components=[]
    while todo:
        first=min(todo,key=key);found={first};q=collections.deque([first]);todo.remove(first)
        while q:
            for other in sorted(neighbors[q.popleft()] & todo,key=key):todo.remove(other);found.add(other);q.append(other)
        components.append(found)
    components.sort(key=lambda c:(-len(c),min(key(k) for k in c)))
    if compact:
        ordered=[]
        for component in components:
            remaining=set(component);root=min(component,key=lambda k:(-len(neighbors[k]),key(k)));q=collections.deque([root]);remaining.remove(root)
            while q:
                oid=q.popleft();ordered.append(oid)
                for other in sorted(neighbors[oid]&remaining,key=key):remaining.remove(other);q.append(other)
        width=max(240,float(available_width));cell_width=max((sizes[k][0] for k in ordered),default=230);columns=max(1,int((width-24+18)//(cell_width+18)))
        # Use the current canvas width, keeping neighbouring BFS nodes close
        # at row boundaries. A partial final row does not stretch two relatives
        # to opposite ends of a wide monitor.
        step=(width-24-cell_width)/(columns-1) if columns>1 else cell_width+18
        result={};y=12
        for offset in range(0,len(ordered),columns):
            row=ordered[offset:offset+columns]
            for column,oid in enumerate(row):
                slot=columns-1-column if (offset//columns)%2 else column
                result[oid]=(12+slot*step,y)
            y+=max(sizes[oid][1] for oid in row)+24
        return result
    blocks=[]
    for component in components:
        roots=[k for k in component if not incoming[k]]
        root=min(roots or component,key=lambda k:(-len(neighbors[k]),key(k)))
        levels={root:0};q=collections.deque([root])
        while q:
            parent=q.popleft()
            for child in sorted(neighbors[parent],key=key):
                if child not in levels:levels[child]=levels[parent]+1;q.append(child)
        cols=collections.defaultdict(list)
        for k in component:cols[levels.get(k,0)].append(k)
        positions={};x=0;maxh=0
        for level,items in sorted(cols.items()):
            y=0;w=max(sizes[k][0] for k in items)
            for k in sorted(items,key=key):positions[k]=(x,y);y+=sizes[k][1]+30
            maxh=max(maxh,y-30);x+=w+92
        blocks.append((positions,max(0,x-92),maxh))
    margin=12 if compact else 24;gap=18 if compact else 36
    x=y=margin;shelf=0;result={};width=max(240 if compact else 660,float(available_width)-(margin if compact else 48))
    for positions,w,h in blocks:
        if x>margin and x+w>width:x=margin;y+=shelf+(24 if compact else 40);shelf=0
        for k,(px,py) in positions.items():result[k]=(x+px,y+py)
        x+=w+gap;shelf=max(shelf,h)
    return result


