def excel_availability():
    """Discovery only: never start Office, read VBA, or change macro policy."""
    if os.name!='nt':return {'available':False,'reason':'Sesja Excel wymaga Windows i zainstalowanego Microsoft Excel.'}
    import winreg
    for view in (winreg.KEY_WOW64_64KEY,winreg.KEY_WOW64_32KEY):
        try:
            with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT,r'Excel.Application\CLSID',0,winreg.KEY_READ|view) as key:clsid=winreg.QueryValue(key,None)
            with winreg.OpenKey(winreg.HKEY_CLASSES_ROOT,'CLSID\\'+clsid+r'\LocalServer32',0,winreg.KEY_READ|view) as key:server=winreg.QueryValue(key,None)
            if server:
                dependency=dependency_status('excel')
                if dependency['state']!='ready':
                    return {'available':False,'reason':dependency['title']+' '+dependency['message'],'dependency':dependency}
                return {'available':True,'reason':'Microsoft Excel jest zarejestrowany. Sesja użyje oddzielnej kopii pliku.'}
        except OSError:continue
    return {'available':False,'reason':'Nie znaleziono Microsoft Excel. Podgląd XLSX/XLSM nadal działa; wykonanie makr i wydruk przez Excel wymagają jego instalacji.'}


def excel_process_ids():
    if os.name!='nt':return set()
    import ctypes
    from ctypes import wintypes as w
    class Entry(ctypes.Structure):
        _fields_=[('dwSize',w.DWORD),('cntUsage',w.DWORD),('th32ProcessID',w.DWORD),('th32DefaultHeapID',ctypes.c_size_t),('th32ModuleID',w.DWORD),('cntThreads',w.DWORD),('th32ParentProcessID',w.DWORD),('pcPriClassBase',w.LONG),('dwFlags',w.DWORD),('szExeFile',w.WCHAR*260)]
    kernel=ctypes.WinDLL('kernel32',use_last_error=True)
    kernel.CreateToolhelp32Snapshot.argtypes=[w.DWORD,w.DWORD];kernel.CreateToolhelp32Snapshot.restype=w.HANDLE
    kernel.Process32FirstW.argtypes=[w.HANDLE,ctypes.POINTER(Entry)];kernel.Process32FirstW.restype=w.BOOL
    kernel.Process32NextW.argtypes=[w.HANDLE,ctypes.POINTER(Entry)];kernel.Process32NextW.restype=w.BOOL
    kernel.CloseHandle.argtypes=[w.HANDLE];kernel.CloseHandle.restype=w.BOOL
    handle=kernel.CreateToolhelp32Snapshot(2,0)
    if handle==ctypes.c_void_p(-1).value:raise UserError('Nie udało się sprawdzić istniejących procesów Excel.')
    found=set();entry=Entry();entry.dwSize=ctypes.sizeof(entry)
    try:
        ok=kernel.Process32FirstW(handle,ctypes.byref(entry))
        while ok:
            if entry.szExeFile.casefold()=='excel.exe':found.add(int(entry.th32ProcessID))
            ok=kernel.Process32NextW(handle,ctypes.byref(entry))
        return found
    finally:kernel.CloseHandle(handle)


class ExcelOwnedProcess:
    """Keep an OS handle, so a recycled PID can never become a kill target."""
    def __init__(self,pid,hwnd,previous):
        if os.name!='nt' or type(pid) is not int or type(hwnd) is not int or pid<=0 or hwnd<=0 or pid in previous:raise UserError('Nie potwierdzono oddzielnego procesu Excel. Istniejące okna pozostają nietknięte.')
        import ctypes
        from ctypes import wintypes as w
        self.ctypes=ctypes;self.kernel=ctypes.WinDLL('kernel32',use_last_error=True);self.handle=None;self.pid=pid;self.hwnd=hwnd;self.handle_lock=threading.RLock()
        user=ctypes.WinDLL('user32',use_last_error=True);user.GetWindowThreadProcessId.argtypes=[w.HWND,ctypes.POINTER(w.DWORD)];user.GetWindowThreadProcessId.restype=w.DWORD
        actual=w.DWORD();user.GetWindowThreadProcessId(hwnd,ctypes.byref(actual))
        if actual.value!=pid:raise UserError('Okno nie należy do nowego procesu Excel.')
        k=self.kernel;k.OpenProcess.argtypes=[w.DWORD,w.BOOL,w.DWORD];k.OpenProcess.restype=w.HANDLE
        k.CloseHandle.argtypes=[w.HANDLE];k.CloseHandle.restype=w.BOOL
        k.QueryFullProcessImageNameW.argtypes=[w.HANDLE,w.DWORD,w.LPWSTR,ctypes.POINTER(w.DWORD)];k.QueryFullProcessImageNameW.restype=w.BOOL
        k.WaitForSingleObject.argtypes=[w.HANDLE,w.DWORD];k.WaitForSingleObject.restype=w.DWORD
        k.TerminateProcess.argtypes=[w.HANDLE,w.UINT];k.TerminateProcess.restype=w.BOOL
        self.handle=k.OpenProcess(0x1000|0x100000|1,False,pid)
        if not self.handle:raise UserError('Nie uzyskano uchwytu własnej sesji Excel.')
        name=ctypes.create_unicode_buffer(32768);length=w.DWORD(len(name))
        if not k.QueryFullProcessImageNameW(self.handle,0,name,ctypes.byref(length)) or Path(name.value).name.casefold()!='excel.exe':
            self.close();raise UserError('Nowy proces nie jest Microsoft Excel.')
    def alive(self):
        with self.handle_lock:return bool(self.handle and self.kernel.WaitForSingleObject(self.handle,0)==258)
    def terminate(self):
        with self.handle_lock:
            if self.alive():self.kernel.TerminateProcess(self.handle,130)
    def close(self):
        with self.handle_lock:
            if self.handle:self.kernel.CloseHandle(self.handle);self.handle=None


def excel_copy_workbook(source,destination,cancelled,cancel_flag=None):
    """Windows copy preserves Zone.Identifier and other NTFS streams."""
    if cancelled.is_set():raise Cancelled('Anulowano otwieranie skoroszytu.')
    if os.name=='nt':
        import ctypes
        from ctypes import wintypes as w
        flag=cancel_flag if cancel_flag is not None else w.BOOL(False);kernel=ctypes.WinDLL('kernel32',use_last_error=True)
        kernel.CopyFileExW.argtypes=[w.LPCWSTR,w.LPCWSTR,ctypes.c_void_p,ctypes.c_void_p,ctypes.POINTER(w.BOOL),w.DWORD];kernel.CopyFileExW.restype=w.BOOL
        if not kernel.CopyFileExW(str(source),str(destination),None,None,ctypes.byref(flag),1):
            if cancelled.is_set() or flag.value:raise Cancelled('Anulowano kopiowanie skoroszytu.')
            raise ctypes.WinError(ctypes.get_last_error())
    else:shutil.copy2(source,destination)  # Test transport on other platforms only.
    os.chmod(destination,0o600)  # The private working copy must remain editable/removable.
    if cancelled.is_set():raise Cancelled('Anulowano otwieranie skoroszytu.')


EXCEL_SESSION_MAX_MESSAGE=4*1024*1024
EXCEL_HANDOFF_INCOMPLETE_MESSAGE='Przeniesienie zmian nie zostało zakończone. Przejrzyj lub zapisz kopię w Excelu, a potem rozpocznij nową sesję. Makra i edycja są wstrzymane.'


def excel_worker_command():
    """Run this installed source with the same environment, using data-only IPC."""
    interpreter=Path(sys.executable)
    # pythonw has no dependable stdio. A console interpreter with redirected
    # pipes supplies the protocol without creating another user-facing window.
    if os.name=='nt' and interpreter.name.lower()=='pythonw.exe':
        interpreter=interpreter.with_name('python.exe')
        if not interpreter.is_file():raise UserError('Nie znaleziono python.exe do obsługi sesji Excel. Napraw środowisko Pivot Studio.')
    return [str(interpreter),'-u',str(Path(__file__).resolve()),'--excel-worker']


def excel_session_foreground(owned,hwnd,cancelled):
    """Only an explicit reveal may foreground its verified, still-owned Excel."""
    if os.name!='nt' or cancelled.is_set() or not owned or not owned.alive():return False
    if type(hwnd) is not int or hwnd<=0:return False
    api=_ExcelNativeWindows();c=api.c;user=api.user
    for name,args,result in (('IsIconic',[c.c_void_p],c.c_int),('ShowWindowAsync',[c.c_void_p,c.c_int],c.c_int),('GetForegroundWindow',[],c.c_void_p)):
        function=getattr(user,name);function.argtypes=args;function.restype=result
    if api.pid(hwnd)!=owned.pid or api.root(hwnd)!=hwnd or api.class_name(hwnd)!='XLMAIN':return False
    foreground=int(user.GetForegroundWindow() or 0)
    # Do not interrupt somebody who changed to another application while COM
    # was busy. Windows also retains its own foreground activation restrictions.
    if foreground and api.pid(foreground) not in (os.getpid(),owned.pid):return False
    # A normal, hidden automation window is not iconic. Reveal it as well as
    # restoring a minimized one; never wait on Excel's potentially blocked STA.
    user.ShowWindowAsync(hwnd,9 if user.IsIconic(hwnd) else 5)
    if cancelled.is_set() or not owned.alive() or api.pid(hwnd)!=owned.pid:return False
    return bool(user.SetForegroundWindow(hwnd))


def excel_session_edits(edits):
    """Validate the entire explicit write set before any Office command is sent."""
    if not isinstance(edits,list) or len(edits)>1000:raise UserError('Jedna operacja może zmienić najwyżej 1000 komórek.')
    result=[];seen=set()
    for edit in edits:
        if not isinstance(edit,dict):raise UserError('Nieprawidłowa zmiana komórki Excel.')
        sheet=edit.get('sheet','');address=edit.get('address','');kind=edit.get('kind');value=edit.get('value')
        if not isinstance(sheet,str) or not sheet or len(sheet)>31 or not isinstance(address,str) or not re.fullmatch(r'[A-Za-z]{1,3}[1-9][0-9]{0,6}',address):raise UserError('Zmiana wymaga dokładnej nazwy arkusza i adresu jednej komórki A1.')
        col=0
        for char in re.match('[A-Za-z]+',address)[0].upper():col=col*26+ord(char)-64
        if col>16384 or int(re.search('[0-9]+',address)[0])>1048576:raise UserError('Adres poza arkuszem Excel.')
        key=(sheet.casefold(),address.upper())
        if key in seen:raise UserError('Ta sama komórka występuje dwukrotnie w operacji.')
        seen.add(key)
        def checked(k,v,expected=False):
            if k not in ('text','number','boolean','formula','blank','error') or (k=='error' and not expected):raise UserError('Nieobsługiwany typ komórki Excel.')
            if k in ('text','formula','error') and (not isinstance(v,str) or len(v)>32767):raise UserError('Nieprawidłowy tekst komórki Excel.')
            if k=='formula' and (not v.startswith('=') or len(v)>8192):raise UserError('Formuła Excel musi zaczynać się od = i mieć najwyżej 8192 znaki.')
            if k=='boolean' and type(v) is not bool:raise UserError('Nieprawidłowa wartość logiczna.')
            if k=='number':
                if type(v) not in (str,int,float) or not re.fullmatch(r'[+-]?(?:\d+(?:\.\d*)?|\.\d+)(?:[eE][+-]?\d+)?',str(v)) or not math.isfinite(float(v)):raise UserError('Liczba Excel musi być skończona i zapisana z kropką dziesiętną.')
                if not expected and Decimal(str(float(v)))!=Decimal(str(v)):raise UserError('Excel zaokrągliłby tę liczbę. Wpisz ją jako tekst, aby zachować wszystkie cyfry.')
            if k=='blank' and v not in (None,''):raise UserError('Pusta komórka nie może zawierać wartości.')
            return {'kind':k,'value':v}
        item=dict(sheet=sheet,address=address.upper(),**checked(kind,value))
        if 'sheet_id' in edit:
            sid=edit['sheet_id']
            if not isinstance(sid,str) or not sid or len(sid)>200:raise UserError('Nieprawidłowa tożsamość arkusza Excel.')
            item['sheet_id']=sid
        if 'expected' in edit:
            exp=edit['expected']
            if not isinstance(exp,dict):raise UserError('Nieprawidłowa oczekiwana wartość komórki.')
            ek=exp.get('kind');ev=exp.get('formula') if ek=='formula' and exp.get('formula') else exp.get('value')
            item['expected']=checked(ek,ev,True)
        result.append(item)
    if len(dumps(result).encode('utf-8'))>1024*1024:raise UserError('Zmiany komórek przekraczają 1 MiB. Podziel operację.')
    return result


def excel_session_layout(layout):
    """Bound only explicit row/column dimension changes, expressed in pixels."""
    if not isinstance(layout,list) or len(layout)>500:raise UserError('Nieprawidłowa lista zmian wymiarów arkuszy Excel.')
    result=[];sheets=set();count=0
    for raw in layout:
        if not isinstance(raw,dict) or set(raw)-{'sheet','columns','rows'}:raise UserError('Nieprawidłowa zmiana układu Excel.')
        name=raw.get('sheet')
        if not isinstance(name,str):raise UserError('Zmiana wymiarów wymaga nazwy arkusza.')
        sheet_title(name)
        if name.casefold() in sheets:raise UserError('Arkusz występuje dwukrotnie w zmianach wymiarów.')
        sheets.add(name.casefold());item={'sheet':name,'columns':[],'rows':[]}
        for axis,field,limit,maximum in (('columns','width',16384,2000),('rows','height',1048576,546)):
            entries=raw.get(axis,[])
            if not isinstance(entries,list):raise UserError('Wymiary arkusza muszą być listą.')
            seen=set()
            for entry in entries:
                if not isinstance(entry,dict) or set(entry)!={'index',field}:raise UserError('Nieprawidłowy wymiar arkusza Excel.')
                index=entry['index'];value=entry[field]
                if type(index) is not int or not 1<=index<=limit or index in seen:raise UserError('Nieprawidłowy albo powtórzony indeks wymiaru Excel.')
                if type(value) not in (int,float) or not math.isfinite(value) or not 0<value<=maximum:raise UserError('Wymiar Excel jest poza obsługiwanym zakresem: '+field+'.')
                seen.add(index);count+=1
                if count>10000:raise UserError('Sesja Excel przyjmuje najwyżej 10 000 zmian wymiarów.')
                item[axis].append({'index':index,field:float(value)})
        if item['columns'] or item['rows']:result.append(item)
    if len(dumps(result).encode('utf-8'))>1024*1024:raise UserError('Zmiany wymiarów przekraczają 1 MiB.')
    return result


class _ExcelDispatch:
    """Late-bound IDispatch only: no type-library generation or executable input."""
    def __init__(self,ole,pythoncom):
        object.__setattr__(self,'_ole',ole);object.__setattr__(self,'_com',pythoncom);object.__setattr__(self,'_ids',{})
    def _wrap(self,value):
        com=self._com
        if isinstance(value,com.TypeIIDs[com.IID_IDispatch]):return _ExcelDispatch(value,com)
        if isinstance(value,com.TypeIIDs[com.IID_IUnknown]):
            try:return _ExcelDispatch(value.QueryInterface(com.IID_IDispatch),com)
            except com.com_error:return value
        if isinstance(value,tuple):return tuple(self._wrap(item) for item in value)
        return value
    def _invoke(self,name,flags,*args):
        if name not in self._ids:self._ids[name]=self._ole.GetIDsOfNames(name)
        args=tuple(value._ole if isinstance(value,_ExcelDispatch) else value for value in args)
        return self._wrap(self._ole.Invoke(self._ids[name],0,flags,True,*args))
    def get(self,name,*args):return self._invoke(name,self._com.DISPATCH_PROPERTYGET,*args)
    def call(self,name,*args):return self._invoke(name,self._com.DISPATCH_METHOD,*args)
    def __getattr__(self,name):
        if name.startswith('_'):raise AttributeError(name)
        return self.get(name)
    def __setattr__(self,name,value):
        if name.startswith('_'):object.__setattr__(self,name,value)
        else:self._invoke(name,self._com.DISPATCH_PROPERTYPUT,value)
    def __iter__(self):
        # Shapes.Item is a method, whereas Worksheets.Item is a property.
        # The standard collection enumerator avoids either interpretation.
        com=self._com
        enum=self._ole.Invoke(com.DISPID_NEWENUM,0,com.DISPATCH_METHOD|com.DISPATCH_PROPERTYGET,True).QueryInterface(com.IID_IEnumVARIANT)
        while True:
            values=enum.Next(1)
            if not values:return
            yield self._wrap(values[0])
    def same(self,other):
        if not isinstance(other,_ExcelDispatch):return False
        # IUnknown is the COM identity, even when Excel returns a new proxy.
        return self._ole.QueryInterface(self._com.IID_IUnknown)==other._ole.QueryInterface(self._com.IID_IUnknown)


class _ExcelOleMessageFilter:
    """STA retry policy for calls COM explicitly rejected before execution.

    The native interface is static Python/ctypes code. Failed writes and macros
    are never replayed by application-level retries.
    """
    @staticmethod
    def retry_delay(tick_count,reject_type):return 250 if reject_type==2 and tick_count<15000 else -1
    def __init__(self):
        import ctypes as c
        self.c=c;self.previous=c.c_void_p();self.registered=False;self.refs=1
        pointer=c.c_void_p;word=c.c_uint32
        query_type=c.WINFUNCTYPE(c.c_int32,pointer,pointer,c.POINTER(pointer))
        ref_type=c.WINFUNCTYPE(word,pointer)
        incoming_type=c.WINFUNCTYPE(word,pointer,word,pointer,word,pointer)
        pending_type=c.WINFUNCTYPE(word,pointer,pointer,word,word)
        supported={uuid.UUID('00000000-0000-0000-c000-000000000046').bytes_le,uuid.UUID('00000016-0000-0000-c000-000000000046').bytes_le}
        def query(this,iid,out):
            if not out:return -2147467261  # E_POINTER
            out[0]=None
            if iid and c.string_at(iid,16) in supported:out[0]=this;self.refs+=1;return 0
            return -2147467262  # E_NOINTERFACE
        def add_ref(this):self.refs+=1;return self.refs
        def release(this):self.refs=max(0,self.refs-1);return self.refs
        self.callbacks=(query_type(query),ref_type(add_ref),ref_type(release),
                        incoming_type(lambda this,kind,caller,ticks,info:0),
                        pending_type(lambda this,callee,ticks,kind:self.retry_delay(ticks,kind)&0xffffffff),
                        pending_type(lambda this,callee,ticks,kind:2))
        self.vtable=(pointer*6)(*(c.cast(callback,pointer).value for callback in self.callbacks))
        class Interface(c.Structure):_fields_=[('vtable',c.POINTER(pointer))]
        self.interface=Interface(self.vtable)
        self.ole=c.WinDLL('ole32');self.ole.CoRegisterMessageFilter.argtypes=[pointer,c.POINTER(pointer)];self.ole.CoRegisterMessageFilter.restype=c.c_int32
    def register(self):
        result=self.ole.CoRegisterMessageFilter(self.c.byref(self.interface),self.c.byref(self.previous))
        if result!=0:raise UserError('Could not register the Excel STA message filter (0x%08X).'%(result&0xffffffff))
        self.registered=True
    def _release_pointer(self,pointer):
        if pointer:
            c=self.c;vtable=c.cast(pointer,c.POINTER(c.POINTER(c.c_void_p))).contents
            c.WINFUNCTYPE(c.c_uint32,c.c_void_p)(vtable[2])(pointer)
    def close(self):
        if not self.registered:return
        current=self.c.c_void_p()
        result=self.ole.CoRegisterMessageFilter(self.previous,self.c.byref(current))
        if result!=0:raise UserError('Could not restore the previous COM message filter.')
        self.registered=False
        self._release_pointer(current);self._release_pointer(self.previous);self.previous=self.c.c_void_p()


def excel_worker_error_text(exc):
    """Keep HRESULTs in JSON errors so the UI can explain Office busy states."""
    codes=[];info=getattr(exc,'excepinfo',None)
    for value in (getattr(exc,'hresult',None),(info or (None,)*6)[-1]):
        if isinstance(value,int) and value:codes.append('0x%08X'%(value&0xffffffff))
    text=str(exc)
    if isinstance(info,(tuple,list)):
        for value in info[1:3]:
            if value and str(value) not in text:text+='\n'+str(value)
    return (((' '.join(dict.fromkeys(codes)))+' ') if codes else '')+text[:5000]


def excel_worker_error_fields(exc,operation='',macro_name='',diagnostics=None):
    """Separate actionable Office text from the original COM diagnostic."""
    details=excel_worker_error_text(exc);info=getattr(exc,'excepinfo',None)
    description=str(info[2]).strip() if isinstance(info,(tuple,list)) and len(info)>2 and info[2] else str(exc).strip()
    description=description[:2500];diagnostics=diagnostics or {};code='operation_failed'
    busy=bool(re.search(r'0x800AC472|0x8001010A|0x80010001|RPC_E_SERVERCALL_RETRYLATER|RPC_E_CALL_REJECTED',details,re.IGNORECASE))
    if busy:
        code='office_busy';message='Excel jest zajęty. Kliknij „Pokaż Excel” i zakończ edycję komórki albo odpowiedz w otwartym oknie.'
        if macro_name:message+=' Makro „'+macro_name+'” nie zostało automatycznie ponowione.'
    elif operation in ('run_macro','run_control_macro') or macro_name:
        code='macro_failed';message='Nie udało się wykonać makra'+(' „'+macro_name+'”' if macro_name else '')+'.'
        if description:message+=' '+description
        if re.search(r'cannot run the macro|can.t run the macro|nie można uruchomić makra',description,re.IGNORECASE):
            code='macro_unavailable';message+=' Sprawdź nazwę procedury i jej modułu oraz komunikat zabezpieczeń w „Pokaż Excel”.'
        if operation=='run_control_macro':message+=' Jeśli procedura korzysta z Application.Caller, uruchom przycisk bezpośrednio w Excelu.'
        if diagnostics.get('has_vba_project') is False:message+=' Excel nie wykrywa projektu VBA w tym skoroszycie.'
        message+=' Sprawdź wynik przed ponowną próbą; makro mogło wykonać część pracy.'
    else:message=description or 'Excel nie wykonał operacji.'
    if diagnostics.get('protected_view'):
        code='protected_view';message+=' Excel ma otwarte okno Widoku chronionego. Sprawdź je przez „Pokaż Excel”; ustawienia zabezpieczeń pozostają bez zmian.'
    if macro_name:details='Makro: '+macro_name+'\n'+details
    if diagnostics:details+='\nStan Excela: '+dumps(diagnostics)
    result={'message':message,'details':details[:6000],'code':code}
    if macro_name:result['macro_name']=macro_name
    return result


class ExcelSessionWorker:
    """One bound workbook in an owned Excel process; all COM stays on its STA."""
