    if s.get('password'):u=u._replace(netloc=quote(s['username'],safe='')+':'+quote(s['password'],safe='')+'@'+u.netloc)
    args+=['--index-url',urlunsplit(u)]
    if s.get('ca_file'):args+=['--cert',s['ca_file']]
    if s.get('proxy'):args+=['--proxy',s['proxy']]
