@contextlib.contextmanager
def installation_lock(root,cancel):
    """OS-owned lock is released after a crash; no stale PID-file deletion required."""
    with (Path(root)/'prepare.lock').open('a+b') as f:
        if not f.seek(0,os.SEEK_END): f.write(b'0'); f.flush()
        held=False; deadline=time.monotonic()+300
        try:
            while not held:
                if cancel.is_set():raise Cancelled('Anulowano przygotowanie.')
                f.seek(0)
                try:
                    if os.name=='nt':
                        import msvcrt
                        msvcrt.locking(f.fileno(),msvcrt.LK_NBLCK,1)
                    else:
                        import fcntl
                        fcntl.flock(f.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
                    held=True
                except OSError:
                    if time.monotonic()>deadline:raise UserError('Inne okno nadal przygotowuje środowisko. Spróbuj później.')
                    time.sleep(.08)
            yield
        finally:
            if held:
                f.seek(0)
                if os.name=='nt':
                    import msvcrt
                    msvcrt.locking(f.fileno(),msvcrt.LK_UNLCK,1)
                else:
                    import fcntl
                    fcntl.flock(f.fileno(),fcntl.LOCK_UN)


def stop_installation_process(proc):
    if proc.poll() is not None:return
    if os.name=='nt':
        subprocess.run([str(Path(os.environ.get('SystemRoot','C:/Windows'))/'System32'/'taskkill.exe'),
            '/PID',str(proc.pid),'/T','/F'],stdin=subprocess.DEVNULL,stdout=subprocess.DEVNULL,stderr=subprocess.DEVNULL,
            timeout=20,creationflags=CREATE_NO_WINDOW)
    else:
        import signal
        with contextlib.suppress(ProcessLookupError):os.killpg(proc.pid,signal.SIGTERM)
    try:proc.wait(timeout=5)
    except subprocess.TimeoutExpired:
        if os.name!='nt':
            import signal
            with contextlib.suppress(ProcessLookupError):os.killpg(proc.pid,signal.SIGKILL)
        else:proc.kill()
        proc.wait(timeout=5)


def install_environment(profile,root=None,wheelhouse=None,progress=print,*,source=None,cancel=None,stage=None):
    """Prepare a new generation. Publish only after pip check AND real Qt imports.

    Source password crosses stdin only, never OS arguments, files or child env.
    Download hashes lock these downloaded bytes; they are NOT publisher signatures.
    """
    problem=installer_profile_problem(profile)
    if problem:raise UserError(problem)
    requested=set(OPTIONAL_INSTALL_PROFILES)-{'excel'} if profile=='drivers' else {'desktop',*OPTIONAL_INSTALL_PROFILES} if profile=='all' else {profile}
    for key in requested:
        problem=installer_profile_problem(key)
        if problem:raise UserError(problem)
    root=private_dir(Path(root or runtime_root())); cancel=cancel or threading.Event(); stage=stage or (lambda *_:None)
    if source is None:
        source=package_source('offline',wheel_dir=str(wheelhouse)) if wheelhouse else load_package_source(root)
        if source is None:raise UserError('Najpierw wybierz źródło bibliotek w oknie Przygotowanie (--setup).')
    source=package_source(**source)
    if source['mode']=='internal' and source['username'] and not source['password']:
        raise UserError('Wpisz hasło lub token repozytorium. Nie jest zapisywany między instalacjami.')
    redact=installation_redactor(source); log=[]
    def check():
        if cancel.is_set():raise Cancelled('Przygotowanie anulowane. Poprzednie środowisko i projekty pozostają bez zmian.')
    def emit(line):
        line=redact(line);log.append(line)
        if len(log)>1500:del log[:200]
        progress(line)
    def run(command,payload=None,timeout=900):
        check();emit('> '+redact(subprocess.list2cmdline([str(x) for x in command])))
        proc=subprocess.Popen([str(x) for x in command],stdin=subprocess.PIPE if payload is not None else subprocess.DEVNULL,
            stdout=subprocess.PIPE,stderr=subprocess.STDOUT,creationflags=CREATE_NO_WINDOW,
            env=installer_environment(source),start_new_session=os.name!='nt',bufsize=0)
        messages=queue.Queue(maxsize=512)
        def reader():
            try:
                # Bounded whole lines are redacted before entering logs/UI.
                while True:
                    raw=proc.stdout.readline(65537)
                    if not raw:break
                    if len(raw)>65536:
                        while raw and not raw.endswith(b'\n'):raw=proc.stdout.readline(65537)
                        raw=b'[Pominieto nadmiernie dlugi komunikat instalatora.]\n'
                    text=redact(raw.decode('utf-8','replace').rstrip())
                    while True:
                        try:messages.put(text,timeout=.1);break
                        except queue.Full:
                            if cancel.is_set():return
            except (OSError,ValueError):pass
            finally:
                with contextlib.suppress(queue.Full):messages.put_nowait(None)
        thread=threading.Thread(target=reader,name='InstallerPipe',daemon=True); thread.start()
        began=time.monotonic()
        try:
            if payload is not None:
                raw=(json.dumps(payload,ensure_ascii=True)+'\n').encode()
                if len(raw)>32768:raise UserError('Zbyt duża konfiguracja instalatora.')
                proc.stdin.write(raw);proc.stdin.close()
            while proc.poll() is None or not messages.empty() or thread.is_alive():
                check()
                if time.monotonic()-began>timeout:raise UserError('Przekroczono czas etapu instalacji. Sprawdź źródło, sieć lub proxy.')
                try:
                    text=messages.get(timeout=.05)
                    if text is not None:emit(text)
                except queue.Empty:pass
            if proc.wait()!=0:
                raise UserError('Etap instalacji nie zakończył się poprawnie. '+installation_hint('\n'.join(log[-24:]))+'\n\n'+'\n'.join(log[-10:]))
        finally:
            if proc.poll() is None:stop_installation_process(proc)
            thread.join(timeout=2)
            with contextlib.suppress(Exception):proc.stdout.close()
            if proc.stdin is not None and not proc.stdin.closed:proc.stdin.close()
    try:
        with installation_lock(root,cancel):
            check(); previous=load_runtime_marker(root)
            profiles=set(previous.get('profiles',[]))&set(REQUIREMENTS) if previous else set()
            profiles|=requested; profiles.add('desktop')
            for key in profiles:
                problem=installer_profile_problem(key)
                if problem:raise UserError(problem)
            save_package_source(source,root)
            generation=root/('py'+str(sys.version_info.major)+str(sys.version_info.minor)+'-'+uid()[:8]);private_dir(generation)
            py=generation/('Scripts/python.exe' if os.name=='nt' else 'bin/python')
            base=Path(sys.executable)
            if os.name=='nt' and base.name.lower()=='pythonw.exe':base=base.with_name('python.exe')
            stage('environment','Tworzę prywatne środowisko Pythona.');run([base,'-I','-m','venv',generation],timeout=180)
            wheels=private_dir(generation/'wheels'); packages=[p for x in sorted(profiles) for p in REQUIREMENTS[x]]
            constraints=reuse_verified_wheels(previous,root,wheels,source)
            constraints_file=generation/'previous-versions.txt'
            if constraints:atomic_bytes(constraints_file,('\n'.join(constraints)+'\n').encode('utf-8'))
            stage('download','Pobieram biblioteki z wybranego źródła.');emit('Źródło: '+(source['wheel_dir'] if source['mode']=='offline' else source['index_url']))
            run([py,'-I','-u','-c',_PIP_DOWNLOAD_CODE],payload={'source':source,'packages':packages,'dest':str(wheels),
                'reuse':bool(constraints),'constraints':str(constraints_file)},timeout=1800)
            check();lines=[]
            for whl in sorted(wheels.glob('*.whl')):
                bits=whl.name.split('-');lines.append(f'{bits[0].replace("_","-")}=={bits[1]} --hash=sha256:{file_digest(whl)}')
            if not lines:raise UserError('Nie pobrano zgodnych pakietów wheel.')
            lockfile=generation/'requirements.lock';atomic_bytes(lockfile,('\n'.join(lines)+'\n').encode())
            stage('install','Instaluję pobrane pakiety; weryfikuję ich sumy kontrolne.')
            run([py,'-I','-m','pip','--isolated','install','--disable-pip-version-check','--no-input','--require-virtualenv',
                '--no-index','--find-links',wheels,'--require-hashes','-r',lockfile])
            stage('verify','Sprawdzam spójność zależności i rzeczywiste importy.')
            run([py,'-I','-m','pip','--isolated','check'])
            desktop_imports='from PySide6 import QtCore, QtGui, QtWidgets, QtSvg'
            if 'secrets' in profiles:desktop_imports+='; import keyring'
            run([py,'-I','-c',desktop_imports+"; print('Importy interfejsu: OK')"],timeout=90)
            # Drivers run in isolated workers. Qt's import hook must not participate
            # in their probes (notably dateutil/six imported by Firebird on Windows).
            for key,code in [('oracle','import oracledb'),('firebird','import firebird.driver'),('h2','import jpype'),
                             ('excel','import pythoncom; import win32com.client.dynamic')]:
                if key in profiles:run([py,'-I','-c',code+f"; print('Import {key}: OK')"],timeout=90)
            check();marker={'python':str(py),'profiles':sorted(profiles),'version':APP_VERSION,'installed':utcnow(),
                'platform':platform.platform(),'python_version':list(sys.version_info[:2]),
                'lock_sha256':file_digest(lockfile),'source_identity':package_source_identity(source)}
            atomic_bytes(root/'current.json',json.dumps(marker,indent=2).encode())
            stage('ready','Środowisko jest gotowe.');emit('Gotowe. Poprzednie środowisko pozostaje na dysku.');return marker
    finally:
        source['password']=''
        with contextlib.suppress(Exception):atomic_bytes(root/'last-install.log',('\n'.join(log)).encode('utf-8'))


def installation_hint(text):
    lower=text.lower()
    if any(x in lower for x in ('certificate verify','certificate_verify','sslcertverification')):
        return 'Wskaż firmowy certyfikat CA (PEM). Sprawdzanie TLS pozostaje włączone.'
    if any(x in lower for x in ('401','403','unauthorized','forbidden')):
        return 'Sprawdź adres /simple, login i hasło/token oraz dostęp do pobierania.'
    if any(x in lower for x in ('no matching distribution','could not find a version')):
        return 'Repozytorium musi zawierać wymagane wersje dla Twojego Pythona i systemu. Sprawdź też wcześniejsze błędy sieci.'
    if any(x in lower for x in ('connection','getaddrinfo','resolution','timed out','proxyerror')):
        return 'Sprawdź sieć, VPN, adres i proxy. Źródło nie zostało przełączone na inne.'
    return 'Popraw źródło lub sprawdź szczegóły. Poprzednia instalacja i projekty pozostają bez zmian.'



def diagnostics(runtime=None):
    def present(name):
        try: return importlib.util.find_spec(name) is not None
        except (ImportError,ModuleNotFoundError,ValueError): return False
    return {'python':sys.version.split()[0],'executable':sys.executable,'platform':platform.platform(),
            'desktop':present('PySide6'),'oracle':present('oracledb'),'firebird':present('firebird.driver'),
            'h2':present('jpype'),'keyring':present('keyring'),'java':shutil.which('java') or '',
            'sqlite':sqlite3.sqlite_version,'runtime':runtime or {},'version':APP_VERSION}


def create_demo(directory):
    path=private_dir(Path(directory))/'sprzedaz-demo-v1.sqlite'
    if not path.exists():
        temp=path.with_suffix('.part'); conn=sqlite3.connect(temp)
        conn.execute('CREATE TABLE sprzedaz (ID INTEGER, Region TEXT, Kanał TEXT, Data DATE_TEXT, '
                     'Produkt TEXT, Klient TEXT, Ilość INTEGER, Przychód DECIMAL_TEXT, Koszt DECIMAL_TEXT)')
        regions=['Północ','Południe','Wschód','Zachód']; products=['Atlas','Nova','Orbit']
        rows=[]
        for i in range(1440):
            month=(i//40)%6+1; qty=(i*7)%12+1; rate=Decimal(89+(i*13)%240)+Decimal('0.90')
            revenue=rate*qty; cost=(revenue*Decimal('0.61')).quantize(Decimal('.01'))
            rows.append((i+1,regions[(i//3)%4],['Online','Partnerzy','Sklep'][i%3],
                         f'2026-{month:02d}-{(i%27)+1:02d}',products[(i//5)%3],f'K{(i*17)%173:04d}',
                         qty,str(revenue),None if i%71==0 else str(cost)))
        conn.executemany('INSERT INTO sprzedaz VALUES(?,?,?,?,?,?,?,?,?)',rows); conn.commit(); conn.close(); os.replace(temp,path)
    source=validate_source({'name':'Sprzedaż — dane przykładowe','kind':'sqlite','options':{'path':str(path),'owned':True}})
    analysis=validate_analysis({'name':'Sprzedaż według regionu i miesiąca',
              'dataset':{'source_id':source['id'],'schema':'main','table':'sprzedaz'},
              'rows':[{'field':'Region'}],'columns':[{'field':'Data','grain':'month'}],
              'measures':[{'agg':'sum','field':'Przychód','label':'Przychód','format':'money'}]})
    return source,analysis


