class CatalogCacheCoordinator:
    """Local metadata I/O; remote workers only create private staging databases.

    Cache jobs are separate from installers and never publish through Qt's poll
    callback. One import batch runs between queued reads, keeping pages responsive.
    """
    ACTIONS=frozenset(('database_cache_page','database_cache_details','database_cache_status',
                       'database_cache_sync','database_cache_clear','database_cache_hydrate','database_cache_graph'))
    BACKGROUND=frozenset(('database_cache_sync','database_cache_hydrate'))
    MAX_COMPLETED=64;MAX_RESULT_BYTES=32*1024*1024
    def __init__(self,service):
        self.service=service;self.cache=CatalogCache(service.root/'cache'/'metadata-v1.sqlite')
        self.jobs={};self.requests={};self.syncs={};self.hydrations={};self.lock=threading.RLock()
        self.result_bytes={};self.delivered=set();self.pending_details={}
        self.queue=queue.Queue();self.stopping=threading.Event();self.thread=None
    def submit(self,operation,args,source):
        if self.stopping.is_set():raise UserError('Magazyn katalogu jest zamykany.')
        jid=uid();request={'source':clone(source),'args':clone(args),'generation':self.service.generation,
                          'fingerprint':source_data_fingerprint(source),'cancel':threading.Event()}
        with self.lock:
            if sum(j['status']=='running' for j in self.jobs.values())>=64:
                raise UserError('Trwa zbyt wiele odczytów katalogu. Poczekaj na ich zakończenie.')
            if operation in self.BACKGROUND:
                for old_id,job in self.jobs.items():
                    if job['status']!='running' or job['operation'] not in self.BACKGROUND:continue
                    previous=self.requests[old_id]
                    if operation=='database_cache_sync' and job['operation']=='database_cache_hydrate':previous['cancel'].set()
                    if not previous['cancel'].is_set():raise UserError('Odczyt katalogu w tle już trwa. Poczekaj albo go wstrzymaj.')
            self.requests[jid]=request
            self.jobs[jid]={'id':jid,'operation':operation,'status':'running','stage':'Odczyt lokalnego katalogu',
                            'created':utcnow(),'source_id':source['id'],'lane':'catalog-cache'}
            if self.thread is None:
                self.thread=threading.Thread(target=self._run,name='CatalogCacheIO',daemon=True);self.thread.start()
        self.queue.put(('job',jid));return {'job_id':jid}
    def poll(self,jid):
        with self.lock:
            job=self.jobs[jid]
            if job['status']!='running':self.delivered.add(jid)
            return dict(job)
    def running(self):
        with self.lock:return [jid for jid,j in self.jobs.items() if j['status']=='running']
    def cancel(self,jid):
        with self.service.lock,self.lock:
            request=self.requests.get(jid)
            if request:request['cancel'].set()
        return {'ok':True}
    def cancel_all(self):
        for jid in self.running():self.cancel(jid)
    def _live(self,request):
        with self.service.lock:
            if self.stopping.is_set() or request['cancel'].is_set():return False
            if request['generation']!=self.service.generation:return False
            try:source=self.service.source(request['source']['id'])
            except UserError:return False
            return source_data_fingerprint(source)==request['fingerprint']
    def _finish(self,jid,value=None,error=None,published=False):
        request=self.requests[jid]
        size=len(dumps(value).encode('utf-8')) if value is not None and error is None else 0
        with self.service.lock,self.lock:
            cancelled=(not published and not self._live(request)) or isinstance(error,Cancelled)
            job=self.jobs[jid];job['ended']=utcnow()
            if cancelled:job.update(status='cancelled',error='Anulowano odczyt katalogu lub zmieniono źródło. Poprzednia wersja pozostaje dostępna.')
            elif error is not None:job.update(status='error',error=safe_error(error))
            else:job.update(status='done',value=value)
            self.requests.pop(jid,None);self.result_bytes[jid]=0 if cancelled else size
            # A page/detail result can be large. Keep recent results repeatable,
            # without retaining every page ever viewed throughout the session.
            finished=sorted((key for key,j in self.jobs.items() if key!=jid and j['status']!='running'),
                            key=lambda key:key not in self.delivered)
            for key in finished:
                if len(self.result_bytes)<=self.MAX_COMPLETED and sum(self.result_bytes.values())<=self.MAX_RESULT_BYTES:break
                self.jobs.pop(key,None);self.result_bytes.pop(key,None);self.delivered.discard(key)
    @staticmethod
    def _scope(request):
        args=request['args'];source=request['source']
        return {'schema':args.get('schema',source['options'].get('schema','')),
                'include_system':args.get('include_system',False)}
    def _execute(self,jid):
        request=self.requests[jid]
        if not self._live(request):self._finish(jid,error=Cancelled());return
        args=request['args'];identity=catalog_cache_identity(request['source']);scope=self._scope(request)
        operation=self.jobs[jid]['operation']
        if operation=='database_cache_sync':
            self.syncs[jid]={'lease':None,'identity':identity,'scope':scope,'worker_id':None,'phase':'queued',
                            'path':self.service.session/('catalog-'+jid+'.sqlite')}
            return
        if operation=='database_cache_hydrate':
            current=self.cache.status(identity,scope);generation=args.get('generation') or current.get('generation')
            if not generation or current.get('generation')!=generation:raise Cancelled('Migawka katalogu została zmieniona. Otwórz aktualną wersję.')
            status=self.cache.hydration_status(identity,scope,generation=generation)
            self.hydrations[jid]={'identity':identity,'scope':scope,'generation':generation,'worker_id':None,
                                  'last_worker_id':None,'claim':None,'retry':args.get('retry_failed') is True}
            self._hydration_progress(jid,status)
            return
        if operation=='database_cache_page':
            value=self.cache.page(identity,scope,offset=args.get('offset',0),query=args.get('query',''),kind=args.get('kind',''),
                                  page_size=args.get('page_size',1000),include_system=scope['include_system'],generation=args.get('generation'))
            if value is not None:
                value['source_id']=request['source']['id']
                value['hydration']=self.cache.hydration_status(identity,scope,generation=value['cache']['generation'])
        elif operation=='database_cache_details':
            value=self.cache.get_details(identity,args.get('object',{}),scope=scope,generation=args.get('generation'))
            if value is not None:value['source_id']=request['source']['id']
        elif operation=='database_cache_status':
            value=self.cache.status(identity,scope)
            if value.get('generation'):value['hydration']=self.cache.hydration_status(identity,scope,generation=value['generation'])
        elif operation=='database_cache_graph':
            value=self.cache.graph(identity,scope,ids=args.get('ids',()),focus=args.get('focus',''),focus_object=args.get('focus_object'),generation=args.get('generation'),limit=args.get('limit',120))
            if value is not None:value['source_id']=request['source']['id']
        elif operation=='database_cache_clear':
            value=dict(self.cache.clear(identity,scope) or {},cleared=True)
        else:raise UserError('Nieznana operacja lokalnego katalogu.')
        self._finish(jid,value if value is not None else {'cache_miss':True})
    def _cleanup_sync(self,jid):
        state=self.syncs.pop(jid,None)
        if state is None:return
        if state.get('lease'):
            with contextlib.suppress(Exception):self.cache.abort(state['lease'])
        worker_id=state.get('worker_id')
        if worker_id and self.service.hub.poll(worker_id)['status']=='running':return
        with contextlib.suppress(OSError):state['path'].unlink()
    def _step_sync(self,jid):
        request=self.requests[jid];state=self.syncs[jid];worker_id=state.get('worker_id')
        if not self._live(request):
            if worker_id and self.service.hub.poll(worker_id)['status']=='running':
                if not state.get('cancel_sent'):
                    self.service.hub.cancel(worker_id);state['cancel_sent']=True
                return
            raise Cancelled()
        if state['phase']=='queued':
            if self.hydrations or any(key!=jid for key in self.syncs):return
            with self.service.hub.lock:
                if sum(j['status']=='running' for j in self.service.hub.jobs.values())>=3:return
            lease=self.cache.begin_refresh(state['identity'],state['scope'],owner=self.service.session.name,
                                            supersede=request['args'].get('force',False) is True)
            if lease is None:
                status=self.cache.status(state['identity'],state['scope'])
                self._cleanup_sync(jid);self._finish(jid,dict(status,cache=status,synced=False));return
            state['lease']=lease
            if not self._live(request):raise Cancelled()
            source=request['source']
            worker_id=self.service.hub.submit('database_cache_sync',state['scope'],source,self.service.secrets.get(source),
                self.service.settings,str(state['path']),int(self.service.settings.get('timeout',60)))
            state.update(worker_id=worker_id,phase='remote')
            with self.service.hub.lock:
                self.service.hub.jobs[worker_id].update(generation=request['generation'],source_fingerprint=request['fingerprint'])
            return
        if state['phase']=='remote':
            remote=self.service.hub.poll(worker_id)
            if remote['status']=='running':
                with self.lock:self.jobs[jid]['stage']=remote.get('stage','Synchronizacja katalogu')
                return
            if remote['status']!='done':
                with self.lock:
                    for key in ('dependency','connected','catalog_scope'):
                        if key in remote:self.jobs[jid][key]=remote[key]
                raise Cancelled() if remote['status']=='cancelled' else UserError(remote.get('error','Nie odczytano katalogu.'))
            descriptor=remote['value']
            if Path(descriptor['path']).resolve()!=state['path'].resolve():raise UserError('Nieprawidłowy plik synchronizacji katalogu.')
            self.cache.prepare_import(descriptor,state['lease']);state['phase']='import';return
        progress=self.cache.import_batch(state['lease'],batch_size=500,cancelled=request['cancel'])
        with self.lock:self.jobs[jid]['stage']='Zapisywanie lokalnego katalogu · '+str(progress.get('imported',0))+' obiektów'
        if not progress['done']:return
        if not self.cache.commit_publish(state['lease'],guard=lambda:self._live(request),guard_lock=self.service.lock):
            raise Cancelled('Nowsza synchronizacja zastąpiła ten odczyt.')
        status=self.cache.status(state['identity'],state['scope'])
        self._cleanup_sync(jid);self._finish(jid,dict(status,cache=status,synced=True),published=True)
        with contextlib.suppress(Exception):self.cache.gc()
    def _hydration_progress(self,jid,status,paused=False,changed_ids=None):
        value=dict(status,paused=bool(paused),changed_ids=list(status.get('changed_ids',()) if changed_ids is None else changed_ids))
        with self.lock:
            self.jobs[jid]['hydration']=value
            self.jobs[jid]['stage']=('Oczekiwanie na bieżący odczyt danych' if paused else
                'Odczyt kolumn i relacji · '+str(status.get('completed',0))+' / '+str(status.get('total',0))+
                ' · częściowe: '+str(status.get('partial',0))+' · błędy: '+str(status.get('failed',0)))
    def _cleanup_hydration(self,jid):
        state=self.hydrations.pop(jid,None)
        if state is None:return
        if state.get('claim'):
            with contextlib.suppress(Exception):self.cache.release_hydration_claim(state['identity'],state['scope'],state['generation'],state['claim'])
        if state.get('last_worker_id'):
            with contextlib.suppress(Exception):self.service.hub.release_background(state['last_worker_id'])
            with self.service.hub.lock:
                remote=self.service.hub.jobs.get(state['last_worker_id'])
                if remote and remote['status']!='running':self.service.hub.jobs.pop(state['last_worker_id'],None)
    def _step_hydration(self,jid):
        request=self.requests[jid];state=self.hydrations[jid];worker_id=state.get('worker_id')
        if not self._live(request):
            if worker_id and self.service.hub.poll(worker_id)['status']=='running':
                if not state.get('cancel_sent'):
                    self.service.hub.cancel(worker_id);state['cancel_sent']=True
                return
            raise Cancelled()
        if worker_id:
            remote=self.service.hub.poll(worker_id)
            if remote['status']=='running':return
            if remote['status']!='done':
                with self.lock:
                    for key in ('dependency','connected','catalog_scope'):
                        if key in remote:self.jobs[jid][key]=remote[key]
                raise Cancelled() if remote['status']=='cancelled' else UserError(remote.get('error','Nie ukończono odczytu kolumn i relacji.'))
            batch=remote['value'];identity=batch.get('cache_identity')
            if not isinstance(identity,dict) or not identity.get('context') or identity.get('source_key')!=state['identity']['source_key']:
                raise UserError('Nie potwierdzono tożsamości bazy. Odczyt kolumn i relacji wstrzymano.')
            status=self.cache.put_hydration_results(identity,batch,state['scope'],observed_generation=state['generation'],claim=state['claim'],
                                                     guard=lambda:self._live(request),guard_lock=self.service.lock)
            if not status:raise Cancelled('Migawka lub źródło zostały zmienione. Zatrzymano odczyt struktury.')
            changed=[r.get('object',{}).get('id') for r in batch.get('results',[]) if r.get('object',{}).get('id')]
            state.update(worker_id=None,claim=None)
            self._hydration_progress(jid,status,changed_ids=changed)
            # Bulk payloads belong to the cache, not an ever-growing hub log.
            with self.service.hub.lock:self.service.hub.jobs[worker_id]['value']={'stored':True}
            return
        if self.syncs or any(key!=jid for key in self.hydrations) or self.service.hub.foreground_busy():
            with self.lock:status=self.jobs[jid].get('hydration',{})
            self._hydration_progress(jid,status,paused=True);return
        current=self.cache.status(state['identity'],state['scope'])
        if current.get('generation')!=state['generation']:raise Cancelled('Opublikowano nowszy katalog. Zatrzymano poprzedni odczyt struktury.')
        batch=self.cache.hydration_batch(state['identity'],state['scope'],state['generation'],limit=20,retry=state.pop('retry',False))
        status={k:v for k,v in batch.items() if k not in ('objects','claim')};objects=batch.get('objects',[])
        if not objects:
            self._hydration_progress(jid,status)
            self._cleanup_hydration(jid);self._finish(jid,{'hydration':status,'hydrated':True,'generation':state['generation']});return
        state['claim']=batch['claim'];source=request['source']
        if not self._live(request):raise Cancelled()
        try:
            worker_id=self.service.hub.submit('database_cache_hydrate_batch',{'objects':objects,'cache_generation':state['generation'],'cache_scope':state['scope']},
                source,self.service.secrets.get(source),self.service.settings,'',int(self.service.settings.get('timeout',60)))
        except CatalogBackgroundBusy:
            self.cache.release_hydration_claim(state['identity'],state['scope'],state['generation'],state['claim']);state['claim']=None
            self._hydration_progress(jid,status,paused=True);return
        if state.get('last_worker_id'):
            with self.service.hub.lock:
                previous=self.service.hub.jobs.get(state['last_worker_id'],{})
                if previous.get('worker') is not self.service.hub.jobs[worker_id].get('worker'):
                    self.service.hub.release_background(state['last_worker_id'])
                self.service.hub.jobs.pop(state['last_worker_id'],None)
        state.update(worker_id=worker_id,last_worker_id=worker_id)
        self._hydration_progress(jid,status)
    def remember_details(self,job):
        args=job.get('args',{})
        if self.stopping.is_set() or args.get('cache_generation') is None:return
        try:source=clone(self.service.source(job['source_id']))
        except UserError:return
        identity=job.get('value',{}).get('cache_identity')
        if not isinstance(identity,dict) or not identity.get('context') or identity.get('source_key')!=catalog_cache_identity(source)['source_key']:return
        request={'source':source,'args':{},'generation':self.service.generation,
                 'fingerprint':source_data_fingerprint(source),'cancel':threading.Event()}
        # Completed worker results are immutable; serialize on the I/O thread,
        # outside the GUI/service/worker locks.
        key=(identity['key'],args['cache_generation'],job['value'].get('object',{}).get('id',''))
        with self.lock:
            if key not in self.pending_details and len(self.pending_details)>=2:return
            enqueue=key not in self.pending_details
            self.pending_details[key]=(request,job['value'],clone(args))
            if enqueue:self.queue.put(('details',key))
            if self.thread is None:
                self.thread=threading.Thread(target=self._run,name='CatalogCacheIO',daemon=True);self.thread.start()
    @staticmethod
    @contextlib.contextmanager
    def _stage_owner(directory,create=False):
        try:file=(directory/'catalog.lock').open('a+b' if create else 'r+b')
        except FileNotFoundError:
            if create:raise
            yield;return
        held=False
        try:
            if not file.seek(0,os.SEEK_END):file.write(b'0');file.flush()
            file.seek(0)
            if os.name=='nt':
                import msvcrt
                msvcrt.locking(file.fileno(),msvcrt.LK_NBLCK,1)
            else:
                import fcntl
                fcntl.flock(file.fileno(),fcntl.LOCK_EX|fcntl.LOCK_NB)
            held=True;yield
        finally:
            if held:
                file.seek(0)
                if os.name=='nt':msvcrt.locking(file.fileno(),msvcrt.LK_UNLCK,1)
                else:fcntl.flock(file.fileno(),fcntl.LOCK_UN)
            file.close()
    def _sweep_stages(self):
        base=(self.service.root/'sessions').resolve();cutoff=time.time()-86400;deadline=time.monotonic()+.5;seen=0
        # Never remove session directories, recovery files, or another live
        # instance's stages. Old runs without an owner lock use the age gate.
        with os.scandir(base) as entries:
            for index,entry in enumerate(entries):
                if index>=128 or time.monotonic()>deadline:break
                if not re.fullmatch('[a-f0-9]{32}',entry.name) or not entry.is_dir(follow_symlinks=False):continue
                directory=Path(entry.path).resolve()
                if directory==self.service.session.resolve() or directory.parent!=base:continue
                try:
                    with self._stage_owner(directory),os.scandir(directory) as files:
                        for file in files:
                            seen+=1
                            if seen>512 or time.monotonic()>deadline:return
                            if not re.fullmatch(r'catalog-[a-f0-9]{32}\.sqlite(?:\.[a-f0-9]{32}\.part)?',file.name):continue
                            path=Path(file.path)
                            if file.is_file(follow_symlinks=False) and path.resolve().parent==directory and file.stat(follow_symlinks=False).st_mtime<cutoff:
                                with contextlib.suppress(OSError):path.unlink()
                except OSError:continue
    def _run(self):
        owner=contextlib.ExitStack()
        try:
            with contextlib.suppress(OSError):owner.enter_context(self._stage_owner(self.service.session,create=True))
            with contextlib.suppress(OSError):self._sweep_stages()
            with contextlib.suppress(Exception):self.cache.gc()
            while not self.stopping.is_set():
                try:kind,value=self.queue.get(timeout=.03)
                except queue.Empty:kind=None
                if kind=='job':
                    try:self._execute(value)
                    except Exception as exc:self._cleanup_sync(value);self._cleanup_hydration(value);self._finish(value,error=exc)
                elif kind=='details':
                    with self.lock:pending=self.pending_details.pop(value,None)
                    if pending is not None:request,details,args=pending
                    if pending is not None and self._live(request):
                        with contextlib.suppress(Exception):
                            scope=args.get('cache_scope') or {'schema':request['source']['options'].get('schema',''),'include_system':False}
                            self.cache.put_details(details['cache_identity'],details,scope,
                                                   observed_generation=args.get('cache_generation'))
                for jid in list(self.syncs):
                    try:self._step_sync(jid)
                    except Exception as exc:self._cleanup_sync(jid);self._finish(jid,error=exc)
                for jid in list(self.hydrations):
                    try:self._step_hydration(jid)
                    except Exception as exc:self._cleanup_hydration(jid);self._finish(jid,error=exc)
        finally:
            for jid in list(self.hydrations):
                state=self.hydrations[jid]
                if state.get('worker_id'):
                    with contextlib.suppress(Exception):self.service.hub.cancel(state['worker_id'])
                with contextlib.suppress(Exception):self._cleanup_hydration(jid)
            for jid in list(self.syncs):
                state=self.syncs[jid]
                if state.get('worker_id'):
                    with contextlib.suppress(Exception):self.service.hub.cancel(state['worker_id'])
                with contextlib.suppress(Exception):self._cleanup_sync(jid)
            for jid in self.running():self._finish(jid,error=Cancelled())
            with self.lock:self.pending_details.clear()
            with contextlib.suppress(Exception):self.cache.close()
            with contextlib.suppress(OSError):owner.close()
    def close(self):
        with self.service.lock:
            self.cancel_all();self.stopping.set()
        if self.thread and self.thread is not threading.current_thread():self.thread.join()


# Native prompt access is independent of COM: Excel can display a modal dialog
# while its COM worker is blocked. Call these helpers on a local I/O thread.
EXCEL_NATIVE_SCAN_SECONDS = .8


class _ExcelNativeWindows:
    def __init__(self):
        if os.name!='nt':raise UserError('Sterowanie komunikatami Excela wymaga Windows.')
        import ctypes as C
        self.c=C;self.user=C.WinDLL('user32',use_last_error=True);u=self.user
        self.callback=C.WINFUNCTYPE(C.c_int,C.c_void_p,C.c_ssize_t)
        signatures=(
            ('IsWindow',[C.c_void_p],C.c_int),('IsWindowVisible',[C.c_void_p],C.c_int),
            ('IsWindowEnabled',[C.c_void_p],C.c_int),('IsChild',[C.c_void_p,C.c_void_p],C.c_int),
            ('GetWindowThreadProcessId',[C.c_void_p,C.POINTER(C.c_uint32)],C.c_uint32),
            ('GetWindow',[C.c_void_p,C.c_uint],C.c_void_p),('GetAncestor',[C.c_void_p,C.c_uint],C.c_void_p),
            ('GetClassNameW',[C.c_void_p,C.c_wchar_p,C.c_int],C.c_int),
            ('GetWindowLongW',[C.c_void_p,C.c_int],C.c_long),('GetDlgCtrlID',[C.c_void_p],C.c_int),
            ('EnumWindows',[self.callback,C.c_ssize_t],C.c_int),
            ('EnumChildWindows',[C.c_void_p,self.callback,C.c_ssize_t],C.c_int),
            ('SendMessageTimeoutW',[C.c_void_p,C.c_uint,C.c_size_t,C.c_ssize_t,C.c_uint,C.c_uint,C.POINTER(C.c_size_t)],C.c_ssize_t),
            ('PostMessageW',[C.c_void_p,C.c_uint,C.c_size_t,C.c_ssize_t],C.c_int),
            ('SetForegroundWindow',[C.c_void_p],C.c_int),('BringWindowToTop',[C.c_void_p],C.c_int))
        for name,args,result in signatures:fn=getattr(u,name);fn.argtypes=args;fn.restype=result
    def pid(self,hwnd):
        value=self.c.c_uint32()
        return value.value if self.user.IsWindow(hwnd) and self.user.GetWindowThreadProcessId(hwnd,self.c.byref(value)) else 0
    def visible(self,hwnd):return bool(self.user.IsWindowVisible(hwnd))
    def enabled(self,hwnd):return bool(self.user.IsWindowEnabled(hwnd))
    def owner(self,hwnd):return int(self.user.GetWindow(hwnd,4) or 0)
    def root(self,hwnd):return int(self.user.GetAncestor(hwnd,2) or 0)
    def child(self,parent,hwnd):return bool(self.user.IsChild(parent,hwnd))
    def style(self,hwnd):return int(self.user.GetWindowLongW(hwnd,-16)) & 0xffffffff
    def control_id(self,hwnd):return int(self.user.GetDlgCtrlID(hwnd))
    def class_name(self,hwnd):
        buffer=self.c.create_unicode_buffer(256)
        return buffer.value if self.user.GetClassNameW(hwnd,buffer,len(buffer)) else ''
    def windows(self,parent=0,deadline=None,limit=1024):
        result=[];complete=True
        def visit(hwnd,_):
            nonlocal complete
            if len(result)>=limit or (deadline is not None and time.monotonic()>=deadline):complete=False;return 0
            result.append(int(hwnd));return 1
        callback=self.callback(visit)
        if parent:self.user.EnumChildWindows(parent,callback,0)
        else:self.user.EnumWindows(callback,0)
        return result,complete
    def message(self,hwnd,message,wparam,lparam,deadline):
        remaining=deadline-time.monotonic()
        if remaining<=0:return None
        result=self.c.c_size_t()
        # ABORTIFHUNG | BLOCK | ERRORONEXIT, never NOTIMEOUTIFNOTHUNG.
        ok=self.user.SendMessageTimeoutW(hwnd,message,wparam,lparam,0x23,max(1,min(50,int(remaining*1000))),self.c.byref(result))
        return int(result.value) if ok else None
    def text(self,hwnd,deadline,limit=4096):
        buffer=self.c.create_unicode_buffer(limit+1)
        count=self.message(hwnd,0x000d,len(buffer),self.c.addressof(buffer),deadline)
        return (buffer.value,count is not None and count<limit)
    def checked(self,hwnd,deadline):return self.message(hwnd,0x00f0,0,0,deadline)
    def activate(self,hwnd):
        self.user.BringWindowToTop(hwnd);self.user.SetForegroundWindow(hwnd)
    def click(self,hwnd):return bool(self.user.PostMessageW(hwnd,0x00f5,0,0))


def _excel_native_target(api,pid,main_hwnd):
    return (isinstance(pid,int) and not isinstance(pid,bool) and 0<pid<=0xffffffff
            and isinstance(main_hwnd,int) and not isinstance(main_hwnd,bool) and main_hwnd>0
            and api.pid(main_hwnd)==pid and api.root(main_hwnd)==main_hwnd)


def _excel_native_owned_modal(api,pid,main_hwnd,hwnd):
    if hwnd==main_hwnd or api.pid(hwnd)!=pid or api.root(hwnd)!=hwnd or api.class_name(hwnd)!='#32770' or not api.visible(hwnd):return False
    seen={hwnd};owner=api.owner(hwnd);disabled=False
    for _ in range(16):
        if not owner or owner in seen or api.pid(owner)!=pid:return False
        disabled=disabled or not api.enabled(owner)
        # Excel SDI can create another workbook window in the same exclusively
        # owned process. Its modal prompt belongs to this session as well.
        if owner==main_hwnd or (api.root(owner)==owner and api.class_name(owner)=='XLMAIN'):return disabled
        seen.add(owner);owner=api.owner(owner)
    return False


def _excel_native_snapshot(api,pid,main_hwnd,hwnd,deadline):
    if not _excel_native_target(api,pid,main_hwnd) or not _excel_native_owned_modal(api,pid,main_hwnd,hwnd):return None
    title,complete=api.text(hwnd,deadline);texts=[];buttons=[];controls=[];total=len(title)
    children,all_children=api.windows(hwnd,deadline,128);complete=complete and all_children
    for child in children:
        if time.monotonic()>=deadline:complete=False;break
        if api.pid(child)!=pid or not api.child(hwnd,child):complete=False;continue
        if not api.visible(child):continue
        class_name=api.class_name(child);style=api.style(child)
        if class_name.casefold()=='static' and style & 0x1f in (3,14,15):continue  # Icon / bitmap, not text.
        # Password edit controls are never read or echoed into application state.
        if class_name.casefold()=='edit' and style & 0x20:text='[Pole hasła — treść ukryta]';read_ok=True
        else:text,read_ok=api.text(child,deadline)
        complete=complete and read_ok;total+=len(text)
        if total>16384:complete=False;break
        control={'hwnd':child,'class':class_name,'text':text,'enabled':api.enabled(child),'id':api.control_id(child)}
        if class_name.casefold()=='button':
            kind=style & 0xf
            if kind in (0,1,11,12,13,14,15):
                if len(buttons)>=32:complete=False;break
                buttons.append({k:control[k] for k in ('hwnd','text','id','enabled')})
            else:
                if kind in (2,3,4,5,6,9):
                    checked=api.checked(child,deadline);complete=complete and checked is not None;control['checked']=checked
                    text=('☑ ' if checked==1 else '☐ ' if checked==0 else '▣ ')+text
                if text:texts.append(text)
        elif text:texts.append(text)
        controls.append(control)
    if not _excel_native_target(api,pid,main_hwnd) or not _excel_native_owned_modal(api,pid,main_hwnd,hwnd):return None
    identity={'pid':pid,'main_hwnd':main_hwnd,'hwnd':hwnd,'owner':api.owner(hwnd),'title':title,
              'text':'\n'.join(texts),'buttons':buttons,'enabled':api.enabled(hwnd),'complete':bool(complete),'controls':controls}
    fingerprint=digest(identity);identity.pop('controls');identity['fingerprint']=fingerprint
    if not complete:identity['notice']='Nie odczytano całego komunikatu. Użyj oryginalnego okna Excela.'
    return identity


def excel_native_dialogs(pid,main_hwnd):
    """Only native modal dialogs owned by this exact Excel window/process.

    No COM, hooks, keyboard events or automatic actions. Discovery is bounded,
    but must run outside the GUI thread because foreign WM_GETTEXT can time out.
    The caller also checks its session's owned process handle remains alive.
    """
    if os.name!='nt':return []
    api=_ExcelNativeWindows()
    if not _excel_native_target(api,pid,main_hwnd):return []
    deadline=time.monotonic()+EXCEL_NATIVE_SCAN_SECONDS;result=[]
    windows,_=api.windows(deadline=deadline)
    for hwnd in windows:
        if len(result)>=8 or time.monotonic()>=deadline:break
        if _excel_native_owned_modal(api,pid,main_hwnd,hwnd):
            value=_excel_native_snapshot(api,pid,main_hwnd,hwnd,deadline)
            if value is not None:result.append(value)
    return result


def excel_native_dialog_skip_button(snapshot):
    """A label suggestion only; callers still require a deliberate user click."""
    if not isinstance(snapshot,dict) or not snapshot.get('complete') or not snapshot.get('enabled',True):return None
    buttons=[b for b in snapshot.get('buttons',[]) if isinstance(b,dict) and b.get('enabled')]
    def caption(button):return re.sub(r'\s+',' ',str(button.get('text','')).replace('&','')).strip().casefold()
    ignores=[b for b in buttons if caption(b) in ('ignoruj','ignore')]
    if len(ignores)==1:return clone(ignores[0])
    prompt=str(snapshot.get('text','')).casefold()
    asks_abort=bool(re.search(r'\bczy\s+(?:chcesz\s+)?przerwa[ćc]\b|\b(?:do you want to|would you like to)\s+abort\b',prompt))
    no=[b for b in buttons if caption(b) in ('nie','no')]
    return clone(no[0]) if asks_abort and len(no)==1 else None


def excel_native_dialog_action(pid,main_hwnd,dialog_snapshot,button_hwnd):
    """Revalidate an observed native button and queue one BM_CLICK, never wait."""
    stale='Komunikat Excela zmienił się lub został zamknięty. Odśwież jego podgląd; niczego nie kliknięto.'
    if not isinstance(dialog_snapshot,dict) or not dialog_snapshot.get('complete'):raise UserError('Niepełny podgląd komunikatu. Użyj oryginalnego okna Excela.')
    if not isinstance(button_hwnd,int) or isinstance(button_hwnd,bool) or button_hwnd<=0:raise UserError(stale)
    if dialog_snapshot.get('pid')!=pid or dialog_snapshot.get('main_hwnd')!=main_hwnd:raise UserError(stale)
    hwnd=dialog_snapshot.get('hwnd')
    if not isinstance(hwnd,int) or isinstance(hwnd,bool) or hwnd<=0:raise UserError(stale)
    api=_ExcelNativeWindows();deadline=time.monotonic()+EXCEL_NATIVE_SCAN_SECONDS
    current=_excel_native_snapshot(api,pid,main_hwnd,hwnd,deadline)
    if not current or not current['complete'] or current['fingerprint']!=dialog_snapshot.get('fingerprint') or not current['enabled']:raise UserError(stale)
    button=next((b for b in current['buttons'] if b['hwnd']==button_hwnd),None)
    if not button or not button['enabled'] or api.pid(button_hwnd)!=pid or not api.child(hwnd,button_hwnd):raise UserError(stale)
    api.activate(hwnd)
    # Activation may have dismissed/replaced the prompt. Check again before posting.
    confirmed=_excel_native_snapshot(api,pid,main_hwnd,hwnd,deadline)
    if (not confirmed or confirmed['fingerprint']!=current['fingerprint'] or not confirmed['complete']
            or not _excel_native_target(api,pid,main_hwnd) or not _excel_native_owned_modal(api,pid,main_hwnd,hwnd)
            or api.pid(button_hwnd)!=pid or not api.child(hwnd,button_hwnd)
            or not api.visible(button_hwnd) or not api.enabled(button_hwnd)):raise UserError(stale)
    if not api.click(button_hwnd):raise UserError('Windows nie przyjął kliknięcia. Użyj oryginalnego okna Excela i odśwież podgląd.')
    return {'ok':True,'sent':True,'hwnd':hwnd,'button_hwnd':button_hwnd,
            'message':'Wysłano kliknięcie do okna Excela. Wynik sprawdź po odświeżeniu komunikatów.'}


class ApplicationService:
    def __init__(self,root):
        self.root=private_dir(Path(root)); self.session=private_dir(self.root/'sessions'/uid())
        self.import_dir=private_dir(self.root/'imports'); self.resource_dir=private_dir(self.root/'resources')
        self.recovery_dir=private_dir(self.root/'recovery'); self.recovery_path=self.recovery_dir/(self.session.name+'.json')
        self.settings_path=self.root/'settings.json'
        try: self.settings=json.loads(self.settings_path.read_text('utf-8'))
        except (OSError,ValueError): self.settings={}
        self.document=new_project(); self.saved_fingerprint=digest(self.document); self.project_path=''; self.disk_digest=None
        self.lock=threading.RLock(); self.hub=WorkerHub(); self.secrets=SecretStore(); self.trusted=set(); self.trusted_sql=set()
        self.results={}; self.finalized=set(); self.generation=0
        self.quit_event=threading.Event(); self.cleanup_recovery=False; self.local_jobs={}
        self.export_authorizations={}
        self.workbooks=WorkbookCoordinator(self)
        self.catalog_cache=CatalogCacheCoordinator(self)
    def dirty(self): return digest(self.document)!=self.saved_fingerprint
    def checkpoint(self):
        if self.dirty():
            atomic_bytes(self.recovery_path,dumps({'project':self.document,'saved_path':self.project_path,'time':utcnow()}).encode('utf-8'))
        else:
            with contextlib.suppress(FileNotFoundError): self.recovery_path.unlink()
    def source(self,sid):
        source=next((s for s in self.document['sources'] if s['id']==sid),None)
        if source is None: raise UserError('Nie znaleziono źródła.')
        return source
    def authorize(self,source,dataset=None):
        if digest(source) not in self.trusted:
            raise UserError('Potwierdź połączenie ze źródłem. Otwieranie projektu nie uruchamia połączeń.')
        if dataset and dataset.get('sql') and digest({'source':source,'sql':dataset['sql']}) not in self.trusted_sql:
            raise UserError('Własny SQL wymaga osobnego potwierdzenia wykonania.')
    def save_analysis(self,raw):
        a=validate_analysis(raw); source=self.source(a['dataset']['source_id'])
        if source['kind']=='xlsx':workbook_version(source,a['dataset'])
        index=next((i for i,x in enumerate(self.document['analyses']) if x['id']==a['id']),None)
        if index is None:
            if len(self.document['analyses'])>=200: raise UserError('Limit 200 analiz.')
            self.document['analyses'].append(a)
        else: self.document['analyses'][index]=a
        self.document['active']=a['id']; self.checkpoint(); return a
    def add_local_analysis(self,source,analysis):
        """Publish a read-only SQLite source and analysis together, only after user approval."""
        with self.lock:
            source=validate_source(source);analysis=validate_analysis(analysis)
            if source['kind']!='sqlite' or analysis['dataset']['source_id']!=source['id']:
                raise UserError('Niezgodne źródło lokalnej analizy.')
            old=next((s for s in self.document['sources'] if s['id']==source['id']),None)
            if old is not None and old!=source:raise UserError('Połączenie zmieniło się. Ponownie wybierz tabelę.')
            if old is None and len(self.document['sources'])>=100:raise UserError('Limit 100 źródeł.')
            if len(self.document['analyses'])>=200:raise UserError('Limit 200 analiz.')
            if any(a['id']==analysis['id'] for a in self.document['analyses']):raise UserError('Analiza już istnieje.')
            before=clone(self.document);trusted=set(self.trusted)
            try:
                if old is None:self.document['sources'].append(source)
                self.trusted.add(digest(source));self.save_analysis(analysis)
            except Exception:
                self.document=before;self.trusted=trusted;raise
            return {'source':source,'analysis':analysis}

    def check_current_result(self,rid,raw_analysis=None):
        if rid not in self.results: raise UserError('Wynik nie istnieje w tej sesji. Odśwież analizę.')
        result=self.results[rid]; meta=result['meta']
        if result.get('browse_only'):
            source=self.source(meta['source_id'])
            if result['source_fingerprint']!=source_data_fingerprint(source,meta['analysis']['dataset']):
                raise UserError('Wersja danych przeglądu jest niedostępna.')
            return result
        current=next((a for a in self.document['analyses'] if a['id']==meta['analysis_id']),None)
        if (not current or digest(current)!=meta['fingerprint'] or
                (raw_analysis is not None and digest(validate_analysis(raw_analysis))!=meta['fingerprint'])):
            raise UserError('Wynik nie odpowiada bieżącej konfiguracji. Najpierw kliknij Zastosuj.')
        source=self.source(meta['source_id'])
        if result.get('source_fingerprint')!=source_data_fingerprint(source,meta['analysis']['dataset']):
            raise UserError('Definicja połączenia zmieniła się. Odśwież wynik.')
        return result
    def cell_export_destination(self,value):
        text=clean_text(value,2048)
        if not text:raise UserError('Wybierz plik docelowy eksportu komórki.')
        destination=Path(text).expanduser().resolve()
        if not destination.parent.is_dir() or destination.is_dir():raise UserError('Wybierz plik w istniejącym katalogu eksportu.')
        protected={Path(__file__).resolve()}
        if self.project_path:protected.add(Path(self.project_path).resolve())
        def protect(path):
            if path and not str(path).startswith('@'):protected.add(Path(path).expanduser().resolve())
        for book in self.document.get('workpads',[]):protect(book.get('origin'))
        for source in self.document['sources']:
            options=source['options'];kind=source['kind']
            if kind in ('sqlite','xlsx'):protect(options.get('path'))
            if kind=='xlsx':
                protect(options.get('origin'))
                for dataset in source['workbook']['datasets']:
                    for version in dataset['versions']:protect(version.get('path'))
            elif kind=='h2' and options.get('mode','file')=='file':
                path=options.get('path','');protect(path)
                if path:
                    for suffix in ('.mv.db','.h2.db','.lock.db','.trace.db'):protect(path+suffix)
            elif kind=='firebird' and options.get('host','').lower() in ('','localhost','127.0.0.1','::1'):
                protect(options.get('database'))
        if destination in protected or destination.is_relative_to(self.root.resolve()):
            raise UserError('Eksport komórki nie może nadpisać źródła, projektu ani prywatnych plików aplikacji.')
        return str(destination)
    def submit_db(self,op,args,source):
        self.authorize(source,args.get('analysis',{}).get('dataset') or args.get('dataset'))
        output=str(self.session/(uid()+'.sqlite')) if op in ('pivot','preview','drill') else ''
        jid=self.hub.submit(op,args,source,self.secrets.get(source),self.settings,output,int(self.settings.get('timeout',60)))
        self.hub.jobs[jid]['generation']=self.generation
        self.hub.jobs[jid]['source_fingerprint']=source_data_fingerprint(source,args.get('dataset') or args.get('analysis',{}).get('dataset'))
        return {'job_id':jid}
    def finalize(self,jid):
        if jid in self.finalized: return
        with self.hub.lock:
            job=self.hub.jobs.get(jid)
            if not job or job['status']!='done': return
            if job.get('generation',self.generation)!=self.generation:
                if job['operation'].startswith('workbook_'):self.workbooks.cleanup_job(job)
                job.update(status='cancelled',error='Projekt został zmieniony. Stary wynik został odrzucony.'); self.finalized.add(jid); return
            if job['operation'].startswith('database_'):
                try:current_source=self.source(job['source_id'])
                except UserError:current_source=None
                if current_source is None or job.get('source_fingerprint')!=source_data_fingerprint(current_source):
                    job.update(status='cancelled',error='Źródło zmieniono lub usunięto. Odrzucono spóźnione metadane/dane.');self.finalized.add(jid);return
            if job['operation'] in ('pivot','preview','drill'):
                self.results[jid]={'path':job['output'],'meta':job['value'],'source_fingerprint':job.get('source_fingerprint'),'browse_only':job.get('browse_only',False)}
                job['value']['result_id']=jid
            elif job['operation'].startswith('workbook_'):
                try:self.workbooks.finalize(job)
                except Exception as exc:job.update(status='error',error=safe_error(exc))
            elif job['operation']=='database_object_details':self.catalog_cache.remember_details(job)
            elif job['operation']=='import':
                value=job['value'];source=validate_source({'kind':'sqlite','name':Path(job['args']['path']).stem,
                        'options':{'path':value['path'],'owned':True}})
                analysis=validate_analysis({'name':source['name'],'dataset':{'source_id':source['id'],'schema':'main','table':'dane'},
                                    'measures':[{'agg':'count_rows','label':'Liczba rekordów','format':'integer'}]})
                try:value.update(self.add_local_analysis(source,analysis))
                except Exception as exc:
                    job.update(status='error',error=safe_error(exc))
                    # Only our unregistered import output is eligible for cleanup.
                    output=Path(job['output'])
                    if output.parent==self.import_dir and not any(s['options'].get('path')==str(output) for s in self.document['sources']):
                        with contextlib.suppress(OSError):output.unlink()
            self.finalized.add(jid)
    def start_install(self,profile):
        if profile not in INSTALL_PROFILE_LABELS: raise UserError('Nieznany profil.')
        if any(j['status']=='running' for j in self.local_jobs.values()): raise UserError('Instalacja już trwa.')
        jid=uid(); job={'id':jid,'status':'running','stage':'Przygotowanie instalatora','operation':'install','log':[]}; self.local_jobs[jid]=job
        def install():
            try:
                def progress(text):
                    with self.lock:
                        job['log'].append(text); job['log']=job['log'][-50:]; job['stage']=text
                value=install_environment(profile,progress=progress)
                with self.lock: job.update(status='done',value={'message':'Instalacja zakończona. Uruchom aplikację ponownie.','profiles':value['profiles']})
            except Exception as exc:
                with self.lock: job.update(status='error',error=safe_error(exc))
        threading.Thread(target=install,daemon=True).start(); return {'job_id':jid}
    def call(self,action,args):
        if not isinstance(args,dict): raise UserError('Nieprawidłowe parametry.')
        with self.lock:
            if action in CatalogCacheCoordinator.ACTIONS:
                source=self.source(args['source_id'])
                if source['kind']!='oracle':raise UserError('Lokalny katalog dotyczy źródeł Oracle.')
                if action in CatalogCacheCoordinator.BACKGROUND:self.authorize(source)
                return self.catalog_cache.submit(action,{k:v for k,v in args.items() if k!='source_id'},source)
            if action.startswith('workbook_'):return self.workbooks.handle(action,args)
            if action=='state':
                recoveries=[{'id':p.stem,'time':dt.datetime.fromtimestamp(p.stat().st_mtime).isoformat(timespec='seconds')}
                            for p in sorted(self.recovery_dir.glob('*.json'),key=lambda p:p.stat().st_mtime,reverse=True)
                            if p!=self.recovery_path][:5]
                return {'document':self.document,'path':self.project_path,'dirty':self.dirty(),'diagnostics':diagnostics(self.settings),
                        'recoveries':recoveries,'trusted':[s['id'] for s in self.document['sources'] if digest(s) in self.trusted],
                        'root':str(self.root),'native_ui':True}
            if action=='source_save':
                if args.get('source',{}).get('kind')=='xlsx':raise UserError('Skoroszyt dodaj przez Importuj plik, nie przez formularz połączenia.')
                source=validate_source(args['source']); old=next((s for s in self.document['sources'] if s['id']==source['id']),None)
                if old and old['kind']!=source['kind'] and any(v['plan']['source_id']==source['id'] for v in self.document.get('join_views',[])):raise UserError('Zapisane połączenia wymagają dotychczasowego silnika. Dodaj nowe źródło zamiast zmieniać jego rodzaj.')
                if source['kind']=='sqlite':
                    p=Path(source['options'].get('path','')).expanduser().resolve()
                    source['options']['owned']=any(p.is_relative_to(r.resolve()) for r in (self.import_dir,self.resource_dir))
                    source['options']['path']=str(p)
                if 'password' in args and (args['password'] or args.get('clear_password')):
                    self.secrets.set(source,str(args['password']),bool(args.get('remember')))
                if old:
                    self.document['sources'][self.document['sources'].index(old)]=source
                    if digest(old)!=digest(source): self.trusted.discard(digest(old))
                else:
                    if len(self.document['sources'])>=100: raise UserError('Limit 100 źródeł.')
                    self.document['sources'].append(source)
                self.checkpoint(); return {'source':source}
            if action=='database_join_save':
                view=database_saved_join(args.get('view'));source=self.source(view['plan']['source_id'])
                if source['kind']!=view['plan']['backend']:raise UserError('Plan należy do innego źródła.')
                values=self.document.setdefault('join_views',[])
                existing=next((v for v in values if v['id']==view['id'] or (v['name']==view['name'] and digest(v['plan'])==digest(view['plan']))),None)
                if existing:
                    view=dict(view,id=existing['id']);values[values.index(existing)]=view
                else:
                    if len(values)>=100:raise UserError('Limit 100 zapisanych połączeń tabel.')
                    values.append(view)
                self.checkpoint();return {'view':view}
            if action=='source_delete':
                source=self.source(args['source_id'])
                if any(a['dataset']['source_id']==source['id'] for a in self.document['analyses']):
                    raise UserError('Najpierw usuń analizy korzystające z tego źródła.')
                self.document['join_views']=[v for v in self.document.get('join_views',[]) if v['plan']['source_id']!=source['id']]
                self.document['sources'].remove(source); self.secrets.forget(source); self.trusted.discard(digest(source)); self.checkpoint(); return {'ok':True}
            if action=='trust':
                if not args.get('confirmed'): raise UserError('Brak potwierdzenia.')
                source=self.source(args['source_id']); self.trusted.add(digest(source))
                if args.get('sql'): self.trusted_sql.add(digest({'source':source,'sql':validate_select(args['sql'])}))
                return {'ok':True}
            if action in ('database_catalog','database_object_details','database_page','database_join_page','database_cell','database_cell_export'):
                source=self.source(args['source_id'])
                if source['kind'] not in ('sqlite','h2','firebird','oracle'):raise UserError('Eksplorator wymaga połączenia z bazą.')
                payload={k:v for k,v in args.items() if k!='source_id'}
                if action=='database_cell_export':payload['destination']=self.cell_export_destination(args.get('destination'))
                return self.submit_db(action,payload,source)
            if action in ('tables','test'):
                source=self.source(args['source_id'])
                if source['kind']=='xlsx':raise UserError('Wybierz nazwany arkusz w katalogu skoroszytu.')
                return self.submit_db(action,{},source)
            if action=='columns':
                d=validate_dataset(args['dataset']); return self.submit_db('columns',{'dataset':d},self.source(d['source_id']))
            if action=='analysis_save': return {'analysis':self.save_analysis(args['analysis']),'dirty':self.dirty()}
            if action=='analysis_delete':
                self.document['analyses']=[a for a in self.document['analyses'] if a['id']!=args['id']]
                self.document['active']=self.document['analyses'][0]['id'] if self.document['analyses'] else ''
                self.checkpoint(); return {'ok':True}
            if action=='active':
                if not any(a['id']==args['id'] for a in self.document['analyses']): raise UserError('Analiza nie istnieje.')
                self.document['active']=args['id']; return {'ok':True}
            if action=='browse':
                d=validate_dataset(args['dataset']);source=self.source(d['source_id'])
                if source['kind']!='xlsx':raise UserError('Podgląd katalogu wymaga skoroszytu.')
                a=validate_analysis({'id':'browse-'+d['dataset_id'],'name':dataset_caption(source,d),
                                    'dataset':d,'measures':[{'agg':'count_rows','label':'Liczba rekordów'}]})
                response=self.submit_db('preview',{'analysis':a},source)
                self.hub.jobs[response['job_id']]['browse_only']=True
                return response
            if action in ('pivot','preview','plan'):
                a=self.save_analysis(args['analysis']); return self.submit_db(action,{'analysis':a},self.source(a['dataset']['source_id']))
            if action=='drill':
                result=self.check_current_result(args['result_id'],args.get('analysis'))
                analysis,filters=ResultStore.drill_filters(result['path'],args['row_id'],args['column_id'])
                return self.submit_db('drill',{'analysis':analysis,'extra':filters},self.source(analysis['dataset']['source_id']))
            if action=='job':
                jid=args['id']
                if jid in self.catalog_cache.jobs:return self.catalog_cache.poll(jid)
                if jid in self.local_jobs: return self.local_jobs[jid]
                self.finalize(jid); return self.hub.poll(jid)
            if action=='cancel':
                if args['id'] in self.catalog_cache.jobs:return self.catalog_cache.cancel(args['id'])
                return self.hub.cancel(args['id'])
            if action=='result_page':
                r=self.results.get(args['id'])
                if r is None: raise UserError('Wynik nie istnieje.')
                return ResultStore.page(r['path'],args.get('page',0),args.get('sort'),args.get('direction','asc'))
            if action=='chart':
                result=self.results.get(args['id'])
                if result is None: raise UserError('Wynik nie istnieje.')
                meta=result['meta']; cols=meta['columns']
                index=next((i for i,c in enumerate(cols) if c['id']==args.get('column') and c['kind']=='number' and c.get('measure')),None)
                if index is None: raise UserError('Wybierz liczbową kolumnę miary.')
                dimensions=[i for i,c in enumerate(cols) if c.get('dimension')]; ranked=[]
                for row,total in ResultStore.iter_rows(result['path']):
                    if total or row[index] is None or row[index].get('t')!='n': continue
                    value=Decimal(row[index]['v']); label=' / '.join(display_cell(row[i]) for i in dimensions) or 'Wynik'
                    ranked.append((abs(value),value,label,row[index]))
                    if len(ranked)>40: ranked=sorted(ranked,key=lambda x:x[0],reverse=True)[:20]
                ranked=sorted(ranked,key=lambda x:x[0],reverse=True)[:20]
                scale=max((x[0] for x in ranked),default=Decimal(1)) or Decimal(1)
                return {'items':[{'label':label,'display':display_cell(cell,cols[index]['format']),
                                  'width':float(magnitude/scale*100),'negative':value<0}
                                 for magnitude,value,label,cell in ranked]}
            if action=='result_meta':
                r=self.results.get(args['id'])
                if r is None: raise UserError('Wynik nie istnieje.')
                return r['meta']
            if action=='export':
                result=self.check_current_result(args['result_id'],args.get('analysis'))
                destination=Path(clean_text(args.get('path'),2048)).expanduser().resolve()
                fmt=args.get('format','xlsx'); destination=destination.with_suffix('.'+fmt)
                if not destination.parent.is_dir(): raise UserError('Katalog eksportu nie istnieje.')
                # Never overwrite a source DB, project, application or private resource through export.
                protected={Path(__file__).resolve()}
                if self.project_path: protected.add(Path(self.project_path).resolve())
                for s in self.document['sources']:
                    if s['kind']=='sqlite':protected.add(Path(s['options']['path']).resolve())
                    elif s['kind']=='xlsx':
                        for path in (s['options'].get('path'),s['options'].get('origin')):
                            if path and not path.startswith('@'):protected.add(Path(path).resolve())
                        for d in s['workbook']['datasets']:
                            for v in d['versions']:
                                if v['path'] and not v['path'].startswith('@'):protected.add(Path(v['path']).resolve())
                if destination in protected: raise UserError('Eksport nie może nadpisać źródła ani projektu.')
                if destination.exists() and not args.get('overwrite'): raise UserError('Plik istnieje. Potwierdź zastąpienie albo wybierz nową nazwę.')
                jid=self.hub.submit('export',{'result_path':result['path'],'destination':str(destination),'format':fmt})
                return {'job_id':jid}
            if action=='inspect_file':
                path=incoming_file_plan([args['path']])[0]['path']
                return {'job_id':self.hub.submit('inspect_file',{'path':path})}
            if action=='import_preview':
                jid=self.hub.submit('import_preview',{'path':clean_text(args['path'],2048),'options':args.get('options',{})})
                return {'job_id':jid}
            if action=='import':
                if len(self.document['sources'])>=100 or len(self.document['analyses'])>=200:raise UserError('Osiągnięto limit źródeł lub analiz projektu.')
                jid=self.hub.submit('import',{'path':clean_text(args['path'],2048),'options':args.get('options',{}),'columns':args['columns'],'file_state':args.get('file_state')},
                                    output=str(self.import_dir/(uid()+'.sqlite')))
                self.hub.jobs[jid]['generation']=self.generation; return {'job_id':jid}
            if action=='demo':
                source,analysis=create_demo(self.import_dir); self.document['sources'].append(source)
                self.trusted.add(digest(source)); self.save_analysis(analysis); return {'source':source,'analysis':analysis}
            if action=='project_save':
                path=clean_text(args.get('path') or self.project_path,2048)
                if not path: raise UserError('Wybierz nazwę pliku projektu.')
                actual=Path(path).expanduser().resolve().with_suffix('.pivot')
                expected=self.disk_digest if self.project_path and actual==Path(self.project_path).resolve() else None
                path,checksum=ProjectStore.save(actual,self.document,expected,bool(args.get('include_data')),
                                               (self.import_dir,self.resource_dir),bool(args.get('include_originals')))
                self.project_path=path; self.disk_digest=checksum; self.saved_fingerprint=digest(self.document); self.checkpoint()
                return {'path':path,'dirty':False}
            if action in ('project_open','project_new','recover'):
                if self.hub.running(): raise UserError('Zakończ lub anuluj aktywne zadania przed zmianą projektu.')
                if self.dirty() and not args.get('discard'): raise UserError('Projekt ma niezapisane zmiany. Zapisz go lub potwierdź porzucenie zmian.')
                if action=='project_open':
                    path=Path(clean_text(args.get('path'),2048)).expanduser().resolve()
                    p,checksum=ProjectStore.load(path,self.resource_dir)
                    self.document=p; self.project_path=str(path); self.disk_digest=checksum; self.saved_fingerprint=digest(p)
                elif action=='recover':
                    rid=clean_text(args.get('id'),64)
                    if not re.fullmatch('[a-f0-9]{32}',rid): raise UserError('Nieprawidłowy identyfikator odzyskiwania.')
                    file=self.recovery_dir/(rid+'.json')
                    if not file.is_file() or file.stat().st_size>SHEET_MAX_BYTES+65536: raise UserError('Nie znaleziono poprawnej kopii roboczej.')
                    p=validate_project(json.loads(file.read_text('utf-8'))['project'])
                    self.document=p; self.project_path=''; self.disk_digest=None; self.saved_fingerprint=''
                else:
                    self.document=new_project(); self.project_path=''; self.disk_digest=None; self.saved_fingerprint=digest(self.document)
                self.generation+=1; self.trusted.clear(); self.trusted_sql.clear(); self.results.clear(); self.checkpoint()
                self.catalog_cache.cancel_all()
                return {'document':self.document,'path':self.project_path,'dirty':self.dirty()}
            if action=='settings':
                allowed={'h2_jar','oracle_client','firebird_client','timeout'}
                data=args.get('settings',{})
                if not isinstance(data,dict) or set(data)-allowed: raise UserError('Nieobsługiwane ustawienie.')
                timeout=int(data.get('timeout',60))
                if not 5<=timeout<=600: raise UserError('Limit czasu musi wynosić 5–600 sekund.')
                self.settings={k:clean_text(data.get(k,''),2048) for k in allowed-{'timeout'}}; self.settings['timeout']=timeout
                atomic_bytes(self.settings_path,dumps(self.settings).encode('utf-8')); return {'ok':True}
            if action=='install': return self.start_install(args['profile'])
            if action=='quit':
                self.catalog_cache.cancel_all()
                if self.hub.running():
                    for jid in self.hub.running(): self.hub.cancel(jid)
                    raise UserError('Wysłano żądania anulowania. Zamknij aplikację po zakończeniu zadań.')
                if any(j['status']=='running' for j in self.local_jobs.values()): raise UserError('Instalator jeszcze pracuje. Zakończ aplikację po instalacji.')
                if self.dirty() and not args.get('discard'): raise UserError('Zapisz projekt lub potwierdź odrzucenie niezapisanych zmian.')
                self.cleanup_recovery=True; self.quit_event.set(); return {'ok':True}
            raise UserError('Nieznana operacja aplikacji.')
    def close(self):
        self.catalog_cache.close()
        self.hub.close(); self.secrets.memory.clear(); self.workbooks.close()
        if self.cleanup_recovery or not self.dirty():
            with contextlib.suppress(FileNotFoundError): self.recovery_path.unlink()
        # Windows workers may still be closing result files. Only remove our own random session.
        with contextlib.suppress(OSError): shutil.rmtree(self.session)

def prepare_restart_handoff(service, context=None):
    """Save and read back an isolated restart copy before touching the live GUI.

    Only document data and source identity cross the restart. Passwords, trust,
    SQL authorization and active jobs never do. The original save target and
    dirty state are retained so a private recovery copy cannot masquerade as a
    successful save to the user's project file.
    """
    context=context or {}
    with service.lock:
        service.catalog_cache.cancel_all()
        if service.hub.running():raise UserError('Zakończ lub anuluj zadania przed ponownym uruchomieniem.')
        if any(j.get('status')=='running' for j in service.local_jobs.values()):
            raise UserError('Przygotowanie bibliotek jeszcze trwa.')
        marker=load_runtime_marker()
        if not marker:raise UserError('Nie znaleziono przygotowanego środowiska. Bieżąca sesja pozostaje otwarta.')
        source_id=''
        if context.get('generation',service.generation)==service.generation:
            source=next((s for s in service.document['sources'] if s['id']==context.get('source_id')),None)
            if source and context.get('source_fingerprint')==digest(source):source_id=source['id']
        directory=private_dir(service.recovery_dir/'restarts'/uid())
        snapshot,checksum=ProjectStore.save(directory/'document.pivot',service.document)
        restored,verified=ProjectStore.load(snapshot,service.resource_dir)
        if verified!=checksum or digest(restored)!=digest(validate_project(service.document)):
            raise UserError('Nie potwierdzono kopii roboczej. Nie zamknięto programu.')
        manifest={'version':1,'snapshot_sha256':checksum,'project_path':service.project_path,
                  'disk_digest':service.disk_digest,'saved_fingerprint':service.saved_fingerprint,
                  'source_id':source_id,'created':utcnow()}
        path=directory/'handoff.json';atomic_bytes(path,dumps(manifest).encode('utf-8'))
        return {'path':str(path),'ready_path':str(directory/'ready'),'python':marker['python'],
                'cancel_path':str(directory/'cancelled'),'data_root':str(service.root),'source_id':source_id}


def load_restart_handoff(service, path):
    path=Path(path).expanduser().resolve()
    base=(service.recovery_dir/'restarts').resolve()
    if (path.name!='handoff.json' or not re.fullmatch('[a-f0-9]{32}',path.parent.name)
        or path.parent.parent!=base or not path.is_file() or path.stat().st_size>16384):
        raise UserError('Nieprawidłowa kopia ponownego uruchomienia.')
    if (path.parent/'cancelled').exists():raise Cancelled('Ponowne uruchomienie zostało anulowane przez poprzednią sesję.')
    try:
        value=json.loads(path.read_text('utf-8'))
        if not isinstance(value,dict) or value.get('version')!=1:raise ValueError()
        if set(value)!={'version','snapshot_sha256','project_path','disk_digest','saved_fingerprint','source_id','created'}:raise ValueError()
        for key in ('snapshot_sha256','saved_fingerprint'):
            if not isinstance(value[key],str) or (value[key] and not re.fullmatch('[a-f0-9]{64}',value[key])):raise ValueError()
        if value['disk_digest'] is not None and not re.fullmatch('[a-f0-9]{64}',str(value['disk_digest'])):raise ValueError()
        if not isinstance(value['project_path'],str) or len(value['project_path'])>2048:raise ValueError()
        document,checksum=ProjectStore.load(path.parent/'document.pivot',service.resource_dir)
        if checksum!=value['snapshot_sha256']:raise ValueError()
    except (ValueError,TypeError,KeyError,OSError) as exc:
        raise UserError('Nie potwierdzono kopii ponownego uruchomienia. Poprzednia sesja pozostaje dostępna.') from exc
    service.document=document;service.project_path=value['project_path'];service.disk_digest=value['disk_digest']
    service.saved_fingerprint=value['saved_fingerprint'];service.generation+=1
    service.trusted.clear();service.trusted_sql.clear();service.secrets.memory.clear();service.checkpoint()
    source_id=value['source_id'] if any(s['id']==value['source_id'] for s in document['sources']) else ''
    return {'source_id':source_id,'ready_path':str(path.parent/'ready'),'cancel_path':str(path.parent/'cancelled')}


def launch_restart(handoff):
    """Launch verified new runtime; the caller closes only after the paint ack."""
    path=Path(handoff['path']).resolve();python=Path(handoff['python'])
    if not path.is_file() or not python.is_file():raise UserError('Brak kopii roboczej lub przygotowanego interpretera.')
    if os.name=='nt' and python.with_name('pythonw.exe').is_file():python=python.with_name('pythonw.exe')
    env=installer_environment();env['PIVOTSTUDIO_RUNTIME']='1';env['_PIVOT_GUI_DETACHED']='1'
    with (path.parent/'startup.log').open('ab') as log:
        return subprocess.Popen([str(python),str(Path(__file__).resolve()),'--no-bootstrap','--no-runtime',
                                 '--data-dir',handoff['data_root'],'--resume',str(path)],
                                stdin=subprocess.DEVNULL,stdout=log,stderr=subprocess.STDOUT,
                                env=env,creationflags=CREATE_NO_WINDOW)


# ======================== 8. NATYWNY INTERFEJS QT WIDGETS ====================


def clone(value):
    """Project structures are small, JSON-serializable value objects."""
    return json.loads(dumps(value))


class AnalysisHistory:
    """Bounded value history, independent of Qt and database connections."""
    def __init__(self, analysis, limit=100):
        self.states=[validate_analysis(analysis)]; self.position=0; self.limit=limit
    def push(self, analysis):
        value=validate_analysis(analysis)
        if value==self.states[self.position]: return False
        self.states=self.states[:self.position+1]+[value]
        if len(self.states)>self.limit: self.states=self.states[-self.limit:]
        self.position=len(self.states)-1; return True
    def undo(self):
        if self.position==0: return None
        self.position-=1; return clone(self.states[self.position])
    def redo(self):
        if self.position+1==len(self.states): return None
        self.position+=1; return clone(self.states[self.position])


def copy_result_selection(path, rectangles, sort=None, direction='asc', headers=False):
    """Copy typed values, including not-yet-rendered pages, without loss of precision."""
    meta=ResultStore.metadata(path)
    if not rectangles: return ''
    r0=min(x[0] for x in rectangles); r1=max(x[2] for x in rectangles)
    c0=min(x[1] for x in rectangles); c1=max(x[3] for x in rectangles)
    if not (0<=r0<=r1<meta['row_count'] and 0<=c0<=c1<len(meta['columns'])):
        raise UserError('Zaznaczenie wykracza poza wynik.')
    if (r1-r0+1)*(c1-c0+1)>MAX_CELLS:
        raise UserError('Zaznaczenie jest zbyt duże. Użyj eksportu całego wyniku.')
    output=io.StringIO(); writer=csv.writer(output,delimiter='\t',lineterminator='\n')
    if headers:
        writer.writerow([(c.get('group','')+' / ' if c.get('group') else '')+c['label']
                         for c in meta['columns'][c0:c1+1]])
    for page in range(r0//PAGE_SIZE,r1//PAGE_SIZE+1):
        result=ResultStore.page(path,page,sort,direction)
        for off,row in enumerate(result['rows']):
            ri=page*PAGE_SIZE+off
            if not r0<=ri<=r1: continue
            writer.writerow([csv_safe(row['v'][ci]) if any(a<=ri<=b and c<=ci<=d for a,c,b,d in rectangles)
                             else '' for ci in range(c0,c1+1)])
    return output.getvalue()


_NATIVE_TYPES = None


# ==================== 11. LOCAL SPREADSHEET DOCUMENT =========================
# Workbook editing is independent of SQL adapters and result snapshots. The
# document is sparse, coordinates never depend on sorting/filtering a view.
SHEET_MAX_ROWS = 1048576
SHEET_MAX_COLS = 16384
SHEET_MAX_CELLS = 200000
SHEET_MAX_PATCH = 100000
SHEET_MAX_BYTES = 32 * 1024 * 1024
SHEET_NS = 'http://schemas.openxmlformats.org/spreadsheetml/2006/main'
SHEET_REL = 'http://schemas.openxmlformats.org/officeDocument/2006/relationships'


def sheet_col_name(column):
    if not 0 <= column < SHEET_MAX_COLS: raise UserError('Kolumna poza zakresem A:XFD.')
    name = ''; column += 1
    while column:
        column, remainder = divmod(column - 1, 26); name = chr(65 + remainder) + name
    return name


def sheet_address(row, column):
    if not 0 <= row < SHEET_MAX_ROWS: raise UserError('Wiersz poza zakresem arkusza.')
    return sheet_col_name(column) + str(row + 1)


def sheet_position(address):
    match = re.fullmatch(r'\$?([A-Za-z]{1,3})\$?([1-9][0-9]{0,6})', str(address).strip())
    if not match: raise UserError('Podaj adres komórki, np. A1 albo AA25.')
    column = 0
    for ch in match[1].upper(): column = column * 26 + ord(ch) - 64
    row = int(match[2])
    if row > SHEET_MAX_ROWS or column > SHEET_MAX_COLS: raise UserError('Adres poza zakresem arkusza.')
    return row - 1, column - 1


def sheet_range(text):
    parts = str(text).strip().split(':')
    if len(parts) not in (1, 2): raise UserError('Podaj komórkę lub zakres, np. A1:C20.')
    r1, c1 = sheet_position(parts[0]); r2, c2 = sheet_position(parts[-1])
    return min(r1, r2), min(c1, c2), max(r1, r2), max(c1, c2)


def sheet_range_name(rect):
    r1, c1, r2, c2 = rect
    first, last = sheet_address(r1, c1), sheet_address(r2, c2)
    return first if first == last else first + ':' + last


def sheet_rect_count(rect):
    return (rect[2] - rect[0] + 1) * (rect[3] - rect[1] + 1)


def sheet_title(value):
    value = str(value)
    if (not value.strip() or len(value) > 31 or any(ch in value for ch in '[]:*?/\\')
            or any(ord(ch) < 32 for ch in value) or value.startswith("'") or value.endswith("'")):
        raise UserError('Nazwa arkusza: 1–31 znaków, bez [ ] : * ? / \\ i apostrofu na końcach.')
    return value


def sheet_new(name='Arkusz 1'):
    return {'id': uid(), 'name': sheet_title(name), 'cells': {}, 'columns': {}, 'rows': {},
            'merges': [], 'hidden': False, 'hidden_rows': [], 'hidden_columns': [],
            'controls': [], 'source': {}, 'freeze': [0, 0], 'filter': ''}


def sheet_new_book(title='Nowy skoroszyt'):
    first = sheet_new()
    return {'id': uid(), 'title': str(title)[:160], 'source_id': '', 'sheets': [first],
            'active_sheet': first['id'], 'styles': [{}], 'styles_xml': '', 'theme_xml': '',
            'date1904': False, 'warnings': [], 'revision': 0, 'origin': ''}


def sheet_style_validate(value):
    if not isinstance(value, dict): raise UserError('Nieprawidłowy format komórki.')
    result = {}
    for key, item in value.items():
        if key in ('bold', 'italic', 'underline', 'wrap', 'border'):
            result[key] = bool(item)
        elif key in ('foreground', 'background'):
            if item and not re.fullmatch('#[0-9a-fA-F]{6}', str(item)): raise UserError('Nieprawidłowy kolor.')
            result[key] = str(item)
        elif key == 'size':
            size = float(item)
            if not math.isfinite(size) or not 6 <= size <= 72: raise UserError('Rozmiar pisma: 6–72 pkt.')
            result[key] = size
        elif key in ('font', 'number_format'):
            result[key] = clean_text(item, 180)
        elif key == 'align':
            if item not in ('left', 'center', 'right', 'general'): raise UserError('Nieprawidłowe wyrównanie.')
            result[key] = item
        elif key == 'valign':
            if item not in ('top', 'center', 'bottom'): raise UserError('Nieprawidłowe wyrównanie pionowe.')
            result[key] = item
        else: raise UserError('Nieobsługiwane ustawienie formatu: ' + str(key))
    return result


def sheet_cell_validate(cell, style_count=100000):
    if cell is None: return None
    if not isinstance(cell, dict) or set(cell) - {'v', 'f', 's', 'format', 'error', 'formula_type', 'saved_value'}:
        raise UserError('Nieprawidłowa komórka arkusza.')
    result = {}
    if cell.get('v') is not None:
        v = cell['v']
        if not isinstance(v, dict) or set(v) != {'t', 'v'} or v['t'] not in ('s', 'n', 'b', 'd', 'dt'):
            raise UserError('Nieprawidłowa wartość komórki.')
        if len(str(v['v'])) > MAX_CELL_TEXT: raise UserError('Zbyt długa zawartość komórki.')
        if v['t'] == 'n':
            try: valid = Decimal(str(v['v'])).is_finite()
            except decimal.InvalidOperation: valid = False
            if not valid or abs(Decimal(str(v['v'])).adjusted()) > 308: raise UserError('Liczba poza obsługiwanym zakresem.')
        if not isinstance(v['v'], str): raise UserError('Niejednoznaczny zapis wartości komórki.')
        if v['t']=='b' and v['v'] not in ('true','false'): raise UserError('Nieprawidłowa wartość logiczna.')
        result['v'] = dict(v)
    if cell.get('f'):
        f = str(cell['f'])
        if not f.startswith('=') or len(f) > 8192: raise UserError('Formuła musi zaczynać się od =; limit 8192 znaków.')
        result['f'] = f
    if cell.get('error'):
        result['error'] = clean_text(cell['error'], 64)
    if cell.get('formula_type'):
        result['formula_type'] = clean_text(cell['formula_type'], 40)
    if cell.get('saved_value') and (cell.get('f') or cell.get('formula_type')): result['saved_value'] = True
    if 's' in cell:
        index = int(cell['s'])
        if not 0 <= index < style_count: raise UserError('Brak definicji stylu komórki.')
        result['s'] = index
    if cell.get('format'): result['format'] = sheet_style_validate(cell['format'])
    return result or None


def sheet_validate_book(raw):
    if not isinstance(raw, dict): raise UserError('Nieprawidłowy skoroszyt roboczy.')
    sheets = raw.get('sheets', [])
    if not isinstance(sheets, list) or not 1 <= len(sheets) <= 100: raise UserError('Skoroszyt musi zawierać 1–100 arkuszy.')
    styles = raw.get('styles', [{}])
    if not isinstance(styles, list) or not 1 <= len(styles) <= 10000: raise UserError('Nieprawidłowe style skoroszytu.')
    result = {'id': workbook_id(raw.get('id')), 'title': clean_text(raw.get('title', 'Skoroszyt'), 160),
              'source_id': clean_text(raw.get('source_id', ''), 64), 'origin': clean_text(raw.get('origin',''),2048), 'sheets': [], 'styles': [sheet_style_validate(s) for s in styles],
              'styles_xml': str(raw.get('styles_xml', '')), 'theme_xml': str(raw.get('theme_xml', '')),
              'date1904': bool(raw.get('date1904', False)), 'warnings': [clean_text(x, 500) for x in raw.get('warnings', [])[:100]],
              'revision': max(0, int(raw.get('revision', 0)))}
    if raw.get('source_revision'):
        if not re.fullmatch('[0-9a-f]{64}', str(raw['source_revision'])): raise UserError('Nieprawidłowy odcisk źródła Office.')
        result['source_revision'] = raw['source_revision']
    if raw.get('office_structure_changed'):result['office_structure_changed']=True
    if raw.get('formula_cache'):
        cache = raw['formula_cache']
        if not isinstance(cache, dict) or not re.fullmatch('[0-9a-f]{64}', str(cache.get('source_revision', ''))):
            raise UserError('Nieprawidłowe pochodzenie wyników formuł.')
        result['formula_cache'] = {'revision': max(0, int(cache.get('revision', 0))),
                                   'read_at': clean_text(cache.get('read_at', ''), 80),
                                   'source_revision': cache['source_revision']}
    names_metadata = raw.get('defined_names', [])
    if not isinstance(names_metadata, list) or len(names_metadata) > 2000: raise UserError('Zbyt wiele nazw zdefiniowanych.')
    if names_metadata:
        result['defined_names'] = [{'name': clean_text(n.get('name', ''), 255),
                                   'formula': clean_text(n.get('formula', ''), 8192),
                                   'local_sheet_id': clean_text(n.get('local_sheet_id', ''), 20),
                                   'native_only': True} for n in names_metadata]
    for key in ('styles_xml', 'theme_xml'):
        if len(result[key].encode('utf-8')) > 4 * 1024 * 1024: raise UserError('Zbyt duże metadane XLSX.')
        if result[key]:
            if '<!DOCTYPE' in result[key].upper() or '<!ENTITY' in result[key].upper(): raise UserError('Niedozwolona deklaracja XML.')
            try: ET.fromstring(result[key])
            except ET.ParseError as exc: raise UserError('Nieprawidłowe style XLSX.') from exc
    names = set(); ids = set(); count = 0
    for sh in sheets:
        name = sheet_title(sh.get('name', '')); sid = workbook_id(sh.get('id'))
        if name.casefold() in names or sid in ids: raise UserError('Powtórzona nazwa lub identyfikator arkusza.')
        names.add(name.casefold()); ids.add(sid)
        cells = {}
        for address, cell in sh.get('cells', {}).items():
            normalized = sheet_address(*sheet_position(address))
            if normalized != address: raise UserError('Niejednoznaczny adres komórki.')
            v = sheet_cell_validate(cell, len(styles))
            if v: cells[address] = v
        count += len(cells)
        if count > SHEET_MAX_CELLS: raise UserError('Limit edycji lokalnej: 200 000 zapisanych komórek. Oryginał pozostaje bez zmian.')
        item = {'id': sid, 'name': name, 'cells': cells, 'columns': {}, 'rows': {}, 'merges': [],
                'hidden': bool(sh.get('hidden')), 'freeze': [0, 0], 'filter': '', 'source': {}, 'controls': []}
        for key, limit in (('hidden_rows', SHEET_MAX_ROWS), ('hidden_columns', SHEET_MAX_COLS)):
            indices = sh.get(key, [])
            if not isinstance(indices, list) or len(indices) > SHEET_MAX_CELLS: raise UserError('Zbyt wiele ukrytych wierszy lub kolumn.')
            if any(type(n) is not int or not 0 <= n < limit for n in indices): raise UserError('Nieprawidłowy ukryty wiersz lub kolumna.')
            item[key] = sorted(set(indices))
        source = sh.get('source', {})
        if not isinstance(source, dict): raise UserError('Nieprawidłowa tożsamość arkusza źródłowego.')
        for key in ('name', 'sheet_id', 'relationship_id', 'path', 'code_name', 'visibility'):
            if key in source: item['source'][key] = clean_text(source[key], 2048 if key == 'path' else 255)
        controls = sh.get('controls', [])
        if not isinstance(controls, list) or len(controls) > 500: raise UserError('Zbyt wiele kontrolek arkusza.')
        for control in controls:
            if not isinstance(control, dict) or not isinstance(control.get('anchor'), dict): raise UserError('Nieprawidłowa kontrolka Office.')
            anchor = {}
            for key, limit in (('row', SHEET_MAX_ROWS), ('row2', SHEET_MAX_ROWS), ('col', SHEET_MAX_COLS), ('col2', SHEET_MAX_COLS)):
                n = control['anchor'].get(key)
                if type(n) is not int or not 0 <= n < limit: raise UserError('Kontrolka poza arkuszem.')
                anchor[key] = n
            for key in ('dx', 'dy', 'dx2', 'dy2'):
                value = float(control['anchor'].get(key, 0))
                if not math.isfinite(value) or not 0 <= value <= 100000: raise UserError('Nieprawidłowe położenie kontrolki.')
                anchor[key] = value
            if anchor['row2'] < anchor['row'] or anchor['col2'] < anchor['col']: raise UserError('Odwrócony obszar kontrolki.')
            item['controls'].append({**{k: clean_text(control.get(k, ''), limit) for k, limit in
                (('id', 160), ('caption', 2000), ('kind', 80), ('macro', 1024), ('source_part', 2048), ('name', 255))},
                'anchor': anchor, 'native_only': True})
        for key, lower, upper in (('default_row_height',1,1000),('default_column_width',1,2000)):
            if key in sh:
                size=float(sh[key])
                if not math.isfinite(size) or not lower<=size<=upper:raise UserError('Nieprawidłowe domyślne wymiary arkusza.')
                item[key]=size
        for key, limit, lower, upper in (('columns', SHEET_MAX_COLS, 1, 2000), ('rows', SHEET_MAX_ROWS, 1, 1000)):
            for index, size in sh.get(key, {}).items():
                n, v = int(index), float(size)
                if not 0 <= n < limit or not math.isfinite(v) or not lower <= v <= upper:
                    raise UserError('Nieprawidłowe wymiary arkusza.')
                item[key][str(n)] = v
        merge_rects=[]
        for merged in sh.get('merges', []):
            rect = sheet_range(merged)
            if len(item['merges']) >= 2000: raise UserError('Za dużo scalonych obszarów.')
            if sheet_rect_count(rect) <= 1: continue
            if any(not (rect[2]<other[0] or rect[0]>other[2] or rect[3]<other[1] or rect[1]>other[3]) for other in merge_rects):
                raise UserError('Scalone obszary nie mogą na siebie nachodzić.')
            merge_rects.append(rect);item['merges'].append(sheet_range_name(rect))
        freeze = sh.get('freeze', [0, 0])
        if len(freeze) != 2 or not 0 <= int(freeze[0]) < SHEET_MAX_ROWS or not 0 <= int(freeze[1]) < SHEET_MAX_COLS:
            raise UserError('Nieprawidłowe blokowanie okienek.')
        item['freeze'] = list(map(int, freeze))
        if sh.get('filter'): item['filter'] = sheet_range_name(sheet_range(sh['filter']))
        result['sheets'].append(item)
    if all(s['hidden'] for s in result['sheets']): raise UserError('Pozostaw co najmniej jeden widoczny arkusz.')
    result['active_sheet'] = raw.get('active_sheet') if raw.get('active_sheet') in ids else result['sheets'][0]['id']
    if len(dumps(result).encode('utf-8')) > SHEET_MAX_BYTES: raise UserError('Skoroszyt roboczy przekracza 32 MB.')
    return result


def sheet_find(book, identifier):
    for sh in book['sheets']:
        if sh['id'] == identifier or sh['name'].casefold() == str(identifier).casefold(): return sh
    raise UserError('Arkusz nie istnieje.')


def sheet_cell_input(text):
    if text is None or text == '': return None
    if isinstance(text, (int, float, Decimal, bool, dt.date)): return {'v': pack(text)}
    text = str(text)
    if len(text) > MAX_CELL_TEXT: raise UserError('Komórka przekracza limit 32 000 znaków.')
    if text.startswith("'"): return {'v': {'t': 's', 'v': text[1:]}}
    if text.startswith('='): return sheet_cell_validate({'f': text})
    stripped = text.strip()
    if stripped.upper() in ('TRUE', 'FALSE', 'PRAWDA', 'FAŁSZ'):
        return {'v': pack(stripped.upper() in ('TRUE', 'PRAWDA'))}
    # Leading zero identifiers remain text. Explicit date typing is deliberately
    # not guessed from ambiguous dd/mm strings; formatting never changes a value.
    if re.fullmatch(r'[+-]?(?:0|[1-9][0-9]*)(?:[.,][0-9]+)?(?:[eE][+-]?[0-9]+)?%?', stripped):
        percent = stripped.endswith('%'); candidate = stripped.rstrip('%').replace(',', '.')
        try:
            n = Decimal(candidate)
            if n.is_finite() and abs(n.adjusted()) < 310:
                return {'v': pack(n / 100 if percent else n), **({'format': {'number_format': '0.00%'}} if percent else {})}
        except decimal.InvalidOperation: pass
    return {'v': {'t': 's', 'v': text}}


def sheet_raw(cell):
    if not cell: return ''
    if cell.get('f'): return cell['f']
    if cell.get('error'): return cell['error']
    value = cell.get('v')
    if value is None: return ''
    if value['t'] == 'b': return 'TRUE' if unpack(value) else 'FALSE'
    if value['t'] == 's':
        text = str(value['v'])
        # Preserve literal text on a roundtrip through the editing field.
        guessed = sheet_cell_input(text)
        return "'" + text if text.startswith(("'", '=')) or (guessed and guessed.get('v', {}).get('t') != 's') else text
    return str(value['v'])


@dataclasses.dataclass(frozen=True)
class SheetError:
    code: str
    message: str = ''
    def __str__(self): return self.code


class SheetFormulaFailure(Exception):
    def __init__(self, code, message=''):
        self.value = SheetError(code, message); super().__init__(message or code)


_SF_REF_BODY = r'\$?[A-Za-z]{1,3}\$?[1-9][0-9]{0,6}'
_SF_PATTERN = re.compile(
    r'(?P<STRING>"(?:[^"]|"")*")|'
    r'(?P<REF>(?:(?:\'(?:[^\']|\'\')+\'|[^\W\d][\w.]*)!)?' + _SF_REF_BODY + r'(?![\w.(]))|'
    r'(?P<NUMBER>(?:[0-9]+(?:\.[0-9]*)?|\.[0-9]+)(?:[Ee][+-]?[0-9]+)?)|'
    r'(?P<ERROR>\#(?:REF!|DIV/0!|VALUE!|NAME\?|N/A|NUM!|NULL!|CYCLE!))|'
    r'(?P<NAME>[^\W\d][\w.]*)|(?P<OP><>|<=|>=|[+\-*/^&%=<>():,;])', re.UNICODE)


def sheet_tokens(formula):
    text = formula[1:] if formula.startswith('=') else formula
    if len(text) > 8192: raise SheetFormulaFailure('#VALUE!', 'Formuła jest za długa.')
    result = []; position = 0
    while position < len(text):
        if text[position].isspace(): position += 1; continue
        match = _SF_PATTERN.match(text, position)
        if match is None: raise SheetFormulaFailure('#NAME?', 'Nieobsługiwana składnia przy: ' + text[position:position+35])
        result.append((match.lastgroup, match.group(), match.start(), match.end())); position = match.end()
        if len(result) > 2048: raise SheetFormulaFailure('#NUM!', 'Zbyt złożona formuła.')
    return text, result


def sheet_ref_parts(text):
    if '!' in text:
        sheet, text = text.rsplit('!', 1)
        if sheet.startswith("'"): sheet = sheet[1:-1].replace("''", "'")
    else: sheet = None
    try: row, col = sheet_position(text)
    except UserError as exc: raise SheetFormulaFailure('#REF!', str(exc)) from exc
    match = re.fullmatch(r'(\$?)[A-Za-z]+(\$?)[0-9]+', text)
    return sheet, row, col, bool(match[2]), bool(match[1])


def sheet_ref_text(parts):
    sheet, row, col, ar, ac = parts
    if not 0 <= row < SHEET_MAX_ROWS or not 0 <= col < SHEET_MAX_COLS: return '#REF!'
    return (("'" + sheet.replace("'", "''") + "'!") if sheet is not None else '') + \
        ('$' if ac else '') + sheet_col_name(col) + ('$' if ar else '') + str(row+1)


def sheet_translate_formula(formula, dr=0, dc=0, *, owner='', target=None, axis=None, position=0, count=0, deleting=False, rename=None):
    """Rewrite reference tokens only; quoted string literals and function names survive."""
    text, tokens = sheet_tokens(formula); replacements = []; i = 0
    def point(parts, inherited=None):
        sn, r, c, ar, ac = parts; actual = sn or inherited or owner
        if rename and actual.casefold() == rename[0].casefold() and sn is not None: sn = rename[1]
        if axis is None:
            r += 0 if ar else dr; c += 0 if ac else dc
        elif actual.casefold() == str(target).casefold():
            v = r if axis == 'row' else c
            if deleting:
                if position <= v < position + count: return None
                if v >= position + count: v -= count
            elif v >= position: v += count
            if axis == 'row': r = v
            else: c = v
        return (sn, r, c, ar, ac)
    while i < len(tokens):
        kind, token, start, end = tokens[i]
        if kind != 'REF': i += 1; continue
        left = sheet_ref_parts(token)
        if i+2 < len(tokens) and tokens[i+1][1] == ':' and tokens[i+2][0] == 'REF':
            right = sheet_ref_parts(tokens[i+2][1]); inherited = left[0]
            p1, p2 = point(left), point(right, inherited)
            actual1 = left[0] or owner; actual2 = right[0] or inherited or owner
            if axis and deleting and actual1.casefold() == str(target).casefold() == actual2.casefold():
                idx = 1 if axis == 'row' else 2; lo, hi = sorted((left[idx], right[idx]))
                newlo = lo if lo < position else max(position, lo-count)
                newhi = hi if hi < position else (hi-count if hi >= position+count else position-1)
                if newlo <= newhi:
                    p1, p2 = list(left), list(right); p1[idx], p2[idx] = newlo, newhi
                else: p1 = p2 = None
            replacement = '#REF!' if p1 is None or p2 is None else sheet_ref_text(p1) + ':' + sheet_ref_text(p2)
            end = tokens[i+2][3]; i += 3
        else:
            p = point(left); replacement = sheet_ref_text(p) if p is not None else '#REF!'; i += 1
        replacements.append((start, end, replacement))
    for start, end, value in reversed(replacements): text = text[:start] + value + text[end:]
    return '=' + text


class SheetFormulaParser:
    PRECEDENCE = {'=': 10, '<>': 10, '<': 10, '>': 10, '<=': 10, '>=': 10,
                  '&': 20, '+': 30, '-': 30, '*': 40, '/': 40, '^': 60}
    def __init__(self, formula):
        self.text, self.tokens = sheet_tokens(formula); self.index = 0; self.depth = 0
    def peek(self): return self.tokens[self.index][1] if self.index < len(self.tokens) else ''
    def pop(self):
        if self.index >= len(self.tokens): raise SheetFormulaFailure('#VALUE!', 'Niepełna formuła.')
        token = self.tokens[self.index]; self.index += 1; return token
    def parse(self):
        node = self.expr(0)
        if self.index != len(self.tokens): raise SheetFormulaFailure('#VALUE!', 'Nieoczekiwany fragment formuły.')
        return node
    def expr(self, minimum):
        self.depth += 1
        if self.depth > 128: raise SheetFormulaFailure('#NUM!', 'Zbyt głębokie zagnieżdżenie.')
        kind, value, _, _ = self.pop()
        if value in ('+', '-'):
            node = ('unary', value, self.expr(70))
        elif kind == 'NUMBER': node = ('number', value)
        elif kind == 'STRING': node = ('string', value[1:-1].replace('""', '"'))
        elif kind == 'ERROR': node = ('error', value)
        elif kind == 'REF':
            node = ('ref', sheet_ref_parts(value))
            if self.peek() == ':':
                self.pop(); other = self.pop()
                if other[0] != 'REF': raise SheetFormulaFailure('#REF!', 'Nieprawidłowy zakres.')
                p2 = sheet_ref_parts(other[1]); node = ('range', node[1], p2)
        elif value == '(':
            node = self.expr(0)
            if self.pop()[1] != ')': raise SheetFormulaFailure('#VALUE!', 'Brakuje nawiasu zamykającego.')
        elif kind == 'NAME':
            upper = value.upper()
            if self.peek() == '(':
                self.pop(); args = []
                if self.peek() != ')':
                    while True:
                        args.append(self.expr(0))
                        if self.peek() not in (',', ';'): break
                        self.pop()
                if self.pop()[1] != ')': raise SheetFormulaFailure('#VALUE!', 'Nieprawidłowe argumenty.')
                node = ('call', upper, args)
            elif upper in ('TRUE', 'FALSE', 'PRAWDA', 'FAŁSZ'): node = ('bool', upper in ('TRUE', 'PRAWDA'))
            else: raise SheetFormulaFailure('#NAME?', 'Nieobsługiwana nazwa: ' + value)
        else: raise SheetFormulaFailure('#VALUE!', 'Nieprawidłowe wyrażenie.')
        while self.index < len(self.tokens):
            op = self.peek()
            if op == '%': self.pop(); node = ('unary', '%', node); continue
            priority = self.PRECEDENCE.get(op, -1)
            if priority < minimum: break
            self.pop(); node = ('binary', op, node, self.expr(priority + 1))
        self.depth -= 1; return node


class SheetCalculator:
    FUNCTIONS = ('SUM', 'AVERAGE', 'MIN', 'MAX', 'COUNT', 'COUNTA', 'IF', 'IFERROR', 'ROUND',
                 'ABS', 'AND', 'OR', 'NOT', 'LEN', 'LEFT', 'RIGHT', 'MID', 'TRIM', 'LOWER', 'UPPER',
                 'CONCAT', 'CONCATENATE', 'SUMIF', 'COUNTIF', 'SUMIFS', 'COUNTIFS', 'TRUE', 'FALSE')
    ALIASES = {'SUMA':'SUM', 'ŚREDNIA':'AVERAGE', 'ILE.LICZB':'COUNT', 'ILE.NIEPUSTYCH':'COUNTA',
               'JEŻELI':'IF', 'JEŻELI.BŁĄD':'IFERROR', 'ZAOKR':'ROUND', 'MODUŁ.LICZBY':'ABS',
               'ORAZ':'AND', 'LUB':'OR', 'NIE':'NOT', 'DŁ':'LEN', 'LEWY':'LEFT', 'PRAWY':'RIGHT',
               'FRAGMENT.TEKSTU':'MID', 'USUŃ.ZBĘDNE.ODSTĘPY':'TRIM', 'LITERY.MAŁE':'LOWER',
               'LITERY.WIELKIE':'UPPER', 'SUMA.JEŻELI':'SUMIF', 'LICZ.JEŻELI':'COUNTIF',
               'SUMA.WARUNKÓW':'SUMIFS', 'LICZ.WARUNKI':'COUNTIFS', 'PRAWDA':'TRUE', 'FAŁSZ':'FALSE'}
    def __init__(self, book):
        self.book = book; self.cache = {}; self.parsed = {}; self.visiting = set(); self.steps = 0
        self.revision = book.get('revision', 0);self.total_steps=0
    def invalidate(self): self.cache.clear(); self.visiting.clear(); self.revision = self.book.get('revision', 0);self.total_steps=0
    def saved_cache_valid(self, cell):
        metadata = self.book.get('formula_cache', {})
        return bool(cell.get('saved_value') and metadata.get('source_revision') and
                    metadata.get('source_revision') == self.book.get('source_revision') and
                    metadata.get('revision') == self.book.get('revision', 0))
    def provenance(self, sheet_id, row, col):
        cell = sheet_find(self.book, sheet_id)['cells'].get(sheet_address(row, col), {})
        kind = 'value'
        if cell.get('f') or cell.get('formula_type'):
            if self.saved_cache_valid(cell): kind = 'saved'
            else:
                value = self.cell(sheet_id, row, col)
                kind = 'native_required' if isinstance(value, SheetError) and value.code in ('#NAME?', '#UNSUPPORTED!') else 'local'
        return {'kind': kind, 'valid': kind != 'native_required',
                'read_at': self.book.get('formula_cache', {}).get('read_at', '') if kind == 'saved' else '',
                'source_revision': self.book.get('source_revision', '')}
    @staticmethod
    def number(value):
        if isinstance(value, SheetError): raise SheetFormulaFailure(value.code, value.message)
        if value is None: return Decimal(0)
        if isinstance(value, bool): return Decimal(int(value))
        if isinstance(value, (int, float, Decimal)):
            v = Decimal(str(value))
            if not v.is_finite(): raise SheetFormulaFailure('#NUM!')
            return v
        if isinstance(value,str):
            try:
                v=Decimal(value.strip())
                if v.is_finite() and abs(v.adjusted())<=308:return v
            except decimal.DecimalException:pass
        raise SheetFormulaFailure('#VALUE!', 'Oczekiwano liczby, nie tekstu.')
    @staticmethod
    def text(value):
        if isinstance(value, SheetError): raise SheetFormulaFailure(value.code, value.message)
        if value is None: return ''
        if isinstance(value, bool): return 'TRUE' if value else 'FALSE'
        if isinstance(value, Decimal):
            if not value.is_finite() or abs(value.adjusted())>308: raise SheetFormulaFailure('#NUM!')
            return str(value) if abs(value.adjusted())>24 else format(value, 'f')
        return str(value)
    def cell(self, sheet_id, row, col):
        if self.revision != self.book.get('revision', 0): self.invalidate()
        if not self.visiting: self.steps = 0
        try: sh = sheet_find(self.book, sheet_id)
        except UserError: return SheetError('#REF!', 'Nie znaleziono arkusza.')
        key = (sh['id'], row, col)
        if key in self.cache: return self.cache[key]
        if key in self.visiting: return SheetError('#CYCLE!', 'Odwołanie cykliczne.')
        if len(self.visiting) >= 128: return SheetError('#NUM!', 'Zbyt długa zależność formuł.')
        if not 0 <= row < SHEET_MAX_ROWS or not 0 <= col < SHEET_MAX_COLS: return SheetError('#REF!')
        cell = sh['cells'].get(sheet_address(row, col), {})
        if (cell.get('f') or cell.get('formula_type')) and self.saved_cache_valid(cell):
            return SheetError(cell['error'], 'Wynik zapisany w pliku źródłowym; nie przeliczono w Excelu.') if cell.get('error') else unpack(cell.get('v'))
        if cell.get('formula_type') not in (None, '', 'normal', 'shared'):
            return SheetError('#UNSUPPORTED!', 'Ta formuła wymaga przeliczenia w Excelu; zapisany wynik utracił ważność po edycji.')
        if cell.get('error') == '#UNSUPPORTED!': return SheetError('#UNSUPPORTED!', 'Nieobsługiwana formuła tablicowa lub tabela danych.')
        if not cell.get('f'):
            return SheetError(cell['error']) if cell.get('error') else unpack(cell.get('v'))
        self.visiting.add(key)
        try:
            f = cell['f']
            if f not in self.parsed:
                if len(self.parsed)>=4096:self.parsed.clear()
                self.parsed[f] = SheetFormulaParser(f).parse()
            with localcontext() as ctx:
                ctx.prec = 28; result = self.evaluate(self.parsed[f], sh['name'])
            if isinstance(result, list): raise SheetFormulaFailure('#VALUE!', 'Formuły rozlewające nie są obsługiwane.')
            if isinstance(result, Decimal) and (not result.is_finite() or abs(result.adjusted())>308): raise SheetFormulaFailure('#NUM!', 'Wynik liczbowy poza zakresem.')
            if isinstance(result,str) and len(result)>MAX_CELL_TEXT: raise SheetFormulaFailure('#VALUE!', 'Wynik tekstowy jest za długi.')
        except SheetFormulaFailure as exc: result = exc.value
        except (ZeroDivisionError, decimal.DivisionByZero): result = SheetError('#DIV/0!')
        except (decimal.DecimalException, OverflowError, ValueError, RecursionError): result = SheetError('#NUM!')
        except UserError as exc: result = SheetError('#REF!',str(exc))
        finally: self.visiting.discard(key)
        self.cache[key] = result; return result
    def evaluate(self, node, owner):
        self.steps += 1;self.total_steps+=1
        if self.total_steps>2000000:raise SheetFormulaFailure('#NUM!', 'Skoroszyt przekroczył budżet przeliczenia. Zmniejsz zakresy formuł.')
        if self.steps > 200000: raise SheetFormulaFailure('#NUM!', 'Przekroczono budżet obliczenia jednej formuły.')
        kind = node[0]
        if kind == 'number':
            value=Decimal(node[1])
            if not value.is_finite() or abs(value.adjusted())>308:raise SheetFormulaFailure('#NUM!')
            return value
        if kind in ('string', 'bool'): return node[1]
        if kind == 'error': raise SheetFormulaFailure(node[1])
        if kind == 'ref':
            sh, r, c, _, _ = node[1]; value = self.cell(sh or owner, r, c)
            if isinstance(value, SheetError): raise SheetFormulaFailure(value.code, value.message)
            return value
        if kind == 'range':
            sh, r1, c1, _, _ = node[1]; sh2, r2, c2, _, _ = node[2]
            if sh2 and sh2.casefold() != (sh or owner).casefold(): raise SheetFormulaFailure('#REF!')
            r1,r2 = sorted((r1,r2)); c1,c2 = sorted((c1,c2))
            if (r2-r1+1)*(c2-c1+1) > SHEET_MAX_PATCH: raise SheetFormulaFailure('#NUM!', 'Zakres formuły przekracza 100 000 komórek.')
            result=[]
            for r in range(r1,r2+1):
                for c in range(c1,c2+1):
                    self.steps+=1;self.total_steps+=1
                    if self.total_steps>2000000:raise SheetFormulaFailure('#NUM!', 'Skoroszyt przekroczył budżet przeliczenia.')
                    if self.steps>200000: raise SheetFormulaFailure('#NUM!', 'Przekroczono budżet obliczenia.')
                    value=self.cell(sh or owner,r,c)
                    if isinstance(value,SheetError): raise SheetFormulaFailure(value.code,value.message)
                    result.append(value)
            return result
        if kind == 'unary':
            number = self.number(self.evaluate(node[2], owner))
            return -number if node[1]=='-' else number/100 if node[1]=='%' else number
        if kind == 'binary':
            op=node[1]; a=self.evaluate(node[2],owner); b=self.evaluate(node[3],owner)
            if op=='&':
                result=self.text(a)+self.text(b)
                if len(result)>MAX_CELL_TEXT:raise SheetFormulaFailure('#VALUE!', 'Wynik tekstowy przekracza limit.')
                return result
            if op in ('=','<>','<','>','<=','>='): return self.compare(a,b,op)
            a,b=self.number(a),self.number(b)
            if op=='+':return a+b
            if op=='-':return a-b
            if op=='*':return a*b
            if op=='/':
                if not b:raise SheetFormulaFailure('#DIV/0!')
                return a/b
            if abs(b)>1000 or abs(a.adjusted())>300:raise SheetFormulaFailure('#NUM!')
            value=a**b
            if not value.is_finite() or abs(value.adjusted())>308:raise SheetFormulaFailure('#NUM!')
            return value
        if kind!='call':raise SheetFormulaFailure('#NAME?')
        name=self.ALIASES.get(node[1],node[1]); args=node[2]
        if name not in self.FUNCTIONS:raise SheetFormulaFailure('#NAME?', 'Nieobsługiwana funkcja: '+node[1])
        def arg(index):
            if index>=len(args):raise SheetFormulaFailure('#VALUE!', 'Brakuje argumentu '+name)
            return self.evaluate(args[index],owner)
        def arity(lo,hi=None):
            if not lo<=len(args)<=(lo if hi is None else hi):raise SheetFormulaFailure('#VALUE!', 'Nieprawidłowa liczba argumentów '+name)
        def logical(value):
            if value is None:return False
            if isinstance(value,(bool,int,float,Decimal)):return bool(value)
            if isinstance(value,str) and value.upper() in ('TRUE','FALSE'):return value.upper()=='TRUE'
            raise SheetFormulaFailure('#VALUE!', 'Oczekiwano wartości logicznej.')
        if name=='IF':
            arity(2,3);condition=arg(0)
            return arg(1) if logical(condition) else (arg(2) if len(args)==3 else False)
        if name=='IFERROR':
            arity(2)
            try:return arg(0)
            except SheetFormulaFailure:return arg(1)
        if name in ('TRUE','FALSE'):arity(0);return name=='TRUE'
        values=[]
        for index in range(len(args)):
            value=arg(index); values.extend(value if isinstance(value,list) else [value])
        if name in ('SUM','AVERAGE','MIN','MAX','COUNT','COUNTA'):
            arity(1,255)
            if name=='COUNTA':return Decimal(sum(x is not None for x in values))
            numbers=[]
            for child in args:
                item=self.evaluate(child,owner)
                if child[0] in ('range','ref'):
                    seq=item if isinstance(item,list) else [item]
                    numbers.extend(self.number(x) for x in seq if isinstance(x,(int,float,Decimal)) and not isinstance(x,bool))
                else:
                    for x in (item if isinstance(item,list) else [item]):
                        if x is None:continue
                        try:numbers.append(self.number(x))
                        except SheetFormulaFailure:
                            if name!='COUNT':raise
            if name=='SUM':return sum(numbers,Decimal(0))
            if name=='COUNT':return Decimal(len(numbers))
            if name=='COUNTA':return Decimal(sum(x is not None for x in values))
            if name=='AVERAGE':
                if not numbers:raise SheetFormulaFailure('#DIV/0!')
                return sum(numbers,Decimal(0))/len(numbers)
            return (min(numbers) if name=='MIN' else max(numbers)) if numbers else Decimal(0)
        if name in ('AND','OR'):
            arity(1,255);truth=[]
            for child in args:
                item=self.evaluate(child,owner)
                seq=item if isinstance(item,list) else [item]
                truth.extend(logical(v) for v in seq if child[0] not in ('ref','range') or v is not None and not isinstance(v,str))
            if not truth:raise SheetFormulaFailure('#VALUE!')
            return all(truth) if name=='AND' else any(truth)
        if name=='NOT':arity(1);return not logical(arg(0))
        if name=='ROUND':
            arity(2);places=int(self.number(arg(1)))
            if not -25<=places<=25:raise SheetFormulaFailure('#NUM!')
            return self.number(arg(0)).quantize(Decimal(1).scaleb(-places),rounding=decimal.ROUND_HALF_UP)
        if name=='ABS':arity(1);return abs(self.number(arg(0)))
        if name in ('CONCAT','CONCATENATE'):
            arity(1,255);parts=[];length=0
            for x in values:
                part=self.text(x);length+=len(part)
                if length>MAX_CELL_TEXT:raise SheetFormulaFailure('#VALUE!', 'Wynik tekstowy przekracza limit.')
                parts.append(part)
            return ''.join(parts)
        if name in ('LEN','TRIM','UPPER','LOWER'):
            arity(1);s=self.text(arg(0))
            return {'LEN':lambda:Decimal(len(s)), 'TRIM':lambda:' '.join(s.split(' ')).strip(),
                    'UPPER':s.upper,'LOWER':s.lower}[name]() if name!='TRIM' else ' '.join(x for x in s.split(' ') if x)
        if name in ('LEFT','RIGHT'):
            arity(1,2);s=self.text(arg(0));n=int(self.number(arg(1))) if len(args)>1 else 1
            if n<0:raise SheetFormulaFailure('#VALUE!')
            return s[:n] if name=='LEFT' else (s[-n:] if n else '')
        if name=='MID':
            arity(3);s=self.text(arg(0));start=int(self.number(arg(1)));n=int(self.number(arg(2)))
            if start<1 or n<0:raise SheetFormulaFailure('#VALUE!')
            return s[start-1:start-1+n]
        def sequence(v):return v if isinstance(v,list) else [v]
        if name in ('SUMIF','COUNTIF'):
            arity(2,3 if name=='SUMIF' else 2);seq=sequence(arg(0));criterion=arg(1)
            target=sequence(arg(2)) if len(args)==3 else seq
            if len(seq)!=len(target):raise SheetFormulaFailure('#VALUE!', 'Zakresy mają różne rozmiary.')
            found=[v for x,v in zip(seq,target) if self.matches(x,criterion)]
            return Decimal(len(found)) if name=='COUNTIF' else sum((self.number(v) for v in found if isinstance(v,(int,float,Decimal)) and not isinstance(v,bool)),Decimal(0))
        if name in ('SUMIFS','COUNTIFS'):
            offset=1 if name=='SUMIFS' else 0
            if len(args)<offset+2 or (len(args)-offset)%2:raise SheetFormulaFailure('#VALUE!')
            pairs=[(sequence(arg(i)),arg(i+1)) for i in range(offset,len(args),2)]
            length=len(pairs[0][0]);target=sequence(arg(0)) if offset else [Decimal(1)]*length
            if len(target)!=length or any(len(seq)!=length for seq,_ in pairs):raise SheetFormulaFailure('#VALUE!')
            found=[target[j] for j in range(length) if all(self.matches(seq[j],crit) for seq,crit in pairs)]
            return sum((self.number(v) for v in found if isinstance(v,(int,float,Decimal)) and not isinstance(v,bool)),Decimal(0))
        raise SheetFormulaFailure('#NAME?')
    @staticmethod
    def compare(a,b,op):
        if a is None:a=0 if isinstance(b,(int,float,Decimal)) else ''
        if b is None:b=0 if isinstance(a,(int,float,Decimal)) else ''
        if isinstance(a,str) and isinstance(b,str):a,b=a.casefold(),b.casefold()
        if type(a)!=type(b) and not (isinstance(a,(int,float,Decimal)) and isinstance(b,(int,float,Decimal))):
            equal=False
            if op=='=':return equal
            if op=='<>':return not equal
            # Defined type ordering, never Python's mixed-type comparison.
            a=(2 if isinstance(a,bool) else 1 if isinstance(a,str) else 0,str(a))
            b=(2 if isinstance(b,bool) else 1 if isinstance(b,str) else 0,str(b))
        return {'=':lambda:a==b,'<>':lambda:a!=b,'<':lambda:a<b,'>':lambda:a>b,'<=':lambda:a<=b,'>=':lambda:a>=b}[op]()
    def matches(self,value,criterion):
        if isinstance(criterion,str):
            match=re.match(r'^(<=|>=|<>|=|<|>)(.*)$',criterion)
            op,crit=(match[1],match[2]) if match else ('=',criterion)
            try:crit=Decimal(crit)
            except decimal.InvalidOperation:pass
            if isinstance(crit,str) and any(ch in crit for ch in '*?') and op in ('=','<>'):
                expr='';i=0
                while i<len(crit):
                    ch=crit[i]
                    if ch=='~' and i+1<len(crit):i+=1;expr+=re.escape(crit[i])
                    else:expr+='.*' if ch=='*' else '.' if ch=='?' else re.escape(ch)
                    i+=1
                found=re.fullmatch(expr,self.text(value),re.I|re.S) is not None
                return found if op=='=' else not found
            return self.compare(value,crit,op)
        return self.compare(value,criterion,'=')


@dataclasses.dataclass(frozen=True)
class SheetChange:
    """Transient notification; never serialized into a project."""
    kind: str = 'book'
    sheet_id: str = ''
    addresses: tuple[str, ...] = ()


@dataclasses.dataclass
class SheetEditDraft:
    """A draft belongs to the cell where editing began, not the current selection."""
    token: str
    book_id: str
    sheet_id: str
    row: int
    column: int
    structure_epoch: int
    original: dict | None
    text: str


@dataclasses.dataclass(frozen=True)
class SheetCommitResult:
    accepted: bool
    changed: bool = False
    message: str = ''


def sheet_begin_edit(session, sheet_id, row, column):
    address = sheet_address(row, column)
    original = sheet_find(session.book, sheet_id)['cells'].get(address)
    return SheetEditDraft(uid(), session.book['id'], sheet_id, row, column,
                          session.structure_epoch, clone(original), sheet_raw(original or {}))


def sheet_commit_edit(session, draft, *, read_only=False):
    """One atomic commit. An unchanged value is success, not a validation error."""
    if read_only:
        return SheetCommitResult(False, message='Ten arkusz jest tylko do odczytu.')
    if not session or session.book['id'] != draft.book_id:
        return SheetCommitResult(False, message='Zmieniono skoroszyt. Wpis nie został zapisany w innym dokumencie.')
    if session.structure_epoch != draft.structure_epoch:
        return SheetCommitResult(False, message='Zmieniono strukturę arkusza podczas edycji. Skopiuj wpis i anuluj go przez Escape.')
    try:
        record = sheet_find(session.book, draft.sheet_id)['cells'].get(sheet_address(draft.row, draft.column))
        if record != draft.original:
            return SheetCommitResult(False, message='Zawartość komórki zmieniła się podczas edycji. Nie nadpisano jej. Skopiuj wpis i naciśnij Escape.')
        if draft.text == sheet_raw(draft.original or {}):
            return SheetCommitResult(True)
        changed = session.edit(draft.sheet_id, draft.row, draft.column, draft.text)
        return SheetCommitResult(True, bool(changed))
    except Exception as exc:
        return SheetCommitResult(False, message=safe_error(exc))


@dataclasses.dataclass(frozen=True)
class SheetHiddenAxis:
    """Compressed hidden intervals; Enter does not scan a million filtered rows."""
    intervals: tuple[tuple[int, int], ...] = ()

    @classmethod
    def from_sections(cls, sections):
        intervals = []
        for value in sorted(set(sections)):
            if intervals and value == intervals[-1][1] + 1:
                intervals[-1] = (intervals[-1][0], value)
            else:
                intervals.append((value, value))
        return cls(tuple(intervals))

    def next_visible(self, value, step, lower, upper):
        import bisect
        value = max(lower, value) if step > 0 else min(upper, value)
        if not lower <= value <= upper:
            return None
        index = bisect.bisect_right(self.intervals, (value, math.inf)) - 1
        if index >= 0 and self.intervals[index][0] <= value <= self.intervals[index][1]:
            value = self.intervals[index][1] + 1 if step > 0 else self.intervals[index][0] - 1
        return value if lower <= value <= upper else None


def sheet_nav_subtract(rect, block):
    r, c, er, ec = rect
    a, b, d, e = block
    top, left, bottom, right = max(r, a), max(c, b), min(er, d), min(ec, e)
    if top > bottom or left > right:
        return (rect,)
    return tuple(piece for piece in ((r, c, top - 1, ec), (bottom + 1, c, er, ec),
                                     (top, c, bottom, left - 1), (top, right + 1, bottom, ec))
                 if piece[0] <= piece[2] and piece[1] <= piece[3])


@functools.lru_cache(maxsize=32)
def sheet_navigation_regions(ranges, merges):
    """Subtract covered merge cells geometrically; do not enumerate selections."""
    regions = tuple(ranges)
    for r, c, er, ec in merges:
        for block in ((r, c + 1, r, ec), (r + 1, c, er, ec)):
            if block[0] > block[2] or block[1] > block[3]:
                continue
            regions = tuple(piece for rect in regions for piece in sheet_nav_subtract(rect, block))
            if len(regions) > 32768:
                raise UserError('Zaznaczenie ze scaleniami jest zbyt złożone. Zaznacz mniejszy obszar.')
    return regions


def sheet_next_cell(current, direction, *, ranges=(), merges=(), hidden_rows=None,
                    hidden_columns=None, max_rows=SHEET_MAX_ROWS, max_columns=SHEET_MAX_COLS):
    """Pure navigation. Enter traverses columns; Tab traverses rows in a selection.

    Outside a multi-cell selection the movement is straight and bounded. Frozen
    panes are a presentation detail and must not be included in hidden sections.
    """
    if direction not in ('down', 'up', 'right', 'left'):
        raise ValueError('Nieznany kierunek nawigacji.')
    if not 0 <= current[0] < max_rows or not 0 <= current[1] < max_columns:
        raise ValueError('Nieprawidłowa aktywna komórka.')
    rows = hidden_rows or SheetHiddenAxis()
    columns = hidden_columns or SheetHiddenAxis()
    vertical = direction in ('down', 'up')
    step = 1 if direction in ('down', 'right') else -1
    merges = tuple(tuple(x) for x in merges)
    ranges = tuple(tuple(x) for x in ranges)
    if len(ranges) > 4096:
        raise UserError('Zbyt wiele oddzielnych zaznaczeń do nawigacji.')
    for r, c, er, ec in (*ranges, *merges):
        if not 0 <= r <= er < max_rows or not 0 <= c <= ec < max_columns:
            raise ValueError('Zakres nawigacji jest poza arkuszem.')
    span = next((x for x in merges if x[0] <= current[0] <= x[2] and x[1] <= current[1] <= x[3]), None)
    if span:
        current = span[:2]
    in_selection = any(r <= current[0] <= er and c <= current[1] <= ec for r, c, er, ec in ranges)
    regions = sheet_navigation_regions(ranges, merges) if in_selection else ()
    multi = bool(regions) and not (len(regions) == 1 and regions[0][:2] == regions[0][2:])

    if multi:
        major_axis, minor_axis = (columns, rows) if vertical else (rows, columns)
        def key(cell):
            return (cell[1], cell[0]) if vertical else cell
        def candidate(rect, after):
            r, c, er, ec = rect
            lo, hi, minor_lo, minor_hi = (c, ec, r, er) if vertical else (r, er, c, ec)
            major, minor = key(after) if after is not None else (lo if step > 0 else hi, minor_lo - 1 if step > 0 else minor_hi + 1)
            first = major_axis.next_visible(major, step, lo, hi)
            if first is None:
                return None
            minor_start = minor + step if first == major else (minor_lo if step > 0 else minor_hi)
            second = minor_axis.next_visible(minor_start, step, minor_lo, minor_hi)
            if second is None:
                first = major_axis.next_visible(first + step, step, lo, hi)
                if first is None:
                    return None
                second = minor_axis.next_visible(minor_lo if step > 0 else minor_hi, step, minor_lo, minor_hi)
            if second is None:
                return None
            return (second, first) if vertical else (first, second)
        def choose(after):
            choices = [cell for rect in regions if (cell := candidate(rect, after)) is not None]
            return (min if step > 0 else max)(choices, key=key) if choices else None
        return choose(current) or choose(None) or current

    row, col = current
    for _ in range(len(merges) + 2):
        start = (span[2] if step > 0 else span[0]) if vertical and span else (span[3] if step > 0 else span[1]) if span else row if vertical else col
        value = (rows if vertical else columns).next_visible(start + step, step, 0, (max_rows if vertical else max_columns) - 1)
        if value is None:
            return current
        row, col = (value, col) if vertical else (row, value)
        span = next((x for x in merges if x[0] <= row <= x[2] and x[1] <= col <= x[3]), None)
        target = span[:2] if span else (row, col)
        if rows.next_visible(target[0], 1, target[0], target[0]) is not None and columns.next_visible(target[1], 1, target[1], target[1]) is not None:
            return target
    return current


class SheetSession:
    """Sparse atomic edit commands. UI and persisted project share one owned book.

    Cell edits keep before/after patches; infrequent structural operations keep
    compressed checkpoints. Undo is bounded by both action count and byte size.
    """
    def __init__(self, book, changed=None):
        self.book=book;self.changed=changed or (lambda:None);self.calculator=SheetCalculator(book)
        self.last_change=SheetChange();self.structure_epoch=0
        self.history=[];self.position=0;self.history_bytes=0;self.available_bytes=lambda:SHEET_MAX_BYTES;self._dimension_stamp=None
    def notify(self, change=None):
        self.last_change=change or SheetChange()
        if self.last_change.kind=='book':self.structure_epoch+=1
        previous=self.book.get('revision',0);cache=self.book.get('formula_cache',{})
        preserve=self.last_change.kind=='dimensions' and cache.get('revision')==previous and bool(cache.get('source_revision')) and cache.get('source_revision')==self.book.get('source_revision')
        self.book['revision']=previous+1
        if self.last_change.kind=='dimensions':
            if preserve:cache['revision']=self.book['revision']
            if self.calculator.revision!=previous:self.calculator.invalidate()
            self.calculator.revision=self.book['revision']
        else:self.calculator.invalidate()
        self.changed()
    def record(self,command,coalesce=False):
        import zlib
        now=time.monotonic();previous=self.history[-1] if self.history and self.position==len(self.history) else None
        if (coalesce and command['type']=='dimensions' and previous and previous['type']=='dimensions' and self._dimension_stamp is not None
                and now-self._dimension_stamp<.5 and all(previous[key]==command[key] for key in ('sid','axis','index'))):
            self.history_bytes-=previous['_bytes'];previous['after']=command['after'];previous.pop('_bytes')
            previous['_bytes']=len(dumps(previous).encode('utf-8'));self.history_bytes+=previous['_bytes'];self._dimension_stamp=now
            self.notify(SheetChange('dimensions',command['sid'],(command['axis']+':'+str(command['index']),)));return
        self._dimension_stamp=now if coalesce and command['type']=='dimensions' else None
        command['_bytes']=len(dumps(command).encode('utf-8'))
        self.history=self.history[:self.position];self.history.append(command)
        self.history_bytes=sum(x['_bytes'] for x in self.history)
        while len(self.history)>60 or self.history_bytes>24*1024*1024:
            removed=self.history.pop(0);self.history_bytes-=removed['_bytes']
        self.position=len(self.history)
        self.notify(SheetChange('cells',command['sid'],tuple(command['after'])) if command['type']=='cells' else SheetChange('dimensions',command['sid'],(command['axis']+':'+str(command['index']),)) if command['type']=='dimensions' else SheetChange())
    def set_dimension(self,sid,axis,index,size,coalesce=False):
        if axis not in ('columns','rows') or type(index) is not int or not 0<=index<(SHEET_MAX_COLS if axis=='columns' else SHEET_MAX_ROWS):raise UserError('Nieprawidłowy wymiar arkusza.')
        if size is not None and (type(size) not in (int,float) or not math.isfinite(size) or not 0<size<=(2000 if axis=='columns' else 1000)):raise UserError('Nieprawidłowy rozmiar kolumny lub wiersza.')
        sheet=sheet_find(self.book,sid);key=str(index);old=sheet[axis].get(key)
        fallback=sheet.get('default_column_width' if axis=='columns' else 'default_row_height',112 if axis=='columns' else 27)
        if old==size or (old is None and size is not None and abs(size-fallback)<.5):return False
        if old is None and len(dumps(self.book).encode('utf-8'))+128>min(SHEET_MAX_BYTES,self.available_bytes())-4096:raise UserError('Brak miejsca na zmianę wymiaru w projekcie.')
        if size is None:sheet[axis].pop(key,None)
        else:sheet[axis][key]=float(size)
        self.record({'type':'dimensions','sid':sid,'axis':axis,'index':index,'before':old,'after':size,
                     'label':'Szerokość kolumny' if axis=='columns' else 'Wysokość wiersza'},coalesce=coalesce)
        return True
    def apply_cells(self,sid,changes,label='Edycja komórek'):
        sheet=sheet_find(self.book,sid)
        if len(changes)>SHEET_MAX_PATCH:raise UserError('Jedna operacja może zmienić najwyżej 100 000 komórek.')
        before={};after={}
        for address,value in changes.items():
            r,c=sheet_position(address);address=sheet_address(r,c)
            cleaned=sheet_cell_validate(value,len(self.book['styles']))
            original=sheet['cells'].get(address)
            content={k:v for k,v in (cleaned or {}).items() if k in ('v','f','error')}
            previous={k:v for k,v in (original or {}).items() if k in ('v','f','error')}
            for merge in sheet['merges']:
                a,b,d,e=sheet_range(merge)
                # Covered cells retain physical styles for XLSX borders/fills.
                # Formatting must not permit entering hidden values or formulas.
                if a<=r<=d and b<=c<=e and (r,c)!=(a,b) and content and content!=previous:
                    raise UserError('Edytuj lewą górną komórkę scalenia albo najpierw rozłącz komórki.')
            if original!=cleaned:before[address]=clone(original);after[address]=cleaned
        if not after:return False
        total=sum(len(s['cells']) for s in self.book['sheets'])+sum((1 if v else 0)-(1 if before[k] else 0) for k,v in after.items())
        if total>SHEET_MAX_CELLS:raise UserError('Limit edycji: 200 000 zapisanych komórek.')
        if len(dumps(after).encode('utf-8'))>16*1024*1024:raise UserError('Operacja jest zbyt duża. Wklej mniejszy zakres.')
        # Check the new serialized size before mutating the live document.
        current_bytes=len(dumps(self.book).encode('utf-8'))
        growth=sum(len(dumps(v).encode('utf-8'))-len(dumps(before[k]).encode('utf-8'))+(len(k)+4 if not before[k] and v else 0) for k,v in after.items())
        if current_bytes+max(0,growth)>min(SHEET_MAX_BYTES,self.available_bytes())-4096:raise UserError('Skoroszyt przekroczyłby 32 MB. Nie zmieniono danych.')
        self._patch(sheet,after);self.record({'type':'cells','sid':sid,'before':before,'after':clone(after),'label':label});return True
    @staticmethod
    def _patch(sheet,patch):
        for address,cell in patch.items():
            if cell:sheet['cells'][address]=clone(cell)
            else:sheet['cells'].pop(address,None)
    def edit(self,sid,row,col,text):
        sh=sheet_find(self.book,sid);address=sheet_address(row,col);old=sh['cells'].get(address,{})
        value=sheet_cell_input(text) or {}
        if value.get('format') and old.get('format'):value['format']={**old['format'],**value['format']}
        for k in ('s','format'):
            if k in old and k not in value:value[k]=clone(old[k])
        return self.apply_cells(sid,{address:value or None},'Wpisanie '+address)
    def checkpoint_command(self,label,mutation):
        import zlib,base64
        before=clone(self.book);staged=clone(self.book);mutation(staged);staged=sheet_validate_book(staged)
        if before==staged:return False
        if len(dumps(staged).encode('utf-8'))>min(SHEET_MAX_BYTES,self.available_bytes())-4096:raise UserError('Brak miejsca w limicie projektu. Nie zmieniono skoroszytu.')
        b=base64.b64encode(zlib.compress(dumps(before).encode('utf-8'),3)).decode('ascii')
        a=base64.b64encode(zlib.compress(dumps(staged).encode('utf-8'),3)).decode('ascii')
        self.book.clear();self.book.update(staged);self.record({'type':'book','before':b,'after':a,'label':label});return True
    def _restore(self,command,direction):
        if command['type']=='cells':
            staged=clone(self.book);self._patch(sheet_find(staged,command['sid']),command[direction])
            if len(dumps(staged).encode('utf-8'))>self.available_bytes()-4096:raise UserError('Cofnięcie przekroczyłoby limit projektu.')
            self._patch(sheet_find(self.book,command['sid']),command[direction])
        elif command['type']=='dimensions':
            dimensions=sheet_find(self.book,command['sid'])[command['axis']];key=str(command['index']);value=command[direction]
            if value is None:dimensions.pop(key,None)
            else:dimensions[key]=value
        else:
            import zlib,base64
            raw=json.loads(zlib.decompress(base64.b64decode(command[direction])).decode('utf-8'))
            if len(dumps(raw).encode('utf-8'))>self.available_bytes()-4096:raise UserError('Przywrócenie przekroczyłoby limit projektu.')
            rev=self.book.get('revision',0);self.book.clear();self.book.update(raw);self.book['revision']=rev
        self._dimension_stamp=None
        self.notify(SheetChange('cells',command['sid'],tuple(command[direction])) if command['type']=='cells' else SheetChange('dimensions',command['sid'],(command['axis']+':'+str(command['index']),)) if command['type']=='dimensions' else SheetChange())
    def undo(self):
        if self.position:
            self.position-=1
            try:self._restore(self.history[self.position],'before')
            except Exception:self.position+=1;raise
            return True
        return False
    def redo(self):
        if self.position<len(self.history):
            command=self.history[self.position];self.position+=1
            try:self._restore(command,'after')
            except Exception:self.position-=1;raise
            return True
        return False
    def format_range(self,sid,rect,properties):
        if sheet_rect_count(rect)>SHEET_MAX_PATCH:raise UserError('Zaznacz mniejszy zakres do formatowania.')
        properties=sheet_style_validate(properties);sh=sheet_find(self.book,sid);patch={}
        for r in range(rect[0],rect[2]+1):
            for c in range(rect[1],rect[3]+1):
                address=sheet_address(r,c);cell=clone(sh['cells'].get(address,{}));cell.setdefault('format',{}).update(properties);patch[address]=cell
        return self.apply_cells(sid,patch,'Formatowanie')
    def clear_range(self,sid,rect):
        sh=sheet_find(self.book,sid);patch={}
        for address,cell in sh['cells'].items():
            r,c=sheet_position(address)
            if rect[0]<=r<=rect[2] and rect[1]<=c<=rect[3]:patch[address]={k:clone(v) for k,v in cell.items() if k in ('s','format')} or None
        return self.apply_cells(sid,patch,'Wyczyść zawartość')
    def add_sheet(self,name=None,duplicate=None):
        used={s['name'].casefold() for s in self.book['sheets']};base=name or 'Arkusz';candidate=base;index=1
        while candidate.casefold() in used:candidate=base[:25]+' '+str(index);index+=1
        result=sheet_new(candidate)
        if duplicate:
            source=sheet_find(self.book,duplicate);result=clone(source);result['id']=uid();result['name']=candidate;result['hidden']=False
            for cell in result['cells'].values():
                if cell.get('f'):cell['f']=sheet_translate_formula(cell['f'],owner=source['name'],rename=(source['name'],candidate))
        def mutate(book):book['sheets'].append(result);book['active_sheet']=result['id']
        self.checkpoint_command('Dodaj arkusz',mutate);return result['id']
    def rename_sheet(self,sid,name):
        name=sheet_title(name);original=sheet_find(self.book,sid)['name']
        if any(s['id']!=sid and s['name'].casefold()==name.casefold() for s in self.book['sheets']):raise UserError('Taka nazwa arkusza już istnieje.')
        def mutate(book):
            for sh in book['sheets']:
                for cell in sh['cells'].values():
                    if cell.get('f'):
                        try:cell['f']=sheet_translate_formula(cell['f'],owner=sh['name'],rename=(original,name))
                        except SheetFormulaFailure:raise UserError('Nie można bezpiecznie zmienić nazwy: skoroszyt zawiera nieobsługiwaną składnię formuł.')
            sheet_find(book,sid)['name']=name
        return self.checkpoint_command('Zmień nazwę arkusza',mutate)
    def remove_sheet(self,sid):
        sh=sheet_find(self.book,sid)
        if len(self.book['sheets'])==1 or (not sh['hidden'] and sum(not s['hidden'] for s in self.book['sheets'])==1):raise UserError('Pozostaw przynajmniej jeden widoczny arkusz.')
        def mutate(book):
            original=sheet_find(book,sid)['name'];book['sheets']=[s for s in book['sheets'] if s['id']!=sid]
            for other in book['sheets']:
                for cell in other['cells'].values():
                    if cell.get('f'):
                        try:cell['f']=sheet_translate_formula(cell['f'],owner=other['name'],target=original,axis='row',position=0,count=SHEET_MAX_ROWS,deleting=True)
                        except SheetFormulaFailure:raise UserError('Usunięcie zablokowane: nieobsługiwana składnia formuł. Nie zmieniono danych.')
            book['active_sheet']=next(s['id'] for s in book['sheets'] if not s['hidden'])
        return self.checkpoint_command('Usuń arkusz',mutate)
    def fill(self,sid,source_rect,target_rect):
        if sheet_rect_count(target_rect)>SHEET_MAX_PATCH:raise UserError('Wypełnij mniejszy zakres.')
        sh=sheet_find(self.book,sid);patch={};r1,c1,r2,c2=source_rect;h,w=r2-r1+1,c2-c1+1
        for r in range(target_rect[0],target_rect[2]+1):
            for c in range(target_rect[1],target_rect[3]+1):
                if r1<=r<=r2 and c1<=c<=c2:continue
                sr,sc=r1+(r-r1)%h,c1+(c-c1)%w
                cell=clone(sh['cells'].get(sheet_address(sr,sc)))
                if cell and cell.get('f'):
                    try:cell['f']=sheet_translate_formula(cell['f'],r-sr,c-sc)
                    except SheetFormulaFailure:raise UserError('Nie obsługujemy przesunięcia tej formuły. Niczego nie zmieniono.')
                patch[sheet_address(r,c)]=cell
