def _license_text(value, limit=2000):
    text=str(value or '')
    return ''.join(ch if ch in '\n\t' or ord(ch)>=32 and ord(ch)!=127 else ' ' for ch in text)[:limit]


def _license_key(name):
    return re.sub(r'[-_.]+','-',str(name)).lower()


def _license_cancel(cancel):
    if cancel is not None and cancel.is_set():raise Cancelled('Odczyt wykazu anulowany.')


def _license_https(url):
    """Only absolute HTTPS documentation, never credentials, shell/file URLs."""
    try:
        if not isinstance(url,str) or len(url)>2048 or any(ch.isspace() or ord(ch)<32 for ch in url) or '\\' in url:return False
        u=urllib.parse.urlsplit(url);u.port
        return u.scheme=='https' and bool(u.hostname) and u.username is None and u.password is None and not u.query
    except ValueError:return False


def _license_row(name, version, license_name, role, *, group='Pakiety', present=True, status='Do weryfikacji', commercial='Do weryfikacji', terms='', proofs=(), expected='', origin=''):
    return dict(id=uid(),name=_license_text(name,160),version=_license_text(version,100),license=_license_text(license_name,240),
        role=_license_text(role),group=group,present=bool(present),status=status,commercial=commercial,
        terms=_license_text(terms,10000),expected_version=expected,origin=origin,review_date='',notices=[],
        proofs=[{'label':_license_text(label,120),'url':url} for label,url in proofs if _license_https(url)])


def _license_safe_file(root,path):
    """Reject all symbolic links/junctions and escapes, including parent links."""
    import stat
    root=Path(os.path.abspath(root));path=Path(os.path.abspath(path))
    try:relative=path.relative_to(root)
    except ValueError:raise UserError('Tekst licencji znajduje się poza zakresem odczytu.') from None
    for part in (root,*[root.joinpath(*relative.parts[:i]) for i in range(1,len(relative.parts)+1)]):
        if part.is_symlink() or getattr(part,'is_junction',lambda:False)():raise UserError('Odmowa odczytu licencji przez dowiązanie.')
    if not stat.S_ISREG(path.stat().st_mode):raise UserError('Wskazany składnik nie jest zwykłym plikiem.')
    return path


def _license_read_bytes(root,path,maximum=LICENSE_NOTICE_LIMIT):
    import stat
    path=_license_safe_file(root,path)
    fd=os.open(path,os.O_RDONLY|getattr(os,'O_NOFOLLOW',0)|getattr(os,'O_BINARY',0))
    with os.fdopen(fd,'rb') as stream:
        details=os.fstat(stream.fileno())
        if not stat.S_ISREG(details.st_mode) or details.st_size>maximum:raise UserError('Tekst licencji przekracza limit odczytu lub nie jest zwykłym plikiem.')
        data=stream.read(maximum+1)
    if len(data)>maximum:raise UserError('Tekst licencji przekracza limit odczytu.')
    if b'\0' in data:raise UserError('Nie otwarto binarnego pliku jako tekstu licencji.')
    return data


def _license_is_notice(name):
    path=Path(str(name));suffix=path.suffix.lower()
    if suffix in _LICENSE_DENIED_EXT:return False
    if _LICENSE_NOTICE_NAME.match(path.name):return True
    # Read texts in designated notice directories without inferring a license
    # from names such as MIT.txt or LGPL-3.0-only.txt.
    return suffix in ('','.txt','.md','.rst','.license') and any(part.lower() in ('licenses','licences','legal') for part in path.parts[:-1])


def _license_notice(root,path,budget):
    """A hash identifies the observed bytes; it never grants a license."""
    if budget['bytes']>=LICENSE_SCAN_BUDGET:raise UserError('Osiągnięto limit 16 MiB tekstów licencji.')
    data=_license_read_bytes(root,path,min(LICENSE_NOTICE_LIMIT,LICENSE_SCAN_BUDGET-budget['bytes']))
    budget['bytes']+=len(data)
    return {'label':Path(path).relative_to(root).as_posix(),'sha256':hashlib.sha256(data).hexdigest(),'bytes':len(data),
            '_root':str(Path(root).absolute()),'_path':str(Path(path).absolute())}


def read_license_notice(record):
    """Viewer entry point. A changed file must be rescanned, never blindly opened."""
    if not isinstance(record,dict) or not _license_is_notice(record.get('label','')):raise UserError('Nieprawidłowy wpis tekstu licencji.')
    if record.get('_archive'):
        path=_license_safe_file(record['_root'],record['_archive']);member=record['_member']
        if path.stat().st_size>256*1024*1024:raise UserError('Archiwum przekracza limit odczytu.')
        with zipfile.ZipFile(path) as archive:
            info=archive.getinfo(member)
            if info.file_size>LICENSE_NOTICE_LIMIT or info.flag_bits&1:raise UserError('Niedostępny tekst w archiwum.')
            with archive.open(info) as stream:data=stream.read(LICENSE_NOTICE_LIMIT+1)
    else:data=_license_read_bytes(record['_root'],record['_path'])
    if len(data)>LICENSE_NOTICE_LIMIT or b'\0' in data or hashlib.sha256(data).hexdigest()!=record.get('sha256'):
        raise UserError('Tekst licencji zmienił się od odczytu. Odśwież wykaz przed otwarciem.')
    return data.decode('utf-8-sig','replace')


def _license_package_row(dist, expected=None):
    meta=dist.metadata;name=_license_text(meta.get('Name') or 'Nieznany pakiet',160)
    version=_license_text(dist.version,100);declared=_license_text(meta.get('License-Expression') or meta.get('License') or '',500)
    declared=' '.join(declared.split())
    classifiers=[str(x).removeprefix('License :: ') for x in (meta.get_all('Classifier') or []) if str(x).startswith('License :: ')]
    if not declared:declared='; '.join(classifiers) or 'Brak deklaracji w metadanych'
    proof=('Deklaracja wydawcy · '+version,'https://pypi.org/project/'+urllib.parse.quote(_license_key(name),safe='')+'/'+urllib.parse.quote(version,safe='')+'/')
    if expected:
        title,pinned,license_name,role=expected
        commercial,terms,url=_LICENSE_RULES.get(license_name,('Zależnie od składnika',
            'Wheel Essentials nie ma jednej licencji obejmującej wszystkie pliki. Moduły używane przez Pivot mają wariant LGPLv3, '
            'ale przy przekazywaniu całego pakietu uwzględnij także pozostałe moduły i zależności, w tym składniki GPL-only. '+_LICENSE_LGPL_TERMS,
            'https://doc.qt.io/qt-6/licensing.html'))
        status='Deklaracja wydawcy · ta wersja' if version==pinned else 'Wersja do weryfikacji'
        if version!=pinned:commercial='Do weryfikacji wersji'
        # Do not award a known permissive interpretation to a contradictory local
        # declaration (e.g. a differently packaged internal distribution).
        normalized=' '.join(declared.lower().split())
        accepted={'MIT':{'mit','mit license','mit license (mit license)','osi approved :: mit license'},
            'PSF + licencje składników':{'psf','python software foundation license','osi approved :: python software foundation license'},
            'Apache-2.0':{'apache-2.0','apache 2.0','apache license 2.0','apache software license'},
            'UPL-1.0 OR Apache-2.0':{'upl-1.0 or apache-2.0','apache-2.0 or upl-1.0'},
            'LGPL-3.0-only':{'lgpl-3.0-only','lgpl-3.0','lgplv3','lgpl-3.0-only or gpl-3.0-only','licenseref-qt-commercial or lgpl-3.0-only or gpl-3.0-only'},
            'LGPL/GPL/commercial · per component':{'lgpl-3.0-only','lgpl-3.0','lgplv3','lgpl-3.0-only or gpl-3.0-only','licenseref-qt-commercial or lgpl-3.0-only or gpl-3.0-only'}}
        local_match=normalized in accepted.get(license_name,set())
        # SPDX OR is commutative. Only exact alternatives are accepted; AND,
        # arbitrary prose and expressions containing additional terms are not.
        choices=set(normalized.split(' or '))
        if license_name=='UPL-1.0 OR Apache-2.0':local_match=local_match or choices=={'upl-1.0','apache-2.0'}
        if license_name in ('LGPL-3.0-only','LGPL/GPL/commercial · per component'):
            allowed={'lgpl-3.0-only','gpl-2.0-only','gpl-2.0-or-later','gpl-3.0-only','gpl-3.0-or-later','licenseref-qt-commercial'}
            local_match=local_match or 'lgpl-3.0-only' in choices and choices<=allowed
        if version==pinned and not local_match:
            status='Rozbieżna deklaracja';commercial='Do weryfikacji'
            terms+=' Lokalna deklaracja jest nieobecna, odmienna lub niejednoznaczna; porównaj ją ze źródłem wydawcy.'
        row=_license_row(title,version,license_name,role,expected=pinned,status=status,commercial=commercial,terms=terms,
            proofs=(proof,('Warunki i składniki',url)),origin='Katalog wydawcy + lokalne metadane')
        row['review_date']=LICENSE_CATALOG_DATE
    else:
        row=_license_row(name,version,declared[:200],'Pakiet obecny w środowisku; nie oznacza, że aplikacja go używa.',
            group='Środowisko',terms='Deklaracja z lokalnych metadanych, bez niezależnej oceny tej wersji ani składników wbudowanych.',
            proofs=(proof,),origin='Wyłącznie lokalne metadane')
        if _license_key(name)=='pip':
            row.update(license='MIT + licencje składników',commercial='Sprawdź składniki',
                role='Narzędzie instalacyjne. Jego wbudowane biblioteki mają osobne licencje.',
                terms='Licencja samego pip nie zastępuje licencji pakietów w pip/_vendor. Sprawdź dołączone teksty i odpowiadające źródła.')
            row['proofs'].append({'label':'Polityka vendoringu','url':'https://pip.pypa.io/en/stable/development/vendoring-policy/'})
    row['metadata_license']=declared
    row['requires_python']=_license_text(meta.get('Requires-Python'),100)
    return row


def collect_technology_inventory(settings=None,cancel=None,*,distributions=None,native=True):
    """Read only local metadata and bounded notice texts. Does not import drivers.

    settings is a whitelist of external library paths, never connection data.
    distributions is injectable for deterministic tests. No filesystem scans run
    on import/startup: only an explicit request calls this function.
    """
    import importlib.metadata as metadata
    _license_cancel(cancel);settings={k:str((settings or {}).get(k,'') or '') for k in ('h2_jar','firebird_client','oracle_client')}
    rows=[];warnings=[];budget={'bytes':0,'files':0};seen=set()
    def warn(text):
        text=_license_text(text,300)
        if text not in warnings and len(warnings)<80:warnings.append(text)
    def built(name,version,license_name,role,terms,url,commercial='Tak · warunki licencji'):
        row=_license_row(name,version,license_name,role,group='Platforma',status='Warunki projektu · sprawdź dystrybucję',commercial=commercial,
                         terms=terms,proofs=(('Warunki wydawcy',url),));rows.append(row);return row
    built('Pivot Studio',APP_VERSION,'MIT','Kod aplikacji w jednym pliku.',
          'Zachowaj dołączony copyright i tekst MIT. Ta licencja nie obejmuje bibliotek zewnętrznych. Tekst znajduje się też w Informacjach o programie.',
          'https://opensource.org/license/mit')
    py=built('Python',platform.python_version(),'PSF-2.0 + licencje składników','Interpreter i biblioteka standardowa.',
          'Zachowaj licencję i noty PSF; przy dystrybucji sprawdź także dołączone składniki. Wersja interpretera nie jest pełnym wykazem jego komponentów.',
          'https://docs.python.org/3/license.html')
    built('SQLite',sqlite3.sqlite_version,'Public domain','Lokalne zbiory i zapytania SQLite. Wersja biblioteki Pythona, nie zewnętrznych serwerów.',
          'Kod SQLite został oddany do domeny publicznej. Nie rozszerza to statusu public domain na rozszerzenia, kodeki ani inne narzędzia.',
          'https://www.sqlite.org/copyright.html','Tak · public domain')
    try:
        import _tkinter
        tkver='Tcl '+str(_tkinter.TCL_VERSION)+' / Tk '+str(_tkinter.TK_VERSION)+' (wersja interfejsu)'
    except ImportError:tkver='Niewykryty składnik _tkinter'
    built('Tcl / Tk',tkver,'Tcl/Tk (BSD-style)','Okno przygotowania Tkinter. Nie otwiera nowej sesji Tk podczas skanowania.',
          'Dopuszczalne zastosowania komercyjne; zachowaj wymagane noty. Numer pochodzi z _tkinter i nie potwierdza patchlevel ani wszystkich rozszerzeń.',
          'https://www.tcl-lang.org/software/tcltk/license.html')
    # Qt module versions are supplied by the already running binding. Never load
    # an arbitrary discovered DLL or execute a version command for inventory.
    qc=sys.modules.get('PySide6.QtCore');qtver='Nie odczytano (Qt niezaładowane)'
    if qc is not None:
        with contextlib.suppress(Exception):qtver=qc.qVersion()
    for module,role in (('Core','Zdarzenia, sygnały i modele.'),('Gui','Rysowanie i tekst.'),('Widgets','Okna, tabele i kontrolki.'),('Svg','Wbudowane ikony wektorowe.')):
        row=built('Qt '+module,qtver,'LGPL-3.0-only (wybrana opcja)',role,_LICENSE_LGPL_TERMS,
                  'https://doc.qt.io/qt-6/qt'+module.lower()+'-index.html','Tak · warunki LGPLv3')
        row['present']=qc is not None;row['group']='Qt';row['status']='Moduł wymagany · sprawdź dystrybucję'
    iterable=metadata.distributions() if distributions is None else iter(distributions)
    candidates=[]
    for count,dist in enumerate(iterable):
        _license_cancel(cancel)
        if count>=LICENSE_PACKAGE_LIMIT:warn('Osiągnięto limit 512 pakietów; wykaz niepełny.');break
        try:candidates.append((_license_key(dist.metadata.get('Name') or ''),dist))
        except Exception as exc:warn('Nie odczytano metadanych pakietu ('+type(exc).__name__+').')
    for _,dist in sorted(candidates,key=lambda pair:(pair[0] not in _LICENSE_PACKAGES,pair[0])):
        _license_cancel(cancel)
        try:
            name=dist.metadata.get('Name') or '';key=_license_key(name)
            if not name:warn('Pominięto pakiet bez nazwy.');continue
            if key in seen:warn('Więcej niż jedna dystrybucja o nazwie '+name+'; pokazano oddzielne wpisy.')
            seen.add(key);row=_license_package_row(dist,_LICENSE_PACKAGES.get(key));rows.append(row)
            root=Path(dist.locate_file('')).absolute()
            files=dist.files
            if files is None:row['notice_status']='Brak spisu plików; teksty nieodczytane';continue
            candidates=[]
            for item in files:
                _license_cancel(cancel);budget['files']+=1
                if budget['files']>LICENSE_FILE_LIMIT:warn('Osiągnięto limit 24 000 wpisów plikowych; lista tekstów niepełna.');break
                if _license_is_notice(str(item)):candidates.append(item)
                if len(candidates)>=160:warn(name+': limit 160 tekstów licencji.');break
            for item in candidates:
                try:row['notices'].append(_license_notice(root,Path(dist.locate_file(item)).absolute(),budget))
                except (OSError,UserError,ValueError) as exc:warn(name+': pominięto tekst '+Path(str(item)).name+' ('+type(exc).__name__+').')
            row['notice_status']='Odczytane lokalne teksty: '+str(len(row['notices'])) if row['notices'] else 'Nie odnaleziono bezpiecznie dostępnych tekstów'
        except Cancelled:raise
        except Exception as exc:warn('Nie odczytano jednego pakietu ('+type(exc).__name__+').')
    for key,record in _LICENSE_PACKAGES.items():
        if key not in seen:
            title,version,lic,role=record
            row=_license_row(title,'—',lic,role,present=False,status=('Nie wykryto · skan ograniczony' if any('512 pakietów' in w for w in warnings) else 'Niezainstalowany'),commercial='Nie potwierdzono instalacji',expected=version,
                terms='Wersja planowana: '+version+'. Pakiet opcjonalny lub brakujący. Nie wykonano instalacji. Deklaracja wersji planowanej nie opisuje nieznanych zamienników.',
                proofs=(('Wersja planowana','https://pypi.org/project/'+urllib.parse.quote(title)+'/'+version+'/'),))
            rows.append(row)
    if native:
        _license_cancel(cancel)
        # Explicit known notice locations only; no scan of home, projects, DBs or
        # credentials. DLLs and java executables are never loaded by this feature.
        for path in (Path(sys.base_prefix)/'LICENSE.txt',Path(sys.base_prefix)/'LICENSE'):
            if path.is_file():
                with contextlib.suppress(OSError,UserError,ValueError):py['notices'].append(_license_notice(path.parent,path,budget))
        external=(
            ('Java runtime',os.environ.get('JAVA_HOME',''),'directory','Zależnie od dystrybucji',
             'Nie ustalono licencji Javy po samej nazwie. Sprawdź dystrybucję, wersję i teksty; nie uruchamiamy java -version.',
             'https://adoptium.net/temurin/'),
            ('H2 JDBC / silnik',settings['h2_jar'],'jar','MPL-2.0 OR EPL-1.0 (projekt H2)',
             'Projekt H2 oferuje dwa warianty. Sprawdź konkretny JAR i jego dołączone składniki; samo wskazanie pliku nie potwierdza wydawcy.',
             'https://h2database.com/html/license.html'),
            ('Firebird Client',settings['firebird_client'],'file','IPL / IDPL + licencje składników',
             'Odrębne od MIT pythonowego sterownika. Wersja i licencje konkretnego fbclient wymagają kontroli dystrybucji.',
             'https://www.firebirdsql.org/en/licensing/'),
            ('Oracle Client',settings['oracle_client'],'directory','Odrębne warunki Oracle',
             'Instant Client może być używany bez opłaty na jego warunkach. Nie obejmuje to licencji serwera. Nie zakładamy, że wskazany katalog jest wersją Instant Client.',
             'https://www.oracle.com/database/technologies/instant-client.html'))
        for name,value,kind,lic,terms,url in external:
            _license_cancel(cancel);present=False
            if value:
                with contextlib.suppress(OSError,ValueError):present=Path(value).exists()
            row=_license_row(name,'Nieustalona',lic,'Osobno dostarczany składnik; nie jest instalowany przez ten wykaz.',group='Zewnętrzne',
                present=present,status='Sprawdź konkretną dystrybucję' if present else 'Nie wskazano / niewykryty',commercial='Do weryfikacji dystrybucji',terms=terms,proofs=(('Warunki projektu',url),))
            rows.append(row)
            if not present:continue
            target=Path(value).absolute();root=target if kind=='directory' else target.parent
            if kind=='jar':
                try:
                    _license_safe_file(root,target)
                    if target.stat().st_size>256*1024*1024:raise UserError('Za duży JAR.')
                    with zipfile.ZipFile(target) as archive:
                        infos=archive.infolist()
                        if len(infos)>8192:raise UserError('Za dużo wpisów w JAR.')
                        for info in infos:
                            _license_cancel(cancel)
                            if info.filename.upper()=='META-INF/MANIFEST.MF' and info.file_size<65536:
                                manifest=archive.read(info).decode('utf-8','replace')
                                match=re.search(r'^Implementation-Version:\s*([^\r\n]+)',manifest,re.M)
                                if match:row['version']=_license_text(match.group(1),80)+' (manifest)'
                            if len(row['notices'])>=40:break
                            if not _license_is_notice(info.filename) or info.is_dir():continue
                            parts=posixpath.normpath(info.filename).split('/')
                            if '..' in parts or info.filename.startswith('/') or '\\' in info.filename or info.flag_bits&1:continue
                            if info.file_size>LICENSE_NOTICE_LIMIT or budget['bytes']+info.file_size>LICENSE_SCAN_BUDGET:continue
                            with archive.open(info) as f:data=f.read(LICENSE_NOTICE_LIMIT+1)
                            if len(data)>LICENSE_NOTICE_LIMIT or b'\0' in data:continue
                            budget['bytes']+=len(data)
                            row['notices'].append(dict(label=info.filename,sha256=hashlib.sha256(data).hexdigest(),bytes=len(data),_root=str(root),_archive=str(target),_member=info.filename))
                except (OSError,ValueError,UserError,zipfile.BadZipFile,KeyError):warn(name+': nie odczytano metadanych JAR; sprawdź plik.')
            else:
                if name=='Java runtime':
                    with contextlib.suppress(OSError,UserError):
                        release=_license_read_bytes(root,root/'release',65536).decode('utf-8','replace')
                        match=re.search(r'^JAVA_VERSION="([^"]+)"',release,re.M)
                        if match:row['version']=match.group(1)+' (release)'
                for directory in (root,root/'legal',root/'licenses',root/'LICENSES',root/'doc'):
                    if not directory.is_dir() or directory.is_symlink():continue
                    try:
                        for i,path in enumerate(directory.iterdir()):
                            _license_cancel(cancel)
                            if i>=256:warn(name+': ograniczono skan tekstów.');break
                            if path.is_dir() and not path.is_symlink() and directory!=root:
                                for n,child in enumerate(path.iterdir()):
                                    if n>=64:break
                                    _license_cancel(cancel)
                                    if _license_is_notice(child.relative_to(root)):
                                        with contextlib.suppress(OSError,UserError,ValueError):row['notices'].append(_license_notice(root,child,budget))
                            elif _license_is_notice(path.relative_to(root)):
                                with contextlib.suppress(OSError,UserError,ValueError):row['notices'].append(_license_notice(root,path,budget))
                    except OSError:warn(name+': nie odczytano katalogu tekstów.')
    rows.sort(key=lambda r:({'Platforma':0,'Qt':1,'Pakiety':2,'Zewnętrzne':3,'Środowisko':4}.get(r['group'],5),r['name'].casefold(),r['version']))
    # Stable IDs preserve selection on refresh. Do not expose paths in IDs/exports.
    occurrences={}
    for row in rows:
        key=row['group']+':'+_license_key(row['name']);n=occurrences.get(key,0);occurrences[key]=n+1
        row['id']=key+':'+str(n)
    return {'format':1,'application':APP_NAME,'version':APP_VERSION,'catalog_date':LICENSE_CATALOG_DATE,'generated_at':utcnow(),
        'platform':platform.system(),'python':platform.python_version(),'rows':rows,'warnings':warnings,
        'notice_bytes_read':budget['bytes'],'scope':LICENSE_REVIEW_LIMITATION,'full_audit':False}


def public_technology_inventory(report):
    """Whitelisted portable export: no absolute paths, settings, or credentials."""
    keys=('id','name','version','license','role','group','present','status','commercial','terms','expected_version','origin','review_date','metadata_license','notice_status','requires_python')
    result={k:report[k] for k in ('format','application','version','catalog_date','generated_at','platform','python','scope','full_audit','warnings') if k in report}
    result['rows']=[]
    for row in report.get('rows',[]):
        clean={k:row[k] for k in keys if k in row}
        clean['proofs']=[dict(p) for p in row.get('proofs',[]) if _license_https(p.get('url'))]
        clean['notices']=[{k:n[k] for k in ('label','sha256','bytes')} for n in row.get('notices',[])]
        result['rows'].append(clean)
    return result


def technology_inventory_text(report):
    report=public_technology_inventory(report)
    lines=[APP_NAME+' '+report.get('version',APP_VERSION)+' — technologie i licencje',
           'Katalog deklaracji: '+report.get('catalog_date',''),'Odczyt: '+report.get('generated_at',''),
           report.get('scope',''),'']
    for row in report['rows']:
        lines.extend([row['name']+' · '+row['version'],
            'Licencja: '+row['license']+' | '+row['commercial'],
            'Status: '+row['status'],'Rola: '+row['role'],'Warunki: '+row['terms']])
        if row.get('expected_version'):lines.append('Wersja katalogowa: '+row['expected_version'])
        for proof in row['proofs']:lines.append(proof['label']+': '+proof['url'])
        for notice in row['notices']:lines.append('Tekst: '+notice['label']+' | SHA-256: '+notice['sha256'])
        lines.append('')
    if report.get('warnings'):lines+=['Ograniczenia odczytu:',*report['warnings']]
    return '\n'.join(lines)+'\n'


def filter_technology_rows(report,query='',group='',installed_only=False):
    words=str(query).strip().casefold().split()
    return [r for r in report.get('rows',[]) if (not group or r['group']==group) and
        (not installed_only or r['present']) and all(word in ' '.join(str(r.get(k,'')) for k in
        ('name','license','role','commercial','status','version','terms')).casefold() for word in words)]



