    def animate_reveal(widget):
        app=QW.QApplication.instance();root=app.property('pivotPreferencesRoot')
        if appearance_preferences(root)['reduced_motion'] or not widget.isVisible():return
        if widget.graphicsEffect() is not None:return
        effect=QW.QGraphicsOpacityEffect(widget);effect.setOpacity(.25);widget.setGraphicsEffect(effect)
        animation=QC.QPropertyAnimation(effect,b'opacity',effect);animation.setDuration(160)
        animation.setStartValue(.25);animation.setEndValue(1.);animation.setEasingCurve(QC.QEasingCurve.Type.OutCubic)
        animation.finished.connect(lambda:widget.setGraphicsEffect(None));widget._reveal_animation=animation;animation.start()

    class EdgeController(QC.QObject):
        """Handle only left presses on this window's resize edges.

        Application-wide filters also see paint/layout/destruction events.
        Reject unrelated events before resolving a QWidget or its native handle.
        The controller and its QWidget clients must not shadow QWidget.window().
        """
        def __init__(self, window):
            super().__init__(window)
            self._host_window = window
            self._handling = False
            self._installed = True
            QW.QApplication.instance().installEventFilter(self)

        def detach(self):
            if not self._installed:
                return
            self._installed = False
            app = QW.QApplication.instance()
            if app is not None and qt_object_alive(app):
                app.removeEventFilter(self)

        def eventFilter(self, obj, event):
            if (not self._installed or self._handling
                    or event.type() != QC.QEvent.Type.MouseButtonPress):
                return False
            if event.button() != Qt.MouseButton.LeftButton:
                return False
            if not isinstance(obj, QW.QWidget) or not qt_object_alive(obj):
                return False
            host = self._host_window
            if not qt_object_alive(host) or getattr(host, 'closing', False):
                return False
            if (host.isMaximized() or host.isFullScreen()
                    or not (host.windowFlags() & Qt.WindowType.FramelessWindowHint)):
                return False
            # Call the known base API; never an incidental Python attribute.
            if QW.QWidget.window(obj) is not host:
                return False
            point = host.mapFromGlobal(event.globalPosition().toPoint())
            rect = host.rect()
            if not rect.contains(point):
                return False
            edges = Qt.Edge(0)
            if point.x() < 5:
                edges |= Qt.Edge.LeftEdge
            elif point.x() > rect.width() - 6:
                edges |= Qt.Edge.RightEdge
            if point.y() < 5:
                edges |= Qt.Edge.TopEdge
            elif point.y() > rect.height() - 6:
                edges |= Qt.Edge.BottomEdge
            if not edges:
                return False
            handle = host.windowHandle()
            if handle is None or not qt_object_alive(handle):
                return False
            self._handling = True
            try:
                return bool(handle.startSystemResize(edges))
            finally:
                self._handling = False

