    class WheelGuard(QC.QObject):
        def eventFilter(self,obj,event):
            if event.type()==QC.QEvent.Type.Wheel and isinstance(obj,(QW.QComboBox,QW.QAbstractSpinBox)):
                if isinstance(obj,QW.QComboBox) and obj.view().isVisible():return False
                parent=obj.parentWidget()
                while parent and not isinstance(parent,QW.QAbstractScrollArea):parent=parent.parentWidget()
                if parent:
                    bar=parent.verticalScrollBar();delta=event.pixelDelta().y() or event.angleDelta().y()/120*35
                    bar.setValue(bar.value()-int(delta))
                event.accept();return True
            return False

