    def alert(parent,title,text,detail=''):
        box=QW.QMessageBox(parent); box.setWindowTitle(title)
        box.setIcon(QW.QMessageBox.Icon.Warning); box.setTextFormat(Qt.TextFormat.PlainText)
        box.setText(str(text)); box.setStandardButtons(QW.QMessageBox.StandardButton.Ok)
        if detail: box.setDetailedText(detail)
