    def confirm(parent,title,text):
        box=QW.QMessageBox(parent); box.setWindowTitle(title); box.setTextFormat(Qt.TextFormat.PlainText)
        box.setText(text); box.setIcon(QW.QMessageBox.Icon.Question)
        yes=box.addButton('Kontynuuj',QW.QMessageBox.ButtonRole.AcceptRole)
        no=box.addButton('Anuluj',QW.QMessageBox.ButtonRole.RejectRole); box.setDefaultButton(no)
        box.exec(); return box.clickedButton()==yes

