    class AsyncTasks(QC.QObject):
        """I/O workers return immutable values. All callbacks run in the Qt thread."""
        changed=QC.Signal()
        def __init__(self,parent=None):
            super().__init__(parent); self.pool=ThreadPoolExecutor(max_workers=2,thread_name_prefix='LocalResultIO')
            self.pending={}; self.closed=False
            self.timer=QC.QTimer(self); self.timer.setInterval(35); self.timer.timeout.connect(self.poll); self.timer.start()
        def submit(self,fn,done,error=None,title=''):
            if self.closed: return ''
            key=uid(); self.pending[key]=(self.pool.submit(fn),done,error,title); self.changed.emit(); return key
        def poll(self):
            for key,(future,done,error,title) in list(self.pending.items()):
                if key not in self.pending or not future.done(): continue
                self.pending.pop(key,None)
                try:
                    value=future.result()
                    if done: done(value)
                except Exception as exc:
                    if error: error(safe_error(exc))
                    else:
                        parent=self.parent()
                        if parent is not None and not self.closed: alert(parent,'Operacja nie powiodła się',safe_error(exc))
                self.changed.emit()
        def close(self):
            self.closed=True; self.timer.stop(); self.pending.clear(); self.pool.shutdown(wait=False,cancel_futures=True)

    class JobWatcher(QC.QObject):
        changed=QC.Signal()
        def __init__(self,service,parent=None):
            super().__init__(parent); self.service=service; self.jobs={}; self.stages={}
            self.timer=QC.QTimer(self); self.timer.setInterval(100); self.timer.timeout.connect(self.poll); self.timer.start()
        def watch(self,response,done,error=None,progress=None,title='Zadanie'):
            jid=response['job_id']; self.jobs[jid]=(done,error,progress,title); self.changed.emit(); return jid
        def poll(self):
            # Project persistence may hold the service lock in an I/O thread.
            # Never wait for it on the Qt event loop; resume at the next tick.
            for jid,(done,error,progress,title) in list(self.jobs.items()):
                if jid not in self.jobs: continue
                if not self.service.lock.acquire(blocking=False): return
                try:
                    try: job=self.service.call('job',{'id':jid})
                    except Exception as exc: job={'status':'error','error':safe_error(exc)}
                finally: self.service.lock.release()
                self.stages[jid]=job.get('stage',title)
                if progress: progress(job)
                if job['status']=='running': continue
                self.jobs.pop(jid,None); self.stages.pop(jid,None)
                try:
                    if job['status']=='done':
                        if done: done(job.get('value'))
                    elif error: error(QtFailure(job.get('error','Zadanie anulowano.'),job.get('dependency'),
                                               job.get('catalog_scope'),job.get('connected',False)))
                    else: alert(self.parent(),'Nie wykonano operacji',job.get('error','Zadanie anulowano.'))
                except Exception as exc: alert(self.parent(),'Błąd obsługi wyniku',safe_error(exc))
                self.changed.emit()
        def cancel(self,jid): self.service.call('cancel',{'id':jid})

    class QtFailure(str):
        def __new__(cls,message,dependency=None,catalog_scope=None,connected=False):
            value=super().__new__(cls,message);value.dependency=clone(dependency) if dependency else None
            value.catalog_scope=clone(catalog_scope) if catalog_scope else None;value.connected=bool(connected);return value

    class ResultTableModel(QC.QAbstractTableModel):
        """Full virtual row range, asynchronous pages, precise numeric transport."""
        failed=QC.Signal(str)
        pageLoaded=QC.Signal(int)
        def __init__(self,tasks,parent=None):
            super().__init__(parent); self.tasks=tasks; self.path=''; self.meta={}; self.cache=collections.OrderedDict()
            self.pending=set(); self.bad_pages=set(); self.epoch=0; self.sort_id=None; self.direction='asc'
        def reset_result(self,path='',meta=None):
            self.beginResetModel(); self.path=str(path); self.meta=clone(meta or {}); self.cache.clear()
            self.pending.clear(); self.bad_pages.clear(); self.epoch+=1; self.sort_id=None; self.direction='asc'; self.endResetModel()
            if self.rowCount(): self.request_page(0)
        def rowCount(self,parent=QC.QModelIndex()): return 0 if parent.isValid() else int(self.meta.get('row_count',0))
        def columnCount(self,parent=QC.QModelIndex()): return 0 if parent.isValid() else len(self.meta.get('columns',[]))
        def flags(self,index):
            return (Qt.ItemFlag.ItemIsEnabled|Qt.ItemFlag.ItemIsSelectable) if index.isValid() else Qt.ItemFlag.NoItemFlags
        def headerData(self,section,orientation,role=Qt.ItemDataRole.DisplayRole):
            if role==Qt.ItemDataRole.DisplayRole:
                if orientation==Qt.Orientation.Vertical: return str(section+1)
                if 0<=section<self.columnCount():
                    c=self.meta['columns'][section]
                    return (c.get('group','')+'\n' if c.get('group') else '')+c['label']
            if role==Qt.ItemDataRole.ToolTipRole and orientation==Qt.Orientation.Horizontal and 0<=section<self.columnCount():
                c=self.meta['columns'][section]
                return (c.get('group','')+' / ' if c.get('group') else '')+c['label']
            return None
        def row_value(self,row):
            page=row//PAGE_SIZE
            if page in self.cache:
                self.cache.move_to_end(page); rows=self.cache[page]['rows']; offset=row%PAGE_SIZE
                return rows[offset] if offset<len(rows) else None
            self.request_page(page); return None
        def data(self,index,role=Qt.ItemDataRole.DisplayRole):
            if not index.isValid() or not 0<=index.row()<self.rowCount() or not 0<=index.column()<self.columnCount(): return None
            column=self.meta['columns'][index.column()]
            if role==Qt.ItemDataRole.TextAlignmentRole:
                return int(Qt.AlignmentFlag.AlignVCenter|(Qt.AlignmentFlag.AlignRight if column['kind']=='number' else Qt.AlignmentFlag.AlignLeft))
            row=self.row_value(index.row())
            if row is None:
                if role==Qt.ItemDataRole.DisplayRole: return 'Błąd odczytu' if index.row()//PAGE_SIZE in self.bad_pages else '…'
                return None
            cell=row['v'][index.column()]
            if role==Qt.ItemDataRole.DisplayRole: return 'NULL' if cell is None else cell.get('d',display_cell(cell,column.get('format','auto')))
            if role==Qt.ItemDataRole.ToolTipRole: return 'Pusta wartość (NULL), nie zero.' if cell is None else str(cell['v'])
            if role==Qt.ItemDataRole.ForegroundRole and cell is None: return QG.QBrush(ui_color('muted'))
            if role==Qt.ItemDataRole.BackgroundRole and row['total']: return QG.QBrush(ui_color('total'))
            if role==Qt.ItemDataRole.FontRole and (row['total'] or cell is None):
                f=QG.QFont(); f.setBold(row['total']); f.setItalic(cell is None); return f
            if role==ROLE: return cell
            return None
        def request_page(self,page):
            if not self.path or page in self.pending or page in self.cache or page in self.bad_pages: return
            self.pending.add(page); epoch=self.epoch; path=self.path; sort=self.sort_id; direction=self.direction
            def success(value):
                if epoch!=self.epoch: return
                self.pending.discard(page); self.cache[page]=value
                while len(self.cache)>16: self.cache.popitem(last=False)
                start=page*PAGE_SIZE; end=min(self.rowCount()-1,start+PAGE_SIZE-1)
                if end>=start and self.columnCount(): self.dataChanged.emit(self.index(start,0),self.index(end,self.columnCount()-1),[])
                self.pageLoaded.emit(page)
            def failure(message):
                if epoch!=self.epoch: return
                self.pending.discard(page); self.bad_pages.add(page); self.failed.emit(message)
            self.tasks.submit(lambda:ResultStore.page(path,page,sort,direction),success,failure)
        def sort(self,column,order=Qt.SortOrder.AscendingOrder):
            if not self.path: return
            sid=self.meta['columns'][column]['id'] if 0<=column<self.columnCount() else None
            direction='desc' if order==Qt.SortOrder.DescendingOrder else 'asc'
            if sid==self.sort_id and direction==self.direction: return
            self.beginResetModel(); self.sort_id=sid; self.direction=direction; self.epoch+=1
            self.cache.clear(); self.pending.clear(); self.bad_pages.clear(); self.endResetModel()
            if self.rowCount(): self.request_page(0)

    class ReadingDelegate(QW.QStyledItemDelegate):
        """Measure and paint the same plain-text layout. No rich-text execution in cells."""
        def __init__(self,view):
            super().__init__(view);self._view=view;self._cache=collections.OrderedDict()
        def text_layout(self,text,font,width):
            text=text.replace('\r\n','\n').replace('\r','\n').replace('\n','\u2028')
            text=text[:8192]+('…' if len(text)>8192 else '')
            width=max(12,int(width));key=(text,font.toString(),width)
            cached=self._cache.get(key)
            if cached is not None:self._cache.move_to_end(key);return cached
            layout=QG.QTextLayout(text,font);opt=QG.QTextOption()
            opt.setWrapMode(QG.QTextOption.WrapMode.WrapAtWordBoundaryOrAnywhere);layout.setTextOption(opt)
            layout.beginLayout();lines=[];height=0.;overflow=False
            try:
                for _ in range(7):
                    line=layout.createLine()
                    if not line.isValid():break
                    if len(lines)==6:overflow=True;break
                    line.setLineWidth(width);line.setPosition(QC.QPointF(0,height));height+=line.height();lines.append(line)
            finally:layout.endLayout()
            result=(layout,lines,math.ceil(height)+18,overflow)
            self._cache[key]=result
            while len(self._cache)>384:self._cache.popitem(last=False)
            return result
        def metrics_for(self,index,width):
            option=QW.QStyleOptionViewItem();option.initFrom(self._view);self.initStyleOption(option,index)
            return self.text_layout(option.text,option.font,width-24)
        def paint(self,painter,option,index):
            controller=getattr(self._view,'presentation',None)
            if not controller or not controller.reading:
                super().paint(painter,option,index);return
            opt=QW.QStyleOptionViewItem(option);self.initStyleOption(opt,index)
            text=opt.text;opt.text='';style=opt.widget.style() if opt.widget else QW.QApplication.style()
            style.drawControl(QW.QStyle.ControlElement.CE_ItemViewItem,opt,painter,opt.widget)
            layout,lines,height,overflow=self.text_layout(text,opt.font,opt.rect.width()-24)
            painter.save()
            try:
                painter.setClipRect(opt.rect.adjusted(1,1,-1,-1));painter.setFont(opt.font)
                selected=bool(opt.state & QW.QStyle.StateFlag.State_Selected)
                painter.setPen(opt.palette.color(QG.QPalette.ColorRole.HighlightedText if selected else QG.QPalette.ColorRole.Text))
                numeric=bool(opt.displayAlignment & Qt.AlignmentFlag.AlignRight)
                origin=QC.QPointF(opt.rect.left()+12,opt.rect.top()+8)
                for number,line in enumerate(lines):
                    if overflow and number==len(lines)-1:
                        remaining=layout.text()[line.textStart():].replace('\u2028',' ')
                        tail=QG.QFontMetrics(opt.font).elidedText(remaining,Qt.TextElideMode.ElideRight,max(12,opt.rect.width()-24))
                        painter.drawText(QC.QPointF(origin.x(),origin.y()+line.y()+line.ascent()),tail)
                    else:
                        offset=max(0,opt.rect.width()-24-line.naturalTextWidth()) if numeric else 0
                        line.draw(painter,QC.QPointF(origin.x()+offset,origin.y()))
            finally:painter.restore()

    class GridPresentation(QC.QObject):
        """View-only preferences and bounded visible-row measurement; never edits analysis revisions."""
        readingChanged=QC.Signal(bool)
        def __init__(self,grid):
            super().__init__(grid);self._grid=grid;self.reading=False;self._applying=False;self._key='';self._settings=None
            self._auto=True;self._has_saved_mode=False;self._fitted=False;self._dense=False
            self._timer=QC.QTimer(self);self._timer.setSingleShot(True);self._timer.setInterval(35);self._timer.timeout.connect(self.relayout)
            self._save_timer=QC.QTimer(self);self._save_timer.setSingleShot(True);self._save_timer.setInterval(200);self._save_timer.timeout.connect(self.save)
            self.delegate=ReadingDelegate(grid);grid.setItemDelegate(self.delegate)
            # The frozen viewport uses identical measurement and rendering rules.
            grid.frozen.setItemDelegate(ReadingDelegate(grid))
            grid.horizontalHeader().sectionResized.connect(self.column_changed)
            grid.horizontalHeader().sectionMoved.connect(lambda *_:self._save_timer.start())
            grid.horizontalHeader().sectionDoubleClicked.connect(self.fit_one)
            grid.verticalScrollBar().valueChanged.connect(self.schedule)
            grid.installEventFilter(self)
        def attach(self,model):
            model.pageLoaded.connect(self.loaded);model.modelReset.connect(self.schedule)
        def eventFilter(self,obj,event):
            if obj is self._grid and event.type() in (QC.QEvent.Type.Resize,QC.QEvent.Type.Show,QC.QEvent.Type.FontChange,QC.QEvent.Type.StyleChange):
                self.schedule()
            return False
        def schedule(self,*_):
            if not self._applying:self._timer.start()
        def setup(self,meta):
            self._save_timer.stop();grid=self._grid
            host=grid.window();self._settings=getattr(host,'ui_settings',None)
            d=meta.get('analysis',{}).get('dataset',{})
            identity={'source':meta.get('source_id'),'dataset':d.get('dataset_id') or d,
                'sheet':meta.get('sheet_name'), 'kind':'data' if meta.get('kind') in ('sample','preview') else meta.get('kind'),
                'analysis':meta.get('analysis_id') if meta.get('kind')=='pivot' else ''}
            self._key='grid-v2/'+digest(identity);self._fitted=False;self._auto=True;self._has_saved_mode=False
            raw=self._settings.value(self._key,'') if self._settings else ''
            try:state=json.loads(raw) if raw else {}
            except (ValueError,TypeError):state={}
            if not isinstance(state,dict):state={}
            self._applying=True
            try:
                self.reading=state.get('reading') is True;self._has_saved_mode=isinstance(state.get('reading'),bool)
                grid.setWordWrap(self.reading);grid.frozen.setWordWrap(self.reading)
                labels=[c.get('id','')+'|'+c['label'] for c in meta.get('columns',[])]
                self._labels=labels;widths=state.get('widths',{})
                saved=isinstance(widths,dict) and bool(widths) and all(type(widths.get(k)) is int and 55<=widths[k]<=1600 for k in labels)
                if saved:
                    for i,key in enumerate(labels):grid.setColumnWidth(i,max(70,min(1400,int(widths[key]))))
                    self._auto=bool(state.get('auto',False));self._fitted=not self._auto
                else:
                    for i in range(len(labels)):grid.setColumnWidth(i,180)
                order=state.get('order',[])
                if isinstance(order,list) and all(isinstance(k,str) for k in order) and len(order)==len(labels) and set(order)==set(labels):
                    header=grid.horizontalHeader()
                    for pos,key in enumerate(order):header.moveSection(header.visualIndex(labels.index(key)),pos)
                height=max(30,grid.fontMetrics().height()+18)
                grid.verticalHeader().setDefaultSectionSize(height);grid.frozen.verticalHeader().setDefaultSectionSize(height)
                grid.update_frozen()
            finally:self._applying=False
            self.readingChanged.emit(self.reading);self.schedule()
        def loaded(self,page):
            if page==0 and self._auto and not self._fitted:self.fit(False)
            if page==0 and not self._has_saved_mode:
                model=self._grid.model();rows=model.cache.get(0,{}).get('rows',[])
                lengths=[len(str(c.get('v',''))) for row in rows[:40] for c in row['v'] if c and c.get('t')=='s']
                if lengths and max(lengths)>100 and model.meta.get('kind')!='pivot':self.set_reading(True,False)
                self._has_saved_mode=True
            self.schedule()
        def set_reading(self,value,user=True):
            self.reading=bool(value);self._grid.setWordWrap(self.reading);self._grid.frozen.setWordWrap(self.reading)
            if user:self._has_saved_mode=True;self._save_timer.start()
            self.readingChanged.emit(self.reading);self.schedule();self._grid.viewport().update();self._grid.frozen.viewport().update()
        def column_changed(self,*_):
            if self._applying:return
            self._auto=False;self._fitted=True;self._save_timer.start();self.schedule()
        def save(self):
            if not self._settings or not self._key or self._applying:return
            grid=self._grid;labels=getattr(self,'_labels',[])
            if not grid.model() or grid.model().columnCount()!=len(labels):return
            state={'reading':self.reading,'auto':self._auto,
                'widths':{k:grid.columnWidth(i) for i,k in enumerate(labels)},
                'order':[labels[grid.horizontalHeader().logicalIndex(i)] for i in range(len(labels))]}
            self._settings.setValue(self._key,dumps(state));self._settings.sync()
        def fit(self,user=True):
            grid=self._grid;model=grid.model()
            if not model or not model.columnCount():return
            page=model.cache.get(0)
            if not page:model.request_page(0);return
            fm=grid.fontMetrics();columns=model.meta['columns'];rows=page['rows'][:50];widths=[];weights=[]
            for i,c in enumerate(columns):
                values=[fm.horizontalAdvance(str(r['v'][i].get('d',r['v'][i].get('v',''))).split('\n')[0][:160])
                        for r in rows if i<len(r['v']) and r['v'][i]]
                values.sort();sample=values[int((len(values)-1)*.75)] if values else 90
                header=min(300,fm.horizontalAdvance(c['label'])+42)
                numeric=c.get('kind')=='number';widths.append(max(90,min(180 if numeric else 620,max(header,sample+26))))
                weights.append(0 if numeric else max(1,sample))
            available=max(150,grid.viewport().width()-4);minimums=[min(w,140 if columns[i].get('kind')=='number' else 175) for i,w in enumerate(widths)]
            if sum(widths)>available and sum(minimums)<=available:
                room=available-sum(minimums);want=sum(w-m for w,m in zip(widths,minimums)) or 1
                widths=[m+int(room*(w-m)/want) for w,m in zip(widths,minimums)]
            elif sum(widths)<available and any(weights):
                extra=available-sum(widths);total=sum(weights)
                widths=[min(850,w+int(extra*weights[i]/total)) for i,w in enumerate(widths)]
            self._applying=True
            try:
                for i,w in enumerate(widths):grid.setColumnWidth(i,int(w))
            finally:self._applying=False
            self._auto=True;self._fitted=True
            if user:self.save()
            self.schedule()
        def fit_one(self,index):
            if self._applying or self._grid.model() is None or not 0<=index<self._grid.model().columnCount():return
            grid=self._grid;grid.horizontalHeader().setResizeContentsPrecision(100)
            self._applying=True
            try:grid.resizeColumnToContents(index);grid.setColumnWidth(index,min(900,max(90,grid.columnWidth(index))))
            finally:self._applying=False
            self._auto=False;self.save();self.schedule()
        def relayout(self):
            grid=self._grid;model=grid.model()
            if not grid.isVisible() or model is None:return
            if self._auto and model.cache.get(0):self.fit_if_resized()
            n=model.rowCount()
            if not n:return
            start=max(0,grid.rowAt(0));end=grid.rowAt(grid.viewport().height()-1)
            end=min(n-1,(start+40 if end<0 else end)+2)
            self._applying=True
            try:
                base=max(28 if self._dense else 34,grid.fontMetrics().height()+16)
                for row in range(start,min(end+1,start+100)):
                    height=base
                    if self.reading and model.row_value(row) is not None:
                        for col in range(model.columnCount()):
                            if not grid.isColumnHidden(col):height=max(height,self.delegate.metrics_for(model.index(row,col),grid.columnWidth(col))[2])
                    if grid.rowHeight(row)!=height:grid.setRowHeight(row,height)
                grid.update_frozen_geometry()
            finally:self._applying=False
        def fit_if_resized(self):
            width=self._grid.viewport().width()
            if getattr(self,'_fit_width',None)==width:return
            self._fit_width=width;self.fit(False)


    class ResultGrid(QW.QTableView):
        copyRequested=QC.Signal(bool)
        detailRequested=QC.Signal(object)
        def __init__(self,parent=None):
            super().__init__(parent); self.empty_text='Wybierz tabelę ze źródła albo otwórz przykład.'
            self.setObjectName('resultGrid'); self.setAlternatingRowColors(True); self.setWordWrap(False)
            self.setSelectionMode(QW.QAbstractItemView.SelectionMode.ExtendedSelection)
