    class AxisList(QW.QListWidget):
        fieldDropped=QC.Signal(str)
        reordered=QC.Signal()
        def __init__(self,parent=None):
            super().__init__(parent); self.setAcceptDrops(True); self.setDragEnabled(True)
            self.setDragDropMode(QW.QAbstractItemView.DragDropMode.InternalMove)
            self.setDefaultDropAction(Qt.DropAction.MoveAction); self.setMinimumHeight(40); self.setMaximumHeight(125)
            self.model().rowsMoved.connect(lambda *args:QC.QTimer.singleShot(0,self.reordered.emit))
        def paintEvent(self,event):
            super().paintEvent(event)
            if not self.count():
                painter=QG.QPainter(self.viewport());painter.setRenderHint(QG.QPainter.RenderHint.Antialiasing)
                pen=QG.QPen(ui_color('border'),1,Qt.PenStyle.DashLine);painter.setPen(pen);painter.setBrush(Qt.BrushStyle.NoBrush)
                painter.drawRoundedRect(QC.QRectF(self.viewport().rect().adjusted(2,2,-3,-3)),7,7)
                painter.setPen(ui_color('muted'));painter.drawText(self.viewport().rect().adjusted(12,0,-8,0),Qt.AlignmentFlag.AlignVCenter|Qt.AlignmentFlag.AlignLeft,getattr(self,'placeholder','Upuść pole tutaj'))
                painter.end()
        def dragEnterEvent(self,event):
            if event.mimeData().hasFormat('application/x-pivotstudio-field'): event.acceptProposedAction()
            else: super().dragEnterEvent(event)
        def dragMoveEvent(self,event):
            if event.mimeData().hasFormat('application/x-pivotstudio-field'): event.acceptProposedAction()
            else: super().dragMoveEvent(event)
        def dropEvent(self,event):
            if event.mimeData().hasFormat('application/x-pivotstudio-field'):
                name=bytes(event.mimeData().data('application/x-pivotstudio-field')).decode('utf-8')
                self.fieldDropped.emit(name); event.acceptProposedAction()
            else: super().dropEvent(event)

