                sl.addWidget(view);lay.addWidget(section);view.fieldDropped.connect(lambda name,k=key:self.add(k,name))
                view.itemDoubleClicked.connect(lambda item,k=key:self.edit(k));view.reordered.connect(lambda k=key:self.reorder(k))
                view.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu)
