                    action=QG.QAction(view);action.setShortcut(QG.QKeySequence(shortcut));action.setShortcutContext(Qt.ShortcutContext.WidgetShortcut);action.triggered.connect(lambda checked=False,fn=fn:fn());view.addAction(action)
