            menu.addAction('Połącz oryginał tej samej wersji…',lambda:host.guard(lambda:host.relink_workbook(self.context['source_id']) if self.context else None))
            self.more.setMenu(menu);actions.addWidget(self.more,0,2);self.arrange_actions()
