            for item in (self.sheet_combo,self.hidden,self.prepare_button,self.analyze_button,self.more):self._action_grid.removeWidget(item)
            for col in range(5):self._action_grid.setColumnStretch(col,0)
            self._action_grid.setColumnStretch(0,1)
