    class BarChart(QW.QWidget):
        def __init__(self,parent=None):
            super().__init__(parent); self.items=[]; self.setMinimumHeight(240); self.setAccessibleName('Wykres słupkowy wartości miary; dane dostępne w tabeli przestawnej.')
        def set_items(self,items):
            self.items=clone(items); self.setMinimumHeight(max(240,len(items)*34+45)); self.update()
        def paintEvent(self,event):
            painter=QG.QPainter(self); painter.setRenderHint(QG.QPainter.RenderHint.Antialiasing)
            painter.fillRect(self.rect(),self.palette().base()); painter.setPen(self.palette().text().color())
            if not self.items:
                painter.drawText(self.rect(),Qt.AlignmentFlag.AlignCenter,'Oblicz pivot i wybierz miarę.'); return
            width=self.width(); left=min(170,max(85,int(width*.22))); right=min(150,max(80,int(width*.23)))
            available=max(30,width-left-right-35); signed=any(item['negative'] for item in self.items)
            zero=left+available/2 if signed else left; scale=available/2 if signed else available
            painter.setPen(ui_color('border')); painter.drawLine(int(zero),16,int(zero),len(self.items)*34+24)
            fm=painter.fontMetrics()
            for i,item in enumerate(self.items):
                y=24+i*34; painter.setPen(self.palette().text().color())
                text=fm.elidedText(item['label'],Qt.TextElideMode.ElideRight,left-18)
                painter.drawText(QC.QRect(10,y-2,left-20,24),Qt.AlignmentFlag.AlignVCenter|Qt.AlignmentFlag.AlignRight,text)
                w=max(1,item['width']/100*scale); x=zero-w if item['negative'] else zero
                painter.setPen(Qt.PenStyle.NoPen); painter.setBrush(ui_color('error' if item['negative'] else 'chart'))
                painter.drawRoundedRect(QC.QRectF(x,y,w,20),3,3); painter.setPen(self.palette().text().color())
                value=fm.elidedText(item['display'],Qt.TextElideMode.ElideRight,right-10)
                painter.drawText(QC.QRect(width-right,y-2,right-10,24),Qt.AlignmentFlag.AlignVCenter|Qt.AlignmentFlag.AlignRight,value)

    def mime_local_file_paths(mime):
        """Detach Python paths while the native MIME object is still alive."""
        if not mime.hasUrls():return None
        urls=mime.urls()
        if not urls:raise UserError('Nie otrzymano ścieżki pliku. Zapisz plik na dysku i przeciągnij go ponownie.')
        if len(urls)>MAX_INCOMING_FILES:raise UserError(f'Wybierz najwyżej {MAX_INCOMING_FILES} plików naraz.')
        paths=[]
        for url in urls:
            if not url.isValid() or not url.isLocalFile() or url.hasQuery() or url.hasFragment():
                raise UserError('Przeciągnij plik zapisany na dysku, nie odnośnik internetowy.')
            # QUrl, not hand-written percent decoding: #, %, Unicode and UNC survive.
            value=url.toLocalFile()
            if not value:raise UserError('Nie można odczytać lokalnej ścieżki pliku.')
            paths.append(value)
        return tuple(item['path'] for item in incoming_file_plan(paths))

    class FileDropOverlay(QW.QWidget):
        """Paint-only overlay; never captures the drag or steals keyboard focus."""
        def __init__(self,window):
            super().__init__(window);self._host_window=window;self._headline='';self._detail='';self._allowed=True
            self.setAttribute(Qt.WidgetAttribute.WA_TransparentForMouseEvents,True)
            self.setFocusPolicy(Qt.FocusPolicy.NoFocus);self.setAcceptDrops(False);self.hide()
        def fit_host(self):
            host=self._host_window
            top=host.menuWidget().height() if host.menuWidget() else 0
            bottom=host.statusBar().height() if host.statusBar().isVisible() else 0
            self.setGeometry(4,top+4,max(0,host.width()-8),max(0,host.height()-top-bottom-8))
        def present(self,headline,detail,allowed=True):
            self._headline=headline;self._detail=detail;self._allowed=allowed
            self.setAccessibleName(headline);self.setAccessibleDescription(detail)
            self.fit_host();self.show();self.raise_();self.update()
        def paintEvent(self,event):
            painter=QG.QPainter(self)
            try:
                painter.setRenderHint(QG.QPainter.RenderHint.Antialiasing)
                veil=ui_color('bg');veil.setAlpha(230);painter.fillRect(self.rect(),veil)
                accent=ui_color('accent' if self._allowed else 'error')
                frame=QC.QRectF(self.rect()).adjusted(14,14,-14,-14)
                painter.setPen(QG.QPen(accent,1.5,Qt.PenStyle.DashLine));painter.setBrush(Qt.BrushStyle.NoBrush)
                painter.drawRoundedRect(frame,16,16)
                width=min(570,max(180,self.width()-80));x=(self.width()-width)/2
                y=max(28,(self.height()-208)/2)
                icon=ui_icon('upload' if self._allowed else 'info',40).pixmap(40,40)
                painter.drawPixmap(round((self.width()-40)/2),round(y),icon)
                font=QG.QFont(self.font());font.setPixelSize(24);font.setWeight(QG.QFont.Weight.DemiBold)
                painter.setFont(font);painter.setPen(ui_color('text'))
                flags=int(Qt.AlignmentFlag.AlignHCenter)|int(Qt.AlignmentFlag.AlignTop)|int(Qt.TextFlag.TextWordWrap)
                title_rect=QC.QRectF(x,y+57,width,90)
                title_bounds=painter.boundingRect(title_rect,flags,self._headline)
                painter.drawText(title_rect,flags,self._headline)
                font.setPixelSize(14);font.setWeight(QG.QFont.Weight.Normal);painter.setFont(font);painter.setPen(ui_color('muted'))
                painter.drawText(QC.QRectF(x,title_bounds.bottom()+16,width,110),flags,self._detail)
            finally:painter.end()

    class FileDropController(QC.QObject):
        """Scoped native file drop routing, including child views and SQL editors.

        Only URL drops in this main window are intercepted. Internal field drags
        retain their original handlers. No disk access, dialogs or installs here.
        """
        filesDropped=QC.Signal(object)
        def __init__(self,window):
            super().__init__(window);self._host_window=window;self._installed=False
            self._overlay=FileDropOverlay(window);self._drag_visible=False
            self._leave_timer=QC.QTimer(self);self._leave_timer.setSingleShot(True);self._leave_timer.setInterval(35)
            self._leave_timer.timeout.connect(self.clear)
            self.filesDropped.connect(window.receive_files,Qt.ConnectionType.QueuedConnection)
            window.setAcceptDrops(True)
            QW.QApplication.instance().installEventFilter(self);self._installed=True
        def clear(self):
            self._leave_timer.stop();self._drag_visible=False
            if qt_object_alive(self._overlay):self._overlay.hide()
        def detach(self):
            if not self._installed:return
            self._installed=False;app=QW.QApplication.instance()
            if app is not None:app.removeEventFilter(self)
            self.clear()
        def eventFilter(self,obj,event):
            kind=event.type()
            if kind not in (QC.QEvent.Type.DragEnter,QC.QEvent.Type.DragMove,QC.QEvent.Type.DragLeave,QC.QEvent.Type.Drop,
                            QC.QEvent.Type.Resize,QC.QEvent.Type.Hide):return False
            if not self._installed or not qt_object_alive(self._host_window):return False
            host=self._host_window
            if kind in (QC.QEvent.Type.Resize,QC.QEvent.Type.Hide):
                if obj is host:
                    if kind==QC.QEvent.Type.Hide:self.clear()
                    elif self._drag_visible:self._overlay.fit_host()
                return False
            if not isinstance(obj,QW.QWidget) or not qt_object_alive(obj):return False
            # Call the base Qt method explicitly; dialog windows are out of scope.
            if QW.QWidget.window(obj) is not host:return False
            if kind==QC.QEvent.Type.DragLeave:
                if self._drag_visible:self._leave_timer.start()
                return False
            mime=event.mimeData()
            if mime.hasFormat('application/x-pivotstudio-field'):self.clear();return False
            if not mime.hasUrls():return False
            self._leave_timer.stop()
            try:
                paths=mime_local_file_paths(mime)
                if host.closing or host.project_busy or host._file_intake_active:
                    raise UserError('Dokończ albo anuluj bieżący import lub zapis. Następnie upuść kolejny plik.')
                if QW.QApplication.activeModalWidget() is not None:
                    raise UserError('Najpierw zamknij otwarte okno dialogowe.')
                if not (event.possibleActions() & Qt.DropAction.CopyAction):
                    raise UserError('Ta operacja pozwala tylko przenieść plik. Pivot przyjmuje kopię, bez usuwania oryginału.')
                plan=incoming_file_plan(paths)
                if kind==QC.QEvent.Type.Drop:
                    self.clear();event.setDropAction(Qt.DropAction.CopyAction);event.accept()
                    # Never keep event/mime/QUrl wrappers past this callback.
                    self.filesDropped.emit(paths)
                else:
                    if len(plan)>1:
                        title=f'Upuść {len(plan)} plików, aby dodać dane'
                        detail='Przejdziesz przez import kolejno. Anulowanie zatrzyma pozostałe pliki. Oryginały pozostają bez zmian.'
                    else:
                        item=plan[0]
                        title={'tabular':'Upuść, aby zaimportować','sqlite':'Upuść, aby otworzyć całą bazę','project':'Upuść, aby otworzyć projekt'}[item['kind']]
                        detail=item['name']+'\n'+{'tabular':'Najpierw wybór arkusza i podgląd. Oryginał bez zmian.',
                            'sqlite':'Połączenie tylko do odczytu. Bieżąca analiza pozostanie w projekcie.',
                            'project':'Niezapisane zmiany wymagają Twojej decyzji.'}[item['kind']]
                    self._drag_visible=True;self._overlay.present(title,detail)
                    event.setDropAction(Qt.DropAction.CopyAction);event.accept()
                return True
            except UserError as exc:
                event.ignore()
                # A rejected DragEnter need not be followed by DragLeave. Do not
                # strand an overlay on screen after an unsupported-file gesture.
                self.clear();host.statusBar().showMessage(str(exc),12000)
                return True
            except (RuntimeError,AttributeError) as exc:
                # Deleted Qt objects or incomplete native MIME data must not unwind
                # through the operating system's drag loop.
                event.ignore();self.clear()
                if qt_object_alive(host):host.statusBar().showMessage('Nie odczytano przeciąganego pliku. Użyj „Importuj dane”. '+safe_error(exc),10000)
                return True

    class FileJobDialog(FormDialog):
        """A cancellable worker task. Closing requests cancellation, then waits for acknowledgement."""
        def __init__(self,window,response,title):
            super().__init__(title,window);self._host_window=window;self._job_id=response['job_id']
            self._completed=False;self._cancel_requested=False;self._error='';self._result_value=None
            self._note=label('Przygotowanie…',True,True);self.add_widget(self._note)
            bar=QW.QProgressBar();bar.setRange(0,0);bar.setFixedHeight(5);self.add_widget(bar)
            self.buttons.button(QW.QDialogButtonBox.StandardButton.Ok).hide()
            limited_dialog_size(self,570,250)
            window.watcher.watch(response,self._done,self._failed,self._progress,title=title)
        def accept(self):
            # No Enter/default-button shortcut may leave a running worker
            # without its progress observer and cancellation acknowledgement.
            if self._completed:super().accept()
        def _progress(self,job):
            if not self._cancel_requested:self._note.setText(job.get('stage','Trwa odczyt…'))
        def _done(self,value):
            self._completed=True;self._result_value=value
            # Import may have committed just before cancel: keep and display its
            # success; never claim a committed result has been rolled back.
            if self._cancel_requested and not (isinstance(value,dict) and value.get('analysis')):super().reject()
            else:self.accept()
        def _failed(self,message):
            self._completed=True
            if not self._cancel_requested:self._error=message
            super().reject()
        def reject(self):
            if self._completed:super().reject();return
            if not self._cancel_requested:
                self._cancel_requested=True;self._host_window.watcher.cancel(self._job_id)
                self._note.setText('Kończę bieżący odczyt. Poczekaj na potwierdzenie anulowania.')
                self.buttons.button(QW.QDialogButtonBox.StandardButton.Cancel).setEnabled(False)
        def closeEvent(self,event):
            if self._completed:super().closeEvent(event)
            else:self.reject();event.ignore()


    # ================= Native spreadsheet workspace, no ribbon ===============
    class SheetModel(QC.QAbstractTableModel):
        editFailed=QC.Signal(str)
        def __init__(self,parent=None):
            super().__init__(parent);self.session=None;self.sheet_id='';self.row_limit=1000;self.col_limit=52;self.zoom=1.0;self.read_only=False
        def set_book(self,session,sid):
            self.beginResetModel();self.session=session;self.sheet_id=sid
            cells=sheet_find(session.book,sid)['cells'];coords=[sheet_position(a) for a in cells]
            self.row_limit=min(SHEET_MAX_ROWS,max(1000,max((r for r,c in coords),default=0)+101))
            self.col_limit=min(SHEET_MAX_COLS,max(52,max((c for r,c in coords),default=0)+11));self.endResetModel()
        def cells_changed(self,change):
            if self.session is None:return
            if change.sheet_id==self.sheet_id and change.addresses:
                positions=[sheet_position(a) for a in change.addresses]
                self.ensure_cell(max(r for r,c in positions),max(c for r,c in positions))
            # Formulas on this sheet can depend on any edited sheet. Invalidate
            # display roles without resetting indexes, selection, or editor.
            self.dataChanged.emit(self.index(0,0),self.index(self.row_limit-1,self.col_limit-1),[])
        def rowCount(self,parent=QC.QModelIndex()):return 0 if parent.isValid() else self.row_limit
        def columnCount(self,parent=QC.QModelIndex()):return 0 if parent.isValid() else self.col_limit
        def ensure_cell(self,row,col):
            row=min(SHEET_MAX_ROWS-1,max(0,row));col=min(SHEET_MAX_COLS-1,max(0,col))
            if row>=self.row_limit:
                old=self.row_limit;new=min(SHEET_MAX_ROWS,max(row+100,old+1000));self.beginInsertRows(QC.QModelIndex(),old,new-1);self.row_limit=new;self.endInsertRows()
            if col>=self.col_limit:
                old=self.col_limit;new=min(SHEET_MAX_COLS,max(col+10,old+26));self.beginInsertColumns(QC.QModelIndex(),old,new-1);self.col_limit=new;self.endInsertColumns()
        def headerData(self,section,orientation,role=Qt.ItemDataRole.DisplayRole):
            if role==Qt.ItemDataRole.DisplayRole:return sheet_col_name(section) if orientation==Qt.Orientation.Horizontal else str(section+1)
            if role==Qt.ItemDataRole.TextAlignmentRole:return Qt.AlignmentFlag.AlignCenter
            return None
        def flags(self,index):
            if not index.isValid():return Qt.ItemFlag.NoItemFlags
            flags=Qt.ItemFlag.ItemIsEnabled|Qt.ItemFlag.ItemIsSelectable
            return flags if self.read_only else flags|Qt.ItemFlag.ItemIsEditable
        def cell_record(self,index):
            if not self.session or not index.isValid():return {}
            return sheet_find(self.session.book,self.sheet_id)['cells'].get(sheet_address(index.row(),index.column()),{})
        def value(self,index):
            if not self.session or not index.isValid():return None
            return self.session.calculator.cell(self.sheet_id,index.row(),index.column())
        def cell_style(self,index):return sheet_effective_style(self.session.book,self.cell_record(index)) if self.session else {}
        def display_colors(self,index,*,selected=False,current=False):
            cell=self.cell_record(index)
            if self.session and Path(self.session.book.get('origin','')).suffix.lower() in WORKBOOK_SUFFIXES:
                style=self.cell_style(index)
                if not selected or current:
                    return (_sheet_view_hex(style.get('foreground'),'#000000'),_sheet_view_hex(style.get('background'),'#ffffff'))
                return sheet_view_colors(style,style,'light',selected=True,current=False,error=isinstance(self.value(index),SheetError))
            return sheet_view_colors(self.cell_style(index),cell.get('format',{}),ui_theme(),
                                     selected=selected,current=current,error=isinstance(self.value(index),SheetError))
        def data(self,index,role=Qt.ItemDataRole.DisplayRole):
            if not index.isValid() or not self.session or not 0<=index.row()<self.row_limit or not 0<=index.column()<self.col_limit:return None
            cell=self.cell_record(index)
            if role==Qt.ItemDataRole.EditRole:return sheet_raw(cell)
            if role not in (Qt.ItemDataRole.DisplayRole,Qt.ItemDataRole.ToolTipRole,Qt.ItemDataRole.FontRole,
                Qt.ItemDataRole.ForegroundRole,Qt.ItemDataRole.BackgroundRole,Qt.ItemDataRole.TextAlignmentRole):return None
            style=self.cell_style(index)
            if role==Qt.ItemDataRole.DisplayRole:return sheet_display(self.value(index),style,self.session.book['date1904'])
            if role==Qt.ItemDataRole.ToolTipRole:
                value=self.value(index)
                if isinstance(value,SheetError):return sheet_address(index.row(),index.column())+' · '+value.code+'\n'+value.message
                text=sheet_raw(cell) if cell.get('f') else sheet_display(value,style,self.session.book['date1904'])
                if (cell.get('f') or cell.get('formula_type')) and hasattr(self.session.calculator,'provenance'):
                    provenance=self.session.calculator.provenance(self.sheet_id,index.row(),index.column())
                    if isinstance(provenance,dict):
                        saved=provenance.get('kind',provenance.get('source')) in ('saved','cache','saved_cache')
                        text+='\n'+('Wynik zapisany w pliku' if saved else 'Wynik lokalnego przeliczenia')+(' · '+str(provenance['read_at']) if saved and provenance.get('read_at') else '')
                return text[:4000] if text else None
            if role==Qt.ItemDataRole.FontRole:
                f=QG.QFont(style.get('font','Segoe UI' if os.name=='nt' else 'DejaVu Sans'))
                f.setPointSizeF(float(style.get('size',10))*self.zoom);f.setBold(style.get('bold',False));f.setItalic(style.get('italic',False));f.setUnderline(style.get('underline',False));return f
            if role==Qt.ItemDataRole.TextAlignmentRole:
                align=style.get('align','general')
                if align=='general':align='right' if isinstance(self.value(index),(Decimal,int,float)) else 'left'
                x={'left':Qt.AlignmentFlag.AlignLeft,'center':Qt.AlignmentFlag.AlignHCenter,'right':Qt.AlignmentFlag.AlignRight}[align]
                y={'top':Qt.AlignmentFlag.AlignTop,'center':Qt.AlignmentFlag.AlignVCenter,'bottom':Qt.AlignmentFlag.AlignBottom}.get(style.get('valign'),Qt.AlignmentFlag.AlignVCenter)
                return x|y
            if role in (Qt.ItemDataRole.ForegroundRole,Qt.ItemDataRole.BackgroundRole):
                foreground,background=self.display_colors(index)
                return QG.QBrush(QG.QColor(foreground if role==Qt.ItemDataRole.ForegroundRole else background))
            return None
        def setData(self,index,value,role=Qt.ItemDataRole.EditRole):
            if role!=Qt.ItemDataRole.EditRole or not index.isValid() or not self.session or self.read_only:return False
            try:
                changed=self.session.edit(self.sheet_id,index.row(),index.column(),value)
                if changed:self.dataChanged.emit(index,index,[Qt.ItemDataRole.DisplayRole,Qt.ItemDataRole.EditRole])
                return True
            except Exception as exc:self.editFailed.emit(safe_error(exc));return False

    class SheetInput(QW.QLineEdit):
        """Track IME preedit without intercepting the input method's own Enter."""
        def __init__(self, parent=None):
            super().__init__(parent)
            self._sheet_preedit = False
            self._sheet_token = ''
            self._sheet_finished = False
        def inputMethodEvent(self, event):
            super().inputMethodEvent(event)
            self._sheet_preedit = bool(event.preeditString())

    class SheetInteraction(QC.QObject):
        """Scoped owner of commit/cancel/navigation for the four sheet panes.

        No global Return shortcut, no delayed second cursor move. Qt's delegate
        lifecycle can call the same commit, but a consumed token cannot write twice.
        """
        def __init__(self, workspace):
            super().__init__(workspace)
            self._workspace = workspace
            self.draft = None
            self._session = None
            self._editor = None
            self._editor_view = None
            self._active_input = None
            self._busy = False
            self._closing_editor = False
            self._syncing = False
            self._focus_ticket = 0
            self._visibility_key = None
            self._visibility = (SheetHiddenAxis(), SheetHiddenAxis())
            self._completed = collections.deque(maxlen=32)
            self._edit_selection = None
            self._headers = set()
            for view in workspace.views.views:
                for header in (view.horizontalHeader(),view.verticalHeader()):
                    target=header.viewport();self._headers.add(target);target.installEventFilter(self)
            app = QW.QApplication.instance()
            if app is not None:
                app.focusChanged.connect(self.focus_changed)
        @staticmethod
        def key_action(event):
            key = event.key()
            mods = event.modifiers() & ~Qt.KeyboardModifier.KeypadModifier
            plain = mods == Qt.KeyboardModifier.NoModifier
            shift = mods == Qt.KeyboardModifier.ShiftModifier
            if key in (Qt.Key.Key_Return, Qt.Key.Key_Enter):
                if plain or shift:
                    return 'up' if shift else 'down'
                # Do not silently interpret Ctrl/Alt+Enter as plain Enter.
                return 'special-enter'
            if key in (Qt.Key.Key_Tab, Qt.Key.Key_Backtab) and (plain or shift):
                return 'left' if shift or key == Qt.Key.Key_Backtab else 'right'
            if key == Qt.Key.Key_Escape and plain:
                return 'cancel'
            if key == Qt.Key.Key_F6 and (plain or shift):
                return 'previous-area' if shift else 'next-area'
            return ''
        def live(self, widget):
            return widget is not None and qt_object_alive(widget)
        def owns_editor(self, editor):
            return self.live(editor) and editor is self._editor and self.draft is not None and editor._sheet_token == self.draft.token
        def begin(self, index, editor=None, view=None):
            ws = self._workspace
            if self._busy or not ws.session or not index.isValid():
                return False
            target = (ws.session.book['id'], ws.sheet_id, index.row(), index.column())
            if self.draft is not None:
                previous = (self.draft.book_id, self.draft.sheet_id, self.draft.row, self.draft.column)
                if target != previous and not self.finish(focus=False):
                    return False
            if self.draft is None:
                self.draft = sheet_begin_edit(ws.session, ws.sheet_id, index.row(), index.column())
                self._session = ws.session
                self._edit_selection = ws.capture_selection()
                self.clear_error()
            if editor is not None:
                self._editor, self._editor_view = editor, view
                editor._sheet_token = self.draft.token
                editor._sheet_finished = False
                self._active_input = editor
            return True
        def begin_formula(self):
            ws = self._workspace
            text = ws.formula.text()
            existed = self.draft is not None
            if not self.begin(ws.grid.currentIndex()):
                return False
            self._active_input = ws.formula
            if not existed:
                self.draft.text = text
            self.sync_text()
            return True
        def attach_editor(self, editor, index, view):
            if self.owns_editor(editor):
                return  # dataChanged must not replace an in-progress draft.
            if not self.begin(index, editor, view):
                return
            editor.setText(self.draft.text)
            editor.selectAll()
            if not getattr(editor, '_sheet_connected', False):
                editor._sheet_connected = True
                editor.textEdited.connect(lambda text, e=editor: self.text_edited(e, text))
            self.sync_text()
        def text_edited(self, widget, text):
            if self._busy or self._syncing:
                return
            if self.draft is None:
                if widget is not self._workspace.formula or not self.begin_formula():
                    return
            if widget is not self._workspace.formula and not self.owns_editor(widget):
                return
            self._active_input = widget
            self.draft.text = text
            self.clear_error()
            self.sync_text()
        def sync_text(self):
            if self.draft is None or self._syncing:
                return
            self._syncing = True
            try:
                for widget in (self._workspace.formula, self._editor):
                    if not self.live(widget) or widget is self._active_input:
                        continue
                    if widget.text() != self.draft.text:
                        position = widget.cursorPosition()
                        blocker = QC.QSignalBlocker(widget)
                        widget.setText(self.draft.text)
                        widget.setCursorPosition(min(position, len(self.draft.text)))
                        del blocker
            finally:
                self._syncing = False
        def show_error(self, text):
            ws = self._workspace
            ws.edit_error.setText(text)
            ws.edit_error.show()
        def clear_error(self):
            ws = self._workspace
            ws.edit_error.clear()
            ws.edit_error.hide()
        def context_valid(self):
            ws = self._workspace
            d = self.draft
            return d is not None and ws.session is self._session and ws.sheet_id == d.sheet_id and ws.session.book['id'] == d.book_id
        def finish(self, direction=None, *, focus=False, cancel=False, close_editor=True):
            if self._busy:
                return False
            ws = self._workspace
            if not ws.session:
                return self.draft is None
            self._busy = True
            origin = (max(0, ws.grid.currentIndex().row()), max(0, ws.grid.currentIndex().column()))
            editor, view = self._editor, self._editor_view
            changed = False
            try:
                d = self.draft
                if d is not None:
                    if not cancel:
                        if not self.context_valid():
                            self.show_error('Zmieniono kontekst edycji. Wpis nie trafił do innego arkusza. Skopiuj go lub anuluj przez Escape.')
                            self.restore_edit_focus()
                            return False
                        if self.live(self._active_input):
                            d.text = self._active_input.text()
                        result = sheet_commit_edit(self._session, d, read_only=ws.model.read_only)
                        if not result.accepted:
                            self.show_error(result.message)
                            self.restore_edit_focus()
                            return False
                        changed = result.changed
                    origin = (d.row, d.column)
                    self._completed.append(d.token)
                    if self.live(editor):
                        editor._sheet_finished = True
                    self.draft = None
                    self._session = self._editor = self._editor_view = self._active_input = None
                    self._focus_ticket += 1
                    if close_editor and self.live(editor) and self.live(view):
                        self._closing_editor = True
                        try:
                            view.itemDelegate().closeEditor.emit(editor, QW.QAbstractItemDelegate.EndEditHint.NoHint)
                        finally:
                            self._closing_editor = False
                self.clear_error()
                if changed and ws._filters:
                    ws.apply_filters()
                if direction:
                    self.navigate(direction, origin)
                else:
                    ws.selection_changed()
                    if focus:
                        self.focus_cell(origin)
                if ws._refresh_deferred:
                    ws._refresh_deferred = False
                    if not ws._refresh_queued:
                        ws._refresh_queued = True
                        QC.QTimer.singleShot(0, ws.refresh_document)
                return True
            finally:
                self._busy = False
        def from_formula(self, direction=None, *, focus=False):
            if self.draft is None and not self.begin_formula():
                return False
            self._active_input = self._workspace.formula
            return self.finish(direction, focus=focus)
        def native_commit(self, editor):
            if getattr(editor, '_sheet_finished', False) or getattr(editor, '_sheet_token', '') in self._completed:
                return True
            if not self.owns_editor(editor):
                return False
            self._active_input = editor
            return self.finish(close_editor=False)
        def native_close(self, editor, hint):
            if self._closing_editor or not self.owns_editor(editor):
                return True
            if QW.QApplication.focusWidget() is self._workspace.formula:
                return False
            return self.finish(cancel=hint == QW.QAbstractItemDelegate.EndEditHint.RevertModelCache, close_editor=False)
        def editor_destroyed(self, editor):
            if editor is self._editor:
                self._editor = self._editor_view = None
                if self.draft is not None:
                    self._active_input = self._workspace.formula
                    self.sync_text()
        def visibility(self):
            ws = self._workspace
            panes = ws.views
            key = (panes.frozen, *(v._visibility_revision for v in panes.views))
            if key != self._visibility_key:
                fr, fc = panes.frozen
                hidden_rows = {r for r in panes.grid._hidden_rows if r >= fr} | {r for r in panes.top._hidden_rows if r < fr}
                hidden_cols = {c for c in panes.grid._hidden_columns if c >= fc} | {c for c in panes.left._hidden_columns if c < fc}
                self._visibility = (SheetHiddenAxis.from_sections(hidden_rows), SheetHiddenAxis.from_sections(hidden_cols))
                self._visibility_key = key
            return self._visibility
        def navigate(self, direction, origin=None):
            ws = self._workspace
            if not ws.session:
                return
            index = ws.grid.currentIndex()
            current = origin or (max(0, index.row()), max(0, index.column()))
            ranges = tuple((s.top(), s.left(), s.bottom(), s.right()) for s in ws.grid.selectionModel().selection())
            merges = tuple(sheet_range(area) for area in ws.active_sheet()['merges'])
            hidden_rows, hidden_cols = self.visibility()
            target = sheet_next_cell(current, direction, ranges=ranges, merges=merges,
                                     hidden_rows=hidden_rows, hidden_columns=hidden_cols)
            ws.model.ensure_cell(*target)
            new_index = ws.model.index(*target)
            multiple = any(sheet_rect_count(r) > 1 for r in ranges) or len(ranges) > 1
            inside = any(r <= target[0] <= er and c <= target[1] <= ec for r, c, er, ec in ranges)
            if multiple and inside:
                ws.grid.selectionModel().setCurrentIndex(new_index, QC.QItemSelectionModel.SelectionFlag.NoUpdate)
            else:
                ws.grid.selectionModel().setCurrentIndex(new_index, QC.QItemSelectionModel.SelectionFlag.ClearAndSelect)
            ws.anchor_index = None
            ws.selection_changed()
            self.focus_cell(target)
        def focus_cell(self, coordinate=None):
            ws = self._workspace
            if not ws.session:
                return
            index = ws.grid.currentIndex()
            row, col = coordinate or (max(0, index.row()), max(0, index.column()))
            view = ws.views.view_for(row, col)
            view.scrollTo(ws.model.index(row, col), QW.QAbstractItemView.ScrollHint.EnsureVisible)
            view.setFocus(Qt.FocusReason.OtherFocusReason)
        def cycle_area(self, reverse=False):
            ws = self._workspace
            current = QW.QApplication.focusWidget()
            if not self.finish(focus=False):
                return
            index = ws.grid.currentIndex()
            view = ws.views.view_for(max(0, index.row()), max(0, index.column()))
            areas = [view, ws.formula, ws.address, ws.book_button, ws._host_window.titlebar.menu_button]
            position = next((i for i, area in enumerate(areas) if current is area or (current is not None and area.isAncestorOf(current))), 0)
            areas[(position + (-1 if reverse else 1)) % len(areas)].setFocus(Qt.FocusReason.TabFocusReason)
        def handle_key(self, event, widget):
            action = self.key_action(event)
            if not action:
                return False
            if getattr(widget, '_sheet_preedit', False):
                return False
            if isinstance(widget, QW.QLineEdit):
                completer = widget.completer()
                if completer is not None and completer.popup().isVisible():
                    return False
            event.accept()
            if event.type() == QC.QEvent.Type.ShortcutOverride:
                return True
            try:
                if action == 'special-enter':
                    ws = self._workspace
                    ws._host_window.statusBar().showMessage('Enter: zatwierdź i przejdź niżej. Shift+Enter: wyżej. Pełny tekst: przycisk ołówka.', 4500)
                elif action in ('next-area', 'previous-area'):
                    self.cycle_area(action == 'previous-area')
                elif action == 'cancel':
                    self.finish(cancel=True, focus=True)
                elif widget is self._workspace.formula:
                    self.from_formula(action, focus=True)
                else:
                    self.finish(action, focus=True)
            except Exception as exc:
                self.show_error(safe_error(exc))
            return True
        def eventFilter(self, widget, event):
            if widget in self._headers and event.type()==QC.QEvent.Type.MouseButtonPress and self.draft is not None:
                return not self.finish(focus=False)
            return False
