        def copy_cells(self,cut=False):
            if not self.commit_active_editor():return
            rect=self.selected_rect()
            if sheet_rect_count(rect)>SHEET_MAX_PATCH:raise UserError('Kopiuj najwyżej 100 000 komórek naraz.')
            sh=self.active_sheet();matrix=[];cells=[]
            for r in range(rect[0],rect[2]+1):
                row=[]
                for c in range(rect[1],rect[3]+1):
                    cell=sh['cells'].get(sheet_address(r,c));copied=clone(cell)
                    if copied:
                        copied['format']=sheet_effective_style(self.session.book,cell)
                        if copied.get('f'):
                            result=self.session.calculator.cell(self.sheet_id,r,c);copied.pop('error',None);copied.pop('v',None)
                            if isinstance(result,SheetError):copied['error']=result.code
                            elif result is not None:copied['v']=pack(result)
                    cells.append(copied)
                    row.append(sheet_display(self.session.calculator.cell(self.sheet_id,r,c),sheet_effective_style(self.session.book,cell),self.session.book['date1904']))
                matrix.append(row)
            text=io.StringIO();csv.writer(text,delimiter='\t',lineterminator='\n').writerows(matrix)
            mime=QC.QMimeData();mime.setText(text.getvalue())
            payload={'version':1,'book_id':self.session.book['id'],'sheet_id':self.sheet_id,'rect':rect,'revision':self.session.book['revision'],'cells':cells}
            raw=dumps(payload).encode('utf-8')
            if len(raw)>16*1024*1024:raise UserError('Schowek przekracza 16 MB.')
            mime.setData('application/x-pivot-cells',QC.QByteArray(raw));QW.QApplication.clipboard().setMimeData(mime)
            self._cut=payload if cut else None;self._host_window.statusBar().showMessage('Wycięcie nastąpi po wklejeniu.' if cut else 'Skopiowano '+sheet_range_name(rect),3500)
        def paste_cells(self,values_only=False):
            if not self.commit_active_editor():return
            if self._filters:raise UserError('Wyłącz filtr przed wklejaniem zakresu. Nie zmieniono ukrytych wierszy.')
            mime=QW.QApplication.clipboard().mimeData();rect=self.selected_rect();r0,c0=rect[:2];sh=self.active_sheet();patch={};payload=None
            if mime.hasFormat('application/x-pivot-cells'):
                raw=bytes(mime.data('application/x-pivot-cells'))
                if len(raw)>16*1024*1024:raise UserError('Za duży schowek.')
                try:payload=json.loads(raw)
                except (ValueError,UnicodeError):raise UserError('Nieprawidłowe dane schowka.')
                if not isinstance(payload,dict):raise UserError('Nieprawidłowe dane schowka.')
                sr=payload.get('rect');cells=payload.get('cells')
                if not isinstance(payload,dict) or payload.get('version')!=1 or not isinstance(sr,list) or len(sr)!=4 or not isinstance(cells,list) or not all(type(n) is int for n in sr) or sheet_rect_count(sr)!=len(cells) or len(cells)>SHEET_MAX_PATCH:raise UserError('Nieprawidłowy zakres schowka.')
                if not all(type(n) is int for n in sr) or not 0<=sr[0]<=sr[2]<SHEET_MAX_ROWS or not 0<=sr[1]<=sr[3]<SHEET_MAX_COLS:raise UserError('Nieprawidłowe współrzędne schowka.')
                h,w=sr[2]-sr[0]+1,sr[3]-sr[1]+1
                for index,cell in enumerate(cells):
                    rr,cc=divmod(index,w);value=clone(cell)
                    if value:
                        if payload.get('book_id')!=self.session.book['id']:value.pop('s',None)
                        if values_only:value.pop('f',None)
                        elif value.get('f'):
                            if payload.get('book_id')!=self.session.book['id']:raise UserError('Formuły między skoroszytami mogą zmienić znaczenie odwołań. Użyj Wklej wartości (Ctrl+Shift+V).')
                            value['f']=sheet_translate_formula(value['f'],r0-sr[0],c0-sr[1]);value.pop('error',None)
                    patch[sheet_address(r0+rr,c0+cc)]=value
