        def export_book(self):
            if not self.commit_active_editor():return
            book=clone(self.session.book)
            path,_=QW.QFileDialog.getSaveFileName(self,'Zapisz kopię skoroszytu XLSX',book['title']+'.xlsx','Skoroszyt Excel (*.xlsx)')
            if not path:return
            path=str(Path(path).with_suffix('.xlsx'));dest=Path(path).resolve()
            protected={Path(__file__).resolve()}
            for b in self._host_window.service.document.get('workpads',[]):
                if b.get('origin'):protected.add(Path(b['origin']).resolve())
            if self._host_window.service.project_path:protected.add(Path(self._host_window.service.project_path).resolve())
            for source in self._host_window.service.document['sources']:
                for key in ('path','origin'):
                    value=source['options'].get(key)
                    if value and not value.startswith('@'):protected.add(Path(value).resolve())
            if dest in protected:raise UserError('Zapisz nową kopię. Oryginał źródła i zasoby projektu nie są nadpisywane.')
            if dest.exists() and not confirm(self,'Zastąp plik','Zastąpić '+str(dest)+'?'):return
            if book['warnings'] and not confirm(self,'Zakres eksportu XLSX','Nowy plik zachowa komórki, formuły i obsługiwane formaty. Nie zachowa:\n• '+'\n• '.join(book['warnings'])+'\n\nKontynuować do nowego pliku? Oryginał pozostaje bez zmian.'):return
            calc=SheetCalculator(book);errors=[]
            for sh in book['sheets']:
                for address,cell in sh['cells'].items():
                    if cell.get('f'):
                        v=calc.cell(sh['id'],*sheet_position(address))
                        if isinstance(v,SheetError):errors.append(sh['name']+'!'+address+' '+v.code)
            if errors and not confirm(self,'Formuły wymagają sprawdzenia','Nie wszystkie formuły zostały przeliczone:\n'+'\n'.join(errors[:8])+'\nFormuły zostaną zachowane z błędem w zapisanym wyniku. Excel może je przeliczyć. Zapisać mimo to?'):return
            result=self._host_window.blocking_io(lambda:sheet_export_xlsx(book,dest,allow_loss=True,allow_formula_errors=True),'Zapisywanie kopii XLSX')
            if result:self._host_window.statusBar().showMessage('Zapisano kopię: '+str(dest),10000)


