    class DatabaseDataModel(QC.QAbstractTableModel):
        def __init__(self,parent=None):super().__init__(parent);self._page={}
        def set_page(self,page):self.beginResetModel();self._page=page;self.endResetModel()
        def rowCount(self,parent=QC.QModelIndex()):return 0 if parent.isValid() or not self._page else len(self._page['rows'])+1
        def columnCount(self,parent=QC.QModelIndex()):return 0 if parent.isValid() else len(self._page.get('columns',[]))
        def flags(self,index):return (Qt.ItemFlag.ItemIsEnabled|Qt.ItemFlag.ItemIsSelectable) if index.isValid() else Qt.ItemFlag.NoItemFlags
        def headerData(self,section,orientation,role=Qt.ItemDataRole.DisplayRole):
            bound=self.columnCount() if orientation==Qt.Orientation.Horizontal else self.rowCount()
            if role==Qt.ItemDataRole.DisplayRole and 0<=section<bound:
                if orientation==Qt.Orientation.Horizontal:return sheet_col_name(section)
                return str(1 if section==0 else self._page.get('offset',0)+section+1)
            return None
        def data(self,index,role=Qt.ItemDataRole.DisplayRole):
            if not index.isValid() or not 0<=index.row()<self.rowCount() or not 0<=index.column()<self.columnCount():return None
            cell=None if index.row()==0 else self._page['rows'][index.row()-1][index.column()]
            if role in (Qt.ItemDataRole.DisplayRole,Qt.ItemDataRole.ToolTipRole):
                return self._page['columns'][index.column()].get('label',self._page['columns'][index.column()]['name']) if index.row()==0 else database_cell_text(cell)
            if role==Qt.ItemDataRole.FontRole and index.row()==0:
                font=QG.QFont();font.setBold(True);return font
            if role==Qt.ItemDataRole.BackgroundRole:return QG.QBrush(ui_color('raised' if index.row()==0 else 'bg'))
            if role==Qt.ItemDataRole.ForegroundRole:return QG.QBrush(ui_color('text'))
