            self.analyses_list.currentItemChanged.connect(self.analysis_selected);self.analyses_list.setContextMenuPolicy(Qt.ContextMenuPolicy.CustomContextMenu);self.analyses_list.customContextMenuRequested.connect(self.analysis_menu);lay.addWidget(self.analyses_list,3)
            self.analysis_empty=label('Twoje zapisane układy\ni zapytania w jednym miejscu.',True,True);lay.addWidget(self.analysis_empty);lay.addStretch(1)
