            settings=button('Ustawienia',lambda:self.guard(self.settings));settings.setObjectName('navButton');settings.setProperty('iconKey','settings');settings.setIcon(ui_icon('settings'));lay.addWidget(settings)
            self.theme_toggle=button('Jasny motyw' if ui_theme()=='dark' else 'Ciemny motyw',self.toggle_theme);self.theme_toggle.setObjectName('navButton');self.theme_toggle.setIcon(ui_icon('sun' if ui_theme()=='dark' else 'moon'));lay.addWidget(self.theme_toggle)
            version=label('PIVOT STUDIO  '+APP_VERSION,True);version.setObjectName('eyebrow');lay.addWidget(version)
