def qt_attribute_collisions(source):
    """Static regression audit; no Qt imports and not a substitute for a GUI run.

    Return assignments to inherited Qt API names, not legitimate method overrides.
    Names cover QObject, QWidget/QDialog and the model/view bases used by this file.
    """
    tree=ast.parse(source)
    native=next((node for node in tree.body if isinstance(node,ast.FunctionDef) and node.name=='native_ui_types'),None)
    if native is None:raise ValueError('Brak definicji native_ui_types.')
    objects={'parent','children','objectName','setParent','event','eventFilter','timerEvent',
             'installEventFilter','removeEventFilter','deleteLater','thread','moveToThread',
             'signalsBlocked','blockSignals','property','setProperty','destroyed'}
    widgets=objects|{'window','layout','actions','style','palette','font','rect','geometry','frameGeometry',
             'size','sizeHint','minimumSizeHint','minimumSize','maximumSize','width','height','x','y',
             'pos','cursor','windowHandle','windowFlags','windowTitle','parentWidget','focusWidget',
             'metric','paintEngine','devicePixelRatio','devicePixelRatioF','isWindow','show','hide',
             'close','update','repaint','resize','move','setLayout','setStyle','setFont','setPalette',
             'isVisible','isEnabled','isMaximized','isFullScreen','sizePolicy'}
    families={};conflicts=[]
    for cls in (node for node in native.body if isinstance(node,ast.ClassDef)):
        reserved=set(objects)
        for base in cls.bases:
            name=ast.unparse(base)
            if name.startswith('QW.') and name not in ('QW.QStyledItemDelegate','QW.QItemDelegate'):
                reserved|=widgets
            if name=='QW.QDialog':reserved|={'result','accept','reject','done','exec','open'}
            if name in ('QW.QTableView','QW.QListWidget'):
                reserved|={'model','selectionModel','viewport','horizontalHeader','verticalHeader','currentIndex','selectedIndexes'}
            if name=='QC.QAbstractTableModel':reserved|={'data','flags','index','rowCount','columnCount','headerData','sort'}
            reserved|=families.get(name,set())
        families[cls.name]=reserved
        for node in ast.walk(cls):
            if (isinstance(node,ast.Attribute) and isinstance(node.ctx,ast.Store)
                and isinstance(node.value,ast.Name) and node.value.id=='self' and node.attr in reserved):
                conflicts.append((cls.name,node.attr,node.lineno))
            elif (isinstance(node,ast.Call) and isinstance(node.func,ast.Name) and node.func.id=='setattr'
                  and len(node.args)>=2 and isinstance(node.args[0],ast.Name) and node.args[0].id=='self'
                  and isinstance(node.args[1],ast.Constant) and node.args[1].value in reserved):
                conflicts.append((cls.name,node.args[1].value,node.lineno))
    return sorted(set(conflicts))


@contextlib.contextmanager
def test_sqlite_connection(path):
    # sqlite3.Connection.__exit__ commits/rolls back, but does not close the file.
    with contextlib.closing(sqlite3.connect(path)) as connection:
        with connection:yield connection


def gui_contract_test_suite():
    """Source-level regressions for startup. No simulated test is labelled as native Qt."""
    import unittest
    from unittest.mock import patch
    class GuiContractTests(unittest.TestCase):
        @classmethod
        def setUpClass(cls):
            cls.source=Path(__file__).read_text(encoding='utf-8')
            cls.tree=ast.parse(cls.source)
            cls.native=next(node for node in cls.tree.body if isinstance(node,ast.FunctionDef) and node.name=='native_ui_types')
        def fixture(self,base,body):
            return 'def native_ui_types():\n    class Control('+base+'):\n        def __init__(self):\n            '+body+'\n'
        def test_qt_fields_do_not_shadow_inherited_api(self):
            self.assertEqual(qt_attribute_collisions(self.source),[])
        def test_checker_detects_reported_window_collision(self):
            for base in ('QW.QFrame','QW.QWidget','QW.QDialog'):
                self.assertEqual(qt_attribute_collisions(self.fixture(base,'self.window=owner'))[0][:2],('Control','window'))
        def test_checker_detects_layout_and_actions_collisions(self):
            for name in ('layout','actions','metric'):
                self.assertEqual(qt_attribute_collisions(self.fixture('QW.QMainWindow',f'self.{name}=object()'))[0][1],name)
        def test_checker_allows_host_and_nonwidget_model(self):
            self.assertEqual(qt_attribute_collisions(self.fixture('QW.QWidget','self._host_window=owner;self.model=value')),[])
        def test_checker_follows_formdialog_inheritance(self):
            source='def native_ui_types():\n    class FormDialog(QW.QDialog):\n        pass\n    class Editor(FormDialog):\n        def __init__(self):\n            self.window=owner\n'
            self.assertEqual(qt_attribute_collisions(source)[0][:2],('Editor','window'))
        def test_checker_detects_setattr_collision(self):
            self.assertEqual(qt_attribute_collisions(self.fixture('QW.QWidget',"setattr(self, 'window', owner)"))[0][1],'window')
        def test_edge_filter_rejects_non_mouse_events_first(self):
            cls=next(n for n in self.native.body if isinstance(n,ast.ClassDef) and n.name=='EdgeController')
            method=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='eventFilter')
            first=method.body[0];self.assertIsInstance(first,ast.If)
            self.assertIn('MouseButtonPress',ast.unparse(first.test));self.assertNotIn('.window(',ast.unparse(first))
            self.assertTrue(any(isinstance(n,ast.Return) and isinstance(n.value,ast.Constant) and n.value.value is False for n in first.body))
        def test_frame_filter_installed_after_initial_layout(self):
            cls=next(n for n in self.native.body if isinstance(n,ast.ClassDef) and n.name=='MainWindow')
            method=next(n for n in cls.body if isinstance(n,ast.FunctionDef) and n.name=='__init__')
            text=ast.unparse(method)
            self.assertLess(text.index('self.refresh_navigation()'),text.index('EdgeController(self)'))
            self.assertLess(text.index('self.apply_responsive()'),text.index('EdgeController(self)'))
        def test_exception_hook_precedes_mainwindow_construction(self):
            method=next(n for n in self.tree.body if isinstance(n,ast.FunctionDef) and n.name=='native_run')
            text=ast.unparse(method)
            self.assertLess(text.index('sys.excepthook = exception_hook'),text.index("ui['MainWindow'](service)"))
            self.assertIn('if failures:',text)
        def test_removed_preview_flag_is_rejected_before_any_setup(self):
            # Checking the removed spelling is a regression test, not an accepted CLI alias.
            obsolete='--setup'+'-preview'
            with patch(__name__+'.bootstrap_desktop') as setup,contextlib.redirect_stderr(io.StringIO()):
                with self.assertRaises(SystemExit) as result:main([obsolete])
                self.assertEqual(result.exception.code,2);setup.assert_not_called()
        def test_welcome_heading_has_width_dependent_height(self):
            heading=next(n for n in self.native.body if isinstance(n,ast.ClassDef) and n.name=='WrappedHeading')
            text=ast.unparse(heading)
            self.assertIn('heightForWidth',text);self.assertIn('boundingRect',text)
            self.assertIn('math.ceil',text);self.assertIn('setMinimumHeight(needed)',text)
            self.assertNotIn('setFixedHeight',text)
            welcome=next(n for n in self.native.body if isinstance(n,ast.ClassDef) and n.name=='WelcomePage')
            text=ast.unparse(welcome)
            self.assertIn("WrappedHeading('Zobacz więcej w swoich danych.')",text)
            self.assertIn('QW.QLayout.SizeConstraint.SetMinimumSize',text)
            self.assertLess(text.index('QW.QVBoxLayout(content)'),text.index('area.setWidget(content)'))
        def test_help_has_no_removed_preview_option(self):
            output=io.StringIO()
            with contextlib.redirect_stdout(output):
                with self.assertRaises(SystemExit) as result:main(['--help'])
            self.assertEqual(result.exception.code,0);self.assertNotIn('--setup'+'-preview',output.getvalue())
            self.assertIn('--setup',output.getvalue())
    return unittest.defaultTestLoader.loadTestsFromTestCase(GuiContractTests)


