            meta=self.wait(service,service.call('pivot',{'analysis':a}));rid=meta['result_id'];self.assertEqual(meta['row_count'],1)
            self.wait(service,service.call('workbook_prepare',{'source_id':source['id'],'selections':[{'sheet_id':source['workbook']['sheets'][1]['id']}]}))
