        def cleanup_native(self):
            from shiboken6 import isValid
            windows=[w for w in app.topLevelWidgets() if isinstance(w,ui['MainWindow']) and getattr(w,'service',None) is self.service]
            for window in windows:
                if hasattr(window,'database_explorer'):window.database_explorer.dispose()
                if hasattr(window,'watcher'):window.watcher.timer.stop()
                if hasattr(window,'frame_controller'):window.frame_controller.detach()
                if hasattr(window,'file_drop_controller'):window.file_drop_controller.detach()
            for jid in self.service.hub.running():self.service.hub.cancel(jid)
            deadline=time.monotonic()+10
            while any(getattr(w,'tasks',None) and w.tasks.pending for w in windows) and time.monotonic()<deadline:
                QTest.qWait(30);app.processEvents()
            for window in windows:
                if hasattr(window,'tasks'):window.tasks.close()
                window.closing=True;window.hide();window.deleteLater()
            processes=[w.process for w in self.service.hub.workers.values()]
            self.service.cleanup_recovery=True;self.service.close()
            for process in processes:
                with contextlib.suppress(subprocess.TimeoutExpired):process.wait(timeout=5)
            QC.QCoreApplication.sendPostedEvents(None,QC.QEvent.Type.DeferredDelete)
            self.assertFalse(self.callback_errors,str(self.callback_errors))
        def file_mime(self,path):
            mime=QC.QMimeData();mime.setUrls([QC.QUrl.fromLocalFile(str(path))]);return mime
        def drag_event(self,mime):
            event=ui['QtGui'].QDragEnterEvent(QC.QPoint(80,110),Qt.DropAction.CopyAction|Qt.DropAction.MoveAction,
                mime,Qt.MouseButton.LeftButton,Qt.KeyboardModifier.NoModifier)
            event._test_mime=mime  # Qt borrows the pointer; synthetic events must retain its Python owner.
            return event
        def native_drop(self,target,mime):
            enter=self.drag_event(mime);app.sendEvent(target,enter)
            self.assertTrue(enter.isAccepted())
            event=ui['QtGui'].QDropEvent(QC.QPointF(80,110),Qt.DropAction.CopyAction|Qt.DropAction.MoveAction,
                mime,Qt.MouseButton.LeftButton,Qt.KeyboardModifier.NoModifier)
            app.sendEvent(target,event);self.assertTrue(event.isAccepted());self.assertEqual(event.dropAction(),Qt.DropAction.CopyAction)
        def capture_file_drop(self):
            controller=self.window.file_drop_controller;controller.filesDropped.disconnect(self.window.receive_files)
            captured=[];controller.filesDropped.connect(captured.append,Qt.ConnectionType.QueuedConnection)
            return captured
