def qt_widgets_available():
    try:
        from PySide6 import QtCore, QtGui, QtWidgets
        return True
    except (ImportError,OSError): return False


def brand_polygons():
    # Three folded planes; shared by Tk raster and Qt vector rendering.
    return [([(8,41),(32,27),(56,41),(32,55)],'shade'),
            ([(8,30),(32,16),(56,30),(32,44)],'middle'),
            ([(8,19),(32,5),(56,19),(32,33)],'top'),
            ([(32,33),(56,19),(56,24),(32,38)],'edge')]


def brand_ppm(size,background,theme='dark'):
    """Small anti-aliased logo using the standard library only (no setup dependency)."""
    size=max(16,min(192,int(size)));scale=size/64
    def rgb(s):return tuple(int(s[i:i+2],16) for i in (1,3,5))
    bg=rgb(background)
    colors={'top':'#c0d9af','middle':'#82a78a','shade':'#3f6250','edge':'#a0c698'} if theme=='dark' else {'top':'#426d4f','middle':'#6e9974','shade':'#adca9f','edge':'#33573f'}
    data=bytearray(); shapes=[([(x*scale,y*scale) for x,y in p],rgb(colors[k])) for p,k in brand_polygons()]
    for y in range(size):
        for x in range(size):
            value=list(bg)
            for points,color in shapes:
                inside=False;best=1e9;px=x+.5;py=y+.5
                for (ax,ay),(bx,by) in zip(points,points[1:]+points[:1]):
                    dx,dy=bx-ax,by-ay;t=max(0,min(1,((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy)))
                    best=min(best,math.hypot(px-ax-t*dx,py-ay-t*dy))
                    if (ay>py)!=(by>py) and px<(bx-ax)*(py-ay)/(by-ay)+ax:inside=not inside
                a=max(0,min(1,.5-(-best if inside else best)))
                value=[round(v+(c-v)*a) for v,c in zip(value,color)]
            data.extend(value)
    return f'P6\n{size} {size}\n255\n'.encode()+data


def rounded_ppm(size,fill,border,background,radius=9):
    def rgb(s):return tuple(int(s[i:i+2],16) for i in (1,3,5))
    fill,border,bg=map(rgb,(fill,border,background));data=bytearray()
    for y in range(size):
        for x in range(size):
            a=abs(x+.5-size/2)-(size/2-radius);b=abs(y+.5-size/2)-(size/2-radius)
            d=math.hypot(max(0,a),max(0,b))+min(max(a,b),0)-radius
            t=max(0,min(1,.5-d));u=max(0,min(1,-.5-d))
            color=[round(v+(w-v)*t) for v,w in zip(bg,border)]
            data.extend(round(v+(w-v)*u) for v,w in zip(color,fill))
    return f'P6\n{size} {size}\n255\n'.encode()+data


def set_desktop_identity():
    if os.name=='nt':
        with contextlib.suppress(Exception):
            import ctypes
            ctypes.windll.shell32.SetCurrentProcessExplicitAppUserModelID('PivotStudio.Desktop')


def tk_dpi_awareness():
    if os.name!='nt':return
    with contextlib.suppress(Exception):
        import ctypes
        # This process owns Tk only. Qt is launched in its own process.
        ctypes.windll.shcore.SetProcessDpiAwareness(1)


def launch_native_window(marker,arguments,events=None):
    """Keep setup visible until a real Qt paint acknowledgement, not a timer."""
    root=private_dir(runtime_root()/'startup'); token=uid(); folder=private_dir(root/token); ack=folder/'painted'
    py=Path(marker['python'])
    if os.name=='nt' and py.with_name('pythonw.exe').is_file():py=py.with_name('pythonw.exe')
    env=installer_environment();env['PIVOTSTUDIO_RUNTIME']='1';env['_PIVOT_PAINT_ACK']=str(ack)
    args=[str(x) for x in arguments]
    if '--no-bootstrap' not in args:args.append('--no-bootstrap')
    if '--no-runtime' not in args:args.append('--no-runtime')
    logpath=runtime_root()/'native-start.log'
    with logpath.open('ab') as stream:
        child=subprocess.Popen([str(py),str(Path(__file__).resolve()),*args],stdin=subprocess.DEVNULL,
            stdout=stream,stderr=subprocess.STDOUT,env=env,creationflags=CREATE_NO_WINDOW)
    start=time.monotonic()
    try:
        while True:
            if ack.exists():return {'launched':True,'pid':child.pid,**marker}
            if child.poll() is not None:raise UserError(f'Okno aplikacji nie potwierdziło uruchomienia (kod {child.returncode}). Log: {logpath}')
            if time.monotonic()-start>90:
                error=UserError('Start trwa ponad 90 sekund. Proces może nadal pracować; nie uruchamiaj drugiej kopii. Log: '+str(logpath));error.launch_pending=True;raise error
            time.sleep(.06)
    finally:
        with contextlib.suppress(OSError):ack.unlink(missing_ok=True);folder.rmdir()


def setup_png(width, height, rgba):
    """Encode a small RGBA asset with stdlib only. Tk 8.6 reads PNG natively."""
    import struct, zlib
    def chunk(kind, payload):
        return struct.pack('>I', len(payload)) + kind + payload + struct.pack('>I', zlib.crc32(kind + payload) & 0xffffffff)
    rows = b''.join(b'\0' + rgba[y * width * 4:(y + 1) * width * 4] for y in range(height))
    return (b'\x89PNG\r\n\x1a\n' + chunk(b'IHDR', struct.pack('>IIBBBBB', width, height, 8, 6, 0, 0, 0))
            + chunk(b'IDAT', zlib.compress(rows, 6)) + chunk(b'IEND', b''))


def setup_sheet_png(width, index, theme):
    """Antialiased translucent-background bevelled tile. No image/font dependency."""
    width = max(24, min(256, round(width))); height = round(width * .64)
    s = width / 100
    palettes = {
        'dark': (('#446350','#284436','#213a2d'),('#8bad8d','#587b60','#486c53'),('#d1e4c2','#a5c197','#86a878')),
        'light': (('#b8ceb0','#8eaa84','#75996c'),('#799b70','#557d4e','#446b3e'),('#3b6547','#285035','#21432d')),
    }
    top, right, left = palettes[theme][index]
    rgb = lambda x: tuple(int(x[i:i+2],16) for i in (1,3,5))
    shapes = [(((50,6),(95,30),(50,55),(5,30)),rgb(top)),
              (((5,30),(50,55),(50,61),(5,36)),rgb(left)),
              (((50,55),(95,30),(95,36),(50,61)),rgb(right))]
    polygons = [(tuple((x*s,y*s) for x,y in p), c) for p,c in shapes]
    data = bytearray()
    for y in range(height):
        for x in range(width):
            color = [0.,0.,0.]; alpha = 0.
            for points, base in polygons:
                inside = False; distance = 1e8; px=x+.5; py=y+.5
                for (ax,ay),(bx,by) in zip(points, points[1:]+points[:1]):
                    dx=bx-ax;dy=by-ay; t=max(0.,min(1.,((px-ax)*dx+(py-ay)*dy)/(dx*dx+dy*dy)))
                    distance=min(distance,math.hypot(px-ax-t*dx,py-ay-t*dy))
                    if (ay>py)!=(by>py) and px<(bx-ax)*(py-ay)/(by-ay)+ax:inside=not inside
                a=max(0.,min(1.,.5-(-distance if inside else distance)))
                if not a:continue
                # A restrained diagonal light, baked once rather than animated over text.
                light=(.5-(x+y*.6)/(width+height*.6))*.11
                source=[min(255,max(0,c+light*255)) for c in base]
                new_alpha=a+alpha*(1-a)
                color=[(src*a+dst*alpha*(1-a))/new_alpha for src,dst in zip(source,color)]
                alpha=new_alpha
            data.extend((*[round(c) for c in color],round(alpha*255)))
    return setup_png(width,height,bytes(data))


def setup_mark_geometry(size, phase=0., active=False):
    """All three sheets stay inside this separate, text-free square for every phase."""
    size=max(32,round(size)); width=round(size*.72);height=round(width*.64)
    centers=[]
    for index,base in enumerate((.635,.495,.355)):
        lift=math.sin(float(phase)*math.tau-index*.65)*.017*size if active else 0.
        centers.append((size/2,base*size+lift))
    return width,height,tuple(centers)


def setup_symbol_png(size, symbol, color):
    """Small window-control glyphs: antialiased, independent of installed symbol fonts."""
    size=max(12,round(size));s=size/24
    lines={
        'close':((8,8,16,16),(16,8,8,16)),
        'minimize':((7,14,17,14),),
        'expand':((7,7,17,7),(17,7,17,17),(17,17,7,17),(7,17,7,7)),
        'restore':((6,9,15,9),(15,9,15,18),(15,18,6,18),(6,18,6,9),(9,6,18,6),(18,6,18,15),(16,15,18,15),(9,6,9,8)),
        'check':((6,12,10,16),(10,16,18,7)),
        'arrow':((6,12,18,12),(13,7,18,12),(18,12,13,17)),
        'sun':((12,3,12,5),(12,19,12,21),(3,12,5,12),(19,12,21,12),(5.7,5.7,7.1,7.1),(16.9,16.9,18.3,18.3),(5.7,18.3,7.1,16.9),(16.9,7.1,18.3,5.7)),
    }.get(symbol,())
    fg=tuple(int(color[i:i+2],16) for i in (1,3,5));data=bytearray()
    for y in range(size):
        for x in range(size):
            distance=1e8
            for ax,ay,bx,by in lines:
                ax*=s;ay*=s;bx*=s;by*=s;dx=bx-ax;dy=by-ay
                t=max(0.,min(1.,((x+.5-ax)*dx+(y+.5-ay)*dy)/(dx*dx+dy*dy)))
                distance=min(distance,math.hypot(x+.5-ax-t*dx,y+.5-ay-t*dy))
            if symbol=='sun':distance=min(distance,abs(math.hypot(x+.5-12*s,y+.5-12*s)-4*s))
            a=max(0.,min(1.,.5+.63*s-distance));data.extend((*fg,round(255*a)))
    return setup_png(size,size,bytes(data))


class SetupEmblem:
    """Only this Canvas animates; labels live in different widgets outside its bounds."""
    def __init__(self, owner, parent, size):
        self.owner=owner;self.size=owner.px(size);self.images=[];self.items=[];self.theme_key=None
        self.widget=owner.tk.Canvas(parent,width=self.size,height=self.size,bd=0,highlightthickness=0,takefocus=False)
        self.frames=0
    def theme(self, background):
        self.widget.configure(bg=background)
        key=(self.owner.theme,self.size)
        if key!=self.theme_key:
            self.widget.delete('all');width,height,centers=setup_mark_geometry(self.size)
            self.images=[self.owner.tk.PhotoImage(master=self.widget,data=setup_sheet_png(width,i,self.owner.theme),format='png') for i in range(3)]
            self.items=[self.widget.create_image(*center,image=image) for center,image in zip(centers,self.images)]
            self.theme_key=key
        self.render(0,False)
    def render(self, phase, active):
        _,_,centers=setup_mark_geometry(self.size,phase,active)
        for item,center in zip(self.items,centers):self.widget.coords(item,*center)
        self.frames+=1


class SetupWindowsFrame:
    """Owned Tk wrapper only. No WNDPROC replacement, hooks, registry or global settings.

    Adapted to Pivot from the supplied Kontur StartupWindowsChrome design.
    APIs: learn.microsoft.com/windows/win32/api/winuser/nf-winuser-setwindowlongptrw
          learn.microsoft.com/windows/win32/api/winuser/nf-winuser-setwindowpos
    """
    def __init__(self, child):
        import ctypes as C
        self.c=C;self.user=C.WinDLL('user32',use_last_error=True);u=self.user
        for name,args,restype in (
            ('GetAncestor',[C.c_void_p,C.c_uint32],C.c_void_p),('IsWindow',[C.c_void_p],C.c_int32),
            ('GetWindowThreadProcessId',[C.c_void_p,C.POINTER(C.c_uint32)],C.c_uint32),
            ('SetWindowPos',[C.c_void_p,C.c_void_p,C.c_int32,C.c_int32,C.c_int32,C.c_int32,C.c_uint32],C.c_int32),
            ('ShowWindow',[C.c_void_p,C.c_int32],C.c_int32),('IsIconic',[C.c_void_p],C.c_int32),
            ('MonitorFromWindow',[C.c_void_p,C.c_uint32],C.c_void_p)):
            fn=getattr(u,name);fn.argtypes=args;fn.restype=restype
        suffix='LongPtrW' if C.sizeof(C.c_void_p)==8 else 'LongW'
        self.get=getattr(u,'GetWindow'+suffix);self.get.argtypes=[C.c_void_p,C.c_int32];self.get.restype=C.c_ssize_t
        self.set=getattr(u,'SetWindow'+suffix);self.set.argtypes=[C.c_void_p,C.c_int32,C.c_ssize_t];self.set.restype=C.c_ssize_t
        self.hwnd=int(u.GetAncestor(int(child),2) or 0);self.original={};self.check_owned()
    def check_owned(self):
        pid=self.c.c_uint32()
        if not self.hwnd or not self.user.IsWindow(self.hwnd) or not self.user.GetWindowThreadProcessId(self.hwnd,self.c.byref(pid)) or pid.value!=os.getpid():
            raise OSError('Nie potwierdzono własnego okna przygotowania Pivot.')
    def get_style(self,index):
        self.check_owned();self.c.set_last_error(0);value=self.get(self.hwnd,index)
        if not value and self.c.get_last_error():raise self.c.WinError(self.c.get_last_error())
        return value & 0xffffffff
    def set_style(self,index,value):
        self.check_owned();self.c.set_last_error(0);before=self.set(self.hwnd,index,value)
        if not before and self.c.get_last_error():raise self.c.WinError(self.c.get_last_error())
    def apply(self):
        old=self.get_style(-16);ex=self.get_style(-20)
        # Keep minimize/taskbar semantics without reinstating native CAPTION/THICKFRAME.
        wanted={-16:(old & ~0x00c40000)|0x000b0000,-20:(ex & ~(0x80|0x08000000))|0x40000}
        changes=[]
        try:
            for index,value in wanted.items():
                before=self.get_style(index)
                if before!=value:
                    self.original.setdefault(index,before);self.set_style(index,value);changes.append((index,before))
            if changes and not self.user.SetWindowPos(self.hwnd,None,0,0,0,0,0x0037):raise self.c.WinError(self.c.get_last_error())
            if any(self.get_style(i)!=v for i,v in wanted.items()):raise OSError('Windows nie zachował ramki Pivot.')
        except Exception:
            for index,before in reversed(changes):
                with contextlib.suppress(OSError):self.set_style(index,before)
            raise
    def restore(self):
        for index,value in self.original.items():
            with contextlib.suppress(OSError):self.set_style(index,value)
        with contextlib.suppress(OSError):self.user.SetWindowPos(self.hwnd,None,0,0,0,0,0x0037)
        self.original.clear()
    def decorate(self,colors):
        self.check_owned();C=self.c
        try:
            fn=C.WinDLL('dwmapi').DwmSetWindowAttribute
            fn.argtypes=[C.c_void_p,C.c_uint32,C.c_void_p,C.c_uint32];fn.restype=C.c_int32
            rgb=[int(colors['border'][i:i+2],16) for i in (1,3,5)]
            for attr,value in ((33,2),(34,rgb[0]|rgb[1]<<8|rgb[2]<<16)):
                data=C.c_uint32(value);fn(self.hwnd,attr,C.byref(data),C.sizeof(data))
        except (OSError,AttributeError):pass  # Cosmetic only; never fail startup for DWM.
    def workarea(self):
        self.check_owned();C=self.c
        class Rect(C.Structure):_fields_=[('left',C.c_int32),('top',C.c_int32),('right',C.c_int32),('bottom',C.c_int32)]
        class Info(C.Structure):_fields_=[('size',C.c_uint32),('monitor',Rect),('work',Rect),('flags',C.c_uint32)]
        fn=self.user.GetMonitorInfoW;fn.argtypes=[C.c_void_p,C.POINTER(Info)];fn.restype=C.c_int32
        info=Info();info.size=C.sizeof(info)
        if not fn(self.user.MonitorFromWindow(self.hwnd,2),C.byref(info)):raise C.WinError(C.get_last_error())
        r=info.work;return r.left,r.top,r.right-r.left,r.bottom-r.top
    def minimize(self):self.check_owned();self.user.ShowWindow(self.hwnd,6)
    def is_minimized(self):self.check_owned();return bool(self.user.IsIconic(self.hwnd))


class SetupChrome:
    """Borderless from the first mapped frame; real controls, drag, resize and recovery."""
    def __init__(self,owner,system_frame=False):
        self.owner=owner;self.root=owner.root;self.tk=owner.tk;self.enabled=not system_frame
        self.native=None;self.disposed=False;self.drag=None;self.expanded=False;self.restore_rect=None
        self.pending=None;self.motion_id=None;self.map_id=None;self.initial=True;self.return_borderless=False
        self.root.overrideredirect(self.enabled)
        self.host=self.tk.Frame(self.root,bd=0,highlightthickness=0);self.host.pack(fill='both',expand=True,padx=1,pady=1)
        self.bar=self.tk.Frame(self.host,height=owner.px(40),bd=0);self.bar.pack(fill='x');self.bar.pack_propagate(False)
        self.brand_icon=self.tk.Label(self.bar,bd=0);self.brand_icon.pack(side='left',padx=(owner.px(16),owner.px(7)))
        self.brand=self.tk.Label(self.bar,text='Pivot Studio',font=owner.fontspec(12,True),bd=0)
        self.brand.pack(side='left')
        self.caption=self.tk.Label(self.bar,text='  /  PRZYGOTOWANIE',font=owner.fontspec(9),bd=0,anchor='w')
        self.caption.pack(side='left',fill='x',expand=True,padx=(owner.px(6),0))
        self.buttons={};self.icons={}
        for name,command in (('close',owner.close),('expand',self.toggle_expand),('minimize',self.minimize)):
            b=self.tk.Button(self.bar,text={'close':'Zamknij','expand':'Maksymalizuj','minimize':'Minimalizuj'}[name],
                command=command,relief='flat',bd=0,highlightthickness=1,takefocus=True,padx=0,pady=0,cursor='hand2')
            b.pack(side='right',fill='y');self.buttons[name]=b
            b.bind('<Return>',lambda e,button=b:(button.invoke(),'break')[1])
            for event in ('<Enter>','<Leave>','<FocusIn>','<FocusOut>'):
                b.bind(event,lambda e,key=name:self.paint_button(key,e.type))
        self.theme_button=self.tk.Button(self.bar,text='Jasny motyw',command=owner.toggle_theme,font=owner.fontspec(11),
            bd=0,relief='flat',highlightthickness=1,takefocus=True,padx=owner.px(10),pady=0,cursor='hand2')
        self.theme_button.pack(side='right',fill='y',padx=(0,owner.px(8)))
        self.theme_button.bind('<Return>',lambda e:(self.theme_button.invoke(),'break')[1])
        self.divider=self.tk.Frame(self.host,height=1,bd=0);self.divider.pack(fill='x')
        self.grips=[]
        cursors={'n':'top_side','s':'bottom_side','w':'left_side','e':'right_side','nw':'top_left_corner','ne':'top_right_corner','sw':'bottom_left_corner','se':'bottom_right_corner'}
        for edge,cursor in cursors.items():
            grip=self.tk.Frame(self.root,bd=0,cursor=cursor)
            grip.bind('<ButtonPress-1>',lambda e,k=edge:self.begin_drag(e,k));grip.bind('<B1-Motion>',self.move_drag)
            grip.bind('<ButtonRelease-1>',self.end_drag);self.grips.append((edge,grip))
        for widget in (self.bar,self.brand,self.brand_icon,self.caption):
            widget.bind('<ButtonPress-1>',self.begin_drag);widget.bind('<B1-Motion>',self.move_drag)
            widget.bind('<ButtonRelease-1>',self.end_drag);widget.bind('<Double-Button-1>',lambda e:self.toggle_expand())
            widget.bind('<Button-3>',self.menu)
        self.root.bind('<Map>',self.on_map,add='+');self.root.bind('<Alt-space>',self.menu)
        self.root.bind('<Alt-F4>',lambda e:(owner.close(),'break')[1]);self.root.bind('<Escape>',self.escape)
        self.root.bind('<FocusOut>',self.focus_out,add='+')
        if not self.enabled:self.bar.pack_forget()
    def paint_button(self,key,event_type=None):
        b=self.buttons[key];c=self.owner.colors
        over=self.root.winfo_containing(*self.root.winfo_pointerxy()) is b
        focused=self.root.focus_get() is b
        bg=c['error_bg'] if over and key=='close' else c['hover'] if over else c['bg']
        b.configure(bg=bg,activebackground=bg,highlightbackground=c['accent'] if focused else bg,highlightcolor=c['accent'])
    def theme(self):
        c=self.owner.colors;self.root.configure(bg=c['border']);self.host.configure(bg=c['bg']);self.bar.configure(bg=c['bg'])
        self.divider.configure(bg=c['border'])
        for lab in (self.brand,self.caption,self.brand_icon):lab.configure(bg=c['bg'],fg=c['muted'] if lab is self.caption else c['text'])
        self.brand_image=self.tk.PhotoImage(master=self.root,data=brand_ppm(self.owner.px(22),c['bg'],self.owner.theme),format='PPM')
        self.brand_icon.configure(image=self.brand_image)
        for key,b in self.buttons.items():
            icon='restore' if key=='expand' and self.expanded else key
            self.icons[key]=self.tk.PhotoImage(master=self.root,data=setup_symbol_png(self.owner.px(22),icon,c['text']),format='png')
            b.configure(image=self.icons[key],compound='none',width=self.owner.px(40),fg=c['text'],activeforeground=c['text'])
            self.paint_button(key)
        self.theme_button.configure(text='Jasny motyw' if self.owner.theme=='dark' else 'Ciemny motyw',bg=c['bg'],fg=c['muted'],
            activebackground=c['hover'],activeforeground=c['text'],highlightbackground=c['bg'],highlightcolor=c['accent'])
        self.place_grips()
