    def fit(self,width,height):
        if self.expanded or self.disposed:return
        ax,ay,aw,ah=self.workarea();margin=self.owner.px(16)
        width=min(self.owner.px(width),aw-2*margin);height=min(self.owner.px(height),ah-2*margin)
        # Minimums cannot push a high-DPI window beyond its work area.
        self.root.minsize(min(self.owner.px(490),aw-2*margin),min(self.owner.px(340),ah-2*margin))
        width=max(self.root.minsize()[0],width);height=max(self.root.minsize()[1],height)
        if self.initial:
            x=ax+(aw-width)//2;y=ay+(ah-height)//2;self.initial=False
        else:
            # Keep its centre and keep the whole window reachable when it contracts.
            x=self.root.winfo_x()+(self.root.winfo_width()-width)//2
            y=self.root.winfo_y()+(self.root.winfo_height()-height)//2
            x=max(ax,min(x,ax+aw-width));y=max(ay,min(y,ay+ah-height))
        self.root.geometry(f'{width}x{height}+{x}+{y}')
    def begin_drag(self,event,edge='move'):
        if not self.enabled:return
        if self.expanded:
            if edge!='move':return 'break'
            self.toggle_expand()
        self.end_drag();self.owner.user_sized=edge!='move' or self.owner.user_sized
        self.drag=(edge,event.x_root,event.y_root,self.root.winfo_x(),self.root.winfo_y(),self.root.winfo_width(),self.root.winfo_height(),event.widget)
        with contextlib.suppress(self.tk.TclError):event.widget.grab_set()
        return 'break'
    def move_drag(self,event):
        if self.drag is None:return
        edge,sx,sy,x,y,w,h,widget=self.drag;dx=event.x_root-sx;dy=event.y_root-sy
        if edge=='move':
            ax,ay,aw,ah=self.workarea();x=max(ax-w+100,min(x+dx,ax+aw-100));y=max(ay,min(y+dy,ay+ah-self.owner.px(36)))
        else:
            minw,minh=self.root.minsize();ax,ay,aw,ah=self.workarea()
            if 'e' in edge:w=max(minw,min(aw,w+dx))
            if 's' in edge:h=max(minh,min(ah,h+dy))
