    def end_drag(self,event=None,cancel=False):
        if self.motion_id:
            with contextlib.suppress(self.tk.TclError):self.root.after_cancel(self.motion_id)
            self.motion_id=None
        if cancel and self.drag:_,_,_,x,y,w,h,_=self.drag;self.pending=(x,y,w,h)
