        for name,size,bold,fg,bg in labels:st.configure(name,font=self.fontspec(size,bold),foreground=fg,background=bg)
        for name in ('Boot.TButton','Boot.Quiet.TButton','Boot.Primary.TButton','Boot.Source.TRadiobutton'):
            primary=name=='Boot.Primary.TButton';quiet=name=='Boot.Quiet.TButton';source='Source' in name
            fill=c['accent'] if primary else c['bg'] if quiet else c['surface'];fg=c['on_accent'] if primary else c['text']
            st.configure(name,font=self.fontspec(12.5,primary or source),padding=(self.px(14),self.px(12 if source else 6)),foreground=fg,background=fill,anchor='center')
            st.map(name,foreground=[('disabled',c['muted']),('selected',c['accent'])] if source else [('disabled',c['muted'])])
            key=(self.theme,name,self.scale)
            if key not in self.round_cache:
                size=self.px(26);radius=self.px(7)
